import analytics from '@segment/analytics-react-native'


import * as Ordinals from '../../lib/cmtools/Ordinals'
import * as WindWater from '../../lib/cmtools/WindWater'


class EightMansions extends React.Component {
    state = {
        sectionData:[
            { title: '', data: [] },
        ] 
    }
    constructor(props){
        super(props)
        this.header = this.header.bind(this)
        this.chart = this.props.chart
        this.onPressMansion = this.onPressMansion.bind(this)
        analytics.track('Bazi.Analysis.8Mansions')
    }
    componentDidMount(){
        const gua = this.chart.meta.gua
        const map = WindWater.guas[gua.pinyin].eightMansions

        const favorableDirData = [
            { heading: 'Growth', pinyin: 'shengQi', body: map.shengQi },
            { heading: 'Recovery ', pinyin: 'tianYi', body: map.tianYi },
            { heading: 'Longevity', pinyin: 'yanNian', body: map.yanNian },
            { heading: 'Stability', pinyin: 'fuWei', body: map.fuWei},
        ]

        const unfavorableDirData = [
            { heading: 'Obstruction', pinyin: 'huoHai', body: map.huoHai},
            { heading: 'Volatility', pinyin: 'wuGui', body: map.wuGui},
            { heading: 'Disorder', pinyin: 'liuSha', body: map.liuSha},
            { heading: 'Decay', pinyin: 'jueMing', body: map.jueMing},
        ]
        this.setState({ sectionData: [
            { title: 'Favorable Directions', data:  favorableDirData},
            { title: 'Unfavorable Directions', data:  unfavorableDirData}
        ]})
    }
    onPressMansion(payload){
        const path = `windWater.eightMansions.${payload.item.pinyin}`
        this.props.navigation.push('Library', { path, hideClose: true }) 
    }
    header(){
        const gua = this.chart.meta.gua
        return(
            <View style={{ flexDirection: 'column'}}>
                <SectionHeader title="Life Trigram"/> 
                <Toucher
                    style={{ flex: 1 }}
                    onPress={ () => {
                        const path = 'trigrams.' + gua.pinyin
                        this.props.navigation.push('Library', { path, hideClose: true })
                    }}
                >
                    <View style={{ flexDirection:'row'}}>

                    <View style={{borderRightWidth:1, borderRightColor: scolor.separator, flex:1,paddingVertical:12}}>
                        <Text style={{ textAlign:'center', fontSize: 64}}>{ gua.trigram }</Text>
                    </View>
                    <View style={{ flex: 3, alignItems: 'flex-start', justifyContent: 'space-evenly', padding:12, }}>
                        <Text style={{ textAlign:'center', fontSize: 20, fontWeight: 'bold'}}>{ toTitle(gua.english) } - { toTitle(gua.pinyin) }</Text>
                        <Text style={{ textAlign:'center', fontSize: 15, fontWeight: '500', color: Color.GREY[500]}}>{ gua.luoShu } { toTitle(gua.lifeStarDescArr[0]) } { toTitle(gua.lifeStarDescArr[1]) }</Text>
                    </View>
                    </View>
                </Toucher>
  
            </View>
        )
    }
    render(){
        return (
            <SectionList
                keyboardShouldPersistTaps={'always'}
                ref={sectionList => { this.sectionList = sectionList; }}
                sections={this.state.sectionData}
                keyExtractor={(item, index) => index.toString()}
                inverted={false}
                ItemSeparatorComponent={() => (<View style={styles.separator}></View>)}
                ListHeaderComponent={ this.header() }
                renderSectionHeader={payload => {
                    if(!payload.section.title) return <View/>
                    return (
                        <SectionHeader 
                            title={payload.section.title}
                            rightItem={null}
                            leftItem={null}
                        />
                    )
                }}
                renderItem={(payload) => {
                    return (
                        <Toucher 
                            style={[]}
                            onPress={() => this.onPressMansion(payload)}
                        >
                            <View style={styles.infoRow}>
                                <View style={styles.title}>
                                    <Text style={styles.titleText}>
                                        { payload.item.heading }
                                    </Text>
                                </View>
                                <View style={styles.detail}>
                                    <Text style={styles.detailText}>
                                        { payload.item.body }
                                    </Text>
                                </View>
                            </View>
                        </Toucher>
                    )
                }}
                ListFooterComponent={(
                    <View>
                        <View style={styles.separator}/>
                        <Text style={sstyle.layout.footer}>Tap each row to learn more.</Text>
                    </View>
                )}
            />
        )
    }
}
export default withNavigation(EightMansions)

