import * as MysticDoors from '../../lib/cmtools/MysticDoors'
import * as QMDJAssist from '../../lib/utils/QiMenAssist'

class DayBasicQiMen extends React.Component{
    state={
        goodHours: [],
        victoryDay: null,
    }
    constructor(props){
        super(props)
        this.process = this.process.bind(this)
    }
    async componentDidMount(){
        this.process()
    }
    shouldComponentUpdate(nextProps, nextState){
        if(JSON.stringify(nextState) !== JSON.stringify(this.state)) return true
        const t1 = this.props.chart.info.chineseTimeString
        const t2 = nextProps.chart.info.chineseTimeString
        const shouldUpdate = t1 !== t2
        return shouldUpdate
    }
    componentDidUpdate(){
        this.process()
    }
    async process(){
        const preferences = await getPreferences()
        if(!preferences?.bazi?.dayInfo.showNextAuspiciousQiMenFormation) return
        const rootTime = this.props.chart.info.time
        const birthday = await myBirthday(this.context)
        const lookups = QMDJAssist.almanacQMDJLookups(preferences)
        const cKey = QMDJAssist.almanacPayloadCacheKey(birthday, rootTime.year, rootTime.month, lookups)
        const cache = await AsyncStorage.getItem(cKey)
        if(cache ){
            const qmPayload = JSON.parse(cache)
            const today = qmPayload[rootTime.day]
            const goodHours = today.goodHours.filter(i => { return DateTime.fromISO(i.time, { setZone: true }) > rootTime })
            this.setState({ goodHours, victoryDay: today.victoryDay})
        }else{
            this.setState({ goodHours: [], victoryDay: null })
        }
    }
    render(){
        let first = null
        if(this.state.goodHours.length > 0) first = this.state.goodHours[0]
        if(!first && !this.state.victoryDay) return <Fragment/>
        return (
            <View style={styles.container}>
                { this.state.victoryDay && (
                    <View style={[styles.row,
                        first && { borderBottomColor: scolor.separator, borderBottomWidth:1, }
                    ]}>
                        <Toucher
                            style={styles.titleTouch}
                            onPress={() => {
                                const path = 'qiMenDunJia.victoryPalaces'
                                this.props.navigation.push('Library', { path, hideClose: true })
                            }}
                        >
                            <View style={styles.title}>
                                <Image
                                        source={require('../../assets/images/daytable/triforce.png')}
                                        style={styles.icon}
                                        resizeMode="stretch"
                                    />
                                <Text style={styles.titleText}>Victory Day</Text>
                            </View>
                        </Toucher>
                        <Toucher 
                            style={{ flex: 1}}
                            onPress={() => {
                                this.props.navigation.push('QiMenDayList', {  day: this.props.chart.info.time , ...this.state })
                            }}
                        >
                            <View style={styles.detail}>
                                <Text>{ toTitle(this.state.victoryDay.name) }</Text>
                                <Text style={{ color: Color.YELLOW[600]}}> ▼</Text>
                            </View>
                        </Toucher>
                    </View>
                )}
                { first && (
                    <View style={styles.row}>
                        <Toucher
                            style={styles.titleTouch}
                            onPress={() => {
                                const path = 'qiMenDunJia.structures'
                                this.props.navigation.push('Library', { path, hideClose: true }) 
                            }}
                        >
                            <View style={styles.title}>
                                <Image
                                    source={require('../../assets/images/daytable/formation.png')}
                                    style={styles.icon}
                                    resizeMode="stretch"
                                />
                                <Text style={styles.titleText}>Upcoming Form</Text>
                            </View>
                        </Toucher>
                        <Toucher 
                            style={{ flex: 1}}
                            onPress={() => {
                                this.props.navigation.push('QiMenDayList', {  day: this.props.chart.info.time, ...this.state })
                            }}ationation
                        >
                            <View style={styles.detail}>
                                <MaterialCommunityIcon
                                    name={'square'}
                                    color={ MysticDoors.structures[first.structure.name].color || Color.RED[500]}
                                    size={12}
                                />
                                <Text
                                    numberOfLines={1}
                                    ellipsizeMode={'clip'}
                                    style={{ flex: 1, marginLeft:6, }}
                                >
                                    { DateTime.fromISO(first.time).toFormat('ha').toLowerCase() } - { toTitle( MysticDoors.structures[first.structure.name].name) }
                                </Text>
                                <MaterialCommunityIcon
                                    name={'chevron-right'}
                                    size={24}
                                    color={scolor.iconBlurred}
                                    style={styles.chevron}
                                />
                            </View>
                        </Toucher>
                    </View>
                )}
            </View>
        )
    }
}
DayBasicQiMen.contextType = AuthContext
export default DayBasicQiMen = withNavigation(DayBasicQiMen);


