import withPreventDoubleClick from '../../lib/utils/withPreventDoubleClick'
const Toucher = withPreventDoubleClick(TouchableHighlight)
const TouchableOpacityEx = withPreventDoubleClick(TouchableOpacity)


class TabBar extends React.Component{
    constructor(props){
        super(props)
        this.scrollTo = this.scrollTo.bind(this)
    }
    scrollTo(num){
        this.scrollView.scrollTo({ x:num, y:0})
    }
    render(){
        return (
            <View style={styles.container}>
                <ScrollView 
                    style={styles.scrollView}
                    horizontal={true}
                    showsHorizontalScrollIndicator={false}
                    ref={scrollView =>{ this.scrollView = scrollView}}
                >
                    {this.props.tabs.map((tab, index) => (
                        <Toucher
                            onPress={() => this.props.onTabPress(index)}
                            underlayColor={scolor.touchableHighlightUnderlayColor}
                            style={[
                                styles.tab,
                                this.props.selected === index ? styles.selected : styles.notSelected,
                            ]}
                        >
                                <Text style={styles.tabTitle}>{ tab.title }</Text> 
                        </Toucher>
                    ))}
                </ScrollView>
            </View>
        )
    }
}
export default TabBar

