import { CheckBox } from 'react-native-ui-kitten'
import SegmentedControlTab from "react-native-segmented-control-tab";



const QiMenSettings = ({  prefs }) => {
    const [naming, setNaming] = useState(prefs.state.qmdj.palace.namingConvention)
    const [starPath, setStarPath] = useState(prefs.state.qmdj.calculations.starPath)
    const [method, setMethod] = useState(prefs.state.qmdj.calculations.method)

    return (
        <View  style={styles.container}>
            <SectionHeader title={'Palaces'}/>
            <View style={styles.row}>
                <View style={styles.left}>
                    <Text style={styles.title}>Naming Convention</Text>
                </View> 
                <View style={styles.right}>
                    <SegmentedControlTab
                        allowFontScaling={false}
                        tabStyle={styles.segmentTabStyle}
                        activeTabStyle={styles.segmentTabActive}
                        tabTextStyle={styles.segmentTabText}
                        borderRadius={2}
                        tabsContainerStyle={{ flex:1 }}
                        values={['1','2','3']}
                        selectedIndex={naming}
                        onTabPress={index =>  { 
                            setNaming(index)
                            const state = prefs.clone()
                            state.qmdj.palace.namingConvention = index
                            prefs.update(state)
                        }}
                    />
                </View>
            </View>

            { Object.keys(prefs.state.qmdj.palace).map(key => {
                if(key === 'namingConvention') return <Fragment/>
                return (
                    <View>
                        <View style={styles.row}>
                            <CheckBox
                                style={{ flex: 1 }}
                                text={deCamel(key).replace('Show ', '')}
                                checked={prefs.state.qmdj.palace[key]}
                                onChange={(val) => { 
                                    const state = prefs.clone()
                                    state.qmdj.palace[key] = val
                                    prefs.update(state)
                                }}
                            />
                        </View>
                        { key === 'showDayAndHourStemOutline' && (
                            <Text style={{ fontSize: 12, color: Color.GREY[600], padding: 12, paddingLeft:52, }}>Lead Stem will be highlighted if stem is Jia.</Text>
                        )}
                    </View>
                )
            })}


            <SectionHeader title={'Plot'} subtitle={'Changing these settings will alter the calculation of your charts. If unsure, select Rotating and Zhi Run.'}/>
            <View style={styles.row}>
                <View style={styles.left}>
                    <Text style={styles.title}>Star Path</Text>
                </View> 
                <View style={styles.right}>
                    <SegmentedControlTab
                        allowFontScaling={false}
                        tabStyle={styles.segmentTabStyle}
                        activeTabStyle={styles.segmentTabActive}
                        tabTextStyle={styles.segmentTabText}
                        borderRadius={2}
                        tabsContainerStyle={{ flex:1 }}
                        values={['Rotating', 'Flying']}
                        selectedIndex={starPath}
                        onTabPress={index =>  { 
                            setStarPath(index)
                            const state = prefs.clone()
                            state.qmdj.calculations.starPath = index
                            prefs.update(state)
                        }}
                    />
                </View>
            </View>

            <View style={styles.row}>
                <View style={styles.left}>
                    <Text style={styles.title}>Method</Text>
                </View> 
                <View style={styles.right}>
                    <SegmentedControlTab
                        allowFontScaling={false}
                        tabStyle={styles.segmentTabStyle}
                        activeTabStyle={styles.segmentTabActive}
                        tabTextStyle={styles.segmentTabText}
                        borderRadius={2}
                        tabsContainerStyle={{ flex:1 }}
                        values={['Zhi Run', 'Chai Bu']}
                        selectedIndex={ method }
                        onTabPress={index =>  { 
                            setMethod(index)
                            const state = prefs.clone()
                            state.qmdj.calculations.method = index
                            prefs.update(state)
                        }}
                    />
                </View>
            </View>


            <SectionHeader 
                title={'Modifications'}
                subtitle={'Some contemporary schools apply a shift to the late-zi hour (23:00-24:00).  This shift is not documented in traditional texts and does not apply to the Flying Star Path. If you are unsure, leave this checked.'}
            />
            <View style={[styles.row]}>
                <CheckBox
                    style={{ flex: 1 }}
                    text={'Shift Late Zi Stream'}
                    checked={prefs.state.qmdj.calculations.shiftLateZiStream}
                    onChange={(val) => { 
                        const state = prefs.clone()
                        state.qmdj.calculations.shiftLateZiStream = val
                        prefs.update(state)
                    }}
                />
            </View>


        </View>
    )
}
export default QiMenSettings

