import { CheckBox } from 'react-native-ui-kitten'
import SegmentedControlTab from "react-native-segmented-control-tab";


const YiJingSettings = ({  prefs }) => {
    const [numLines, setLines] = useState(prefs.state.yijing.calculations.markedLines)
    const [initialSet, setInitial] = useState(prefs.state.yijing.calculations.initialSet)
    let selected
    if(initialSet === 'random') selected = 0
    if(initialSet === 'empty') selected = 1
    return (
        <View  style={styles.container}>

            <SectionHeader title="Default Hexagram"/>
            <View style={styles.row}>
                <View style={styles.right}>
                    <SegmentedControlTab
                        allowFontScaling={false}
                        tabStyle={styles.segmentTabStyle}
                        activeTabStyle={styles.segmentTabActive}
                        tabTextStyle={styles.segmentTabText}
                        borderRadius={2}
                        tabsContainerStyle={{ flex:1 }}
                        values={['random','empty']}
                        selectedIndex={selected}
                        onTabPress={index =>  { 
                            let result;
                            if(index === 0) result = 'random'
                            if(index === 1) result = 'empty'

                            setInitial(result)
                            const state = prefs.clone()
                            state.yijing.calculations.initialSet = result
                            prefs.update(state)
                        }}
                    />
                </View>
            </View>

            <SectionHeader 
                title="Default # of Random Changing Lines"
                subtitle="When the hexagram is cast, we also generate random changing lines.  Tap the 'Triple' button to see the changed hexagram. By default, this value is 1."
            />
            <View style={styles.row}>
                <View style={styles.right}>
                    <SegmentedControlTab
                        allowFontScaling={false}
                        tabStyle={styles.segmentTabStyle}
                        activeTabStyle={styles.segmentTabActive}
                        tabTextStyle={styles.segmentTabText}
                        borderRadius={2}
                        tabsContainerStyle={{ flex:1 }}
                        values={['0', '1', '2', '3', '4', '5', '6']}
                        selectedIndex={parseInt(numLines)}
                        onTabPress={index =>  { 
                            setLines(index)
                            const state = prefs.clone()
                            state.yijing.calculations.markedLines = index
                            prefs.update(state)
                        }}
                    />
                </View>
            </View>



            <SectionHeader title="Display"/>
            <View style={styles.row}>
                <CheckBox
                    style={{flex: 1}}
                    text={`Show Elemental Colors` }
                    checked={prefs.state.yijing.calculations.showColors}
                    onChange={(val) => { 
                        const state = prefs.clone()
                        state.yijing.calculations.showColors = val
                        prefs.update(state)
                    }}
                />
            </View>
            <View style={styles.row}>
                <CheckBox
                    style={{flex: 1}}
                    text={`Show Process` }
                    checked={prefs.state.yijing.calculations.showMutual}
                    onChange={(val) => { 
                        const state = prefs.clone()
                        state.yijing.calculations.showMutual = val
                        prefs.update(state)
                    }}
                />
            </View>
            <View style={styles.row}>
                <CheckBox
                    style={{flex: 1}}
                    text={`Show Output` }
                    checked={prefs.state.yijing.calculations.showChanged}
                    onChange={(val) => { 
                        const state = prefs.clone()
                        state.yijing.calculations.showChanged = val
                        prefs.update(state)
                    }}
                />
            </View>
        </View>
    )
}
export default YiJingSettings

