class ShiftingPalaceSelector extends React.Component {
    state={
        data: [
        ]
    }
    static navigationOptions = ({ navigation }) => {
        const { params={} } = navigation.state 
		return {
            title: 'Shift',
        }
    }
    constructor(props){
        super(props)
        analytics.track('Bazi.ShiftingPalaceSelector')
        this.chart = props.navigation.getParam('chart')
        if(this.chart.info.gender === 'male'){
            this.state.data = [
                { title: 'Family', data: [
                    { kin: 'Wife', god: 'dw' },
                    { kin: 'Girlfriend', god: 'iw' },
                    { kin: 'Son', god: '7k' },
                    { kin: 'Daughter', god: 'do' },
                    { kin: 'Mother', god: 'dr' },
                    { kin: 'Father', god: 'iw' },
                    { kin: 'Brother', god: 'f' },
                    { kin: 'Sister', god: 'rw' },
                ]},
                { title: 'Extended Family', data: [
                    { kin: 'Mother-In-Law', god: 'ho'},
                    { kin: 'Father-In-Law', god: 'ir'},
                    { kin: `Son-In-Law`, god: 'eg' },
                    { kin: `Son's Wife`, god: 'rw' },
                    { kin: 'Grand Son (son)', god: 'ir'},
                    { kin: 'Grand Daughter (son)', god: 'dr'},
                    { kin: 'Grand Son (daughter)', god: 'eg'},
                    { kin: 'Grand Daughter (daughter)', god: 'ho'},
                    { kin: 'Grandfather (paternal)', god: 'ir' },
                    { kin: 'Grandmother (paternal)', god: 'ho' },
                    { kin: 'Grandfather (maternal)', god: 'eg' },
                    { kin: 'Grandmother (maternal)', god: 'do' },
                ]}
            ]
        }else{
            this.state.data = [
                { title: 'Family', data: [
                    { kin: 'Husband', god: 'do' },
                    { kin: 'Boyfriend', god: '7k' },
                    { kin: 'Son', god: 'ho' },
                    { kin: 'Daughter', god: 'eg' },
                    { kin: 'Mother', god: 'ir' },
                    { kin: 'Father', god: 'dw' },
                    { kin: 'Brother', god: 'rw' },
                    { kin: 'Sister', god: 'f' },
                ]},
                { title: 'Extended Family', data: [
                    { kin: 'Mother-In-Law', god: 'iw'},
                    { kin: 'Father-In-Law', god: 'rw'},
                    { kin: `Daughter's Husband`, god: 'dr' },
                    { kin: `Son's Wife`, god: '7k' },
                    { kin: 'Grand Son (son)', god: 'dr'},
                    { kin: 'Grand Daughter (son)', god: 'ir'},
                    { kin: 'Grand Son (daughter)', god: 'dw'},
                    { kin: 'Grand Daughter (daughter)', god: 'iw'},
                    { kin: 'Grandfather (paternal)', god: 'dr' },
                    { kin: 'Grandmother (paternal)', god: 'eg' },
                    { kin: 'Grandfather (maternal)', god: 'ho' },
                    { kin: 'Grandmother (maternal)', god: '7k' },
                ]}
            ]
        }
    }
    render(){
        if(this.state.data.length === 0) return <View/>
        const godMap = EightWords.dms[this.chart.pillars.day.stem.name].godsToStems
        return (
            <View style={styles.container}>
                <SectionList
                    keyboardShouldPersistTaps={'always'}
                    ref={sectionList => { this.sectionList = sectionList; }}
                    sections={this.state.data}
                    keyExtractor={(item, index) => index.toString()}
                    inverted={false}
                    ItemSeparatorComponent={() => (<View style={styles.separator}></View>)}
                    renderSectionHeader={payload => {
                        if(payload.section.data.length === 0) return Fragment
                        return (
                            <SectionHeader 
                                title={payload.section.title}
                                rightItem={null}
                                leftItem={null}
                            />
                        )
                    }}
                    renderItem={(payload) => {
                        return (
                            <Toucher 
                                underlayColor={scolor.touchableHighlightUnderlayColor}
                                onPress={() => {
                                    this.props.navigation.getParam('onSubmit')({
                                        stem: godMap[payload.item.god],
                                        ...payload.item
                                    })
                                    this.props.navigation.goBack()
                                }}
                            >
                            <View style={styles.row}>
                                <Text style={styles.body}>
                                    { payload.item.kin}
                                </Text> 
                                <Text style={styles.god}>
                                    { `${payload.item.god.toUpperCase()}  ${ Ordinals.stems[godMap[payload.item.god]].chinese }` }
                                </Text>
                            </View>
                            </Toucher>
                        )
                    }}
                    ListFooterComponent={(<View style={styles.separator}/>)}
                />
            </View>
        )
    }
}
export default withNavigation(ShiftingPalaceSelector)

const styles = StyleSheet.create({
    container:{
    },
    separator:{
        height: 1,
        backgroundColor: scolor.separator,
    },
    row:{
        padding:15,
        justifyContent:'space-between',
        alignItems: 'center',
        flexDirection:'row',
    },
    body:{
        fontWeight: 'bold',
    },
    god:{
        fontWeight:'bold',
    }
})