const TouchableOpacityEx = withPreventDoubleClick(TouchableOpacity)

import FontAwesome from 'react-native-vector-icons/FontAwesome';
import FontAwesome5 from 'react-native-vector-icons/FontAwesome5';
import MaterialCommunityIcon from 'react-native-vector-icons/MaterialCommunityIcons'
import { dayStemAux , dayBranchAux, monthBranchAux, yearBranchAux, auxDetails } from '../../lib/cmtools/ShenSha'
import PreferencesContainer from '../../containers/PreferencesContainer';
import analytics from '@segment/analytics-react-native'


import * as Ordinals from '../../lib/cmtools/Ordinals'

class ChartStars extends React.Component {
    state = {
        sectionData:[
            { title: 'Day Stem', data: [] },
            { title: 'Day Branch', data: [] },
            { title: 'Month Branch', data: [] },
            { title: 'Year Branch', data: [] },
        ] 
    }
    constructor(props){
        super(props)
        this.chart = this.props.chart
        analytics.track('Bazi.Analysis.Symbolics')
    }
    componentDidMount(){

        const dayStemIndex = this.chart.pillars.day.stem.number
        const dayBranchIndex =this.chart.pillars.day.branch.number
        const monthBranchIndex =this.chart.pillars.month.branch.number
        const yearBranchIndex =this.chart.pillars.year.branch.number
        
        const dayStemResults = []
        Object.keys(dayStemAux).forEach(name => {
            let matches = typeof dayStemAux[name][dayStemIndex] === 'string' ? [dayStemAux[name][dayStemIndex]] : dayStemAux[name][dayStemIndex]
            matches = matches.map(m => {
                if(name === 'skyWealth'){
                    return `${Ordinals.stems[m].chinese} ${ Ordinals.stems[m].elementName}`
                }else{
                    return `${Ordinals.branches[m].chinese} ${ Ordinals.branches[m].animalName}`
                }
            })
            dayStemResults.push({ aux: 'dayStemAux', name, matches, detail: auxDetails.dayStemAux[name]  });
        })


        const dayBranchResults = []
        Object.keys(dayBranchAux).forEach(name => {
            let matches = typeof dayBranchAux[name][dayBranchIndex] === 'string' ? [dayBranchAux[name][dayBranchIndex]] : dayBranchAux[name][dayBranchIndex]
            matches = matches.map(m => {
                return `${Ordinals.branches[m].chinese} ${ Ordinals.branches[m].animalName}`
            })
            dayBranchResults.push({ aux: 'dayBranchAux', name, matches, detail: auxDetails.dayBranchAux[name]  });
        })

        const monthBranchResults = []
        Object.keys(monthBranchAux).forEach(name => {
            let matches = typeof monthBranchAux[name][monthBranchIndex] === 'string' ? [monthBranchAux[name][monthBranchIndex]] : monthBranchAux[name][monthBranchIndex]
            let newMatches = []
            if(matches[0]) 
                newMatches.push(`${Ordinals.stems[matches[0]].chinese } ${matches[0]}`)
            if(matches[1])
                newMatches.push(`${Ordinals.branches[matches[1]].chinese} ${ Ordinals.branches[matches[1]].animalName }`)
            matches = newMatches
            monthBranchResults.push({ aux: 'monthBranchAux', name, matches, detail: auxDetails.monthBranchAux[name]  });
        })

        const yearBranchResults = []
        Object.keys(yearBranchAux).forEach(name => {
            let matches = typeof yearBranchAux[name][yearBranchIndex] === 'string' ? [yearBranchAux[name][yearBranchIndex]] : yearBranchAux[name][yearBranchIndex]
            matches = matches.map(m => {
                return `${Ordinals.branches[m].chinese} ${ Ordinals.branches[m].animalName}`
            })
            yearBranchResults.push({ aux: 'yearBranchAux', name, matches, detail: auxDetails.yearBranchAux[name]  });
        })


        this.setState({
            sectionData:[
                { title: 'Day Stem', data: dayStemResults },
                { title: 'Day Branch', data: dayBranchResults },
                { title: 'Month Branch', data: monthBranchResults },
                { title: 'Year Branch', data: yearBranchResults }
            ]
        })


    }
    render(){
        return (
            <SectionList
                keyboardShouldPersistTaps={'always'}
                ref={sectionList => { this.sectionList = sectionList; }}
                sections={this.state.sectionData}
                keyExtractor={(item, index) => index.toString()}
                inverted={false}
                renderSectionHeader={payload => {
                    return (
                        <SectionHeader 
                            title={`${payload.section.title} Reference`}
                            rightItem={null}
                            leftItem={null}
                        />
                    )
                }}
                renderItem={(payload) => {
                    return (
                        <Subscribe to={[PreferencesContainer]}>
                        {(prefs) => {
                            if(!prefs?.state?.bazi?.stars[payload.item.aux][payload.item.name]) return <Fragment/>
                            return (
                                <Toucher
                                    underlayColor={scolor.touchableHighlightUnderlayColor}
                                    onPress={() => {
                                        const item = payload.item
                                        let msg = '\n' + toTitle(item.detail.$dict_noun.join(', '))
                                        msg += '\n\n——\n\n' + item.detail.desc
                                        Alert.alert(deCamel(item.name), msg)

                                    }}
                                >
                                    <View style={styles.starRow}>
                                        <MaterialCommunityIcon
                                            name={payload.item.detail.icon}
                                            color={Color.GREY[600]}
                                            size={16}
                                            style={styles.starIcon}
                                        />
                                        <Text style={styles.title}>
                                            { `${ deCamel(payload.item.name) } ${ payload.item.detail.chinese }` }
                                        </Text>
                                        <Text style={styles.body}>
                                            { payload.item.matches.map(i => i.replace('undefined', '')).join(', ') }
                                        </Text>
                                    </View>
                                </Toucher>
                            )
                        }}
                        </Subscribe>
                    )
                }}
                ListFooterComponent={(
                    <View>
                        <View style={styles.separator}/>
                        <Text style={sstyle.layout.footer}>Tap each row to learn more.</Text>
                    </View>
                )}
            />
        )
    }
}
export default withNavigation(ChartStars)

