export const calcMinutePillar = (time, cString, hStem, hBranch) => {
	const t = cString.split('-')
	const begins = DateTime.fromObject({ year: t[0], month: t[1], day: t[2], hour: t[3], zone: time.zone })
	// console.log(time.toFormat('yyyy-MMM-dd H:mm'), '--',begins.toFormat('yyyy-MMM-dd H:mm'), '--', dStem, dBranch)

	const branchNum = Math.floor(time.diff(begins, [ 'minutes' ]).minutes / 10 )
	const minB = Ordinals.branchOrdering[branchNum]
	
	const table = {
		jia: 0,
		yi: 2,
		bing: 4,
		ding: 6,
		wu: 8,
		ji: 0,
		geng: 2,
		xin: 4,
		ren: 6,
		gui: 8
	}

	let stemNum = table[hStem] + branchNum
	if(stemNum >= 10) stemNum = stemNum - 10
	const minS = Ordinals.stemOrdering[stemNum]
	return [minS, minB]

}


export const rawToWeights = (processed, raw) => {
    const ratio = { jia: 0, yi: 0, bing: 0, ding: 0, wu: 0, ji: 0, geng: 0, xin: 0, ren: 0, gui: 0}
    const gods = processed.meta.maps.stemToGod
    let totalScores = 0
	Object.keys(raw).forEach(s => { totalScores += raw[s] })
	Object.keys(raw).forEach(s => {
		ratio[s] = Math.round(raw[s] / totalScores * 100)
    }) //.

	//Convert to Gods
	const godsRaw = {}
	const godsRatio =  {}
	Object.keys(ratio).forEach(key => {
		godsRatio[gods[key]] = ratio[key]
		godsRaw[gods[key]] = raw[key]
	})

	//Element Distribution
	const elementDistRatio = {}
	const elementDistRaw = {}
	Object.keys(Ordinals.elements).forEach(element => {
		elementDistRatio[element] = 0
		elementDistRaw[element] = 0
		const stem1 = Ordinals.elements[element].stems[0]		
		const stem2 = Ordinals.elements[element].stems[1]		
		if(stem1 in ratio) elementDistRatio[element] += ratio[stem1]
		if(stem2 in ratio) elementDistRatio[element] += ratio[stem2]
		if(stem1 in raw) elementDistRaw[element] += raw[stem1]
		if(stem2 in raw) elementDistRaw[element] += raw[stem2]
	})

	//Aspect Distribution
	const aspectDistRatio = {}
	const aspectDistRaw = {}
	const aspectStemMap = processed.meta.maps.aspectToStems
	Object.keys( processed.pillars.day.stem.aspects).forEach(aspect => {
		aspectDistRatio[aspect] = 0
		aspectDistRaw[aspect] = 0
		const stem1 = aspectStemMap[aspect][0]
		const stem2 = aspectStemMap[aspect][1]
		if(stem1 in ratio) aspectDistRatio[aspect] += ratio[stem1]
		if(stem2 in ratio) aspectDistRatio[aspect] += ratio[stem2]
		if(stem1 in raw) aspectDistRaw[aspect] += raw[stem1]
		if(stem2 in raw) aspectDistRaw[aspect] += raw[stem2]
    })
    return {
        ratio: {
			gods: godsRatio,
			stems: ratio,
			elements: elementDistRatio,
			aspects: aspectDistRatio,
		},
		raw: {
			gods: godsRaw,
			stems: raw,
			elements: elementDistRaw,
			aspects: aspectDistRaw,
		},
    }
}


export const formPayload = ({ info, pillars, luckPillars, root =  null, shiftingPalace=undefined}) => {
	const shiftInfo = root?.info?.shiftingPalace || shiftingPalace
	
	const pillarNames = ['year', 'month','day','hour', 'minute', 'conception', 'life']
    let referenceStem = shiftInfo?.stem || root?.pillars?.day?.stem?.name || pillars[2][0]

	let mainElement = Ordinals.stems[referenceStem].element
	let stemToGod = EightWords.dms[referenceStem].stemsToGods
	let godToStem = EightWords.dms[referenceStem].godsToStems

	let aspectToElement =  Ordinals.elements[mainElement].aspects
	let elementToAspect = Ordinals.elements[mainElement].elements
	let aspectToStems = Ordinals.stems[referenceStem].aspects

	const pillarsModified = {}
	pillars.forEach((pill, index) => {
		pillarsModified[pillarNames[index]] = extendPillar(pill, elementToAspect , stemToGod, pillarNames[index])
	})
    if(info.hourUnknown){
		pillarsModified.hour = undefined
	}

	const luckModified = luckPillars.map(item => ({
		pillar: extendPillar(item.pillar, elementToAspect, stemToGod, 'luck'),
		time: item.time 
	}))

	const result = {
		info,
		luck: luckModified,
		pillars: pillarsModified,
		meta:{
			maps: {
				stemToGod,
				godToStem,
				aspectToElement,
				elementToAspect,
				aspectToStems
			}
		},
    }
	
    return result
}


export const extendPillar = (pill, aspects, gods, name) => { //takes [stem, branch]
	const stemElement = Ordinals.stems[pill[0]].element
	//should cloneDeep these
	const pillar = {
		stem: {
			...Ordinals.stems[pill[0]], 

			aspc: EightWords.aspects[aspects[stemElement]],
			gdd: EightWords.gods[ gods[pill[0]] ], 
			elm: Ordinals.elements[stemElement],
		},
		branch:{
			...Ordinals.branches[pill[1]],
			ssn: Ordinals.seasons[ Ordinals.branches[pill[1]].season ]
		},
		jiaGroup: Ordinals.sixtyPillars[pill[0]][pill[1]].stream,
		voidStars: Ordinals.streams[ Ordinals.sixtyPillars[pill[0]][pill[1]].stream   ].void,
	}
	const hs = pillar.branch._hiddenStemsDict
	const hsData = {}
	Object.keys(hs).forEach(q => {
		hsData[q] = undefined
		if(hs[q]){
			const element = Ordinals.stems[hs[q]].element
			hsData[q] = {
				...Ordinals.stems[hs[q]],
				gdd: EightWords.gods[ gods[hs[q]]],
				aspc: EightWords.aspects[aspects[element]],
				elm:Ordinals.elements[element],
			}
		}
	})
	pillar.branch.stems = hsData
	pillar.name = name;
	return pillar
}


export const calcCounts = (processed) =>  {
    const pillars = processed.pillars
    const gods = processed.meta.maps.stemToGod

    const stems = [pillars.year.stem, pillars.month.stem]
	const branches = [pillars.year.branch, pillars.month.branch, pillars.day.branch]
	if(!processed.info.hourUnknown){
		stems.push(pillars.hour.stem)
		branches.push(pillars.hour.branch)
	}
    //Counts
	const stemCounts = { jia: 0, yi: 0, bing: 0, ding: 0, wu: 0, ji: 0, geng: 0, xin: 0, ren: 0, gui: 0}
	const elementCounts = { wood: 0, fire: 0, earth: 0, metal: 0, water: 0}
    const godCounts = { ir: 0, dr: 0, f: 0, rw: 0, eg: 0, ho: 0, iw: 0, dw: 0, '7k': 0, do: 0 }

	const godCoreCounts = { ir: 0, dr: 0, f: 0, rw: 0, eg: 0, ho: 0, iw: 0, dw: 0, '7k': 0, do: 0 }
	const stemCoreCounts ={ jia: 0, yi: 0, bing: 0, ding: 0, wu: 0, ji: 0, geng: 0, xin: 0, ren: 0, gui: 0} 
    const elementCoreCounts = { wood: 0, fire: 0, earth: 0, metal: 0, water: 0}

	stems.forEach(stem => {
		stemCounts[stem] += 1
		godCounts[gods[stem]] += 1
        elementCounts[stem.element] += 1
		stemCoreCounts[stem] += 1
		godCoreCounts[gods[stem]] += 1
		elementCoreCounts[stem.element] += 1
	})

	branches.forEach(branch => {
		branch._hiddenStemsArr.forEach((stem,index) => {
			if(stem){
				stemCounts[stem] += 1
				godCounts[gods[stem]] += 1
				elementCounts[Ordinals.stems[stem].element] += 1
				if(index === 1){
					stemCoreCounts[stem] += 1
					godCoreCounts[gods[stem]] += 1
					elementCoreCounts[Ordinals.stems[stem].element] += 1
				}
			}
		})	
    })
    processed.meta.counts =  {
        gods: godCounts,
        elements: elementCounts,
        stems: stemCounts,
        godsCore: godCoreCounts,
        elementsCore: elementCoreCounts,
        stemsCore: stemCoreCounts
	}
}

export const calcWeights = (processed) => {
    const pillars = processed.pillars
	const stems = [pillars.year.stem.name, pillars.month.stem.name, pillars.day.stem.name]
	const branches = [pillars.year.branch.name, pillars.month.branch.name, pillars.day.branch.name]
	if(!processed.info.hourUnknown){
		stems.push(pillars.hour.stem.name)
		branches.push(pillars.hour.branch.name)
    }

	let raw = { jia: 0, yi: 0, bing: 0, ding: 0, wu: 0, ji: 0, geng: 0, xin: 0, ren: 0, gui: 0}
	stems.forEach(stem => {
		const weight = Scores.stemWeights[stem][pillars.month.branch.name] * Scores.multiplier['stem']
		raw[stem] += weight
	})
	branches.forEach(b => {
		Object.keys(Scores.branchMultipliers[b]).forEach(stem => {
			const multiplier = Scores.branchMultipliers[b][stem]
			const weight = Scores.stemWeights[stem][pillars.month.branch.name] * multiplier
			raw[stem] += weight
		})
    })

	const rawCombo = calcCombineWeights(processed, raw)

	processed.meta['weightsPlain'] = rawToWeights(processed, raw)
	processed.meta['weightsCombo'] = rawToWeights(processed, rawCombo)
	if(processed.info.weightsIncludeCombos)
		processed.meta['weights'] =  processed.meta['weightsCombo']
	else
		processed.meta['weights'] = processed.meta['weightsPlain']
    
}

export const calcStats = (processed) => {
    const dm = processed.pillars.day.stem.name;
    const ratio = processed.meta.weights.ratio.stems
    const  raw = processed.meta.weights.raw
    const elementDistRatio = processed.meta.weights.ratio.elements


	const aspectStems = processed.meta.maps.aspectToStems
	const supporters = [ ...aspectStems.companion, ...aspectStems.resource]
    let supportScore = 0

	supporters.forEach(s => {
		if(ratio[s]) supportScore += ratio[s]
	})
	let strength = 'balanced';
	if(supportScore <= 10){
		strength = 'extreme weak'
	}else if(supportScore > 10 && supportScore <= 45){
		strength = 'weak'
	}else if(supportScore > 45 && supportScore <= 50){
		strength = 'balanced weak'
	}else if(supportScore > 50 && supportScore <= 55){
		strength = 'balanced strong'
	}else if(supportScore > 55 && supportScore <=  90){
		strength = 'strong'
	}else if(supportScore > 90){
		strength = 'extreme strong'
	}

	let temperature = null;
	if(elementDistRatio.fire - elementDistRatio.water >= 7){
		temperature = 'hot'
	}else if( elementDistRatio.water - elementDistRatio.fire >= 7){
		temperature = 'cold'
	}

	
	
	const structure = Object.keys(raw.aspects).reduce((a, b) => raw.aspects[a] > raw.aspects[b] ? a : b);
	const profile = Object.keys(raw.gods).reduce((a, b) => raw.gods[a] > raw.gods[b] ? a : b);


	let yinCount = 0
	let yangCount = 0
	Object.keys(processed.pillars).forEach(key => {
		if(!processed.pillars[key]) return
		if(key === 'conception' || key === 'life' || key === 'minute') return 
		if(processed.pillars[key].stem.number % 2 === 1){
			yinCount += 1
		}else{
			yangCount += 1
		}
	})

	let polarityDesc = null;
	if(yinCount > yangCount){
		polarityDesc = 'yin'
	}else if(yangCount > yinCount){
		polarityDesc = 'yang'
	}else{
		polarityDesc = 'balanced'
	}
	const polarity = {
		yinCount,
		yangCount, 
		desc: polarityDesc
	}

    processed.meta.stats = {
        temperature,
        supportScore,
		strength,
		structure,
		profile,
		polarity
    }
    
}

export const calcCombineWeights = (processed, raw) => {
	let stems = []
	let branches = []
	const sCombos = []
	const bCombos = []
	const dirCombos = []
	const harCombos = []
	const addedElements = []
	const mBranch = processed.pillars.month.branch.name

	Object.keys(processed.pillars).forEach(p => {
		if(!processed.pillars[p]) return
		if(p === 'conception' || p === 'life' || p === 'minute') return 
		stems.push(processed.pillars[p].stem.name)
		branches.push(processed.pillars[p].branch.name)
	})


	let usedStems = []
	for(let x =0; x < stems.length; x++){
		for(let y=x+1; y< stems.length; y++){
			if( Ordinals.stems[stems[x]].combine === stems[y]){
				if(usedStems.indexOf(x) < 0 && usedStems.indexOf(y) < 0){
					if(y - x === 1){ //only side-by-side stems
						sCombos.push({
							indexes: [x, y ],
							stems: [stems[x], stems[y]],
							element: Ordinals.stems[stems[x]].combineResult
						})
						usedStems.push(x)
						usedStems.push(y)
					}
				}
			}
		}
	}

	let usedBranches = []
	for(let x =0; x < branches.length; x++){
		for(let y=x+1; y< branches.length; y++){
			if(Ordinals.branches[branches[x]].combine === branches[y]){
				if(usedBranches.indexOf(x) < 0 && usedBranches.indexOf(y) < 0){
					if(y - x === 1){ //only side-by-side branches
						bCombos.push({
							indexes: [x, y ],
							branches: [branches[x],branches[y]],
							element: Ordinals.branches[branches[x]].combineResult
						})
						usedBranches.push(x)
						usedBranches.push(y)
					}
				}
			}
		}
	}

	Object.keys(Ordinals.branchSpecialRelations.direction).forEach(key => {
		const frame = Ordinals.branchSpecialRelations.direction[key]
		const intersection = _.intersection(frame, branches)
		if(intersection.length === 3){
			dirCombos.push({
				indexes:intersection.map(e => branches.indexOf(e)),
				branches: intersection,
				element: key
			})
		}
	})

	Object.keys(Ordinals.branchSpecialRelations.harmony).forEach(key => {
		const frame = Ordinals.branchSpecialRelations.harmony[key]
		const intersection = _.intersection(frame, branches)
		if(intersection.length >= 2){
			harCombos.push({
				indexes:intersection.map(e => branches.indexOf(e)),
				branches: intersection,
				element: key
			})
		}
	})

	// console.log('------------')
	// console.log('Stem Combos', sCombos)
	// console.log('Branch Combos', bCombos)
	// console.log('Direction Combos', dirCombos)
	// console.log('Harmony Combos', harCombos)
	
	sCombos.forEach(combo => {
		addedElements.push({
			axis: 'stem',
			type: 'stem',
			combo: combo,
		})
	})

	if(dirCombos.length > 0){
		dirCombos.forEach(combo => {
			addedElements.push({
				axis: 'branch',
				type: 'direction',
				combo: combo,
			})
		})
	}

	if(harCombos.length > 0){
		harCombos.forEach(combo => {
			const existing = addedElements.find(i => (i.axis === 'branch' && _.intersection(i.combo.indexes, combo.indexes).length > 0))
			if(!existing){
				const comboType = combo.indexes.length === 3 ? 'harmony' : 'halfHarmony'
				addedElements.push({
					axis: 'branch',
					type: comboType,
					combo: combo,
				})
			}
		})
	}

	if(bCombos.length > 0){
		bCombos.forEach(combo => {
			const existing = addedElements.find(i => (i.axis === 'branch' && _.intersection(i.combo.indexes, combo.indexes).length > 0))
			if(!existing){
				addedElements.push({
					axis: 'branch',
					type: 'branchCombo',
					combo: combo,
				})
			}
		})
    }

	const newRaw = _.cloneDeep(raw)

    addedElements.forEach(item => {
		const stems = Ordinals.elements[item.combo.element].stems
		const mBranchPolarity = Ordinals.branches[mBranch].polarity
		if(item.axis === 'stem'){ 
			const newStem = stems[0] //always yang
			const stemScore = Scores.comboMultiplier['stem'] * Scores.stemWeights[newStem][mBranch]
			newRaw[newStem] += stemScore
		}else{
			const newStem = mBranchPolarity === 'yang' ? stems[0] : stems[1]
			const stemScore = Scores.comboMultiplier[item.type] * Scores.stemWeights[newStem][mBranch]
			newRaw[newStem] += stemScore
		}
    })
	Object.keys(newRaw).forEach(k => { newRaw[k] = Math.round(newRaw[k]) })
	return newRaw
}

export const calcFavorableGods = (processed) => {
	const stemToGod = processed.meta?.maps?.stemToGod
	const pillars = processed.pillars
	const weights = processed.meta?.weights
	const stats = processed.meta?.stats
	const maps = processed.meta?.maps
	const rawGods = weights.raw.gods	
	const rawElements = weights.raw.elements
	const rawStems = weights.raw.stems
	const ratioElements = weights.ratio.elements
	const ratioAspects = weights.ratio.aspects
    const rawAspects = weights.raw.aspects
    const supportScore = processed.meta.stats.supportScore
	const temperature = processed.meta.stats.temperature;

	let medicatingGod = null;
	let regulatingGod = null;
	let arbitratingGod = null;


	//Arbitrating God
	const topElements = Object.keys(rawElements).sort(function(a, b) {
		return rawElements[b] - rawElements[a];
	}).splice(0, 2).sort().join('-')
	const arbitratingMap = {
		'earth-wood': ['bing','ding'],
		'fire-metal': ['wu','ji'],
		'earth-water': ['geng','xin'],
		'metal-wood': ['ren','gui'],
		'fire-water': ['jia','yi'],
	}
	if(topElements in arbitratingMap){
		const set = arbitratingMap[topElements]
		if(rawStems[set[0]] > 0 || rawStems[set[1]] > 0){
			arbitratingGod = rawGods[set[0]] > rawGods[set[1]] ? stemToGod[set[0]] : stemToGod[set[1]]
		}
	}

	//Regulating God
	if(temperature === 'hot'){
		if(rawStems['ren'] > 0 || rawStems['gui'] > 0){
			regulatingGod = rawStems['ren'] > rawStems['gui'] ? stemToGod['ren']: stemToGod['gui']
		}
	}else if(temperature === 'cold'){
		if(rawStems['bing'] > 0 || rawStems['ding'] > 0){
			regulatingGod = rawStems['bing'] > rawStems['ding'] ? stemToGod['bing']: stemToGod['ding']
		}
	}


	//Medicating God
	const fetchGod = (sets) => {
		let result = null;
		for(let set of sets){
			if(rawGods[set[0]] > 0 || rawGods[set[1]] > 0){
				result = rawGods[set[0]] > rawGods[set[1]] ? set[0] : set[1]
				break;
			}
		}
		return result;
	}
	if(supportScore >= 50){
		if(ratioAspects.companion > ratioAspects.resource){
			medicatingGod = fetchGod([['do','7k'], ['eg','ho'], ['dw','iw']])
		}else{
			medicatingGod = fetchGod([['dw','iw'], ['eg','ho']])
		}
	}else if(supportScore < 50){
		if(ratioAspects.power > ratioAspects.wealth && ratioAspects.power > ratioAspects.output){
			medicatingGod = fetchGod([['dr','ir'], ['f','rw']])
		}else if(ratioAspects.wealth > ratioAspects.power && ratioAspects.wealth > ratioAspects.output){
			medicatingGod = fetchGod([['f','rw'], ['dr','ir']])
		}else{
			medicatingGod = fetchGod([['dr','ir'], ['f','rw']])
		}
	}
	processed.meta.usefulGods = {
		regulating: regulatingGod,
		medicating: medicatingGod,
		arbitrating: arbitratingGod
    }

	//Favorable Elements
	const favorable = {
		aspects: [],
		elements: [],
		gods: [],
	}
	const unfavorable = {
		aspects: [],
		elements: [],
		gods: [],
	}
	if(stats.supportScore >= 50){
		favorable.aspects = ['output', 'wealth','power']
		favorable.elements = [maps.aspectToElement['output'], maps.aspectToElement['wealth'], maps.aspectToElement['power'] ],
		favorable.gods = ['eg','ho','iw','dw','7k','do']
		favorable.stems = [maps.godToStem['eg'], maps.godToStem['ho'],maps.godToStem['iw'],maps.godToStem['dw'],maps.godToStem['7k'],maps.godToStem['do'],]

		unfavorable.aspects = ['resource','companion']
		unfavorable.elements = [maps.aspectToElement['resource'],  maps.aspectToElement['companion']]
		unfavorable.gods = ['ir','dr','f','rw']
		unfavorable.stems = [maps.godToStem['ir'],maps.godToStem['dr'], maps.godToStem['f'], maps.godToStem['rw'] ]
	}else{
		favorable.aspects = ['resource','companion']
		favorable.elements = [maps.aspectToElement['resource'],  maps.aspectToElement['companion']]
		favorable.gods = ['ir','dr','f','rw']
		favorable.stems = [maps.godToStem['ir'],maps.godToStem['dr'], maps.godToStem['f'], maps.godToStem['rw'] ]

		unfavorable.aspects = ['output', 'wealth','power']
		unfavorable.elements = [maps.aspectToElement['output'], maps.aspectToElement['wealth'], maps.aspectToElement['power'] ],
		unfavorable.gods = ['eg','ho','iw','dw','7k','do']
		unfavorable.stems = [maps.godToStem['eg'], maps.godToStem['ho'],maps.godToStem['iw'],maps.godToStem['dw'],maps.godToStem['7k'],maps.godToStem['do'],]

	}
	processed.meta.favorable  = favorable
	processed.meta.unfavorable = unfavorable
}

