class  EnterBirthdayGender extends React.Component {
    state={
    }
    constructor(props){
        super(props)
        this.onChange = this.onChange.bind(this)
        this.finish = this.finish.bind(this)
        this.birthday = {
            chartName: 'Me', 
            time: DateTime.local(),
            gender: 'male',
            hourUnknown: false,
        }
    }

    componentDidMount(){
    }
    onChange(data){
        this.birthday = data
        // console.log('changed', data.time.toFormat('yyyy-MMM-dd , h:mma'))
    }
    async finish(){
        this.props.onFinish(this.birthday)
    }
    render(){
        return (
            <SafeAreaView style={styles.container}>
                <View style={styles.header}>
                    <Text style={styles.title}>Enter Birthday</Text>
                    <TouchableHighlight
                        onPress={() => {
                            const bstring = '\n' + toTitle(this.birthday.gender) + '\n\n' + this.birthday.time.toFormat('yyyy-MMMM-dd, h:mma')
                            Alert.alert(
                                'Confirm birthday + gender',
                                bstring,
                                [
                                    { text: 'No'}, 
                                    { text: 'Yes', onPress: () => { 
                                        this.finish()
                                    }}, 
                                ]
                            ) 
                        }}
                        style={styles.buttonTouch}
                    >
                        <Text style={styles.button}>Next</Text>
                    </TouchableHighlight>
                </View>
                <CustomDateSelector
                    initial={this.birthday}
                    onSubmit={this.onChange}
                    showGender={ true } 
                />
                <TouchableHighlight
					underlayColor={scolor.touchableHighlightUnderlayColor}
					style={styles.termsHolder}
					onPress={() => {
						Alert.alert(
							'Read',
							null,
							[
								{ text: 'Terms', onPress: () => {
									Linking.openURL('https://chinesemetaphysics.com/terms')
								}},
								{ text: 'Privacy', onPress: () => {
									Linking.openURL('https://chinesemetaphysics.com/privacy')
								}},
								{ text: 'Cancel', style: 'cancel'},
							]
						)
					}}
				>
					<Text style={styles.termsText}>By continuing, you agree to our Terms of Service and Privacy Policy.</Text>
				</TouchableHighlight>
            </SafeAreaView>
        )
    }
}
EnterBirthdayGender.contextType = AuthContext
export default withApollo(EnterBirthdayGender)

