const winWidth = Dimensions.get('window').width
import { CheckBox } from 'react-native-ui-kitten'

import { DateTime } from 'luxon'

class CustomDateSelector extends React.Component {
    state={
    }
    constructor(props){
        super(props)
        this.updateRaw = this.updateRaw.bind(this)
        this.state.gender = props.initial?.gender
        this.state.hourUnknown = props.initial?.hourUnknown


        this.lux = props.initial.time 
        this.luxOffset = props.initial.time.offset
        // console.log("~~~~~~~~~~~~~~~~~", this.luxOffset)

    }
    updateRaw(data = {}){
        this.lux = this.lux.set(data)
        // console.log('>>', data)
        // console.log(this.lux.toFormat('MMM - d - yyyy / h:mma'))
        this.props.onSubmit({
            time: this.lux ,
            gender: this.state.gender,
            hourUnknown: this.state.hourUnknown
        })
    }
    shouldComponentUpdate(nextProps, nextState){
        return true
    }
    render(){ 
        //1581-1585 bug
        return (
            <ScrollView  style={styles.scrollView}>
                { this.props.showGender && (
                    <SegmentedControlTab
                        allowFontScaling={false}
                        tabStyle={styles.segmentTabStyle}
                        activeTabStyle={{ backgroundColor: Color.GREY[400], color: 'white', }}
                        tabTextStyle={{ color: Color.GREY[600] }}
                        borderRadius={0}
                        tabsContainerStyle={{ marginBottom: 12,}}
                        values={["Male", "Female"]}
                        selectedIndex={this.state.gender === 'male' ? 0 : 1}
                        onTabPress={index =>  { 
                            this.setState({ gender:  index === 0 ? 'male' : 'female' }, () =>  this.updateRaw() )
                        }}
                    />
                )}

                <DatePicker
                    date={this.lux.toJSDate()}
                    timeZoneOffsetInMinutes={this.luxOffset} 
                    width={winWidth}
                    style={styles.datePicker}
                    mode={'date'}
                    onDateChange={x => { //required because offset returned is different from lux offset
                        const xOffset = x.getTimezoneOffset() * -1
                        const newMinutes = x.getMinutes()  - (xOffset - this.luxOffset)
                        x.setMinutes(newMinutes)
                        // console.log('------ DAY - ' , xOffset, x.getMinutes(), newMinutes)

                        const day = x.getDate()
                        const month = x.getMonth() + 1
                        const year = x.getFullYear()
                        if(year < 1584){
                            this.lux =  this.lux.set({ year: 1584, month: 1, day: 1, hour: 0, minute: 0 })
                            return
                        }else{
                            this.updateRaw({ day, month, year })
                        }
                    }}
                />

                { !this.props.hideHourUnknown && (
                <View style={styles.checkboxHolder}>
                    <CheckBox
                        text={'Unknown Hour'}
                        checked={this.state.hourUnknown}
                        onChange={(hourUnknown) => { 
                            this.setState({ hourUnknown }, () => this.updateRaw())
                        }}
                    />
                </View>
                )}

                { !this.state.hourUnknown && (
                    <DatePicker
                        date={this.lux.toJSDate()}
                        timeZoneOffsetInMinutes={this.luxOffset}
                        width={winWidth}
                        style={styles.datePicker}
                        mode={'time'}
                        onDateChange={x => {
                            const xOffset = x.getTimezoneOffset() * -1
                            const newMinutes = x.getMinutes() - (xOffset - this.luxOffset)
                            x.setMinutes(newMinutes)
                            // console.log('------ Hour - ',  xOffset,x.getMinutes(), newMinutes)

                            const hour = x.getHours()
                            const minute = x.getMinutes()
                            this.updateRaw({ hour, minute })
                        }}
                    />
                )}

                { this.props.footer && (
                    <Text style={sstyle.layout.footer}>{ this.props.footer} </Text>
                )}
            </ScrollView>
        )
    }
}
export default CustomDateSelector

