const nullSet = [null, null, null, null, null, null]
const randomSet = () => {
    const results = []
    for(let i = 0; i < 6; i++){ results.push(Math.round(Math.random())) }
    return results;
}

const dataToInfo = (data) => {
    const totalBinary = data.join('')
    const topBinary = String(data[0]) + String(data[1]) + String(data[2])
    const bottomBinary = String(data[3]) + String(data[4]) + String(data[5])
    const topTrigram = objects.find(Ordinals.guas, 'binary', topBinary)
    const bottomTrigram = objects.find(Ordinals.guas, 'binary', bottomBinary)

    const fullHexagram = Hexes.order.find(i => i.binary === totalBinary)


    return { topTrigram, bottomTrigram, fullHexagram }
}

const setToLineData = (set, dm=null) => {
    if(set && set.indexOf(null) >= 0) return
    const data = dataToInfo(set)
    const { topTrigram, bottomTrigram, fullHexagram } = data
    
    const subject = Math.abs(fullHexagram.subjectLine - 6)
    const object = subject < 3 ? subject + 3 : subject - 3
    const element = fullHexagram.element

    const branchOrder = Ordinals.branchOrdering
    const bottomStartBranch = Hexes.hexagramStartBranches[bottomTrigram.pinyin][0]
    const bottomBranchIndex = branchOrder.indexOf(bottomStartBranch)
    const topStartBranch = Hexes.hexagramStartBranches[topTrigram.pinyin][1]
    const topBranchIndex = branchOrder.indexOf(topStartBranch)

    const branches = []
    branches.push(bottomStartBranch)
    if(bottomBranchIndex % 2 === 0){
        for(let i = 1; i < 3; i++){ branches.push(branchOrder[ bottomBranchIndex + (i * 2) ]) }
    }else{
        for(let i = 1; i < 3; i++){ branches.push(branchOrder[ bottomBranchIndex - (i * 2) ]) }
    }
    branches.push(topStartBranch)
    if(topBranchIndex % 2 === 0){
        for(let i = 1; i < 3; i++){ branches.push(branchOrder[ topBranchIndex + (i * 2) ]) }
    }else{
        for(let i = 1; i < 3; i++){ branches.push(branchOrder[ topBranchIndex - (i * 2) ]) }
    }
    branches.reverse()

    const elements = branches.map(i => Ordinals.stems[  Ordinals.branches[i]._hiddenStemsArr[1] ].element )
    const aspects = elements.map(el => Ordinals.elements[element].elements[el] )

    const animals = []
    if(dm){
        const order = Tools.toProxy(Hexes.animalOrder)
        const startAnimal = Hexes.stemAnimalMap[dm]
        const startIndex = order.indexOf(startAnimal)
        for(let i  = 0 ; i < 6; i++){
            animals.push(order[startIndex + i])
        }
    }
    animals.reverse()
    return {
        branches: branches,
        elements,
        aspects,
        subject,
        object,
        animals,
        element,
    }
}



class HexagramSelector extends React.Component {
    static navigationOptions = ({ navigation }) => {
        const { params={} } = navigation.state 
        const iconWidth = 42
		return {
            headerTitle:(
                <View style={{flex: 1}}>
                    <SegmentedControlTab
                        allowFontScaling={false}
                        tabStyle={sstyle.navigation.headerSegmentTabs.segmentTabStyle}
                        activeTabStyle={sstyle.navigation.headerSegmentTabs.segmentTabActive}
                        tabTextStyle={sstyle.navigation.headerSegmentTabs.segmentTabText}
                        borderRadius={2}
                        tabsContainerStyle={{ width:132, alignSelf: 'center' }}
                        values={['Single', 'Triple']}
                        selectedIndex={ params.selectedTabIndex }
                        onTabPress={index =>  { 
                            params.setTabIndex(index)
                        }}
                    />
                </View>
            ),
            headerRight: (
                <View style={sstyle.navigation.navHeaderRight} >
                    <TouchableOpacityEx 
                        style={[sstyle.navigation.navHeaderItem, {minWidth: iconWidth }] }
                        onPress={ () => {
                            params.toggleLiSheeYeeMethod()
                        }}
                    >
                        <MaterialCommunityIcon
                            name={params.inputForm === 'liSheeYee' ? "pound-box" : 'pound'}
                            size={26}
                            color={scolor.iconBlurred}
                        />
                    </TouchableOpacityEx>

                    {/* <TouchableOpacityEx 
                        style={[sstyle.navigation.navHeaderItem, {minWidth: iconWidth }] }
                        onPress={ () => { params.erase() }}
                    >
                        <MaterialCommunityIcon
                            name="eraser"
                            size={24}
                            color={scolor.iconBlurred}
                        />
                    </TouchableOpacityEx> */}
                    <TouchableOpacityEx 
                        style={[sstyle.navigation.navHeaderItem, {minWidth: iconWidth }] }
                        onPress={ () => { 
                            navigation.push('EditSettings', {defaultTabIndexPreferences: 5 }) 
                        } }
                    >
                        <MaterialCommunityIcon
                            name="settings"
                            size={24}
                            color={scolor.iconBlurred}
                        />
                    </TouchableOpacityEx>
				</View>
			),
        }
    }
    state={
        inputForm: null,
    }
    constructor(props){
        super(props)
        this.onHexagramChange = this.onHexagramChange.bind(this)
        this.onMarkLineChange = this.onMarkLineChange.bind(this)
        this.calculate = this.calculate.bind(this)
        this.onInfoSelected = this.onInfoSelected.bind(this)
        this.throw = this.throw.bind(this)
        this.erase = this.erase.bind(this)
        this.setTabIndex = this.setTabIndex.bind(this)
        this.onDateChanged = this.onDateChanged.bind(this)
        this.toggleLiSheeYeeMethod = this.toggleLiSheeYeeMethod.bind(this)
        this.finishInputMethod = this.finishInputMethod.bind(this)

        this.state.snapshot = {
            time: DateTime.local(),
            hourUnknown: false,
            gender: 'male'
        }
        this.state.bazi = FourPillars.plot({ time: this.state.snapshot.time })
        this.state.marks = nullSet
        this.state.original = nullSet
        this.state.selected = 0
        this.state.selectedTabIndex = 0
        

        this.props.navigation.setParams({ inputForm: null, toggleLiSheeYeeMethod: this.toggleLiSheeYeeMethod, throw: this.throw , erase : this.erase, selectedTabIndex: 0, setTabIndex: this.setTabIndex })
        analytics.track('Hexagram')
    }
    toggleLiSheeYeeMethod(){
        if(this.state.inputForm){
            this.setState({ inputForm: null})
            this.props.navigation.setParams({ inputForm: null })
        }else{
            this.setState({ inputForm: 'liSheeYee'})
            this.props.navigation.setParams({ inputForm: 'liSheeYee'})
        }
    }
    finishInputMethod(data, movingLine){
        const marked = []
        for(let i = 0; i < 6; i++){
            if(i === movingLine-1){
                marked.push(1)
            }else{
                marked.push(0)
            }
        }
        this.setState({ inputForm: null, marks: marked.reverse(), selectedTabIndex: 1})
        this.props.navigation.setParams({ inputForm: null, selectedTabIndex:1 })
        this.onHexagramChange(data)
    }
    setTabIndex(selectedTabIndex){
        this.setState({ selectedTabIndex })
        this.props.navigation.setParams({ selectedTabIndex })
    }
    async componentDidMount(){
        this.prefs = await getPreferences()
        this.settings = this.prefs.yijing.calculations

        const initialBinary = this.props.navigation.getParam('initialBinary') || null
        if(initialBinary){
            const original = initialBinary.split('').map(i => parseInt(i))
            this.setState({ original } , () => { this.calculate() })
        }else if(this.settings.initialSet === 'random'){
            this.throw()
        }
    }
    async erase(){
        const blank = nullSet
        this.setState({ changed: blank, mutual:blank, original:blank, marks: blank, })
    }
    async throw(){
        const marked = [0, 0, 0, 0, 0, 0]
        let set = 0
        while(set < this.settings.markedLines){
            const index = strings.randomInt(0, 5)
            if(marked[index] === 0){
                marked[index] = 1
                set += 1
            }
        }
        const original = randomSet()
        this.setState({
            marks: marked,
            original
        }, () => {
            this.calculate() 
        })
    }
    onMarkLineChange(data){  //Marker
        this.setState({ marks: data }, () => { this.calculate() })
    }
    onHexagramChange(data){ //Lines
        this.setState({ original: data }, () => { this.calculate() })
    }
    onInfoSelected(data){ //Buttons
        this.setState({ selected: data})
    }
    onDateChanged(data){
        const bazi = FourPillars.plot({ time: data.time })
        this.setState({ snapshot: data , bazi})
    }
    calculate(){
        const originalFilled = this.state.original.indexOf(null) < 0
        if(!originalFilled){
            this.setState({ changed: nullSet, mutual: nullSet })
            return
        }
        //Calculage Mutual
        const mutual = [
            this.state.original[1],
            this.state.original[2],
            this.state.original[3],
            this.state.original[2],
            this.state.original[3],
            this.state.original[4],
        ]
        //Calculate Changed
        const changed = this.state.original.map((e, i) => {
            if(this.state.marks[i] === 1){ 
                if(this.state.original[i] === null) return null
                else if(this.state.original[i] === 0) return 1
                else return 0
            }
            return e
        })
        this.setState({ changed , mutual })
    }
    render(){
        if(this.state.inputForm === 'liSheeYee'){
            return <LiSheeYeeSelector finishInputMethod={this.finishInputMethod}/>
        }
        return (
            <Subscribe to={[PreferencesContainer]}>
            {(prefs) => {
                const settings = prefs.state.yijing.calculations

                const hasChanged = this.state.changed && this.state.changed.indexOf(null) < 1;
                const hasMutual = this.state.mutual && this.state.mutual.indexOf(null) < 1;
                const showMutual = settings.showMutual && hasMutual
                const showChanged = settings.showChanged && hasChanged

                const chartName = this.state.snapshot.time.toLocaleString(DateTime.DATE_FULL) + ', ' + this.state.snapshot.time.toFormat('H:mm') + '  —  Paused'
                const sti = this.state.selectedTabIndex

                const infoSet = sti === 0 ? this.state.original : [this.state.original, this.state.mutual, this.state.changed][this.state.selected]
                return (
                    <View style={styles.container}>

                        { sti === 1 ? (
                            <View style={styles.titles}>
                                <Text style={styles.titleText}>Input</Text>
                                <Text style={styles.titleText}>–––</Text>
                                <Text style={styles.titleText}>{ settings.showChanged ? 'Output' : '' }</Text>
                            </View>
                        ): (
                            <SectionHeader
                                title={chartName}
                                leftItem={(
                                    <TouchableOpacityEx
                                        style={sstyle.sectionHeader.sectionHeaderTouchLeft}
                                        onPress={() => {
                                            this.props.navigation.push('DateSelector', { 
                                                initial:  this.state.snapshot,
                                                showGender: false,
                                                onSubmit: this.onDateChanged
                                            })
                                        }}
                                    >
                                        <MaterialCommunityIcon
                                            name={'chevron-right'}
                                            color={'white'}
                                            size={22}
                                        />
                                    </TouchableOpacityEx>
                                )}
                            />
                        )}

                        <View style={styles.head}>

                      
                            { (sti === 0 ) ? (
                                <SingularDetails
                                    data={this.state.original}
                                    settings={settings}
                                    bazi={this.state.bazi}
                                />
                            ) : (
                                <ChangingLineArea
                                    data={this.state.marks}
                                    onChange={this.onMarkLineChange}
                                />
                            )}

                            <HexagramArea 
                                data={this.state.original}
                                onChange={this.onHexagramChange}
                                enableChange={true}
                                settings={settings}
                                isSingleView={this.state.selectedTabIndex === 0}
                            />
                
                            { sti === 0 && (
                                <AspectDetails
                                    data={this.state.original}
                                    settings={settings}
                                    snapshot={this.state.snapshot}
                                />
                            )}

                            { (showMutual && sti === 1) ? (
                                <HexagramArea 
                                    data={this.state.mutual}
                                    underlayColor={'transparent'} 
                                    settings={settings}
                                />
                            ) : (
                                <View style={{ flex: sti === 0 ? 0 : 1}}/>
                            )}

                            { (showChanged && sti === 1) ?  (
                                <HexagramArea 
                                    data={this.state.changed}
                                    underlayColor={'white'} 
                                    settings={settings}
                                />
                            ) : (
                                <View style={{ flex: sti === 0 ? 0 : 1}}/>
                            )}
                        </View>

                        { sti === 1 && (
                            <ButtonBar
                                settings={settings}
                                buttons = {[0,1,2]}
                                selected={this.state.selected}
                                onInfoSelected={this.onInfoSelected}
                            />
                        )}
                        <InfoView
                            data={ infoSet }
                            selectedTabIndex = { this.state.selectedTabIndex}
                            navigation={this.props.navigation}
                            bazi={this.state.bazi}
                        />
                    </View>
                )
            }}
            </Subscribe>
        )
    }
}
export default HexagramSelector;

