const HexagramArea = (props) => {
    if(!props.data) return <Fragment/>
    const info = dataToInfo(props.data)
    const lineData = setToLineData(props.data)

    let topColor = 'white';
    let bottomColor = 'white';
    if(props.settings.showColors && !props.isSingleView){
        if(info.topTrigram){
            topColor = Graphics.colors.elements.light[info.topTrigram.element]
        }
        if(info.bottomTrigram){
            bottomColor = Graphics.colors.elements.light[info.bottomTrigram.element]
        }
    }

    const TheLine = ({ element , index}) => {
        const letter = {
            color: 'white',
            fontWeight: 'bold',
            paddingLeft:6,
        }
        const line = {
            backgroundColor: Color.GREY[900],
            flex:1,
            justifyContent: 'center',
        }
        if(element === null){
            return ( <Fragment/>)
        }else if(element === 0){
            return (
                <View style={{ flexDirection:'row' , flex: 1}}>
                    <View style={line}>
                        { props.isSingleView && lineData && lineData.subject === index && ( <Text style={letter}>S</Text>)}
                        { props.isSingleView &&  lineData && lineData.object === index && ( <Text style={letter}>O</Text>)}
                    </View>
                    <View style={{ flex: 0.65 }}></View>
                    <View style={line}/>
                </View>
            )
        }else if(element === 1 ){
            return ( 
                <View style={line}>
                    { props.isSingleView &&  lineData && lineData.subject === index && ( <Text style={letter}>S</Text>)}
                    { props.isSingleView &&  lineData && lineData.object === index && ( <Text style={letter}>O</Text>)}
                </View> 
            )
        }
    }

    return (
        <View style={styles.box}>
            { props.data.map( (element, index) => {
                return (
                    <Toucher 
                        style={[styles.row, {
                            backgroundColor: index < 3 ? topColor : bottomColor
                        }]}
                        underlayColor={ props.enableChange ? 'white' : ( index < 3 ? topColor : bottomColor )}
                        activeOpacity={ props.enableChange ? 0.85 : 1}
                        onPress={() => {
                            analytics.track('Hexagram.line')
                            if(!props.enableChange){
                                return Alert.alert('Only Input can be modified.')
                            }
                            const newData = _.cloneDeep(props.data)
                            switch(props.data[index]){
                                case 0: 
                                    newData[index] = 1
                                    break;
                                case 1:
                                    newData[index] = 0
                                    break;
                                default: //null
                                    newData[index] = 0
                                    break;
                            }
                            props.onChange(newData)
                        }}
                    >
                        <TheLine element={element} index={index}/>
                    </Toucher>
                )
            })}
        </View> 
    )
}




const ButtonBar = (props) => {
    const visibles = [true, props.settings.showMutual, props.settings.showChanged] 
    return (
        <View style={styles.buttonBar}>
            { props.buttons.map( (e, i) => (
                <Toucher
                    style={[
                        { flex: 1, },
                        props.selected === i && { 
                            backgroundColor: Color.BLUEGREY[600]
                        }
                    ]}
                    onPress={() => {
                        if(!visibles[i]) return
                        props.onInfoSelected(i)
                    }}
                >
                    <View style={{
                        justifyContent: 'center',
                        alignItems: 'center',
                        flex:1,
                    }}>
                        { i === props.selected ? (
                            <MaterialCommunityIcon
                                name={'chevron-down'}
                                size={30}
                                color={'white'}
                            />
                        ):(
                            <Fragment/>
                        )}
                    </View> 
                </Toucher> 
            ))}
        </View>
    )
}

