import { DateTime } from 'luxon'
import analytics from '@segment/analytics-react-native'

const HeadDateBar = (props) => {
    if(!props.time) return <View style={styles.container}/>
    return (
        <View style={styles.container} >
            <View style={styles.inner}>
                <TouchableOpacityEx
                    style={styles.sectionHeaderTouchLeft}
                    onPress={() => {
                        const initial = {
                            time: props.time,
                            gender: 'male',
                            hourUnknown: props.hourUnknown,
                        }
                        analytics.track('QiMen-DateSelector')
                        props.navigation.push('DateSelector', { 
                            initial,
                            showGender: false,
                            onSubmit: props.onCustomDateSelected
                        })
                    }}
                >
                    <MaterialCommunityIcon
                        name={'chevron-right'}
                        color={'white'}
                        size={22}
                    />
                </TouchableOpacityEx>

                <View style={styles.separator}/>

                <Toucher 
                    style={{ flex: 1}}
                    onPress={props.onDateBarPress}
                >
                    <View style={styles.main}>
                        { props.timerOn && (
                              <Text style={{ color: Color.RED[500], marginLeft: 15, marginRight: 9 }}>●</Text>
                        )}
                        <Text style={[styles.time1, 
                            !props.timerOn  && { marginLeft: 15 }
                        ]}>
                            {/* { props.time.toLocaleString(DateTime.DATE_FULL) } */}
                            { props.time.toFormat('MMM d, yyyy')}

                            { !props.timerOn && '  —  Paused'}
                        </Text> 
                        <View style={{ flex: 1 }}/>
                        <Text style={styles.time2}>
                            {props.time.toFormat('H:mm') }
                        </Text> 
                    </View>
                </Toucher>

                <View style={styles.separator}/>

                <Toucher
                    style={styles.ticker}
                    onPress={() => {
                        if(props.timerOn){
                            props.onDateBarPress()
                        }else{
                            props.onDateBarPress()
                            props.reload()
                        }
                    }}
                >
                    {props.timerOn ? (
                        <View style={{ flexDirection: 'row'}}>
                        <Text style={styles.tickerText}>
                            { props.time.toFormat('ss')}
                        </Text>
                      
                        </View>
                    ) : (
                        <MaterialCommunityIcon
                            name={'reload'}
                            color={'white'}
                            size={22}
                        />
                    )}
                </Toucher>
            </View>
        </View>
    )
}

export default withNavigation(HeadDateBar)


