const process = (inter, stores, props, additional=undefined) => {
    const { pillarContainer, pillar , root} = props
    const currentSectionSID = props.payload.section.sid;

    const cycles = Ordinals.cycles
    const line = []
    let newElementColor = null
    if(inter.relationElementResult){
        newElementColor = Ordinals.elements[inter.relationElementResult]._colors.light
    }
    line.push({
        words: [toTitle(inter.relation)]
    })


    inter.affects.forEach(affect => {
        const affectedPillar = EightWords.pillars[affect.pillar]
        line.push({
            words: [
                // toTitle(affect.pillar),
                ...Dict.EightWords.pillars[affect.pillar].$dict_syn.map(i => toTitle(i)),
            ]
        })
        const affectedBranch = Ordinals.branches[affect.branch]
        const affectedStem = Ordinals.stems[affectedBranch._hiddenStemsDict.main]
        const affectedElement = Ordinals.elements[affectedStem.element]
        const affectedGod = EightWords.gods[affect.gods[1]]
        const affectedAspect = EightWords.aspects[affectedGod.aspect]
        line.push({ 
            words: [
                `${toTitle(affectedAspect.name)}`,
                ...affectedAspect.$dict_noun.map(i => toTitle(i)),
                ...affectedAspect.$dict_noun2.map(i => toTitle(i)),
                // `${toTitle(affectedGod.name)}`,
                // `${toTitle(affectedBranch.animalName)}`,
                // `${toTitle(affectedStem.natureName)}`,
            ],
            // borderColor: affectedElement._colors.light
        })
    })


   
    // line.push({ words: Dict.EightWords.pillars['$dict_syn'].map(i => toTitle(i)), shuffle: false} )

    if(inter.relationElementResult){
        const newElement = inter.relationElementResult
        const newAspect = EightWords.aspects[root.meta.maps.elementToAspect[newElement]]
        const newStem = root.pillars.month.branch.polarity === 'yin' ? Ordinals.elements[newElement].stems[1] : Ordinals.elements[newElement].stems[0]
        line.push({ 
            words: [' ⇢ ', 'producing', 'forming'], 
            shuffle:false, 
        
        })
        line.push({ 
            words: [
                `${toTitle(newAspect.name)}`,
                ...newAspect.$dict_noun.map(i => toTitle(i)),
                ...newAspect.$dict_noun2.map(i => toTitle(i)),
            ],
            // borderColor: newElementColor,
           
        })
    }


    const iconMap = {
        'direction': ['square', Graphics.colors.elements.dark[inter.relationElementResult ], 16],
        'harmony': ['triangle', Graphics.colors.elements.dark[inter.relationElementResult ], 16],
        '⅔ harmony': ['triangle-outline', Graphics.colors.elements.dark[inter.relationElementResult ], 16],
        '6 combo': ['circle', Graphics.colors.elements.dark[inter.relationElementResult ], 16],
        'hidden combo': ['circle-outline', Graphics.colors.elements.dark[inter.relationElementResult ], 0],
        'clash': ['mixer', Color.GREY[800], 16],
        'harm': ['format-text-wrapping-clip', Color.GREY[800], 16],
        'destruction': ['decagram', Color.GREY[800], 16],
        'self penalty': ['alpha-p-box', Color.GREY[800], 22],
        'uncivilized penalty': ['alpha-p-box', Color.GREY[800], 22],
        'ungrateful penalty': ['hazard-lights', Color.GREY[800], 16],
        'bullying penalty': ['hazard-lights', Color.GREY[800], 16]
    }


    return (
        <View style={[istyle.row,
            additional && { marginTop: 6}
        ]}> 
            <MadLibs
                line={line}
                containerStyle = {istyle.madlibs.containerStyle}
                boxViewStyle={istyle.madlibs.boxViewStyle}
                boxSelectStyle={istyle.madlibs.boxSelectStyle}
                boxTextStyle={istyle.madlibs.boxTextStyle}
                iconStyle={istyle.madlibs.iconStyle} 
            />
            <Toucher
                style={istyle.actionTouch}
                onPress={() => {
                    const items = []
                    inter.affects.forEach(affect => {
                        if(affect.pillar === 'luck'){
                            items.push({ section: 'Comparison', index: 4, palace: 'branch'})
                        }else{
                            items.push({ section: 'Birth', index: pillarContainer.birthPillarNameMap[affect.pillar], palace: 'branch'})
                        }
                    })
                    items.push({
                        section: currentSectionSID, index: props.selectedIndex, palace: 'branch',
                    })
                    pillarContainer.updateFlash(items)
                    analytics.track('Bazi.Pillar.Interactions.Branch.Flash')
                    setTimeout(() => { pillarContainer.resetFlash() }, 2000)
                }}
            >
                   <MaterialCommunityIcon
                        name={iconMap[inter.relation][0]}
                        color={iconMap[inter.relation][1]}
                        size={iconMap[inter.relation][2]}
                    />
            </Toucher>
        </View>
    )
}
const LaymanInteractionBranches = (props) => {
    const { pillar } = props
    const interactions = _.cloneDeep(pillar.branch.interactions)
    if(!interactions || interactions.length === 0) return <Fragment/>
    const [state, setState] = useState({ showAll: false })
    const [stores, setStores] = useState(null)
    const firstInter = interactions.splice(0, 1)
    return (
        <View style={istyle.container}>
            { firstInter.map(inter => process(inter, stores, props))}
            { (!state.showAll && interactions.length > 0) && (
                <Toucher
                    style={istyle.showAllTouch}
                    onPress={() => { setState({ showAll: !state.showAll}) }}
                >
                    <MaterialCommunityIcon
                        name={'chevron-down-box'}
                        size={22}
                        color={Color.GREY[300]}
                    />
                </Toucher>
            )}
            { (state.showAll && interactions.length > 0) && (
                <View>
                    { interactions.map(inter => process(inter, stores,  props, true))}
                </View>
            )}
        </View>
    )
}

const borderRadius = 4



export default withNavigation(LaymanInteractionBranches)

















