const calculateCycles = (t, pillar) => {
    let time = t
    if(pillar.name === 'hour' && time.hour % 2 === 0) time = t.minus({ hour: 1})
    if(pillar.name === 'luck') return null 
    const branch = pillar.branch
    const result = { major:[], minor:[], branch , marked: 0}
    const mapVal = { year: [4, 1], month: [4, 1], day: [4, 1], hour: [8, 2], }
    if(branch.group === 'start'){
        result.major.push(FourPillars.plot({ time }))
        result.major.push(FourPillars.plot({ time: time.plus({ [pillar.name]: mapVal[pillar.name][0] }) }))
        result.major.push(FourPillars.plot({ time: time.plus({ [pillar.name]: mapVal[pillar.name][0] * 2 }) }))

        result.minor.push(FourPillars.plot({ time }))
        result.minor.push(FourPillars.plot({ time: time.plus({ [pillar.name]:  mapVal[pillar.name][1] }) }))
        result.minor.push(FourPillars.plot({ time: time.plus({ [pillar.name]:  mapVal[pillar.name][1]*2 }) }))
        result.marked = 0
    }else if(branch.group === 'peak'){
        result.major.push(FourPillars.plot({ time: time.minus({ [pillar.name]: mapVal[pillar.name][0] }) }))
        result.major.push(FourPillars.plot({ time }))
        result.major.push(FourPillars.plot({ time: time.plus({ [pillar.name]:  mapVal[pillar.name][0] }) }))

        result.minor.push(FourPillars.plot({ time: time.minus({ [pillar.name]:  mapVal[pillar.name][1] }) }))
        result.minor.push(FourPillars.plot({ time }))
        result.minor.push(FourPillars.plot({ time: time.plus({ [pillar.name]:  mapVal[pillar.name][1] }) }))
        result.marked = 1
    }else if(branch.group === 'end'){
        result.major.push(FourPillars.plot({ time: time.minus({ [pillar.name]: mapVal[pillar.name][0] * 2 }) }))
        result.major.push(FourPillars.plot({ time: time.minus({ [pillar.name]: mapVal[pillar.name][0] }) }))
        result.major.push(FourPillars.plot({ time }))

        result.minor.push(FourPillars.plot({ time: time.minus({ [pillar.name]:  mapVal[pillar.name][1] * 2 }) }))
        result.minor.push(FourPillars.plot({ time: time.minus({ [pillar.name]:  mapVal[pillar.name][1]  }) }))
        result.minor.push(FourPillars.plot({ time }))
        result.marked = 2
    }
    return result;
}
const formatTime = (t, pillarName) => {
    if(pillarName === 'year'){
        return t.toFormat('yyyy')
    }else if(pillarName === 'month'){
        return t.toFormat('MMMM')
    }else if(pillarName === 'day'){
        return t.toFormat('MMMM d')
    }else if(pillarName === 'hour'){
        return t.toFormat('ha').toLowerCase()
    }
}

const BigSmallCycle = (props) => {
    const [cycleIndex, setCycleIndex] = useState(0)
    const selected = () => cycleIndex === 0 ? 'major' : 'minor'

    const { time, pillar, root} = props
    if(pillar.name === 'luck') return <Fragment/>
    const data = calculateCycles(time, pillar) 
    const color = Color.GREY[200]
    const markedColor = pillar.branch.stems.main.elm._colors.dark
    const pathWidth = winWidth / 3 * 2
    const middleSeason = Ordinals.seasons[data[selected()][1].pillars[pillar.name].branch.season]
    const middleBranch = data[selected()][1].pillars[pillar.name].branch
    const aspectMap = root.meta.maps.elementToAspect

    const line = []
    const markedMap2 = [
        ['birth','growth','movement'],
        ['exuberant', 'cardinal', 'climax'],
        ['transition', 'graveyard', 'conclusion']
    ]
    line.push({ words: ['As a']})
    line.push({ words: markedMap2[data.marked] , shuffle: true})
    line.push({ words: ['branch,']})
    const thisBranch  = data[selected()][data.marked].pillars[pillar.name].branch
    line.push({ words: [ 
        formatTime(time, pillar.name), 
        `branches-${thisBranch.name}|${toTitle(thisBranch.animalName)} ${toTitle(pillar.name)}`
    ] })
    line.push({ words: ['is the']})
    const markedMap = [ 'start', 'peak', 'end' ]
    line.push({ words: [markedMap[data.marked] ] })
    line.push({ words: ['of']})
    line.push({ words: ['a', 'my'], shuffle: true})
    line.push({ words: [toTitle(selected())] })
    const aspect = aspectMap[middleSeason.element]
    line.push({
        words: [
            `phases-${middleSeason.element}|${toTitle(middleSeason.noun)}`,
            `stems-${middleBranch.stems.main.name}|${toTitle(middleSeason.element)}`,
            `aspects-${aspect}|${toTitle(aspect)}`,
        ],
        shuffle: true,
        borderColor: Graphics.colors.elements.light[middleSeason.element],
    })
    line.push({ words: [
        `Event`,    
    ]})
    line.push({ words: ['which']})

    const branch0 = data[selected()][0].pillars[pillar.name].branch
    const branch1= data[selected()][1].pillars[pillar.name].branch
    const branch2 = data[selected()][2].pillars[pillar.name].branch

    if(data.marked === 0){
        line.push({ words: ['peaks at'] })
        line.push({ words: [ 
            formatTime(data[selected()][1].info.time, pillar.name), 
            `branches-${branch1.name}|${toTitle(branch1.animalName)} ${toTitle(pillar.name)}`,
        ] }) 
        line.push({ words: ['and ends at'] })
        line.push({ words: [ 
            formatTime(data[selected()][2].info.time, pillar.name) + '.' ,
            `branches-${branch2.name}|${toTitle(branch2.animalName)} ${toTitle(pillar.name)}.`,
        ] }) 
    }else if(data.marked === 1){
        line.push({ words: ['began at'] })
        line.push({ words: [ 
            formatTime(data[selected()][0].info.time, pillar.name), 
            `branches-${branch0.name}|${toTitle(branch0.animalName)} ${toTitle(pillar.name)}`,
        ] }) 
        line.push({ words: ['and ends at'] })
        line.push({ words: [ 
            formatTime(data[selected()][2].info.time, pillar.name) + '.' ,
            `branches-${branch2.name}|${toTitle(branch2.animalName)} ${toTitle(pillar.name)}.`,
        ] }) 
    }else if(data.marked === 2){
        line.push({ words: ['began at'] })
        line.push({ words: [ 
            formatTime(data[selected()][0].info.time, pillar.name), 
            `branches-${branch0.name}|${toTitle(branch0.animalName)} ${toTitle(pillar.name)}`,
        ] }) 
        line.push({ words: ['and peaked at'] })
        line.push({ words: [ 
            formatTime(data[selected()][1].info.time, pillar.name) + '.' ,
            `branches-${branch1.name}|${toTitle(branch1.animalName)} ${toTitle(pillar.name)}.`,
        ] }) 
    }






    
    if(!data) return <Fragment/>
    return (
        <View>
            <View style={sstyle.sectionHeader.tabs.tabBarHolder}>
                <SegmentedControlTab
                    allowFontScaling={false}
                    tabStyle={sstyle.tabs.light.tabStyle}
                    activeTabStyle={sstyle.tabs.light.tabActive}
                    tabTextStyle={[sstyle.tabs.light.tabText, { fontSize: 15,}]}
                    activeTabTextStyle={[sstyle.tabs.light.tabTextActive,]}
                    tabsContainerStyle={[sstyle.tabs.light.tabContainer, { height: 44 }]}
                    borderRadius={0}
                    // tabStyle={sstyle.sectionHeader.tabs.segmentTabStyle}
                    // activeTabStyle={sstyle.sectionHeader.tabs.segmentTabActive}
                    // tabTextStyle={sstyle.sectionHeader.tabs.segmentTabText}
                    // activeTabTextStyle={sstyle.sectionHeader.tabs.activeTabTextStyle}
                    // borderRadius={2}
                    // tabsContainerStyle={{width: winWidth-12, alignSelf: 'center' }}
                    values={['Major', 'Minor']}
                    selectedIndex={cycleIndex }
                    onTabPress={async selectedTabIndex =>  { 
                        setCycleIndex(selectedTabIndex)
                    }}
                />
            </View>

            <View style={styles.wrap}>
                <View style={[{
                    height: 4,
                    width: pathWidth,
                    position:'absolute',
                    backgroundColor: Color.GREY[200],
                    left: winWidth / 3 / 2,
                    top: padd + dotSize/2 - 2,
                    
                }]}/>
                <View style={styles.box}>
                    <View style={[styles.dot, 
                        { backgroundColor: data.marked === 0 ? markedColor : color }, 
                        data.marked === 0 && styles.shadowDot
                    ]}/>
                    <Text style={[styles.cycleLabel,
                        data.marked === 0 && styles.cycleLabelSelected
                    ]}>{ formatTime(data[selected()][0].info.time, pillar.name)  }</Text>
                    <Image 
                        source={CMImages.color.branches[data[selected()][0].pillars[pillar.name].branch.name]}
                        style={styles.miniIcon}
                        resizeMode={'contain'}
                    />
                </View>
                <View style={styles.box}>
                    <View style={[styles.dot, 
                        { backgroundColor: data.marked === 1 ? markedColor : color }, 
                        data.marked ===  1  && styles.shadowDot
                    ]}/>
                    <Text style={[styles.cycleLabel,
                        data.marked === 1 && styles.cycleLabelSelected
                    ]}>{ formatTime(data[selected()][1].info.time, pillar.name)  }</Text>
                    <Image 
                        source={CMImages.color.branches[data[selected()][1].pillars[pillar.name].branch.name]}
                        style={styles.miniIcon}
                        resizeMode={'contain'}
                    />
                </View>
                <View style={styles.box}>
                    <View style={[styles.dot, 
                        { backgroundColor: data.marked === 2 ? markedColor : color }, 
                        data.marked ===  2  && styles.shadowDot
                    ]}/>
                    <Text style={[styles.cycleLabel,
                        data.marked === 2 && styles.cycleLabelSelected
                    ]}>{ formatTime(data[selected()][2].info.time, pillar.name) }</Text>
                    <Image 
                        source={CMImages.color.branches[data[selected()][2].pillars[pillar.name].branch.name]}
                        style={styles.miniIcon}
                        resizeMode={'contain'}
                    />
                </View>
            </View>
            
            <View style={{ height: 1, backgroundColor: scolor.separator}}/>
            <MadLibs
                line={line}
                containerStyle={{
                    padding: 18,
                    paddingTop:9,
                }}
            />
        </View>
    )

}

