function stdNormalDistribution (x, numIntervals) {
    const a = 1
    const b = numIntervals / 2  //never change this.
    const c = numIntervals / 4 //shape
    return  a/Math.pow(Math.E, (Math.pow(x-b, 2))/(2*c*c));
}

const MajorCycle = (props) => {
    if(props.pillar.name === 'luck') return <Fragment/>
    const bazi = props.payload.item[props.selectedIndex].bazi || FourPillars.plot({ time: props.time })
    const elementToAspect = props.root.meta.maps.elementToAspect
    const { cycles, frame, terms }= SolarCal.getMajorCycle(bazi, props.pillar.name)

    const beginTime =  frame.begin.time
    const endTime = frame.end.time
    const frameMinutes = endTime.diff(beginTime, 'minutes').minutes
    const intervals = 24
    const intervalValue = frameMinutes / intervals

    const [graph, setGraph] = useState(null)

    const [selectedTabIndex, setSelectedTabIndex ] = useState(1)
    const labelLine = Object.keys(cycles).map((season, indx) => {
        const seasonElement = Ordinals.elements[Ordinals.seasons[season].element]
        const seasonAspect = EightWords.aspects[elementToAspect[Ordinals.seasons[season].element]]
        return {
            words: [
                toTitle(seasonAspect.name),
                ...seasonAspect.$dict_noun.map(i => toTitle(i)),
                ...seasonAspect.$dict_noun2.map(i => toTitle(i)),
                ...seasonAspect.$dict_noun3.map(i => toTitle(i)),
                toTitle(seasonElement.name),
                toTitle(season)
            ],
            boxViewStyle:{
                flex: 1,
                paddingVertical:padd/2,
                borderRightWidth: indx === 2 ? 0 : 1,
                borderRightColor: scolor.separator,
            },
            boxTextStyle:{
                fontSize: 13,
                fontWeight: '600',
                color: indx === selectedTabIndex ? seasonElement._colors.dark : Color.GREY[300]
            },
            shuffle: false,
        }
    })



    const process = () => {
        const name = Object.keys(cycles)[selectedTabIndex]
        const element = Ordinals.elements[Ordinals.seasons[name].element]
        const labels = []
        const yData = []
        const cycleTotalTime = cycles[name].end.time.diff(cycles[name].begin.time, 'minutes').minutes
        const hidePointsAtIndex = []
        let dataPointIndex = null
        for(let i = 0; i <= intervals; i++){
            const thisPoint = beginTime.plus({ minutes: intervalValue * i })

            //X-Axis
            let label = ''
            if(props.pillar.name === 'month'){
                label = (i % (intervals/4)  === 0) ? thisPoint.toFormat('MMM d') : ''
            }else if(props.pillar.name === 'year'){
                label = (i % (intervals/6)  === 0) ? thisPoint.toFormat('yyyy') : ''
            }else if(props.pillar.name === 'day'){
                label = (i % (intervals/6)  === 0) ? thisPoint.toFormat('ccc') : ''
            }else if(props.pillar.name === 'hour'){
                label = (i % (intervals/6)  === 0) ? thisPoint.toFormat('ha').toLowerCase() : ''
            }
            labels.push(label)

            //Y-Axis
            const minutesSinceCycleBegin = thisPoint.diff(cycles[name].begin.time, 'minutes').minutes
            const val = stdNormalDistribution(minutesSinceCycleBegin, cycleTotalTime)
            yData.push(val)

            if(Math.abs(thisPoint.diff(props.time, 'minutes').minutes) >= intervalValue/2){
                // hidePointsAtIndex.push(i) //this will hide labels also.
            }else{
                dataPointIndex = i 
            }
        }
        setGraph({
            data: { labels, datasets: [ { data: yData }]},
            hidePointsAtIndex,
            dataPointIndex,
            element
        })

    }

    useEffect(() => {
        process()
    }, [selectedTabIndex, props])

 

    if(!graph) return <Fragment/>
    return (
        <View style={styles.container}>
        
            <View style={{
                paddingRight:55,
            }}>
                <LineChart
                    data={graph.data}
                    withOuterLines={false}
                    withInnerLines={false}
                    withVerticalLabels={true}
                    withHorizontalLabels={false}
                    width={winWidth}
                    height={180}
                    chartConfig={{
                        backgroundColor: "white",
                        backgroundGradientFrom: "#ffffff",
                        backgroundGradientTo: "#ffffff",
                        decimalPlaces: 1, // optional, defaults to 2dp
                        color: (opacity = 1) => Color.GREY[300],
                        labelColor: (opacity = 1) => Color.GREY[600],
                        style: {
                        },
                        propsForDots: {
                            r: "9",
                        }
                    }}
                    getDotColor={(dataPoint, dataPointIndex) => {
                        if(dataPointIndex === graph.dataPointIndex)
                            return graph.element._colors.dark
                        else
                            return 'transparent'
                    }}
                    withDots={true}
                    // hidePointsAtIndex={graph.hidePointsAtIndex}
                /> 
            </View>
            <MadLibs
                line={labelLine}
                containerStyle={{
                    alignSelf: 'stretch',
                    flex: 1, 
                    marginHorizontal:padd,
                    marginTop:padd,
                    borderRadius,
                    borderWidth:1,
                    borderColor: scolor.separator,
                }}
            />
            <SegmentedControlTab
                allowFontScaling={false}
                tabStyle={[sstyle.tabs.atlas.tabStyle, { paddingHorizontal: 0, paddingVertical:12 , backgroundColor: 'transparent'}]}
                activeTabStyle={[sstyle.tabs.atlas.tabActive, { backgroundColor: 'transparent'}]}
                tabTextStyle={[sstyle.tabs.atlas.tabText, { fontSize: 17 , color: Color.GREY[50] }]}
                activeTabTextStyle={[sstyle.tabs.atlas.tabTextActive, {color: Color.GREY[700]}]}
                borderRadius={2}
                tabsContainerStyle={[sstyle.tabs.atlas.tabContainer,  {borderBottomWidth:0, borderColor: scolor.separator, marginHorizontal: padd, paddingHorizontal: 0}]}
                values={['▲', '▲', '▲']}
                selectedIndex={selectedTabIndex}
                onTabPress={index =>  { 
                    setSelectedTabIndex(index)
                }}
            />
        </View>
    )
}
