class PalaceDetails extends React.Component {
    state={
        showChart:true,
        sections:[
            {
                title: 'Stems',
                data:[]
            },
            {
                title: 'Structures',
                data:[]
            },
            {
                title: 'Door',
                data:[]
            },
            {
                title: 'Star',
                data:[]
            },
            {
                title: 'Spirit',
                data:[]
            },
            {
                title: 'Destiny',
                data: []
            }


        ]
    }
    static navigationOptions = ({ navigation }) => {
        const { params={} } = navigation.state 
        const title =  params.title || ''
		return {
            title: title.toUpperCase(),
            headerRight:(
                <View style={sstyle.navigation.navHeaderRight} >
                    { params.toggleChart && (
                        <TouchableOpacityEx 
                            onPress={() => params.toggleChart() }
                            style={[sstyle.navigation.navHeaderItem] }
                        >
                        <MaterialCommunityIcon
                                name={ params.showChart ? 'chevron-up' : 'chevron-down' } 
                                color={scolor.iconBlurred}
                                size={26}
                        />
                        </TouchableOpacityEx>	
                    )}
				</View>
            )
		}
    }
    constructor(props){
        super(props)
        const load = this.load.bind(this)
        this.toggleChart = this.toggleChart.bind(this)
        this.name = this.props.navigation.getParam('name')
        this.chart = this.props.navigation.getParam('chart')
        this.settings = this.props.navigation.getParam('settings')
        this.props.navigation.setParams({
            title: `${this.name}`,
            toggleChart: this.toggleChart,
            showChart: this.state.showChart,
        })
        analytics.track('QiMen.Palace')
    }
    toggleChart(){
        const newShowChart = !this.state.showChart
        this.setState({ showChart: newShowChart }, () => {
            this.props.navigation.setParams({ showChart: newShowChart })
        })
    }
    componentDidMount(){
        this.load()
    }
    async load(){
        const preferences = await getPreferences()
        const display = MysticDoors.displayTerminology[preferences.qmdj.palace.namingConvention]

        const time = this.chart.bazi.info.time
        const pillars = this.chart.bazi.pillars
        const details = this.chart.details
        const plot = this.chart.palaces[this.name].plot
        const meta = this.chart.palaces[this.name].meta
        const destiny = meta?.destiny
        const sections = JSON.parse(JSON.stringify(this.state.sections))


        sections[0] = {
            title: 'Formations',
            template: 'stems',
            data: meta.formations
        }


        //Structures
        const structures = meta.structuresMap.positive.concat(meta.structuresMap.neutral).concat(meta.structuresMap.negative)
        sections[1] = {
            title: 'Structures',
            template: 'structures',
            data: structures,
            rightItem: (
                <LinkButton
                    path={'qiMenDunJia.structures'}
                />
            )
        }


        //Door
        sections[2] = {
            title: 'Door',
            template: 'door',
            data: [{ plot , meta,  display }],
            rightItem: (
                <LinkButton
                    path={'qiMenDunJia.doors.' + plot.door}
                />
            )
        }

        sections[3] = {
            title: 'Star',
            template: 'star',
            data: [{ plot, meta,  display }],
            rightItem: (
                <LinkButton
                    path={'qiMenDunJia.stars.' + plot.star}
                />
            )
        }


        sections[4] = {
            title: 'Spirit',
            template: 'spirit',
            data: [{ plot, meta,  display}],
            rightItem: (
                <LinkButton
                    path={'qiMenDunJia.spirits.' + plot.spirit}
                />
            )
        }


        if(destiny){
            sections[5] = {
                title: 'Destiny',
                template: 'destiny',
                data: [destiny]
            }
        }

        this.setState({ sections })
    }
    render(){
        const plot = this.chart.palaces[this.name].plot
        return (
            <View style={{ flex: 1}}>
                { this.state.showChart && (
                <View style={{}}>
                    <View style={{
                        backgroundColor: Graphics.colors.elements.dark[ Ordinals.guas[this.name].element ],
                        height: 12,
                        width:64,
                        alignSelf: 'center',

                    }}/>
                    <View style={styles.header}>
                        <View style={styles.headerLeft}>
                            <View style={styles.hiddenTop}>
                                { plot.isHeavenLeadStem && (
                                    <Text style={[styles.hiddenStem]}>{ Ordinals.stems['jia'].chinese }</Text>
                                )}
                                { plot.hiddenHeavenStem && (
                                    <Text style={[styles.hiddenStem, { marginLeft: 9}]}>{ Ordinals.stems[plot.hiddenHeavenStem].chinese }</Text>
                                )}
                            </View>
                            <View style={styles.hiddenBottom}>
                                { plot.isEarthLeadStem && (
                                    <Text style={[styles.hiddenStem ]}>{ Ordinals.stems['jia'].chinese }</Text>
                                )}
                                { plot.hiddenEarthStem && (
                                    <Text style={[styles.hiddenStem , { marginLeft: 9}]}>{ Ordinals.stems[plot.hiddenEarthStem].chinese }</Text>
                                )}
                            </View>
                        </View>
                        <View style={styles.headerCenter}>
                            <SquarePalace
                                displayMode={0}
                                isDetailView={true}
                                chart={this.chart}
                                name={this.name}
                                settings={this.settings}
                            />
                        </View>
                        <View style={styles.headerRight}>
                            <Toucher
                                onPress={() => {
                                    const binary =Ordinals.guas[ MysticDoors.stars[plot.star].details.natalPalace ].binary +  Ordinals.guas[  MysticDoors.doors[plot.door].details.natalPalace ].binary
                                    this.props.navigation.push('HexagramSelector', { initialBinary: binary })
                                }}
                            >
                                <View >
                                    <Text style={[styles.trigram, { marginBottom:-5}]}>{ Ordinals.guas[ MysticDoors.stars[plot.star].details.natalPalace ].trigram }</Text>
                                    <Text style={[styles.trigram, { marginTop:-5}]}>{ Ordinals.guas[ MysticDoors.doors[plot.door].details.natalPalace    ].trigram }</Text>
                                </View>
                            </Toucher>
                            <Text style={styles.periodNum}>{ plot.periodNum }</Text>
                        </View>
                    </View>
                </View>
                )}
                <SectionList
                    showsVerticalScrollIndicator={false}
                    style={styles.sectionlist}
                    sections={this.state.sections}
                    renderItem={(payload) => {
                        switch(payload.section.template){
                            case 'stems':
                                return <FormationCell item={payload.item} />
                                break
                            case 'structures':
                                return <StructureCell item={payload.item}/>
                                break
                            case 'destiny':
                                return <DestinyCell item={payload.item}/>
                            case 'door': 
                                return <DoorCell item={payload.item}/>
                            case 'star':
                                return <StarCell item={payload.item}/>
                            case 'spirit': 
                                return <SpiritCell item={payload.item} />
                        }
                        return <View></View>
                    }}
                    ListFooterComponent={(
                        <View>
                            <View style={styles.separator}/>
                            <Disclaimer
                            />
                        </View>
                    )}
                    renderSectionHeader={({section: {title, data, rightItem}}) => data.length > 0 ? (
                        <SectionHeader title={title} rightItem={rightItem}/>
                    ) : (<View></View>) }
                    keyExtractor={(item, index) => item + index}
                    keyboardShouldPersistTaps='always'
                    keyboardDismissMode='interactive'
                    ItemSeparatorComponent={((props) => {
                        return(<View style={{ height: 1, backgroundColor: scolor.separator }}/>)
                    })}
                />
            </View>
        )
    }
}
export default withNavigation(PalaceDetails)    


const interactionTranslation = (thing, type) => {
    if(type === 'countered'){
        return `Palace controls ${toTitle(thing)}`
    }else if(type === 'compelled')  {
        return `${toTitle(thing)} controls Palace`
    }else if(type === 'produce'){
        return `${toTitle(thing)} produces Palace`
    }else if(type === 'produced'){
        return `Palace produces ${toTitle(thing)}`
    }else if(type === 'harmony'){
        return `Palace same element as ${toTitle(thing)}`
    }
}

      
const reverseStrengthMap = { 'peak' : 8, 'strong' : 7, 'weak': 6, 'trap' : 5, 'dead' : 4 }
const DoorCell = ({ item }) => {
    const { plot, meta,  display } = item
    const doorColor = Graphics.colors.elements.dark[Ordinals.guas[ MysticDoors.doors[plot.door].details.natalPalace].element]
    const data = MysticDoors.doors[plot.door]

    const details = []
    Object.keys(data.details).forEach(d => {
        if(['luoShuNumber', 'originalDirection', 'branches'].indexOf(d) >= 0) return
        details.push({ 
            title: deCamel(d),
            body: capFirst(data.details[d])
        })
    })
    const results = [
        { title: 'Name', body: `${display.door[plot.door][1]} ${ toTitle(display.door[plot.door][0])}` },
        { title: 'Strength by Season', body: `${toTitle(meta.door.strength) } (${reverseStrengthMap[meta.door.strength]})`},
        { title: 'Palace Interaction', body:  `${interactionTranslation('door', meta.door.palaceInteraction)}\n(${ toTitle(meta.door.palaceInteraction) })`},
        { title: 'Special', body:  `${toTitle(meta.door.specialInteraction) || '—'}`},
        ...details, 
    ]
    return (
        <DataTable
            data={ results}
        />
    )
}


