    const yearColor = Graphics.colors.elements.dark[ WindWater.flyingStars[timePayload.year[palace]].element]
    const dayColor = Graphics.colors.elements.dark[ WindWater.flyingStars[timePayload.day[palace]].element]
    const hourColor = Graphics.colors.elements.dark[ WindWater.flyingStars[timePayload.hour[palace]].element]

