import { DateTime } from 'luxon'

import analytics from '@segment/analytics-react-native'

class WikiPeopleList extends React.Component {
    state = {
        searchQuery: "",
        loading: false,
        data: []
    }
    constructor(props){
        super(props)
        this.fetch = this.fetch.bind(this)
        this.searchQueryOnChange = this.searchQueryOnChange.bind(this)
        this.debouncer = _.debounce(this.fetch, 500)
        analytics.track('DateSelector.Wiki')
    }
    componentDidMount(){
        this.searchBox.focus()
    }
    searchQueryOnChange(searchQuery){
        this.setState({ searchQuery })
        this.debouncer()
    }
    async fetch(){
        const  preferences = await getPreferences()
        const lateZi = preferences?.bazi?.calculations?.showDayStartsFrom_23

        this.setState({ loading: true })
        const q = `
        SELECT ?person ?personLabel ?personDescription (GROUP_CONCAT(DISTINCT ?dob ; SEPARATOR = ' | ') AS ?dobs) (GROUP_CONCAT(DISTINCT ?gender ; SEPARATOR = ' | ') AS ?genders) (GROUP_CONCAT(DISTINCT ?image ; SEPARATOR = ' | ') AS ?images)
WHERE {
  SERVICE wikibase:mwapi {
    bd:serviceParam wikibase:api "EntitySearch" .
    bd:serviceParam wikibase:endpoint "www.wikidata.org" .
    bd:serviceParam mwapi:search "${this.state.searchQuery}" .
    bd:serviceParam mwapi:language "en" .
    ?person wikibase:apiOutputItem mwapi:item .
  }
  ?person wdt:P31 wd:Q5 .
  OPTIONAL { ?person wdt:P569 ?dob }
  OPTIONAL { ?person wdt:P21 ?gender }
  OPTIONAL { ?person wdt:P18 ?image }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en" . }
}
GROUP BY ?person ?personLabel ?personDescription
`
        const url = `https://query.wikidata.org/sparql?format=json&query=` + encodeURI(q.trim())
        try{
            const result = await axios.get(url)
            const entities = result?.data?.results?.bindings
            const data = []
            entities.forEach(item => {
                const id = item?.person?.value
                const link = id
                const name = item?.personLabel?.value
                const description =  item?.personDescription?.value
                let image = item?.images?.value
                let gender = item?.genders?.value === 'http://www.wikidata.org/entity/Q6581072' ? 'female' : 'male'
                let dob = item?.dobs?.value

                if(image.indexOf('|') >= 0) image = image.split('|')[0].trim()
                if(gender.indexOf('|') >= 0) gender = gender.split('|').pop().trim()
                if(dob.indexOf('|') >= 0) dob = dob.split('|').pop().trim()
                if(!dob) return

                const lux = DateTime.fromISO(dob, { setZone: true })
                if(!lux.isValid) return
                if(lux < DateTime.fromObject({ year: 1583 })) return 

                const payload = { id, link , name, description, gender, image, time: lux.plus({ hours: 12 }),  hourUnknown: true, lateZi }

                data.push(payload)
            })
            this.setState({ data, loading: false })
        }catch(err){
            this.setState({ data: [], loading: false })
        }
    }
    render(){
        return (
            <View style={styles.container}>
                <View style={styles.searchBar}>
                    <TextInput  
                        ref={searchBox => { this.searchBox = searchBox; }}
                        placeholder={'Find Famous Person'}
                        style={styles.searchBarTextInput}
                        value={this.state.searchQuery}
                        onChangeText={this.searchQueryOnChange}
                        autoCapitalize="none"
                        autoCorrect={false}
                        clearButtonMode={'while-editing'}
                    />
                </View>

                { this.state.loading && (
                    <View style={{ paddingVertical:24 }}>
                        <ActivityIndicator size="large" color={Color.GREY[700]} />
                    </View>
                )}

                { (!this.state.loading && this.state.data.length > 0) && (
                    <FlatList
                        keyboardShouldPersistTaps={'always'}
                        ref={flatList => { this.flatList = flatList; }}
                        data={this.state.data}
                        keyExtractor={(item, index) => index.toString()}
                        inverted={false}
                        ItemSeparatorComponent={() => (<View style={styles.separator}></View>)}
                        renderItem={(payload) => {
                            return <PersonRecord
                                info={payload.item}
                                onSubmit={this.props.onSubmit}
                            />
                        }}
                        ListFooterComponent={(<View style={styles.separator}/>)}
                    />
                )}
                
            </View>
        )
    }
}
export default WikiPeopleList


