

import hourJus from '../../Data/jusHour'
import dayJus from '../../Data/jusDay'
import monthJus from '../../Data/jusMonth'
import yearJus from '../../Data/jusYear'

import * as SolarCal from '../../SolarCal'
import * as Ordinals from '../../Ordinals'

export const zhiRun = (reference, bazi) => {
    const year = bazi.info.time.toFormat('yyyy')
    const month = bazi.info.time.toFormat('MM')
    const day = bazi.info.time.toFormat('dd')
    try{
        let juArr = []  
        if(reference === 'hour' || reference === 'destiny'){
            juArr = hourJus[year][month][day]
        }else if(reference === 'day'){
            juArr = dayJus[year][month][day]
        }else if(reference === 'month'){
            juArr = bazi.info.isPreviousYear ? monthJus[year-1] : monthJus[year]
        }else if(reference === 'year'){
            juArr = bazi.info.isPreviousYear ? yearJus[year-1] : yearJus[year]
        }
        juArr = juArr.split('-')
        const dun = parseInt(juArr[0]) === 0 ? 'yin' : 'yang'
        const ju = juArr[1]
        return [dun, ju]
    }catch(err){
        console.error("missing ju", err, reference, year, month, day)
        return null
    }
}



export const chaiBu = (bazi) => {
    const stem = bazi.pillars.day.stem.name
    const  branch = bazi.pillars.day.branch.name
    const time = bazi.info.time
    const  term = SolarCal.getCurrentSolarTerm(time).thisTerm
    const cycleArr = SolarCal.solarJus[term.data.num]
    const yuan = Ordinals.threeYuanTable[stem][branch]

    let ju;
    if(yuan.cycle === 'upper'){
        ju = cycleArr[0]
    }else if(yuan.cycle === 'middle'){
        ju = cycleArr[1]
    }else{
        ju = cycleArr[2]
    }
    const dun = (parseInt(term.data.num) >= 9 && parseInt(term.data.num) < 21) ? 'yin' : 'yang'
    console.log(dun)
    return [dun, ju]
}