//Get a list of solar Terms of last year, this year, and next year (72) total .
//Will mark current solar Term.
export const getMonthlyTerms = ({ time, term,  showMidTerm = false}) => {
	const thisTerm = term || getCurrentSolarTerm(time).thisTerm
	let results = []
	const sets = [
		{ year: time.year-1, data: solarData[time.year-1] },
		{ year: time.year, data: solarData[time.year] }, 
		{ year: time.year + 1, data: solarData[time.year+1] },
	]
	sets.forEach(set => {
		Object.keys(set.data).forEach(monthKey => {
			const month = parseInt(monthKey)
			const num = set.data[month][0][0]
			const day = set.data[month][0][1][0]
			const hour = set.data[month][0][1][1]
			const minute = set.data[month][0][1][2]
			const num2 = set.data[month][1][0]
			const day2 = set.data[month][1][1][0]
			const hour2 = set.data[month][1][1][1]
			const minute2 = set.data[month][1][1][2]
			//Jie
			const d1 = {
				data: solarTerms[num],
				branch: solarTerms[num].branch,
				time: DateTime.fromObject({ year: set.year , month, day, hour, minute , zone: time.zone }).plus({ minutes: time.offset }),
				markers: [],
			}
			results.push(d1)
			if(time.year === set.year && num === thisTerm.data.num) d1.markers.push('current')
			//Qi
			const d2 = {
				data: solarTerms[num2],
				branch: solarTerms[num2].branch,
				time: DateTime.fromObject({ year: set.year , month, day: day2, hour: hour2, minute: minute2 , zone: time.zone }).plus({ minutes: time.offset }),
				markers: [],
			}
			if(showMidTerm) results.push(d2)
			if(time.year === set.year && num2 === thisTerm.data.num){
				if(showMidTerm) d2.markers.push('current')
				else			d1.markers.push('current')
			}
		})
	})
	let currentIndex = results.findIndex(i => i.markers.indexOf('current') >= 0)
	return { terms: results, currentIndex}
}

