export const getMinorCycle = (bazi, type) => {
	let begin = null
	let end = null
	if(type === 'month'){
		const thisTerm = bazi.info.solarTerm?.thisTerm
		const { terms, currentIndex } =  getMonthlyTerms({ time: bazi.info.time, term: thisTerm , showMidTerm: true })
		const tNum = thisTerm.data.num
		if(tNum >= 0 && tNum <= 5){
			begin = terms[currentIndex - (tNum - 0)].time
			end = terms[currentIndex + (6 - tNum)].time
		}else if(tNum >= 6 && tNum <= 11){
			begin = terms[currentIndex - (tNum - 6)].time
			end = terms[currentIndex + (12 - tNum)].time
		}else if(tNum >= 12 && tNum <= 17){
			begin = terms[currentIndex - (tNum - 12)].time
			end = terms[currentIndex + (18 - tNum)].time
		}else if(tNum >= 18 && tNum <= 23){
			begin = terms[currentIndex - (tNum - 18)].time
			end = terms[currentIndex + (24 - tNum)].time
		}
	}else if(type === 'year'){
		const group = bazi.pillars[type].branch.group
		const prevYearModifier  = bazi.info.isPreviousYear ? 1 : 0
		if(group === 'start'){
			begin = getCurrentYearJie(bazi.info.time.plus({ years: 0 - prevYearModifier }))
			end  = getCurrentYearJie(bazi.info.time.plus({ years: 3 - prevYearModifier}))
		}else if(group === 'peak'){
			begin = getCurrentYearJie(bazi.info.time.plus({ years : -1 - prevYearModifier }))
			end  = getCurrentYearJie(bazi.info.time.plus({ years: 2 - prevYearModifier }))
		}else if(group === 'end'){
			begin = getCurrentYearJie(bazi.info.time.plus({ years: -2 - prevYearModifier }))
			end  = getCurrentYearJie(bazi.info.time.plus({ years: 1 - prevYearModifier }))
		}
	}else if(type === 'day'){
		const group = bazi.pillars[type].branch.group
		// let lateZiModifier = bazi.info.lateZi ? 1 : 0 //doesn't work yet
		let lateZiModifier = 0 
		if(group === 'start'){
			begin = bazi.info.time.plus({ days: 0 }).startOf('day').minus({ hours: lateZiModifier })
			end = bazi.info.time.plus({ days: 2 }).endOf('day').minus({ hours: lateZiModifier})
		}else if(group === 'peak'){
			begin = bazi.info.time.plus({ days: -1 }).startOf('day').minus({ hours: lateZiModifier })
			end = bazi.info.time.plus({ days: 1 }).endOf('day').minus({ hours: lateZiModifier })
		}else if(group === 'end'){
			begin = bazi.info.time.plus({ days: -2 }).startOf('day').minus({ hours: lateZiModifier })
			end = bazi.info.time.plus({ days: 0 }).endOf('day').minus({ hours: lateZiModifier })
		}
	}else if(type === 'hour'){
		const group = bazi.pillars[type].branch.group
		let beginHour 
		if(bazi.info.time.hour % 2 === 0) 
			beginHour = bazi.info.time.minus({ hour: 1 })
		else
			beginHour = bazi.info.time
		if(group === 'start'){
			begin = beginHour.plus({ hours: 0}).startOf('hour')
			end = beginHour.plus({ hours: 5}).endOf('hour')	
		}else if(group === 'peak'){
			begin = beginHour.plus({ hours: -2}).startOf('hour')
			end = beginHour.plus({ hours: 3}).endOf('hour')
		}else if(group === 'end'){
			begin = beginHour.plus({ hours: -4}).startOf('hour')
			end = beginHour.plus({ hours: 1}).endOf('hour')
		}
	}
	// console.log('>> BEGIN' , begin?.toFormat('dd - H:mm'))
	// console.log('>> END', end?.toFormat('dd - H:mm'))
	return [begin, end]
}

