//Given bazi, get the previous solstice point
export const getSolstice = (bazi) => {
	const term = bazi.info.solarTerm.thisTerm	
	if(term.data.num === 9)
		return { solstice: 'summer', time: term.begins}
	if(term.data.num === 21)
		return { solstice: 'winter', time: term.begins}
	let found = null;
	//keep going backwards until we hit 9 or 21
	for(let i = 1; i < 99; i++){
		const newTime = bazi.info.time.minus({ day: i * 15 })
		const data = solarData[newTime.year][newTime.month]
		if(data[0][0] === 9)  
			found = {
				solstice: 'summer',
				time: DateTime.fromObject({ year: newTime.year, month: newTime.month, day: data[0][1][0], hour: data[0][1][1], minute: data[0][1][2]})
			}
		if(data[1][0] === 9)
			found = {
				solstice: 'summer',
				time: DateTime.fromObject({ year: newTime.year, month: newTime.month, day: data[1][1][0], hour: data[1][1][1], minute: data[1][1][2]})
			}
		if(data[0][0] === 21)
			found = {
				solstice: 'winter',
				time: DateTime.fromObject({ year: newTime.year, month: newTime.month, day: data[0][1][0], hour: data[0][1][1], minute: data[0][1][2]})
			}
		if(data[1][0] === 21){
			found = {
				solstice: 'winter',
				time: DateTime.fromObject({ year: newTime.year, month: newTime.month, day: data[1][1][0], hour: data[1][1][1], minute: data[1][1][2]})
			}
		}
		if(found) break;
	}
	return found
}


//Given year, month, get the two terms of this month
export const getYearMonthSolarTerm = (y,m, zone=null, offset=0)  => {
	let year = y
	let month = m
	if(m > 12){
		year += 1
		month = m - 12
	}
	if(m < 1){
		year -= 1
		month = m + 12
	}
	let data = _.cloneDeep(solarData[year][month])
	data[0][1] = DateTime.fromObject({ zone, year, month, day: data[0][1][0], hour: data[0][1][1], minute: data[0][1][2]}).plus({ minutes: offset })
	data[1][1] = DateTime.fromObject({ zone, year, month, day: data[1][1][0], hour: data[1][1][1], minute: data[1][1][2]}).plus({ minutes: offset })

	return data 
}


//Given time, get the start of the year (current numerical year)
export const getCurrentYearJie = (current) => {
	const { year, zone=null, offset=0 } = current
	let jie
	for(let m = 1; m < 6; m++){
		jie = solarData[year][m].find(i => i[0] === 0) //find the term number that equals 0. That's the start of the year.
		if(jie){
			jie = DateTime.fromObject({ zone, year: year, month: m, day: jie[1][0], hour: jie[1][1], minute: jie[1][2] }).plus({ minutes: offset })
			break
		}
	}
	if(!jie){ //go backwards if we can't find it
		for(let m = 12; m > 6; m--){
			jie = solarData[year-1][m].find(i => i[0] === 0)
			if(jie){
				jie = DateTime.fromObject({ zone, year: year-1, month: m, date: jie[1][0], hour: jie[1][1], minute: jie[1][2] }).plus({minutes: offset })
				break
			}
		}
	}
	return jie	
}

//Given time, get YearJie
export const getYearJie = (current) => {
	const prev = getCurrentYearJie(current.minus({ year: 1}))
	const now = getCurrentYearJie(current)
	if(current < now)
		return prev
	else
		return now
}


//Given time, return solar term
export const getCurrentSolarTerm = (current) => {
	const thisMonth = getYearMonthSolarTerm(current.year, current.month, current.zone, current.offset)
	const nextMonth = getYearMonthSolarTerm(current.year, current.month + 1, current.zone, current.offset)
	const prevMonth = getYearMonthSolarTerm(current.year, current.month - 1, current.zone, current.offset)
	let term = prevMonth[1]
	let nextTerm = thisMonth[0];
	if(current >= thisMonth[1][1]){
		term = thisMonth[1]
		nextTerm = nextMonth[0]
	}else if(current >= thisMonth[0][1]){
		term = thisMonth[0]
		nextTerm = thisMonth[1]
	}
	return {
		thisTerm: {
			data: solarTerms[parseInt(term[0])],
			begins: term[1]
		},
		nextTerm:{
			data: solarTerms[parseInt(nextTerm[0])],
			begins: nextTerm[1]
		}
	}
}


//Given time, return next Jie
export const getForwardJie = (current) => {
	const thisMonth = getYearMonthSolarTerm(current.year, current.month, current.zone, current.offset)
	const nextMonth = getYearMonthSolarTerm(current.year, current.month+1, current.zone, current.offset)
	if(current < thisMonth[0][1] ){
		return (thisMonth[0][0] % 2 === 0) ? thisMonth[0][1] : thisMonth[1][1]
	}else if(current < thisMonth[1][1] ){
		return (thisMonth[1][0] % 2 === 0) ? thisMonth[1][1] : nextMonth[0][1]
	}else{
		return (nextMonth[0][0] % 2 === 0) ? nextMonth[0][1] : nextMonth[1][1]
	}
}

//Given time, return previous Jie
export const getReverseJie = (current) => {
	const thisMonth = getYearMonthSolarTerm(current.year, current.month, current.zone, current.offset)
	const prevMonth = getYearMonthSolarTerm(current.year, current.month - 1, current.zone, current.offset)
	if(current > thisMonth[1][1]){
		return (thisMonth[1][0] % 2 === 0) ? thisMonth[1][1] : thisMonth[0][1]
	}else if(current > thisMonth[0][1]){
		return (thisMonth[0][0] % 2 === 0) ? thisMonth[0][1] : prevMonth[1][1]
	}else{
		return (prevMonth[1][0] % 2 === 0) ? prevMonth[1][1] : prevMonth[0][1]
	}
}




