
import React from 'react';
import AsyncStorage from '@react-native-community/async-storage';
import { Provider, Subscribe, Container } from 'unstated';
import _ from 'lodash'
import { auxDetails } from '../lib/cmtools/ShenSha'


import * as Ordinals from '../lib/cmtools/Ordinals'
import * as MysticDoors from '../lib/cmtools/MysticDoors'

const getInitialSettings = () => {
    const auxTree = _.cloneDeep(auxDetails)
    for(aux in auxTree)
        for(name in auxTree[aux])
            auxTree[aux][name] = auxTree[aux][name].isDefaultSelected
    const qmdjStructures = {}
    Object.keys(MysticDoors.structures).forEach(k => {
        if( MysticDoors.structures[k].rating > 0 ){
            const defaultVal = MysticDoors.structures[k].almanacDefault ? true : false;
            qmdjStructures[k] = defaultVal
        }
    })

    const qmdjSpirits = {}
    Object.keys(MysticDoors.spirits).forEach(k => {
        const defaultVal = ['chief','harmony','heaven','moon','earth'].indexOf(k) >= 0
        qmdjSpirits[k] = defaultVal
    })
    const qmdjStars = {}
    Object.keys(MysticDoors.stars).forEach(k => {
        // const defaultVal = ['heart','assistant','ambassador', 'destructor', 'grass', 'grain', 'bird', 'hero', 'pillar'].indexOf(k) >= 0
        const defaultVal = ['heart','assistant','ambassador', 'destructor', 'grass', 'grain', 'bird', 'hero', 'pillar'].indexOf(k) >= 0
        qmdjStars[k] = defaultVal
    })
    const qmdjDoors = {}
    Object.keys(MysticDoors.doors).forEach(k => {
        const defaultVal = ['life','rest','open', 'scenery', 'delusion'].indexOf(k) >= 0
        qmdjDoors[k] = defaultVal
    })


    const initial = {
        almanac:{
            qmdj:{
                maxNegativeStructures: 0,
                structures: qmdjStructures ,
                spirits: qmdjSpirits,
                stars: qmdjStars,
                doors: qmdjDoors,
                showHourMin: 0,
                showHourMax: 23,
            }
        },
        yijing:{
            calculations:{
                initialSet: 'random',
                markedLines: 1,
                showColors: true,
                showMutual: true,
                showChanged: true,
            }
        },
        qmdj:{
            palace:{
                namingConvention: 0,
                showDayAndHourStemOutline: true,
                showLeadStemDoorStarOutline: true,
                showElementalColor: true,
                showStrength: true,
                // showNumberOfStructures: true,
            },
            calculations:{
                shiftLateZiStream: true,
                starPath: 0,
                method: 0,
            }
        },
        bazi:{
            calculations:{
                showSimpleLuckCycleCalculation: true,
                showCombinationsInWeightCalculation: false,
                showDayStartsFrom_23: false,
                showDeathEmptinessBasedOnDayPillar: true,
                showDeathEmptinessBasedOnYearPillar: false,
            },
            pillars:{
                showElementBackgroundColor: true,
                showChinese:false,
                showPicture:true,
                showPinYin:false,
                showElementName:false,
                showElementCommonName: true,
                showBranchName:true,
                showHiddenStems: true,
                showTenGods: true,
                showBranchSeason: false,
                showRootingHighlight: true,
                showFuYin: true,
                showFanYinHost: true,
                showFanYinGuest: true,
                showPillarCombo: true,
            },
            details:{
                showNaYin: true,
                showJiaZiStream:true,
                showPillarQiPhase: true,
                showDaymasterQiPhase: true,
                showHexagram: true,
                showFuYin: true,
                showFanYinHost: true,
                showFanYinGuest: true,
                showPillarCombo: true,
                showStemCombos: true,
                showStemConflicts: true,
                showBranchDirectionCombinations: true,
                showBranchHarmonyCombinations: true,
                showBranchThreePenalties: true,
                showBranchClashes: true,
                showBranchHalfHarmonyCombinations: true,
                showBranchSixCombinations: true,
                showBranchSelfPenalities: true,
                showBranchHarms: true,
                showBranchDestructions: true,
                showBranchHiddenCombinations: false,
            },
            analysis: {
                showMatchingRules: true,
                showChineseGoldenVerse: true,
                showCommentary: true,
            },
            dayInfo:{
                showNextAuspiciousQiMenFormation: true,
                show_12Officer: true,
                show_28Constellation: true,
                showYellowBlackBelt: true,
                showDongGong: true,
                showYearlyThreeKillings: true,
                showMonthlyThreeKillings: true,
                showBigDisasterNoWealth:true,
                showYearBreaker: true,
                showMonthBreaker: true,
                showMonthDestructor: true,
                showSolarTerm:true,
                // showMoonPhase: false,
            },
            stars: auxTree
        }
    }
    return initial
}


class PreferencesContainer extends Container{
	constructor(props){
        super(props)
        this.state = getInitialSettings()
        this.clone = this.clone.bind(this)
        this.update = this.update.bind(this)
        this.initialize()
    }
    async initialize(){
        let storedState = await AsyncStorage.getItem('@preferences')
        if(storedState){ 
            //Sync: checks if existing value in storedState. If so, replace origState with that value. Otherwise, discard.
            const origState = _.cloneDeep(this.state)
            storedState = JSON.parse(storedState)

            if(storedState.yijing)
                for(k in storedState.yijing.calculations)
                    if(k in origState.yijing.calculations)
                        origState.yijing.calculations[k] = storedState.yijing.calculations[k]

            for(k in storedState.qmdj.palace)
                if(k in origState.qmdj.palace)
                    origState.qmdj.palace[k] = storedState.qmdj.palace[k] 

            for(k in storedState.qmdj.calculations)
                if(k in origState.qmdj.calculations)
                    origState.qmdj.calculations[k] = storedState.qmdj.calculations[k] 



            for(k in storedState.bazi.calculations)
                if(k in origState.bazi.calculations)
                    origState.bazi.calculations[k] = storedState.bazi.calculations[k] 

            for(k in storedState.bazi.pillars)
                if(k in origState.bazi.pillars)
                    origState.bazi.pillars[k] = storedState.bazi.pillars[k] 

            for(k in storedState.bazi.details)
                if(k in origState.bazi.details)
                    origState.bazi.details[k] = storedState.bazi.details[k] 

            for(k in storedState.bazi.analysis)
                if(k in origState.bazi.analysis)
                    origState.bazi.analysis[k] = storedState.bazi.analysis[k] 

            for(k in storedState.bazi.dayInfo)
                if(k in origState.bazi.dayInfo)
                    origState.bazi.dayInfo[k] = storedState.bazi.dayInfo[k] 

            for(aux in storedState.bazi.stars) {
                if(aux in origState.bazi.stars){
                    for(name in origState.bazi.stars[aux]){
                        if(name in storedState.bazi.stars[aux]){
                            origState.bazi.stars[aux][name] = storedState.bazi.stars[aux][name]
                        }else{
                            origState.bazi.stars[aux][name] =  true
                        }
                    }
                }
            }

            if(storedState.almanac){
                if(storedState.almanac.qmdj.maxNegativeStructures)
                    origState.almanac.qmdj.maxNegativeStructures = storedState.almanac.qmdj.maxNegativeStructures
                for(k in storedState.almanac.qmdj.structures)
                    if(k in origState.almanac.qmdj.structures)
                        origState.almanac.qmdj.structures[k] = storedState.almanac.qmdj.structures[k]
                for(k in storedState.almanac.qmdj.spirits)
                    if(k in origState.almanac.qmdj.spirits)
                        origState.almanac.qmdj.spirits[k] = storedState.almanac.qmdj.spirits[k]
                for(k in storedState.almanac.qmdj.stars)
                    if(k in origState.almanac.qmdj.stars)
                        origState.almanac.qmdj.stars[k] = storedState.almanac.qmdj.stars[k]
                for(k in storedState.almanac.qmdj.doors)
                    if(k in origState.almanac.qmdj.doors)
                        origState.almanac.qmdj.doors[k] = storedState.almanac.qmdj.doors[k]
            }


            this.setState(origState)
            AsyncStorage.setItem('@preferences', JSON.stringify(origState))
        }else{
            AsyncStorage.setItem('@preferences', JSON.stringify(this.state))
        }
    }
    clone(){
        return _.cloneDeep(this.state)
    }
    async update(state){
        this.setState(state)
        await AsyncStorage.setItem('@preferences', JSON.stringify(state))
    }
}
export default PreferencesContainer



export const  getPreferences = async () => {
    let storedState = await AsyncStorage.getItem('@preferences')
    if(storedState){
        const parsed = JSON.parse(storedState)
        return Promise.resolve(parsed)
    }
    return Promise.resolve( getInitialSettings() )
}