const AffinityBox = (props ) => {
    const {pillar, god, root } = props
    const aspect = EightWords.aspects[god.aspect]
    const people = []
    const line = [
        {
            words: [
                ...aspect.$dict_noun3.map(i => `matters-${i}|${toTitle(i)}`) ,
                ...god.$dict_places.map(i => `places-${i}|${toTitle(i)}`),
            ],
            shuffle: true
        },
        {
            words: [
                ...god.$kin(root.info.gender).map(i => `people-${i}|${toTitle(i)}`),
                ...god.$dict_people.map(i => `people-${i}|${toTitle(i)}`)
            ],
            shuffle: true
        },
        // {
        //     words: [
        //     ]
        // },
    ]
    if(props.preLabel){
        line.unshift(props.preLabel)
    }
    return (
        <MadLibs
            line={line}
            containerStyle={props.containerStyle || styles.container}
            boxSelectStyle={styles.boxSelect}
            boxTextStyle={styles.boxText}
            iconStyle={{
                marginRight:6,
                width:22,
                height:22,
            }}
        />
    )
}
export default AffinityBox;

