import Disclaimer from '../Layout/Disclaimer';
import _ from 'lodash'
import * as Sentry from "@sentry/react-native";
import Compendium from '../../lib/cmtools/Compendium'
import Titles from '../../lib/cmtools/Compendium/Titles'

class Library extends React.Component{
    static navigationOptions = ({ navigation }) => {
        const { params={} } = navigation.state 
		return {
            title: params.title || '',
            headerRight: (
                <View style={sstyle.navigation.navHeaderRight} >
                    {params.hideClose === false  && (
                    <TouchableOpacityEx 
                        style={[sstyle.navigation.navHeaderItem, { paddingRight: 15}] }
                        onPress={async () => { 
                            navigation.dispatch(StackActions.popToTop());
                        }}
                    >
                        <MaterialCommunityIcon
                            name="close-circle"
                            size={20}
                            color={Color.GREY[300]}
                        />
                    </TouchableOpacityEx> 
                    )}
				</View>
			),
        }
    }
    state={
        data: []
    }
    constructor(props){
        super(props)
        this.hideClose = this.props.navigation.getParam('hideClose', false)
        this.props.navigation.setParams({ hideClose: this.hideClose })
    }
    componentDidMount(){
        let path = this.props.navigation.getParam('path') || ''
        const tree = path ? _.get(Compendium, path, null) : Compendium
        let title =  Titles[path] || deCamel(path.split('.').pop()) || 'Library'
        this.props.navigation.setParams({ title })

        if(tree === null) {
            analytics.track('ERROR', { path })
            Sentry.captureMessage('error library' + path)
        }


        const data = []
        Object.keys(tree).forEach(key => {
            if(key.indexOf('_') === 0){

            }else if(key.indexOf('$icon') === 0){
                data.push({
                    template: 'icon',
                    ...tree[key]
                })
            }else if(key.indexOf('$header') === 0){
                data.push({
                    template: 'header',
                    title: tree[key].title,
                    subtitle: tree[key].subtitle || null,
                })
            }else if(key.indexOf('$push') === 0){
                data.push({ 
                    template: 'push' , 
                    ...tree[key]
                })
            }else if(key.indexOf('$body') === 0){
                data.push({
                    template: 'textBody',
                    body: tree[key]
                })
            }else if(key.indexOf('$link_wiki') === 0){
                data.push({
                    template: 'wiki',
                    ...tree[key],
                })
            }else if(key.indexOf('$link') === 0){
                data.push({
                    template: 'link',
                    ...tree[key]
                })
            }else if(key.indexOf('$def') === 0){
                data.push({
                    template: 'def',
                    body: tree[key],
                })
            }else if(typeof tree[key] === 'object' && Array.isArray(tree[key])){
                let title = key.replace('$dict', '').replace(/_/g, ' ').replace('adj', 'adjective').replace('syn', 'synonyms')
                title = toTitle(deCamel(title))

                data.push({
                    template: 'tags',
                    tags: tree[key],
                    title
                })
            }else if(typeof tree[key] === 'object' && !Array.isArray(tree[key]) ){
                const newPath = path ? path + '.' + key : key
                data.push({
                    title: Titles[newPath] || deCamel(key) ,
                    template: 'button',
                    key: deCamel(key),
                    path: newPath
                })
            }else if(typeof tree[key] === 'string' || typeof tree[key] === 'number'){
                data.push({
                    template: 'content',
                    body: capFirst(String(tree[key])),
                    title: deCamel(String(key)),
                })
            }
        })
        analytics.track('Library', { title })
        this.setState({ data })
    }
    render(){
        return (
            <FlatList
                data={this.state.data}
                keyExtractor={(item, index) => index.toString()}
                ItemSeparatorComponent={() => (<View style={styles.separator}></View>)}
                renderItem={(payload) => {
                    if(payload.item.template === 'header'){
                        return (
                            <SectionHeader
                                title={payload.item.title}
                                subtitle={payload.item.subtitle || null}
                            />
                        )
                    }else if(payload.item.template === 'textBody'){
                        return (
                            <Text style={styles.textBody}>
                                { payload.item.body}
                            </Text>
                        )
                    }else if(payload.item.template === 'wiki'){
                        return (
                            <Toucher 
                                onPress={() => {
                                    this.props.navigation.push('BasicWebView', { uri: payload.item.uri })
                                }}
                            >
                               <View style={styles.listRow}>
                                    <Text style={[ styles.uri ]} numberOfLines={1} ellipsizeMode={'tail'} >
                                        { payload.item.uri }
                                    </Text> 
                                    <MaterialCommunityIcon
                                        name={'wikipedia'}
                                        color={Color.GREY[800]}
                                        size={22}
                                        style={{ marginRight: 6, marginLeft: 12}}
                                    /> 
                                    <MaterialCommunityIcon
                                        name={'chevron-right'}
                                        color={Color.GREY[300]}
                                        size={22}
                                    /> 
                                </View> 
                            </Toucher>
                        )
                    }else if(payload.item.template === 'push'){
                        return (
                            <Toucher 
                                onPress={() => {
                                    this.props.navigation.push(payload.item.path, payload.item.params)
                                }}
                            >
                                <View style={styles.listRow}>
                                    <Text style={[ styles.listText ]}>
                                        { payload.item.title }
                                    </Text> 
                                    <MaterialCommunityIcon
                                        name={'chevron-right'}
                                        color={Color.GREY[300]}
                                        size={22}
                                    /> 
                                </View>
                            </Toucher>
                        )
                    }else if(['link', 'button'].indexOf(payload.item.template) >= 0){
                        return (
                            <Toucher 
                                onPress={() => {
                                    if(payload.item.template === 'link'){
                                        this.props.navigation.push('BasicWebView', { uri: payload.item.uri })
                                    }else if(payload.item.template === 'button'){
                                        this.props.navigation.push('Library', {  path: payload.item.path })
                                    }else if(payload.item.template === 'qmdjUsefulGods'){
                                        this.props.navigation.push('QiMenUsefulGodList')
                                    }
                                }}
                            >
                                <View style={styles.listRow}>
                                    <Text style={[ styles.listText ]}>
                                        { payload.item.title }
                                    </Text> 
                                    <MaterialCommunityIcon
                                        name={'chevron-right'}
                                        color={Color.GREY[300]}
                                        size={22}
                                    /> 
                                </View>
                            </Toucher>
                        )
                    }else if(payload.item.template === 'def'){
                        return (
                            <View style={styles.defRow}>
                                <Text style={styles.defHeading}>
                                   DEFINITION
                                </Text>
                                <Text style={styles.defText}>
                                    {capFirst(payload.item.body)}
                                </Text>
                            </View>
                        )
                
                    }else if(payload.item.template === 'icon'){
                        return (
                            <View style={[styles.infoRow, { justifyContent: 'center'}]}>
                                <Image
                                    source={payload.item.source}
                                    style={{ width: payload.item.width || 36 , height: payload.item.height || 36}}
                                    resizeMode={'contain'}
                                />
                            </View>
                        )
                    }else if(payload.item.template === 'tags'){
                        return (
                            <View style={styles.infoRow}>
                                <Text style={styles.infoTitle}>
                                    { payload.item.title}
                                </Text>
                                <View style={styles.infoBody}>
                                    {payload.item.tags.map(tag => (
                                        <Text style={styles.tagText}>
                                            {toTitle(tag)}
                                        </Text>
                                    ))}
                                </View>
                            </View>
                        )
                    }else if(payload.item.template === 'content'){
                        return (
                            <View style={styles.infoRow}>
                                <Text style={styles.infoTitle}>
                                    { payload.item.title}
                                </Text>
                                <Text style={styles.infoBody}>
                                    { payload.item.body}
                                </Text>
                            </View>
                        )
                    }

                }}
                ListFooterComponent={(
                    <View>
                        <View style={styles.separator}/>
                        <Disclaimer />
                    </View>
                )}
            />
        )
    }
}

export default Library

