import * as Graphics from '../../lib/cmtools/Graphics'
import * as CMImages from '../../lib/cmtools/Assets'
import * as Ordinals from '../../lib/cmtools/Ordinals'
import * as EightWords from '../../lib/cmtools/EightWords'


const DayMasterHolder = (props) => {
    const { chart, data, navigation} = props
    const dm = chart.pillars.day
    const stemColor = dm.stem.elm._colors.dark
    const branchColor = dm.branch.stems.main.elm._colors.dark

    const [list, setList] = useState([
        { dict: dm.branch.stems.main.elm.$dict_adj ,  desat: CMImages.desat.branches[dm.branch.name], color: CMImages.color.branches[dm.branch.name], label: toTitle(dm.branch.animalName) , sublabel:null , key: 'branch'},
        { dict: dm.branch.stems.main.$dict_adj,   desat: CMImages.desat.stems[dm.branch.stems.main.name], color: CMImages.color.stems[dm.branch.stems.main.name], label: toTitle(dm.branch.stems.main.natureName) , sublabel: toTitle(dm.branch.stems.main.elm.name), key: 'stem'},
        { dict: [ 
            ...dm.branch.stems.main.aspc.$dict_nature,
        ],  desat: CMImages.desat.aspects[dm.branch.stems.main.aspc.name], color: CMImages.color.aspects[dm.branch.stems.main.aspc.name], label: toTitle(dm.branch.stems.main.aspc.archetype), sublabel: toTitle(dm.branch.stems.main.aspc.name) , key: 'aspect' },
        { dict: dm.branch.stems.main.gdd.$dict_adj, desat: CMImages.desat.gods[dm.branch.stems.main.gdd.abbr], color: CMImages.color.gods[dm.branch.stems.main.gdd.abbr], label: toTitle(dm.branch.stems.main.gdd.archetype) , sublabel: dm.branch.stems.main.gdd.abbr.toUpperCase(), key: 'god'},
    ])

    const onTouchBranch = () => {
        let path
        if(list[0].key === 'stem'){
            path = `heavenlyStems.${dm.branch.stems.main.name}`
        }else if(list[0].key === 'branch'){
            path = `earthlyBranches.${dm.branch.name}`
        }else if(list[0].key === 'aspect'){
            path = `fourPillars.${dm.branch.stems.main.aspc.name}`
        }else if(list[0].key === 'god'){
            path = `fourPillars.${dm.branch.stems.main.gdd.abbr}`
        }
        navigation.push('Library', { path, hideClose: true })
        analytics.track('Bazi.Analysis.Ego.Branch')
    }

    return (
        <View style={styles.container}>
            <View style={styles.row}>
                <Toucher
                    onPress={() => {
                        const path = 'heavenlyStems.' + dm.stem.name
                        navigation.push('Library', { path, hideClose: true }) 
                        analytics.track('Bazi.Analysis.Ego.Stem')
                    }}
                    style={{ flex: 1 }}
                >
                    <View style={[styles.box]}>
                        <View style={[styles.imageWrap, { justifyContent: 'flex-end'}]}>
                            <Image
                                source={CMImages.color.stems[dm.stem.name]}
                                style={[styles.mainImage, { width: 42, height: 42}]}
                                resizeMode="contain"
                            />
                        </View>
                        <View style={[styles.titleWrap, { borderBottomWidth: 0.5, borderBottomColor: scolor.separator}]}>
                            <Text style={[
                                styles.title,
                            ]}>
                                { toTitle(dm.stem.natureName) }
                            </Text>
                        </View>
                    </View>
                </Toucher>
                <View style={[styles.content, { justifyContent: 'flex-end'}]}>
                    <Toucher
                        underlayColor={'transparent'}
                        onPress={() => {
                            const path = `elements.${dm.stem.elm.name}`
                            navigation.push('Library', { path, hideClose: true })
                        }}
                    >
                        <View style={[styles.cloud, { paddingTop:0.5}]}>
                            { dm.stem.elm.$dict_adj.map(word => (
                                <View style={[styles.wordWrap,
                                    // { backgroundColor: stemColor }
                                ]}>
                                <Text  numberOfLines={1} ellipsizeMode="clip" style={[
                                    styles.word,
                                    { color: stemColor }
                                ]}>{ toTitle(word) }</Text>
                                </View>
                            ))}
                        </View>
                    </Toucher>
                    <Toucher
                        underlayColor={'transparent'}
                        onPress={() => {
                            const path = `heavenlyStems.${dm.stem.name}`
                            navigation.push('Library', { path, hideClose: true })
                        }}
                    >
                        <View style={[styles.cloud]}>
                            { dm.stem.$dict_adj.map(word => (
                                <View style={[styles.wordWrap]}>
                                <Text  numberOfLines={1} ellipsizeMode="clip" style={[
                                    styles.word,
                                    { color: stemColor }
                                ]}>{ toTitle(word) }</Text>
                                </View>
                            ))}
                        </View>
                    </Toucher>
                </View>
            </View>
            
            <View style={styles.row}>
                <Toucher
                    onPress={onTouchBranch}
                    style={{ flex: 1 }}
                >
                    <View style={[styles.box ]}>
                        <View style={[styles.titleWrap, { borderTopWidth: 0.5, borderTopColor: scolor.separator}]}>
                            <Text style={[styles.title]}>
                                { list[0].label }
                            </Text>
                            { list[0].sublabel && (

                            <Text style={styles.subtitle}>
                                { list[0].sublabel }
                            </Text>
                            )}
                        </View>
                        <View style={[styles.imageWrap, { justifyContent: 'flex-start', }]}>
                            <Image
                                source={ list[0].color }
                                style={[styles.mainImage, { width: 42, height: 42}]}
                                resizeMode="contain"
                            />
                        </View>
                    </View>
                </Toucher>
                <View style={styles.content}>
                    <Toucher
                        underlayColor={'transparent'}
                        onPress={onTouchBranch}
                    >
                        <View style={[styles.cloud, {paddingBottom:0.5}]}>
                        { list[0].dict.map(word => (
                            <View style={[styles.wordWrap,
                                // { backgroundColor: branchColor }
                            ]}>
                                <Text numberOfLines={1} ellipsizeMode="clip" style={[
                                    styles.word,
                                    { color: branchColor}
                                ]}>{ toTitle(word) }</Text>
                            </View>
                        ))}
                        </View>
                    </Toucher>
                    <View style={{height:1, backgroundColor:scolor.separator}}/>
                    <View style={styles.buttons}>
                        { list.map((item, index) => {
                            if(index === 0){ return <Fragment/> }
                            return (
                                <Toucher 
                                    style={styles.miniBox}
                                    onPress={() => {
                                        const newList = _.cloneDeep(list)
                                        const head = newList.splice(0, index)
                                        const result = newList.concat(head)
                                        setList(result)
                                        analytics.track('Bazi.Analysis.Ego.Tabs')
                                    }}
                                >
                                    <Image 
                                        source={ list[index].desat }
                                        style={styles.mainImage}
                                        resizeMode={'contain'}
                                    />
                                </Toucher>
                            )
                        })}
                    </View>
                </View>
            </View>

        </View>
    )
}
export default withNavigation(DayMasterHolder);



