const ElasticHelper = (props) => {
    const result = []
    const start = () => {
        for(let m = 1; m < 13; m++){
            for(let d = 1; d < 31; d++){
                for(let h = 0; h < 24;h++){
                    if(!(h === 0 || h % 2 === 1)) continue
                    const time = DateTime.fromObject({  year: 2020, month: m, day: d, hour: h, minute: 30 })
                    if(!time.isValid) continue
                    const bazi = FourPillars.plot({ time })
                    const chart = QiMap.plot({ bazi, reference: 'hour' , appendMeta: true}) 
                    console.log(time.toFormat('yyyy-MM-dd h:mm'), chart)
                }
            }
        }
    }
    return (
        <TouchableHighlight
            style={{ width: 100, height: 100, backgroundColor: 'blue'}}
            onPress={ () => {
                start()
            }} 
        >
            <View/>
        </TouchableHighlight>
    )
}
export default ElasticHelper;