import { DateTime } from 'luxon'

import * as Ordinals from '../../Ordinals'
import * as WindWater from '../../WindWater'
import * as MysticDoors from '../../MysticDoors'
import * as Graphics from '../../Graphics'
import * as Tools from '../../Tools'
import * as ShenSha from '../../ShenSha'
import * as Jus from './Jus'

const palacesLuoShu = Tools.toProxy(['kan', 'kun','zhen','xun','center','qian','dui','gen','li'])
const earthStems = Tools.toProxy( ['wu','ji','geng','xin','ren','gui','ding','bing','yi'])

export const plot = ({
    bazi,
    reference = 'hour',
    starPath= 0,
    method=0,
    shiftLateZiStream=true,
    houseInput =null,
    appendDestiny = false,
    appendMeta = true,
    appendStyle = false,
}) => {
    let dun
    let ju
    const ref = reference 
    let refStemName 
    let refBranchName
    let lateZiStreamShifted = false;
    let housePeriod = null;
    let houseStemBranch = null;
    if(reference === 'house' &&  (!houseInput || !houseInput?.houseYear || !houseInput?.houseDegree || !houseInput.doorDegree)) return null


    if(ref !== 'house'){
        refStemName = bazi.pillars[ref].stem.name
        refBranchName = bazi.pillars[ref].branch.name
        if(method ===  1 && (['hour'].indexOf(reference) >= 0)){
            dun = Jus.chaiBu(bazi)[0]
            ju = Jus.chaiBu(bazi)[1]
        }else{
            const dat = Jus.zhiRun(reference, bazi)
            if(!dat) return;
            dun = dat[0]
            ju = dat[1]
        }

        if(shiftLateZiStream && ref === 'hour' && starPath === 0){
            if(bazi.info.time.hour === 23){
                lateZiStreamShifted = true
                if(refStemName === 'jia') refStemName = 'ren'
                else if(refStemName === 'bing') refStemName = 'jia';
                else if(refStemName === 'wu') refStemName = 'bing';
                else if(refStemName === 'geng') refStemName = 'wu';
                else if(refStemName === 'ren') refStemName = 'geng';
            } 
        }
    }

    if(houseInput?.houseYear && houseInput?.houseDegree && houseInput?.doorDegree){
        dun = 'yang'
        ju = WindWater.yearToPeriod(houseInput.houseYear)

        const doorSector = WindWater.degreeToMountain(houseInput.doorDegree)
        const faceDir = WindWater.degreeToMountain(houseInput.houseDegree).replace(/[0-9]/g, '');
        const branchNum = WindWater.qiMenFengShuiMap[ju][doorSector][faceDir]
        const pillar = Ordinals.pillarOrdering[branchNum]

        refStemName = pillar[0]
        refBranchName = pillar[1]
        housePeriod = ju
        houseStemBranch = refStemName + ' ' + refBranchName
    }





    const jiaGroup =  Ordinals.sixtyPillars[refStemName][refBranchName].stream
    const horseBranch = ShenSha.dayBranchAux.skyHorse[ Ordinals.branchOrdering.indexOf(refBranchName) ]
    const horsePalace = Ordinals.branches[horseBranch].palace

    //Void
    const voidBranches = Ordinals.streams[jiaGroup].void
    const voidPalaces = voidBranches.map(i => Ordinals.branches[i].palace)


    //Begin --------
    const payload = {}
    const palacesResult = {}

    palacesLuoShu.forEach(palace => { 
        palacesResult[palace] = { 
            plot: {}, 
            meta: {}
        } 
    })

    //Earth Plate
    const beginPalaceIndex = ju - 1 
    const beginPalace = palacesLuoShu[beginPalaceIndex]
    earthStems.forEach((stem, index) => {
        const pal = dun === 'yang' ?  palacesLuoShu[index + beginPalaceIndex] : palacesLuoShu[palacesLuoShu.length - index + beginPalaceIndex]
        palacesResult[pal]['plot']['earthStem'] = stem
    })

    //Heaven Plate
    let leadStem = Ordinals.streams[jiaGroup].leadStem



    const palacesCircular = Tools.toProxy(['kan','gen','zhen','xun','li','kun','dui','qian'])
    let refStemEarthPalace = null
    let heavenIsCenter = false
    let leadStemEarthPalace = null
    let leadStemIsCenter = false
    Object.keys(palacesResult).forEach(pal => {
        if(palacesResult[pal].plot.earthStem === refStemName) refStemEarthPalace = pal
        if(palacesResult[pal].plot.earthStem === leadStem) leadStemEarthPalace = pal
    })
    if(refStemEarthPalace === 'center'){
        heavenIsCenter = true
        refStemEarthPalace = 'kun'
    }
    if(leadStemEarthPalace === 'center'){
        leadStemIsCenter = true
        leadStemEarthPalace = 'kun'
    }
    if(refStemEarthPalace === null){ //couldn't find the palace. It must be "Jia" hour, 
        refStemEarthPalace = leadStemEarthPalace
    }

    //Calculate Heaven Plate
    const heavenLeadPalaceDiff =  8 - (palacesCircular.indexOf(refStemEarthPalace) - palacesCircular.indexOf(leadStemEarthPalace))

    palacesCircular.forEach((pal, index) => {
        const pes = palacesResult[pal].plot.earthStem
        const heavenStem = palacesResult[palacesCircular[index + heavenLeadPalaceDiff]].plot.earthStem

        palacesResult[pal].plot['heavenStem'] = heavenStem
    })
    palacesResult.center.plot.heavenStem = palacesResult.center.plot.earthStem

    //Doors
    const leadStemPalaceLuoShuIndex = palacesLuoShu.indexOf(leadStemEarthPalace) 
    const leadStemPalaceLuoShuTrueIndex = leadStemIsCenter ? 4 : leadStemPalaceLuoShuIndex
    const leadStemPalaceCircularIndex = palacesCircular.indexOf(leadStemEarthPalace)
    const doorCircularFlow = Tools.toProxy(['rest', 'life', 'harm', 'delusion', 'scenery','death', 'fear','open', ])
    const leadDoor = doorCircularFlow[leadStemPalaceCircularIndex]



    const stream = Ordinals.streams[jiaGroup].pillars
    const sCount = Tools.toProxy([1, 2, 3, 4, 5, 6, 7, 8, 9])

    const doorStreamEndpoint = stream.findIndex(i => i[0] === refStemName)
    let leadDoorBeginPalaceLuoShuIndex = dun === 'yang' ?  sCount[leadStemPalaceLuoShuTrueIndex + doorStreamEndpoint ] : sCount[leadStemPalaceLuoShuTrueIndex - doorStreamEndpoint ]
    let leadDoorStartingPalace = palacesLuoShu[leadDoorBeginPalaceLuoShuIndex-1] 
    let leadDoorStartingPalaceCircularIndex = palacesCircular.indexOf(leadDoorStartingPalace)

    if(leadDoorStartingPalace === 'center'){
        leadDoorStartingPalace = 'kun'
        leadDoorStartingPalaceCircularIndex = 5
        leadDoorBeginPalaceLuoShuIndex = 2
    }

    // console.log(stream)
    // console.log(jiaGroup, doorStreamEndpoint)
    // console.log('leadDoorStartingPalace', leadDoorStartingPalace)
    // console.log('leadDoorBeginPalaceLuoShuIndex', leadDoorBeginPalaceLuoShuIndex)
    // console.log('leadDoorStartingPalaceCircularIndex', leadDoorStartingPalaceCircularIndex)

    const hourStemEarthPalaceCircularIndex = palacesCircular.indexOf(refStemEarthPalace)
    const doorOffset = leadDoorStartingPalaceCircularIndex - leadStemPalaceCircularIndex
    palacesCircular.forEach((pal, index) => {
        const door = doorCircularFlow[index - doorOffset]
        palacesResult[pal].plot['door'] = door
    })

    //Stars
    let leadStar = null
    const starCircularFlow = Tools.toProxy(['grass','ambassador','destructor','assistant','hero','grain','pillar','heart'])
    if(starPath === 0 ){
        leadStar = starCircularFlow[leadStemPalaceCircularIndex]
        palacesCircular.forEach((pal, index) => {
            //Place at hour stem = heaven plate
            const star =  starCircularFlow[index - (hourStemEarthPalaceCircularIndex - leadStemPalaceCircularIndex)]
            palacesResult[pal].plot['star'] = star
        })
        palacesResult.center.plot.star = 'bird'
    }else if(starPath === 1){
        const starLuoShuFlow = Tools.toProxy(['grass', 'grain', 'destructor', 'assistant', 'bird', 'heart', 'pillar', 'ambassador', 'hero'])
        leadStar = leadStemIsCenter ? 'bird' : starCircularFlow[leadStemPalaceCircularIndex]
        const leadStarIndex = starLuoShuFlow.indexOf(leadStar)
        // console.log('leadStarIndex', leadStar, leadStarIndex)

        //Place at lead stem = heaven plate. However, follow the Kun rule in this case.
        let starPlacementIndex = null
        let lookup = leadStemIsCenter ? palacesResult.kun.plot.earthStem : leadStem
        // console.log('lookup', lookup)
        palacesLuoShu.forEach((pal, index) => { 
            if(palacesResult[pal].plot['heavenStem'] === lookup){ 
                starPlacementIndex = index 
            } 
        })
        if(refStemName === palacesResult.center.plot.heavenStem){
            starPlacementIndex = 4
        }
        // console.log('starPlacementIndex', starPlacementIndex)
        let shift = starPlacementIndex - leadStarIndex

        palacesLuoShu.forEach((pal, index) => {
            const star = starLuoShuFlow[index - shift]
            palacesResult[pal].plot['star'] = star
            // console.log('>', pal, index)
        })
    }


    const spiritCircularFlowForward = Tools.toProxy(['chief','snake','moon','harmony','hook','phoenix','earth','heaven'])
    const spiritCircularFlowReverse = Tools.toProxy(['chief','heaven','earth','tortoise','tiger','harmony','moon','snake'])
    const spiritFlow = dun === 'yang' ? spiritCircularFlowForward : spiritCircularFlowReverse
    const leadSpirit = spiritFlow[hourStemEarthPalaceCircularIndex]
    palacesCircular.forEach((pal, index) => {
        const spirit = spiritFlow[index - hourStemEarthPalaceCircularIndex]
        palacesResult[pal].plot['spirit'] = spirit
    })


    //period luck
    const periodLuckArr = Tools.toProxy([6, 7, 8, 9, 1, 2, 3, 4, 5]);
    palacesLuoShu.forEach((pal, index) => {
        palacesResult[pal].plot['periodNum'] = periodLuckArr[ju-1 + index]
    })



    //Add Data to Palaces
    palacesResult['kun'].earthStem
    palacesLuoShu.forEach(pal => {
        palacesResult[pal].plot.isLeadDoor = leadDoor === palacesResult[pal].plot.door
        palacesResult[pal].plot.isLeadStar = leadDoor === palacesResult[pal].plot.door

        palacesResult[pal].plot.name = pal
        palacesResult[pal].plot.palace = pal
        palacesResult[pal].plot.number = palacesLuoShu.indexOf(pal) + 1
        palacesResult[pal].plot.void = voidPalaces.indexOf(pal) >= 0 ? true : false
        palacesResult[pal].plot.horse = pal === horsePalace ? true : false 
        palacesResult[pal].plot.hiddenEarthStem = pal === 'kun' ? palacesResult['center'].plot.earthStem : null
        palacesResult[pal].plot.hiddenHeavenStem = palacesResult[pal].plot.heavenStem === palacesResult['kun'].plot.earthStem ? palacesResult['center'].plot.earthStem : null

        palacesResult[pal].plot.isEarthLeadStem = (leadStem === palacesResult[pal].plot.earthStem) ||  (leadStem === palacesResult[pal].plot.hiddenEarthStem)
        palacesResult[pal].plot.isHeavenLeadStem = (leadStem === palacesResult[pal].plot.heavenStem) || (leadStem === palacesResult[pal].plot.hiddenHeavenStem)

        palacesResult[pal].plot.bird = palacesResult[pal].plot.star === 'grain' ? true : false
    })
    payload.palaces = palacesResult

    //Highlights for Forecasting
    let forecastStems = null
    if(reference === 'hour'){
        forecastStems = {}
        const hourPillar = bazi.pillars.hour
        const dayPillar = bazi.pillars.day
        if(hourPillar.stem.name === 'jia'){
            const leadStem = Ordinals.streams[Ordinals.sixtyPillars[hourPillar.stem.name][hourPillar.branch.name].stream].leadStem
            forecastStems['hour'] = leadStem
        }else{
            forecastStems['hour'] = bazi.pillars.hour.stem.name
        }
        if(dayPillar.stem.name === 'jia'){
            const leadStem = Ordinals.streams[Ordinals.sixtyPillars[dayPillar.stem.name][dayPillar.branch.name].stream].leadStem
            forecastStems['day'] = leadStem
        }else{
            forecastStems['day'] = bazi.pillars.day.stem.name
        }
    }

    payload.details = {
        forecastStems,
        dun,
        ju,
        method,
        starPath,
        leadDoor,
        leadStar,
        leadStem,
        reference,
        shiftLateZiStream,
        lateZiStreamShifted,
        reference,
        housePeriod,
        houseStemBranch,
        houseInput,
        grainIsBird: leadStemIsCenter  //if lead star is center, lead star is bird (replace it with grain)
    }
    payload.bazi = bazi

    if(appendMeta)
        appendQiMenMeta(payload)
    if(appendDestiny) //must come after appendMeta
        appendQiMenDestiny(payload)
    if(appendStyle)
        styleQimenChart(payload)

    return payload
}






export const appendQiMenMeta = (chart) => {
    const palaces = chart.palaces
    const details = chart.details
    const pillars = chart.bazi.pillars

    //Determine Victories for the chart
    chart.details['victories'] = { light: null, blessing: null, force: null }
    let lightLookupStar
    Object.keys(palaces).forEach((name) => {
        const plot = palaces[name].plot
        if(plot.door === 'life') chart.details.victories['force'] = name
        if(plot.spirit === 'heaven') chart.details.victories['blessing'] = name
        if(plot.spirit === 'chief'){
            const natalPositions = {
                stars:{
                    qian: 'heart',
                    kan: 'grass',
                    gen: 'ambassador',
                    zhen: 'destructor',
                    xun: 'assistant',
                    li: 'hero',
                    kun: 'grain',
                    dui: 'pillar',
                }
            }
            lightLookupStar = natalPositions.stars[name]
        }
    })
    Object.keys(palaces).forEach(name => {
        if(palaces[name].plot.star === lightLookupStar){
            chart.details.victories['light'] = name
        }
    })

    //Determine Basic Metadata
    Object.keys(palaces).forEach((name) => {
        const plot = palaces[name].plot
        if(name === 'center') return 
        const meta = {}
        meta['score'] = 0
        meta['heavenStems'] = []
        meta['earthStems'] = []
        meta['formations'] = []
        meta.heavenStems.push(plot.heavenStem)
        if(plot.isHeavenLeadStem) meta.heavenStems.push('jia')
        if(plot.hiddenHeavenStem) meta.heavenStems.push(plot.hiddenHeavenStem)

        meta.earthStems.push(plot.earthStem)
        if(plot.isEarthLeadStem) meta.earthStems.push('jia')
        if(plot.hiddenEarthStem) meta.earthStems.push(plot.hiddenEarthStem)

        meta.heavenStems.forEach(hs => {
            meta.earthStems.forEach(es => {
                meta.formations.push({
                    heavenStem: hs,
                    earthStem: es,
                    formation: MysticDoors.formations[hs][es]
                })
            })
        })

        const solarTermNum = chart.bazi.info.solarTerm.thisTerm.data.num
        const doorStrengthScoreMap = { 8: 'peak', 7: 'strong', 6: 'weak', 5: 'trap', 4: 'dead' }
        meta['door'] = {
            specialInteraction: MysticDoors.doors[plot.door].specialInteraction[name],
            palaceInteraction: MysticDoors.doors[plot.door].palaceInteraction[name],
            strength: doorStrengthScoreMap[MysticDoors.doors[plot.door].strength[solarTermNum]],
            desc: MysticDoors.doors[plot.door].desc,
        }
        meta['star'] = {
            specialInteraction: MysticDoors.stars[plot.star].specialInteraction[name],
            palaceInteraction: MysticDoors.stars[plot.star].palaceInteraction[name],
            strength: MysticDoors.stars[plot.star].strength[name],
        }
        if(typeof meta.star.strength === 'undefined'){
        }
        meta['hour'] = {
            doorInteraction: MysticDoors.hours[pillars.hour.stem.name][plot.door]
        }
        meta['structuresArray'] = []
        meta['structuresMap'] = {
            positive: [],
            neutral:[],
            negative: [],
        }

        //Determine Structures
        Object.keys(MysticDoors.structures).forEach(sKey => {
            let matchedRule = null
            for(const rule of MysticDoors.structures[sKey].match){
                let match = true
                Object.keys(rule).forEach(field => {
                    let val = rule[field]
                    if(val === '$yearStem'){ val = pillars.year.stem.name }
                    if(val === '$monthStem'){ val = pillars.month.stem.name }
                    if(val === '$dayStem'){ val = pillars.day.stem.name }
                    if(val === '$hourStem'){ val = pillars.hour.stem.name }
                    if(field === 'heavenStem'){
                        if(plot.heavenStem !== val && plot.hiddenHeavenStem !== val){
                            match = false
                        }
                    }else if(field === 'earthStem'){
                        if(plot.earthStem !== val && plot.hiddenEarthStem !== val){
                            match = false
                        }
                    }else if(plot[field] !== val){
                        match = false
                    }
                })
                if(match){
                    matchedRule = JSON.stringify(rule)
                    break
                }
            }
            if(matchedRule){
                const rating = MysticDoors.structures[sKey].rating
                const result = {
                    name: sKey,
                    rating: rating,
                    matchedRule,
                }
                meta['structuresArray'].push(result)
                rating > 0 && meta['structuresMap']['positive'].push(result)
                rating === 0 && meta['structuresMap']['neutral'].push(result)
                rating < 0 && meta['structuresMap']['negative'].push(result)
            }
        })

        palaces[name]['meta'] = meta
    })
}


