export const appendQiMenDestiny = (hourChart, options = {}) => {
    const dayChart = plot({ bazi: hourChart.bazi ,reference: 'day' , ...options})

    let destinyPalace = null
    Object.keys(hourChart.palaces).forEach(name => {
        if(name === 'center') return
        const plot = hourChart.palaces[name].plot
        const destiny = { labels: []}
        switch(name){
            case 'qian':
                destiny['range'] = [0, 15]
                break
            case 'kan':
                destiny['range'] = [16, 30]
                break
            case 'gen':
                destiny['range'] = [31, 45]
                break
            case 'zhen':
                destiny['range'] = [46, 60]
                break
            case 'xun':
                destiny['range'] = [61, 75]
                break
            case 'li':
                destiny['range'] = [76, 90]
                break
            case 'kun':
                destiny['range'] = [91, 105]
                break
            case 'dui':
                destiny['range'] = [106, 120]
                break
            default:
                break
        }
        switch(plot.door){
            case "open":
                destiny.labels.push('career');
                break
            case "life":
                destiny.labels.push('wealth');
                destiny.labels.push('business');
                break
            case "rest":
                destiny.labels.push('retirement');
                destiny.labels.push('family');
                break
            case "delusion":
                destiny.labels.push('knowledge');
                break
            case "harm":
                destiny.labels.push('risk');
                destiny.labels.push('business');
                break
            case "fear":
                destiny.labels.push('wellness');
                break
            case "death":
                destiny.labels.push('assets');
                break
            case "scenery":
                destiny.labels.push('reputation');
                break
            default: 
                break;
        }
        switch(plot.star){
            case "assistant":
                destiny.labels.push('education')
                break
            case "grain":
                destiny.labels.push('health')
                break
            default:
                break
        }
        switch(plot.spirit){
            case "snake":
                destiny.labels.push('karmic')
                break
            case "harmony":
                destiny.labels.push('relationship')
                break
            default:
                break
        }
   
        if(dayChart.details.leadStem === plot.heavenStem || dayChart.details.leadStem === plot.hiddenHeavenStem){
            destiny.labels.push('soul')
        }

        const hourStem = hourChart.bazi.pillars.hour.stem.name
        const dayStem = hourChart.bazi.pillars.day.stem.name
        const dayBranch = hourChart.bazi.pillars.day.branch.name
        const monthStem = hourChart.bazi.pillars.month.stem.name
        const yearStem = hourChart.bazi.pillars.year.stem.name

        if(name === Ordinals.branches[dayBranch].palace){
            destiny.labels.push('subconscious')
        }

        if(plot.heavenStem === hourStem || plot.hiddenHeavenStem === hourStem || (hourStem === 'jia' && plot.isHeavenLeadStem)){
            destiny.labels.push('children')
        }
        if(plot.heavenStem === monthStem || plot.hiddenHeavenStem === monthStem || (monthStem === 'jia' && plot.isHeavenLeadStem)){
            destiny.labels.push('siblings')
        }
        if(plot.heavenStem ===  yearStem || plot.hiddenHeavenStem === yearStem || (yearStem === 'jia' && plot.isHeavenLeadStem)){
            destiny.labels.push('parent')
        }

        if( 
            (dayStem === 'jia' && (dayChart.details.leadStem === plot.heavenStem || dayChart.details.leadStem === plot.hiddenHeavenStem)) || 
            (dayStem === plot.heavenStem || dayStem === plot.hiddenHeavenStem)
        ){
            destiny['isDestinyPalace'] = true
            destinyPalace = name
            hourChart.details.destinyPalace = name
        }


        hourChart.palaces[name].meta.destiny = destiny
    })
    if(!destinyPalace) console.error("No destiny palace", hourChart.bazi.info.time.toISO())


    const counteringPalaces = {
        qian:  ['li'],
        kan: ['kun', 'gen'],
        gen: ['zhen','xun'],
        zhen: ['dui','qian'],
        xun:['dui','qian'],
        li: ['kan'],
        kun: ['zhen','xun'],
        dui: ['li'],
    }
    counteringPalaces[destinyPalace].forEach(name => {
        if(name === 'center') return
        hourChart.palaces[name].meta.destiny.labels.push('obstruction')
    })
}

export const styleQimenChart = (chart) => {
    const details = chart.details
    const palaces  = chart.palaces
    if(!palaces || !details) return 

    const badColor = Graphics.colors.states.bad
    const goodColor = Graphics.colors.states.good
    const neutralColor = Graphics.colors.states.neutral

    Object.keys(palaces).forEach(name => {
        const palace = palaces[name]
        const meta = palace.meta
        const plot = palace.plot
        if(name === 'center') return 

        //Door
        meta.door['style'] = {}
        meta.door['palaceInteractionIcon'] = ''
        meta.door['specialInteractionIcon'] = null
        meta.door['suitable'] = MysticDoors.doors[plot.door].suitable
        meta.door['unsuitable'] =  MysticDoors.doors[plot.door].unsuitable
        switch(meta.door.specialInteraction){
            case "grave":
                meta.door.specialInteractionIcon = 'christianity'
                break;
            // case "fu yin":
            //     meta.door.specialInteractionIcon = '⨁'
            //     break;
            // case "fan yin":
            //     meta.door.specialInteractionIcon = '⨂'
            //     break;
        }
        switch(meta.door.palaceInteraction){
            case "harmony":
                meta.door.palaceInteractionIcon = 'sync'
                break
            case "produce":
                meta.door.palaceInteractionIcon = 'redo'
                break
            case "produced":
                meta.door.palaceInteractionIcon = 'undo'
                break
            case "countered":
                meta.door.palaceInteractionIcon = 'arrow-bottom-left'
                break
            case "compelled":
                meta.door.palaceInteractionIcon = 'arrow-top-right'
                break
           
        }

        switch(meta.door.strength){
            case "dead":
                meta.door.style['textDecorationLine'] = 'line-through'
                break
            case "trap":
                meta.door.style['fontStyle'] = 'italic'
                break
            case "weak":
                meta.door.style['fontWeight'] = 'normal'
                break
            case "strong":
                meta.door.style['fontWeight'] = '500'
                break
            case "peak":
                meta.door.style['fontWeight'] = '800'
                break
        }

        //Star Interactions
        meta.star['style'] = {}
        meta.star['suitable'] = MysticDoors.stars[plot.star].suitable
        meta.star['unsuitable'] = MysticDoors.stars[plot.star].unsuitable
        meta.star['palaceInteractionIcon'] = ''
        switch(meta.star.palaceInteraction){
            case "harmony":
                meta.star.palaceInteractionIcon = 'sync'
                break
            case "produce":
                meta.star.palaceInteractionIcon = 'redo'
                break
            case "produced":
                meta.star.palaceInteractionIcon = 'undo'
                break
            case "countered":
                meta.star.palaceInteractionIcon = 'arrow-bottom-left'
                break
            case "compelled":
                meta.star.palaceInteractionIcon = 'arrow-top-right'
                break
           
        }
        switch(meta.star.strength){
            case "dead":
                meta.star.style['textDecorationLine'] = 'line-through'
                break
            case "trap":
                meta.star.style['fontStyle'] = 'italic'
                break
            case "weak":
                meta.star.style['fontWeight'] = 'normal'
                break
            case "strong":
                meta.star.style['fontWeight'] = '500'
                break
            case "peak":
                meta.star.style['fontWeight'] = '800'
                break
        }
        if(plot.bird){
            meta['bird'] = {
                suitable: MysticDoors.stars['bird'].suitable,
                unsuitable: MysticDoors.stars['bird'].unsuitable,
            }
        }
       
        //Spirit Content
        meta.spirit = {}
        meta.spirit['style'] = {}
        meta.spirit['suitable'] = MysticDoors.spirits[plot.spirit].suitable
        meta.spirit['unsuitable'] = MysticDoors.spirits[plot.spirit].unsuitable
    })
}



















