export const getStemRawScore = (type, stem, mb) => {
    return Math.round(Scores.multiplier[type] * Scores.stemWeights[stem][mb] * 10)
}

export const getLifePalace = (monthBranch, hourBranch, yearStem, appendMonth) => {
    let month = monthBranch
    if(appendMonth) month = Ordinals.branchOrdering[Ordinals.branchOrdering.indexOf(monthBranch) + 1]
    const branch = lifePalaceBranch[month][hourBranch]
    const stem = lifePalaceStem[yearStem][branch]
    return [stem, branch]
}

//Month stem, branch
export const getConceptionPalace = (stem, branch) => {
    const newStemIndex = Ordinals.stemOrdering.indexOf(stem) + 1
    let conceptionStem = null
    if(newStemIndex > Ordinals.stemOrdering.length - 1){
        conceptionStem = Ordinals.stemOrdering[0]
    }else{
        conceptionStem = Ordinals.stemOrdering[newStemIndex]
    }
    let conceptionBranch = null
    const newBranchIndex = Ordinals.branchOrdering.indexOf(branch) + 3
    if(newBranchIndex > Ordinals.branchOrdering.length - 1){
        conceptionBranch = Ordinals.branchOrdering[newBranchIndex - Ordinals.branchOrdering.length]
    }else{
        conceptionBranch = Ordinals.branchOrdering[newBranchIndex]
    }
    return [conceptionStem, conceptionBranch]
}

//luck cycles, DateTime
export const getCurrentLuckPillar = (lucks, point) => {
    let currentLuckPillar = null
    for(let i = 0 ; i < lucks.length; i++){
        if(point >= lucks[i].time){
            if( i+1 < lucks.length){
                if(point < lucks[i+1].time){
                    currentLuckPillar = lucks[i]
                }
            }else{
                currentLuckPillar = lucks[i]
            }
        }
    }
    if(!currentLuckPillar && point >= lucks[0].time){
        currentLuckPillar = lucks[0]
    }
    if(!currentLuckPillar && point < lucks[0].time){
        currentLuckPillar = lucks[0]
    }
    return currentLuckPillar
}


