export const getSummary = (chart, line=0.1) => {
	const ratios = chart.meta.weights.ratio.gods
	const elementRatios = chart.meta.weights.ratio.elements
    const aspects = {
        resource:[],
        companion:[],
        output:[],
        wealth:[],
        power:[],
    }
    const compare = (aspect, first, second) => {
        if(ratios[first] || ratios[second]){
            if(ratios[first] > ratios[second]){
                if( (ratios[first] - ratios[second]) / ratios[first] > line){
                    aspects[aspect]= [first]
                }else{
                    aspects[aspect]= [first, second]
                }
            }else{
                if( (ratios[second] - ratios[first]) / ratios[second] > line){
                    aspects[aspect] = [second]
                }else{
                    aspects[aspect] = [second, first]
                }
            }
        } 
    }
    compare('resource', 'dr','ir')
    compare('companion', 'rw','f')
    compare('output', 'ho','eg')
    compare('wealth', 'dw','iw')
    compare('power', 'do','7k')
    const resultAspects = {}
    Object.keys(aspects).forEach(aspect => {
        resultAspects[aspect] = aspects[aspect]
    })

    const orderedElements = _.mapValues(_.invert(_.invert( chart.meta.weights.raw.elements)),parseInt);
    const elementResults = {}
    elementResults['weak'] = _.first(Object.keys(orderedElements))
    elementResults['strong'] = _.last(Object.keys(orderedElements))
    const stemResults = { weak: null, strong: null} 
    const weakestStems = Ordinals.elements[elementResults.weak].stems
    const strongestStems= Ordinals.elements[elementResults.strong].stems
    const stems = chart.meta.weights.raw.stems
    const weakStem =  _.first(weakestStems.sort((a, b) => stems[a] > stems[b] ? 1 : -1 ))
    const strongStem = _.first(strongestStems.sort((a, b) => stems[a] < stems[b] ? 1 : -1 ))

    const aspectMap = chart.meta.maps.elementToAspect

    chart.meta.summary = {
        stemStrength: { weak: weakStem, strong: strongStem},
        elementStrength: elementResults,
        aspectStrength:  { weak: aspectMap[elementResults.weak], strong: aspectMap[elementResults.strong] },
        aspectList: resultAspects,
        ratioNum: { strong: elementRatios[elementResults.strong], weak: elementRatios[elementResults.weak]},
    }
	return chart
}



const isFanYin = (p1, p2) => {
    const p1Key = p1.stem.name + '-' + p1.branch.name
    const p2Key = p2.stem.name + '-' + p2.branch.name
    if(Ordinals.sixtyPillars[p1.stem.name][p1.branch.name].hostFanYin.join('-') === p2Key)
        return 'host'
    if(Ordinals.sixtyPillars[p1.stem.name][p1.branch.name].guestFanYin.join('-') === p2Key)
        return 'guest'
    return null
}

const isFuYin = (p1, p2) => {
    return p1.stem.name === p2.stem.name && p1.branch.name === p2.branch.name
}


export const extendAuxDataChart = (chart, root = null) => {
    const pillarKeys = ['year','month','day','hour']
    if(chart.info.hourUnknown) pillarKeys.pop()
    pillarKeys.forEach(key => {
        const keys = _.cloneDeep(pillarKeys)
        keys.splice(keys.indexOf(key) , 1 )
        extendAuxData(chart.pillars[key], DateTime.local(), root || chart, keys)
    })
}

export const extendAuxData = (pillar, time, root, pillarKeys) => {
    const branchName = pillar.branch.name
    const stemName = pillar.stem.name

    let branchInteractions = getBranchInteractions(root, pillar.branch, time, pillarKeys)
    const specialInteractions = getSpecialInteractions(root, pillar.branch, time, pillarKeys, pillar)
    branchInteractions = branchInteractions.concat(specialInteractions)
    branchInteractions.sort((a, b) => {  return Ordinals.branchInteractionOrdering.indexOf(a.relation) - Ordinals.branchInteractionOrdering.indexOf(b.relation) })

    pillar.branch.interactions = branchInteractions
    pillar.stem.interactions = getStemInteractions(root, pillar.stem, time, pillarKeys)
    pillar.stars = ShenSha.starsFromPillar(root, pillar).sort((a, b) => (a.rating < b.rating) ? 1 : -1 )
    pillar.annualStars = ShenSha.annualStarAux['zi'][pillar.branch.name].sort((a, b) => (a.rating < b.rating) ? 1 : -1 )

    pillar.specialMatch = ShenSha.getSpecialPillars(root, pillar)

    pillar.interactions = getPillarInteractions(root, pillar, pillarKeys)

    pillar.stage = {
        pillar: Ordinals.twelveStagesData[ pillar.stem.twelveStages.indexOf(branchName)],
        dm: Ordinals.twelveStagesData[ root.pillars.day.stem.twelveStages.indexOf(branchName)],
    }

    pillar.naYin = {
        element: Ordinals.sixtyPillars[stemName][branchName].naYin[0],
        name: Ordinals.sixtyPillars[stemName][branchName].naYin[1],
        chinese: Ordinals.sixtyPillars[stemName][branchName].naYin[2],
    }

} 


export const getPillarInteractions = (root, pillar, pillarKeys) => {
    const results = []
    pillarKeys.forEach(key => {
        if(!root.pillars[key]) return

        const fuYin = isFuYin(root.pillars[key], pillar)
        const fanYin = isFanYin(root.pillars[key], pillar)
        if(fuYin){
            results.push({
                relation: 'Fu Yin',
                type: '',
                affects: [{
                    pillar: key,
                    stem: root.pillars[key].stem.name,
                    branch: root.pillars[key].branch.name,
                }]
            })
        }
        if(fanYin){
            results.push({
                relation: `Fan Yin`,
                type: fanYin,
                affects: [{
                    pillar: key,
                    stem: root.pillars[key].stem.name,
                    branch: root.pillars[key].branch.name,
                }]
            })
        }

        const stemCombo = pillar.stem.combine === root.pillars[key].stem.name
        const branchCombo = pillar.branch.combine === root.pillars[key].branch.name
        let branchHalfHarmony = null;
        Object.keys(Ordinals.branchSpecialRelations.harmony).forEach(el => {
            if(_.intersection(Ordinals.branchSpecialRelations.harmony[el], [root.pillars[key].branch.name, pillar.branch.name]).length === 2){
                branchHalfHarmony = el
            }
        })

        if(stemCombo && (branchCombo )){
            results.push({
                relation: `Pillar Combo`,
                type: '',
                affects: [{
                    pillar: key,
                    stem: root.pillars[key].stem.name,
                    branch: root.pillars[key].branch.name,
                }]
            })
        }


    })
    return results;
}

export const getStemInteractions = (root, theStem, time, pillarKeys) => {
    const currentLuckPillar =  getCurrentLuckPillar(root.luck, time)
    const results = []
    const map =  dms[root.pillars.day.stem.name].stemsToGods
    const chartStems = {}

    pillarKeys.forEach(key => {
        if(key === 'luck') chartStems[key] = currentLuckPillar.pillar.stem.name
        else               chartStems[key] = root.pillars[key]?.stem.name
    })

    pillarKeys.forEach(key => {
        if(theStem.clashes.indexOf(chartStems[key]) >= 0){
            results.push({
                relation: 'conflict',
                affects: [{
                    pillar: key,
                    stem: chartStems[key],
                    god: map[chartStems[key]]
                }]
            })
        }
        if(theStem.combine === chartStems[key]){
            results.push({
                relation: 'combo',
                relationElementResult: theStem.combineResult,
                affects: [{
                    pillar: key,
                    stem: chartStems[key],
                    god: map[chartStems[key]],
                }]
            })
        }
    })
    return results
}

export const getBranchInteractions = (root, theBranch, time, pillarKeys) => {
    const currentLuckPillar = getCurrentLuckPillar(root.luck, time)

    let results = []
    const map =  dms[root.pillars.day.stem.name].stemsToGods
    const chartBranches = {}
    pillarKeys.forEach(key => {
        if(key === 'luck') chartBranches[key] = currentLuckPillar.pillar.branch.name
        else               chartBranches[key] = root.pillars[key]?.branch.name
    })
    pillarKeys.forEach(key => {
        const relations = theBranch.relations[chartBranches[key]]
        if(relations && relations.length > 0){
            relations.forEach(name => {
                const data = {
                    relation: name,
                    affects: [{
                        pillar: key,
                        branch: chartBranches[key],
                        gods: Ordinals.branches[chartBranches[key]]._hiddenStemsArr.map(s => s ? map[s] : null)
                    }]
                }
                if(name === '6 combo'){
                    data['relationElementResult'] = theBranch.combineResult
                }else if(name === 'hidden combo'){
                    data['relationElementResult'] = theBranch.hiddenCombineResult
                }
                results.push(data)
            })
        }
    })
    return results
}

export const getSpecialInteractions = (root, theBranch, time, pillarKeysOrig, pillar) => {
    const currentLuckPillar =  getCurrentLuckPillar(root.luck, time)
    const map =  dms[root.pillars.day.stem.name].stemsToGods
    const pillarKeys = _.cloneDeep(pillarKeysOrig)

    if(pillar.name !== 'luck')
        if(time.toMillis() !== root.info.time.toMillis()) 
            pillarKeys.unshift('luck') //add luck pillar to comparison if charts are different.

    const pillarBranches = []
    pillarKeys.forEach(key => { //convert keys to branches
        if(key === 'luck'){
            pillarBranches.unshift(currentLuckPillar.pillar.branch.name)
        }else{
            pillarBranches.push(root.pillars[key]?.branch.name)
        }
    })
    const results = []
    Object.keys(Ordinals.branchSpecialRelations).forEach(title => {
        Object.keys(Ordinals.branchSpecialRelations[title]).forEach(key => {
            const frame = Ordinals.branchSpecialRelations[title][key]
            if(frame.indexOf(theBranch.name) >= 0){
                const intersection = frame.filter(value => pillarBranches.concat([theBranch.name]).includes(value))
                // console.log(intersection, title, key)
                if(intersection.length === 2 && ['direction', 'penalty'].indexOf(title) >= 0){
                    //Doesn't count. Must need 3.
                }else if(intersection.length >= 2){
                    const intersectionWithoutBranch = intersection.filter(i => i !== theBranch.name)
                    let nameOfRelation = title
                    if(title === 'harmony'){
                        nameOfRelation = intersection.length === 3 ? `${title}` : `⅔ ${title}`
                    }else if(title === 'penalty'){
                        nameOfRelation = key + ' penalty' 
                    }
                    const data = {
                        relation: nameOfRelation,
                        relationElementResult: title === 'penalty' ? null : key,
                        affects: []
                    }
                    intersectionWithoutBranch.forEach(br => {
                        pillarBranches.forEach((origBranch , index) => {
                            if(origBranch === br){
                                data.affects.push({
                                    pillar: pillarKeys[index],
                                    branch: br,
                                    gods: Ordinals.branches[br]._hiddenStemsArr.map(s => s ? map[s] : null)
                                })
                            }
                        })
                    })
                    results.push(data)
                }
            }
        })
    }) 
    return results
}






























