import SectionHeader from '../Layout/SectionHeader'


class TwelveStagesList extends React.Component{
    static navigationOptions = ({ navigation }) => {
        const { params={} } = navigation.state 
		return {
            title: 'Twelve Stages',
        }
    }
    state={
        data: []
    }
    constructor(props){
        super(props)
        this.stem = this.props.navigation.getParam('stem') || 'jia'
    }
    componentDidMount(){
        const data = []
        Ordinals.branchOrdering.forEach(branch => {
            const stage = Ordinals.twelveStagesData[Ordinals.stems[this.stem].twelveStages.indexOf(branch)]
            data.push({
                branch,
                stage,
                backgroundColor: Graphics.colors.elements.light[Ordinals.branches[branch].element],
            })
        })
        this.setState({ data })
        analytics.track('Library.TwelveStagesList')
    }
    render(){
        const stemInfo = Ordinals.stems[this.stem]
        return (
            <View style={styles.container}>
                <SectionHeader
                    title={`${stemInfo.chinese } ${toTitle(stemInfo.natureName)} — ${ toTitle(stemInfo.elementName) } (${toTitle(this.stem)})`}
                />
                <FlatList
                    keyboardShouldPersistTaps={'always'}
                    ref={sectionList => { this.sectionList = sectionList; }}
                    data={this.state.data}
                    keyExtractor={(item, index) => index.toString()}
                    inverted={false}
                    ItemSeparatorComponent={() => (<View style={styles.separator}></View>)}
                    renderItem={({ item }) => {
                        return (
                            <View style={styles.row}>
                                <View style={[styles.sideLabelWrap,
                                    { backgroundColor: item.backgroundColor}
                                ]}>
                                    <Text style={[styles.sideLabel]}>{ toTitle(Ordinals.branches[item.branch].season) }</Text>
                                </View>
                                <Toucher
                                    onPress={() => {
                                        const path = 'earthlyBranches.' + item.branch
                                        this.props.navigation.push('Library', {path,  hideClose: true })
                                    }} 
                                >
                                    <View
                                        style={[styles.box,
                                            { backgroundColor: item.backgroundColor}
                                        ]} 
                                    >
                                        <Image 
                                            source={ CMImages.color.branches[item.branch]}
                                            style={styles.image}
                                            resizeMode={'contain'}
                                        />
                                     
                                        <Text style={styles.h3}>
                                            { toTitle(Ordinals.branches[item.branch].animalName) }
                                        </Text>
                                        <Text style={styles.chinese}>
                                            { Ordinals.branches[item.branch].chinese }
                                        </Text>
                                    </View>
                                </Toucher>
                                <View
                                    style={{ flex: 1 }}
                                    
                                >
                                    <View style={styles.mid}>
                                        <Text style={styles.h1}>{ item.stage.number }. { toTitle(item.stage.name) }  { item.stage.chinese }</Text>
                                        <Text style={styles.h2}>{ item.stage.visual } ({item.stage.strength })</Text>
                                    </View>
                                </View>
                            </View>
                        )
                    }}
                    ListFooterComponent={<View style={styles.separator}/>}
                />
            </View>
        )
    }
}

