const YinYangBar = (props) => {
    const { pillar, time} = props
    const [state, setState] = useState(null)

    let progress = 0
    let yangNum = null
    let yinNum = null
    if(pillar.name === 'hour'){
        const begin = time.set({ hour: 0 , minute: 0, second: 0}) //high yin, low yang 
        const mid = begin.plus({ seconds: 43200 }) //low yin, high yang
        const end = time.set({ hour: 23, minute: 59, second: 59}) //high yin, low yang
        progress = (time.diff(begin, 'seconds').seconds / 86400 * 100)

        yinNum = Math.abs(time.diff(mid, 'seconds').seconds) 
        yangNum = (43200 - yinNum) 

    }else if(pillar.name === 'day'){
        let begin, end
        const num = pillar.branch.number
        if(num === 0){
            if(time.hour < 12){
                begin = time.minus({ days: 12 }).startOf('day').plus({ hours: 12 })
            }else{
                begin = time.set({ hours: 12, minutes: 0, seconds: 0 })
            }
        }else{
            begin = time.minus({ days: num }).startOf('day').plus({ hours: 12 })
        }
        end = begin.plus({ days: 12 })

        const mid = begin.plus({ minutes: Math.abs(begin.diff(end, 'minutes').minutes / 2) })
        const totalTime = end.diff(begin, 'minutes').minutes

        progress = (time.diff(begin, 'minutes').minutes /   totalTime * 100)


        yinNum = Math.abs(time.diff(mid, 'minutes').minutes)
        yangNum = (17280/2 - yinNum)  //12 days to minutes / 2
    }else if(pillar.name === 'month'){
        const bazi = FourPillars.plot({ time }) 
        const { terms, currentIndex } =  SolarCal.getMonthlyTerms({ time, showMidTerm: true })

        const begin = SolarCal.findTerm({terms, current: currentIndex, num: 21,  direction:'backward' }).time
        const end = SolarCal.findTerm({terms, current: currentIndex, num: 21,  direction:'forward' }).time
        const totalTime = end.diff(begin, 'minutes').minutes
        const mid = begin.plus({ minutes: totalTime / 2})
        progress = (time.diff(begin, 'minutes').minutes /  totalTime * 100)

        yinNum = Math.abs(time.diff(mid, 'minutes').minutes) 
        yangNum = ((totalTime/2)- yinNum) 

    }else if(pillar.name === 'year'){
        let begin, end
        const num = pillar.branch.number
        const beginningOfYear = SolarCal.getYearJie(time)
        const halfYearDays = (365.25/2)
        if(num === 0){
            if(time < beginningOfYear.plus({ days: halfYearDays })){  //august 4
                begin = beginningOfYear.plus({ days: halfYearDays }).minus({ years: 12 })
            }else{
                begin = beginningOfYear.plus({ days: halfYearDays })
            }
        }else{
            begin =  SolarCal.getYearJie(time.minus({years: num })).plus({ years: 0.5 }) 
            //on transition days, this may be off by a little
        }
        end = begin.plus({ years: 12 })

        // console.log('>> ', beginningOfYear.toFormat('yyyy-MMM-d'))
        // console.log('B  ', begin?.toFormat('yyyy-MMM-d'))
        // console.log('E  ', end?.toFormat('yyyy-MMM-d'))

        const mid = begin.plus({days: Math.abs(begin.diff(end, 'days').days / 2) })
        const totalTime = end.diff(begin, 'days').days
        progress = ((time.diff(begin, 'days').days / totalTime) * 100)

        yinNum = Math.abs(time.diff(mid, 'days').days)
        yangNum = ( (365.25 * 12)/2   - yinNum )
    }else{
        const br = pillar.branch
        progress = Math.round((br.number + 1) / 12 * 100)
        yangNum = br.balance[0]
        yinNum = br.balance[1]
    }
    if(yangNum === null || yinNum === null) return <Fragment/>
    let opacity = yinNum / (yangNum + yinNum)

    const flow = [
        { val: 1, element: 'water' },
        { val: 2, element: 'earth' },
        { val: 4, element: 'wood' },
        { val: 2, element: 'earth' },
        { val: 4, element: 'fire' },
        { val: 2, element: 'earth' },
        { val: 4, element: 'metal' },
        { val: 2, element: 'earth' },
        { val: 3, element: 'water' },
    ]
    
    const [mode, setMode] = useState(true)

    return (
        <Toucher
            onPress={() => {
                setMode(!mode)
            }}
            underlayColor={'transparent'}
        >
            <View style={styles.container}>
                <Text style={[styles.icon,
                    {marginLeft: winWidth * (progress/100) - (iconWidth/2) }
                ]}>{ progress <= 50 ? '🌞' : '🌚' }</Text>
                <View style={[styles.bar,
                    { backgroundColor: `rgba(0, 0, 0, ${opacity})`}
                ]}>
                    { mode && flow.map(i => (
                        <View style={{ 
                            backgroundColor: Graphics.colors.elements.light[i.element] , 
                            flex: i.val
                        }}/>
                    ))}
                </View>
            </View>
        </Toucher>
    )
}

export default YinYangBar

