
import React from 'react';
import { StyleSheet, Text, View , Image, Dimensions, FlatList,} from 'react-native';
import {sstyle, scolor } from '../../styles/shared'
import Color from 'react-native-material-color'
import * as strings from '../../lib/utils/strings'

import FontAwesome5 from 'react-native-vector-icons/FontAwesome5';
const winWidth = Dimensions.get('window').width
const winHeight = Dimensions.get('window').height
import { toTitle } from '../../lib/utils/strings'
import ProPillar from './ProPillar'
import HorizontalScroll from './HorizontalScroll'
import { Provider, Subscribe, Container } from 'unstated';
import PreferencesContainer  from '../../containers/PreferencesContainer'

const ScrollChart = (props) => {
    const { chart } = props
    const time = chart.info.time
    const data = [
        { pillarTitle: time.toFormat('yyyy'), pillar: chart.pillars.year },
        { pillarTitle: time.toFormat('MMM'), pillar: chart.pillars.month},
        { pillarTitle: time.toFormat('d'), pillar: chart.pillars.day}
    ]
    if(chart.pillars.hour){
        data.push({ pillarTitle: time.toFormat('H:mm:ss'), pillar: chart.pillars.hour})
    }else{
        data.push({ pillarTitle: null, pillar: null })
    }
    if(props.includeLifeConception){
        data.push({ pillarTitle: 'Life', pillar: chart.pillars.life })
        data.push({ pillarTitle: 'Conception', pillar: chart.pillars.conception })
    }
    return (
        <Subscribe to={[PreferencesContainer]}>
            {(prefs) => {
                const settings = prefs?.state?.bazi
                return (
                    <View style={styles.container}>
                        <FlatList
                            scrollEnabled={props.scrollEnabled === false ? false : true}
                            ref={flatList => { this.flatList = flatList; }}
                            horizontal={true}
                            data={data}
                            keyExtractor={(item, index) => index.toString()}
                            inverted={true}
                            renderItem={(payload) => {
                                return (
                                    <ProPillar
                                        sectionSID={'scrollChart'}
                                        settings={settings}
                                        hideGods={props.hideGods || false}
                                        hideHighlights={props.hideHighlights || false }
                                        hidePillarTitle={props.hidePillarTitle || false}
                                        style={styles.box}
                                        root={chart}
                                        { ...payload.item } //pillar, pillarTitle
                                    />
                                )
                            }}
                        />
                    </View>
                )
            }}
        </Subscribe>
    )
}

export default ScrollChart

const styles = StyleSheet.create({
    container:{
        
    },
    box:{
        width:winWidth / 4 - 2,
        margin:1,
        flexDirection:'column',
        flex: 1,
    },
})