class CreateNewRecord extends React.Component {
    state={
        name: undefined,
        description: undefined
    }
    static navigationOptions = ({ navigation }) => {
        const { params={} } = navigation.state 
		return {
            title: 'New Record',
        }
    }
    constructor(props){
        super(props)
        const { time, gender , hourUnknown, chartName=''} = props.navigation.getParam('info')
        this.time = time
        this.hourUnknown = hourUnknown
        this.gender = gender

        // this.state.name = chartName
    }
    componentDidMount(){
        this.name.focus()
    }

    render(){
        const timePlaceholder = this.hourUnknown ? this.time.toFormat(`yyyy-MM-dd '(Hour Unknown)'`) : this.time.toFormat("yyyy-MM-dd H:mm 'GMT'Z")
        return (
            <ScrollView 
                keyboardShouldPersistTaps={'always'}
            >
                <View style={styles.container}>
                    <TextInput
                        editable={false}
                        style={[styles.textInput, styles.disabled]}
                        value={timePlaceholder}
                    />

                    <TextInput
                        editable={false}
                        style={[styles.textInput, styles.disabled]}
                        value={strings.toTitle(this.gender)}
                    />
                    <TextInput
                        ref={c => { this.name = c }} 
                        placeholder="Name (required)" 
                        style={styles.textInput}
                        value={this.state.name}
                        onChangeText={(name) => this.setState({ name })}
                    />
                    <TextInput
                        placeholder="Description (optional)"
                        style={styles.textInput}
                        value={this.state.description}
                        onChangeText={(description) => this.setState({ description })}
                    />
                    <Mutation
                        mutation={queries.createBirthRecord}
                    >
                    {(createBirthRecord, { data }) => (
                        <Toucher
                            style={styles.touchSave}
                            onPress={() => {
                                if(!this.state.name) return 
                                createBirthRecord({ variables: { name: this.state.name, description: this.state.description, gender: this.gender , time: this.time, hourUnknown: this.hourUnknown }})
                                this.props.navigation.goBack()
                            }}
                        >
                            <Text style={styles.textSave}>Create</Text>
                        </Toucher>
                    )}
                    </Mutation>
                    <Text style={sstyle.layout.footer}>Records can be accessed under "Saved".</Text>

                </View>
            </ScrollView>
        )
    }
}
export default withNavigation(CreateNewRecord)




