    async calculateChart1({time=this.state.chart1?.info?.time, gender=this.state.chart1?.info?.gender, hourUnknown = false, chartName=null}){
        const preferences = await getPreferences()
        const chart1 = FourPillars.plot({ 
            time, 
            gender, 
            hourUnknown, 
            showLuck: true , 
            simpleLuckCycle:preferences?.bazi?.calculations?.showSimpleLuckCycleCalculation,
            lateZi: preferences?.bazi?.calculations?.showDayStartsFrom_23, 
            weightsIncludeCombos: preferences?.bazi?.calculations?.showCombinationsInWeightCalculation, 
            showWeights: true, 
            shiftingPalace: this.state.shiftingPalace,
            chartName,
        })
        //Set Luck Pillars
        this.setState((prevState, props) => ({
            chart1,
            sectionDataSource: update(prevState.sectionDataSource, { 
                1:{ $set: { title: 'L-Cycles', sid: 'Luck', data: [this.calcLuckData(chart1)] }},
                2:{ $set: { title: `— Years`, sid: 'Years', data: [] }},
                3:{ $set: { title: 'Months', sid: 'Months', data: [] }},
                4:{ $set: { title: 'Days', sid: 'Days', data: [] }},
                5:{ $set: { title: 'Hours', sid: 'Hours', data: [] }},
            })
        }), () => {
            const chart1Payload = { section: { title: 'Birth', sid: 'Birth',  }, item: this.formBirthChartData(chart1, false, true) }
            //Set chart1Payload, then Re-calculate Chart2Payload
            this.setState({ chart1Payload }, () => {
                const info = this.state.chart2?.info || defaultChartData
                this.calculateChart2({
                    ...info,
                    force: true
                })
            })
        })
    }
    async calculateChart2({time=DateTime.local(), gender=this.state.chart2.info.gender || male, hourUnknown = false, force=false, chartName=null}){
        let chart2;
        let sameChart = false
        sameChart = (this.state.chart2?.info?.chineseTimeString === Tools.chineseTimeString(time) && this.state.chart2?.info?.hourUnknown === hourUnknown)

        if(this.state.chart2 && sameChart && !force){
            chart2 = this.state.chart2
            chart2.info.time = time
        }else{
            const  preferences = await getPreferences()
            chart2 = FourPillars.plot({ 
                time, 
                gender, 
                genderUnknown: true,
                hourUnknown, 
                root: this.state.chart1,  
                lateZi: preferences?.bazi?.calculations?.showDayStartsFrom_23, 
                showWeights: false,
                chartName
            })
        }
        this.setState((prevState, props) => ({
            chart2,
            sectionDataSource: update(prevState.sectionDataSource, { 
                0:{ $set: { title: 'Comparison', sid: 'Comparison', data: [this.formComparisonChartData(chart2)] }}
            })
        }))
    }
