class EditProfile extends React.Component {
    state={
        selectedTabIndex: 0
    }
    constructor(props){
        super(props)
        this.onTabPress = this.onTabPress.bind(this)
        this.launchPhotoUpload = this.launchPhotoUpload.bind(this)
    }
    async onTabPress(selectedTabIndex){
        this.setState({ selectedTabIndex })
        if(selectedTabIndex === 1) this.launchPhotoUpload()
    }
    async launchPhotoUpload(){
        const options = {
            maxWidth: 512,
            maxHeight:512,
            quality:0.8,
        }
        ImagePicker.launchImageLibrary(options, async (response) => {
            console.log(response)
            const base64 = response?.data
            const fileType = "image/jpeg"
            try{
                const result = await this.props.client.mutate({
                    mutation: queries.updateUserImage,
                    variables: { base64, fileType }
                })
                this.context.profileQuery.refetch()
                this.props.navigation.goBack()
            }catch(err){
                console.log(err)
            }
        })
    }
    render(){
        return (
            <View style={styles.container}>
                <TabBar
                    tabs={[
                        { title: 'Birthday' },
                        // { title: 'Avatar' },
                        // { title: 'Card' },
                    ]}
                    onTabPress={this.onTabPress}
                    selected={this.state.selectedTabIndex}
                />
                { this.state.selectedTabIndex === 0 && (
                    <AuthContext.Consumer>
                    {({profileQuery}) => {
                        const user = profileQuery?.data?.user
                        if(user?.Birth?.time) {
                            const lux = DateTime.fromISO(user.Birth.time, { setZone: true })
                            return (
                                <CustomDateSelector 
                                    initial={{ 
                                        gender: user.Birth.gender,
                                        time: lux,
                                        hourUnknown: user.Birth.hourUnknown
                                    }}
                                    onSubmit={async (data) => {
                                        await this.props.client.mutate({
                                            mutation: queries.updateUserBirth,
                                            variables: data
                                        })
                                        profileQuery.refetch()
                                    }}
                                    showGender={true}
                                />
                            )
                        }
                    }}
                    </AuthContext.Consumer>
                )}
                { (this.state.selectedTabIndex === 1 ) && (
                    <ActivityIndicator size="large" color={Color.GREY[700]} style={{marginTop: 24}} />
                )}

                { (this.state.selectedTabIndex === 2 ) && (
                    <EditCard/>
                )}
            </View>
        )
    }
}
EditProfile.contextType = AuthContext
export default withApollo(withNavigation(EditProfile))

