import * as queries from '../../queries/queries'
import PersonRecord from './PersonRecord'
import { DateTime } from 'luxon'



class BirthRecordList extends React.Component {
    flatlistLoading = false
    numItems=20
    state = {
        searchQuery: "",
        refreshing: false,
    }
    constructor(props){
        super(props)
        this.searchQueryOnChange = this.searchQueryOnChange.bind(this)
        this.onRefresh = this.onRefresh.bind(this)
    }
    searchQueryOnChange(searchQuery){
        this.setState({ searchQuery })
    }
    onRefresh(){
        this.flatlistLoading = false
        this.setState({ refreshing: true }, () => this.setState({ refreshing: false }))
    }
    render(){
        return (
            <View style={styles.container}>
                <View style={styles.searchBar}>
                    <TextInput  
                        placeholder={'Find'}
                        style={styles.searchBarTextInput}
                        value={this.state.searchQuery}
                        onChangeText={this.searchQueryOnChange}
                        autoCapitalize="none"
                        autoCorrect={false}
                    />
                </View>
                <Query 
                    fetchPolicy={"cache-and-network"}
                    query={this.state.searchQuery ? queries.BirthRecordsByPrefixQuery : queries.BirthRecordsQuery } 
                    variables={ this.state.searchQuery ? { prefix: this.state.searchQuery, num: this.numItems } : { time: new Date(), num:  this.numItems  } }
                >
                {({ loading, error, data, fetchMore, refetch }) => {
                    const birthRecords = this.state.searchQuery ? data?.birthRecordsByPrefix : data?.birthRecords
                    return (
                        <FlatList
                            keyboardShouldPersistTaps={'always'}
                            onScroll={() => {  this.flatlistLoading = true  }}
                            ref={flatList => { this.flatList = flatList; }}
                            data={birthRecords}
                            keyExtractor={(item, index) => index.toString()}
                            inverted={false}
                            ItemSeparatorComponent={() => (<View style={styles.separator}></View>)}
                            onEndReachedThreshold={0.3}
                            onEndReached={() => {
                                if(!this.flatlistLoading) return 
                                // this.flatlistLoading = false
                                fetchMore({
                                    query: this.state.searchQuery ? queries.BirthRecordsByPrefixQuery : queries.BirthRecordsQuery,
                                    variables: this.state.searchQuery ? { prefix: this.state.searchQuery, num:  this.numItems  } : { time: birthRecords[birthRecords.length-1].createdAt, num:  this.numItems  },
                                    updateQuery: (prevResult, { fetchMoreResult }) => {
                                        const prevData = this.state.searchQuery ? (prevResult?.birthRecordsByPrefix || []) : (prevResult?.birthRecords || [])
                                        const newData = this.state.searchQuery ? (fetchMoreResult?.birthRecordsByPrefix || []) : (fetchMoreResult?.birthRecords || [])
                                        this.flatlistLoading = true
                                        return { birthRecords: [ ...prevData, ...newData] }
                                    }
                                })                               
                            }}
                            renderItem={(payload) => {
                                payload.item.time = DateTime.fromISO(payload.item.time, { setZone: true })
                                return (
                                    <PersonRecord 
                                        onSubmit={this.props.onSubmit}
                                        info={payload.item}
                                    />
                                )
                            }}
                            refreshControl={
                                <RefreshControl
                                    refreshing={this.state.refreshing}
                                    onRefresh={this.onRefresh}
                                />
                            }
                            ListFooterComponent={(
                                <View>
                                    <View style={styles.separator}/>
                                    <Text style={sstyle.layout.footer}>Long press a record to delete.</Text>
                                </View>
                            )}
                        />
                    )
                }}
                </Query>
            </View>
        )
    }
}
export default BirthRecordList


