class HorizontalScroll extends React.Component {
    state = {
        selectedIndex:null,
    }
    constructor(props){
        super(props)
        this.scrollToIndex = this.scrollToIndex.bind(this)
        this.onPillarPress = this.onPillarPress.bind(this)
        this.onPillarLongPress = this.onPillarLongPress.bind(this)
        this.toggleAccent = this.toggleAccent.bind(this)
    }
    componentDidMount(){
        // if(this.props.payload.section.sid === 'Comparison')
        //     this.setState({ selectedIndex: 3})
    }
    onPillarLongPress(data){
        if(this.props.payload.section.sid === 'Birth'){
        }else if(this.props.payload.section.sid === 'Comparison'){
            this.props.expandCompareSection &&  this.props.expandCompareSection(this.props.payload.section, data)
        }else{
            this.props.expandListSection &&  this.props.expandListSection(this.props.payload.section, data)
            this.props.setPillarFocusSectionList(this.props.payload.section.sid, data.itemIndex, 'isPillarTopFocused')
        }
    }
    scrollToIndex(params){
        this.flatList.scrollToIndex(params)
    }
    shouldComponentUpdate(nextProps, nextState){
        return true
    }
    toggleAccent(pillarContainer, data){
        const newData = this.state.selectedIndex === data.itemIndex ? null : data 
        if(newData){
            const stemMap = { jia: false, yi: false, bing: false, ding: false, wu: false, ji: false, geng: false, xin: false, ren: false, gui: false}
            Object.keys(newData.pillar.branch.stems).forEach(key => {
                if(newData.pillar.branch.stems[key]) stemMap[newData.pillar.branch.stems[key].name] = true
            })
            pillarContainer.updateStemAccent(stemMap)
        }else{
            pillarContainer.resetState()
        }
    }
    onPillarPress(data){
        const selectedIndex = this.state.selectedIndex === data.itemIndex ? null : data.itemIndex
        const sid = this.props.payload.section.sid
        if(sid === 'Birth'){
            this.props.setPillarFocusBirth && this.props.setPillarFocusBirth(selectedIndex, 'isPillarBottomFocused')
        }else{
            this.props.setPillarFocusSectionList && this.props.setPillarFocusSectionList(sid, selectedIndex, 'isPillarBottomFocused')
        }
        this.setState({ selectedIndex })
    }
    render(){
        if(!this.props.root) return <View></View>

        //PillarKeys, for Detail View
        let pillarKeys = ['year','month','day','hour'] 
        if(this.props.root.info.hourUnknown){
            pillarKeys.pop() //remove hour
        }
        if(this.state.selectedIndex !== null){
            if(this.props.payload.section.sid === 'Birth'){
                pillarKeys.splice(this.state.selectedIndex, 1) //remove that pillar
            }
        }

        return (
            <Subscribe to={[PreferencesContainer, PillarContainer]}>
            {(prefs, pillarContainer) => {
                const settings = prefs?.state?.bazi
                return (
                <View style={styles.container}>
                    <FlatList
                        ref={flatList => { this.flatList = flatList; }}
                        horizontal={true}
                        showsHorizontalScrollIndicator={false}
                        data={this.props.payload.item}
                        keyExtractor={(item, index) => index.toString()}
                        inverted={this.props.inverted}
                        renderItem={(payload) => {
                            if(this.props.showMinutePillar === false && payload.item.pillar?.name === 'minute') return <Fragment/>
                            return (
                                <ProPillar
                                    sectionSID={this.props.payload.section.sid}
                                    style={styles.box}
                                    root={this.props.root}
                                    onPillarLongPress={this.onPillarLongPress}
                                    onPillarPress={(data) => {
                                        this.toggleAccent(pillarContainer, data)
                                        this.onPillarPress(data)
                                    }}
                                    itemIndex={payload.index}
                                    { ...payload.item }
                                    settings={settings}
                                    {...this.props}
                                />
                            )
                        }}
                    />
                    { (this.props.payload.section.sid !== 'Birth' && this.state.selectedIndex !== null) && (
                        <PillarExpansion
                            root={this.props.root}
                            payload={this.props.payload}
                            selectedIndex={this.state.selectedIndex}
                            pillarKeys={pillarKeys}
                            showAnnualStars={false}
                        />
                    )}

                    { (this.props.payload.section.sid === 'Birth' && this.state.selectedIndex !== null) && (
                        <ScrollView style={styles.extendedScrollView}>
                            <PillarExpansion
                                root={this.props.root}
                                payload={this.props.payload}
                                selectedIndex={this.state.selectedIndex}
                                pillarKeys={pillarKeys}
                                showAnnualStars={ true }
                            /> 
                        </ScrollView>
                    )}


                </View>
                )
            }}
            </Subscribe>
        )
    }
}

const styles = StyleSheet.create({
    container:{
        
    },
    box:{
        width:winWidth / 4 - 2,
        margin:1,
        flexDirection:'column',
        flex: 1,
    },
    extendedScrollView:{
        maxHeight:winWidth * 1
        // flex:9
    }
})


export default withNavigation(HorizontalScroll)

