export const officers = ['establish','remove','full','balance','stable','initiate','destruction','danger','success','receive','open','close'];
const branchOrder = ['yin','mao','chen','si','wu','wei','shen','you','xu','hai','zi','chou'];
const monthOfficerStartDay = {
    yin:'establish',
    mao:'close',
    chen:'open',
    si:'receive',
    wu:'success',
    wei:'danger',
    shen:'destruction',
    you:'initiate',
    xu:'stable',
    hai: 'balance',
    zi: 'full',
    chou: 'remove',
};
export const getTwelveOfficer = (month, day) => {
    const start = monthOfficerStartDay[month]
    const index = officers.indexOf(start)
    const arr1 = officers.slice(index)
    const arr2 = officers.slice(0, index)
    const list = arr1.concat(arr2)
    const result = {}
    branchOrder.forEach((mo, i) => {
        result[mo] = list[i]
    })
    return result[day]
}

