export const getYearlyThreeKillings = (year, day) => {
    const index = yearlyThreeKillings[year].indexOf(day)
    if(index < 0){ 
        return null
    }else if(index === 0){
        return 'robbery'
    }else if(index === 1){ 
        return 'calamity'
    }else if(index === 2){
        return 'annual'
    }
    return null
}

