export const get28Constellation = (time) => {
    const items = Tools.toProxy(['horn','neck','foundation','house','heart','tail','basket','dipper','ox','weaving','void','danger','room','wall','astride','mound','stomach','pleiades','net','beak','orion','well','ghost','willow','star','bow','wing','carriage'])
    const anchor = DateTime.fromObject({ year: 2020, month: 2, day: 13})
    const now = DateTime.fromObject({ year: time.year, month: time.month, day: time.day })
    const dayDiff = now.diff(anchor, ['days'], { conversionAccuracy: 'longterm'}).days
    return items[dayDiff]
}


