const dongGongNumMap = {
    0: '✕✕', 1: '✕', 2: '★', 3: '★★', 4: '★★★',
}

export const  getAllDayInfo = ({ bazi }) => {
    const p = bazi.pillars
    const time = bazi.info.time;
    const officer = getTwelveOfficer(p.month.branch.name, p.day.branch.name)
    const m3k = getMonthlyThreeKillings(p.month.branch.name, p.day.branch.name)
    const y3k = getYearlyThreeKillings(p.year.branch.name, p.day.branch.name)
    const constellation = get28Constellation(time)
    const yellowBlack = getYellowBlack(p.month.branch.name, p.day.branch.name)
    const dongGongNum = dongGongNumMap[DongGong[p.month.branch.name][`${p.day.stem.name}-${p.day.branch.name}`]]

    let bigDisaster = null;
    if(String(time.year) in bigDisasterDays){
        const lookup = time.toFormat('MM-dd')
        if(bigDisasterDays[String(time.year)].indexOf(lookup) > 0) bigDisaster = true
    }

    let yearBreaker = false
    let monthBreaker = false
    let monthDestructor = false

    if(p.year.branch.clash === p.day.branch.name) yearBreaker = true
    if(p.month.branch.clash === p.day.branch.name)  monthBreaker = true


    if(Ordinals.branches[p.month.branch.name].destruction === p.day.branch.name) monthDestructor = true

    //crawled data
    const dstring = time.toFormat('yyyy-MM-dd')
    let other = null
    if(dstring in tongShu){
        other = tongShu[dstring] 
    }

    return {
        officer,
        constellation,
        yellowBlack,
        m3k,
        y3k,
        bigDisaster,
        yearBreaker,
        monthBreaker,
        monthDestructor,
        other,
        dongGongNum,
    }
}



