import * as ui from '../../lib/utils/ui'
import * as queries from '../../queries/queries'
import analytics from '@segment/analytics-react-native'

class EnterUsername extends React.Component {
    state={
        username: '',
        usernameAvailable: null,
    }
    constructor(props){
        super(props)
        this.destination = this.props.navigation.getParam('destination')
        this.isUsernameAvailable = this.isUsernameAvailable.bind(this)
        this.updateUserUsername = this.updateUserUsername.bind(this)
        this.debouncer = _.debounce(this.isUsernameAvailable, 200)
        analytics.track('Auth.Username')

    }
    componentDidMount(){

    }
    async isUsernameAvailable(){
        const result = await this.props.client.query({
            query : queries.usernameAvailable,
            variables: { username: this.state.username }
        })
        this.setState({ usernameAvailable: result?.data?.usernameAvailable });
    }
    async updateUserUsername(){
        const result = await this.props.client.mutate({
            mutation: queries.updateUsername,
            variables: { username: this.state.username }
        })

        try{
            await this.context?.profileQuery?.refetch()
            if(result?.data?.updateUserUsername){
                // if(this.destination){
                //     this.props.navigation.replace(this.destination)
                // }else{
                    this.props.navigation.dispatch(StackActions.popToTop());
                // }
            }
        }catch(err){
            Alert.alert(err)
        }
    }
    render(){
        return (
            <AuthContext.Consumer>
            {context => (
                <KeyboardAvoidingView 
                    style={styles.container} 
                    behavior="padding" 
                    enabled
                >
                    <Text style={styles.h1}>Username</Text>
                    <View style={styles.inputs}>
                        <TextInput
                            style={styles.textBox}
                            value={this.state.username}
                            onChangeText={(username) => {
                                this.setState({ username })
                                this.debouncer()
                            }}
                            autoCapitalize= 'none'
                            autoCorrect={false}
                            onSubmitEditing={this.updateUserUsername}
                        />
                        <Toucher
                            underlayColor={scolor.touchableHighlightUnderlayColor} 
                            style={styles.submitButtonHolder}
                            onPress={this.updateUserUsername}
                        >
                            <MaterialCommunityIcon
                                name={'arrow-right'}
                                size={30}
                                color={Color.BLUEGREY[300]}
                            /> 
                        </Toucher>
                    </View>
                    <Text style={styles.subnote}>
                        { this.state.usernameAvailable === true && '✓ Username is available.'}
                        { this.state.usernameAvailable === false && '✗ Username is not available.'}
                    </Text>
            </KeyboardAvoidingView>
            )}
            </AuthContext.Consumer>
        )
    }
}
EnterUsername.contextType = AuthContext
export default withApollo(EnterUsername)

