const getTimestamp = (pillarName, end, time) => {
    const seconds = end.diff(time, 'seconds').seconds
    return prettyTime(seconds) 
}

const MinorCycle = (props) => {
    if(props.pillar.name === 'luck') return <Fragment/>
    const bazi = props.payload.item[props.selectedIndex].bazi || FourPillars.plot({ time: props.time })
    const elementToAspect = props.root.meta.maps.elementToAspect
    const boundaries = SolarCal.getMinorCycle(bazi, props.pillar.name)

    if(!(boundaries[0])) return <Fragment/>
    const begin = boundaries[0]
    const end = boundaries[1]
    const totalPeriod = end.diff(begin, 'seconds').seconds
    const timeSinceBegin = props.time.diff(begin, 'seconds').seconds
    const percent = Math.round((timeSinceBegin / totalPeriod) * 100)


    const branch = props.pillar.branch


    const branchStem = branch.stems.main
    const branchElement = branch.stems.main.elm
    const branchAspect = branch.stems.main.aspc
    const branchGod = branch.stems.main.gdd

    const season = Ordinals.seasons[branch.season]
    const seasonElement = Ordinals.elements[season.element]
    const seasonAspect = EightWords.aspects[elementToAspect[seasonElement.name]]

    const nextBranch = Ordinals.branches[Ordinals.branchOrdering[branch.number+1]]
    const nextElement = Ordinals.elements[nextBranch.element]
    const nextAspect = EightWords.aspects[elementToAspect[nextElement.name]]
    const nextSeason = Ordinals.seasons[nextBranch.season]
    const nextAspectIcon = `aspects-${nextAspect.name}|`
    
    let shadowColor = branch.group === 'end' ? Graphics.colors.elements.light.earth : Color.GREY[100]
    let fillColor =  seasonElement._colors.dark

    const trendIcon = { start: 'trending-up', peak: 'format-vertical-align-top', end: 'trending-down', }
    const timestamp = getTimestamp(props.pillar.name, end, props.time)

    const [iconIndex, setIconIndex] = useState(0)
    const iconMap = [branchAspect.$icon.source,branchGod.$icon.source , branchStem.$icon.source, branch.$icon.source]
    //  CMImages.color.gods2[branchGod.abbr]

    let line
    if(iconIndex === 0){ 
        line=[
            { 
                words:[
                    ...branchAspect.$dict_verb2.map(i => toTitle(i)),
                ],
                shuffle: true,
            },
            { words: ['of']},
            {
                words: [
                    toTitle(branchAspect.name),
                    ...branchAspect.$dict_noun.map(i => toTitle(i)),
                ],
                shuffle: true,
            },
   
            
        ]
    }else if(iconIndex === 1){ 
        line=[
            // {
            //     words: ['Prioritized', 'Optimized', 'Focused'],
            //     shuffle: true,
            // },
            {
                words: [
                    ...branchGod.$dict_adj.map(i => toTitle(i) )
                ],
                shuffle: true,
            },
            {
                words: [
                    ...branchAspect.$dict_noun2.map(i => toTitle(i))
                ],
                shuffle: true,
            }
        ]
    }else if(iconIndex === 2){ 
        line = [
            {
                words: [
                    ...branchStem.$dict_adj.map(i => toTitle(i) )
                ],
                shuffle: true,
            },
            { words: ['+']},
        
            {
                words: [
                    ...branchAspect.$dict_nature.map(i => toTitle(i))
                ],
                shuffle: true
            },
           

        ]
    }else{
        line = [
            {
                words: [
                    toTitle(branch.group),
                    ...Dict.Ordinals.branchGroups[branch.group].$dict_syn.map(i => toTitle(i))
                ]
            },
            {
                words: ['of']
            },
            {
                words: [
                    toTitle(seasonAspect.name),
                    toTitle(season.name),
                    toTitle(season.element),
                ],
                shuffle: true,
            }
        ]
    }
 

    return (
        <View style={styles.container}>
            <View style={styles.left}>
                <ProgressCircle
                    percent={percent}
                    radius={36}
                    borderWidth={12}
                    color={fillColor}
                    shadowColor={shadowColor}
                    bgColor="#fff"
                >
                    <Text style={{ fontWeight: '500', fontSize:13, }}>{ percent }</Text>
                </ProgressCircle>
            </View>
            <View style={{ width: 1, backgroundColor: scolor.separator}}/>
            <View style={styles.right}>
                <View style={{ 
                    flex:1, 
                    flexDirection: 'row', 
                }}>
                    <Toucher
                        style={{
                            paddingHorizontal:padd,
                            borderRightWidth:1,
                            borderRightColor: scolor.separator,
                            justifyContent: 'center',
                            alignItems: 'center',
                        }}
                        onPress={() => {
                            let newIndex = iconIndex + 1
                            if(newIndex === 4) newIndex = 0
                            setIconIndex(newIndex)
                        }}
                    >
                        <Image
                            source={iconMap[iconIndex]}
                            style={{
                                width: 24,
                                height: 24,
                            }}
                        />
                    </Toucher>
                    <MadLibs
                        line={line}
                        containerStyle={{
                            alignItems: 'center',
                            justifyContent: 'flex-start',
                            flexWrap:'nowrap',
                            paddingLeft:padd,
                        }}
                        boxTextStyle={styles.boxTextStyle}
                        boxViewStyle={styles.boxViewStyle}
                    />
                </View>

                <View style={{ backgroundColor: scolor.separator, height:1, }}/>

                <View style={{
                    flex:1,
                    paddingHorizontal:padd,
                    flexDirection:'row',
                    justifyContent: 'space-between',
                    alignItems: 'center',
                }}>
                    <Text style={{
                        fontSize: 13,
                        fontWeight: '500',
                        color: Color.GREY[500],
                        textAlign:'right',
                    }}>
                        {  timestamp }
                    </Text>
                    <MaterialCommunityIcon
                        name={trendIcon[branch.group]}
                        size={20}
                        color={Color.GREY[600]}
                    />
                </View>
            </View>
        </View>
    )
}
export default withNavigation(MinorCycle);

