const TwentyFourBox = React.memo(withNavigation((props) => {
    if(props.index < props.visibles[0] || props.index > props.visibles[1]) return <View style={[styles.box, { width: props.width}]}/>
    const box = props.box;
    let extra = ''
    if(box.type === 'branch') extra = ` ∙ ${strings.toTitle( Ordinals.branches[box.pinyin].animalName )}`
    if(box.type === 'stem') extra = ` ∙ ${strings.toTitle( Ordinals.stems[box.pinyin].elementName)}`
    if(box.type === 'trigram') extra = ` ∙ ${strings.toTitle(Ordinals.guas[box.pinyin].english)}`


    let sitFaceLabel = null
    if(props.houseStars?.faceMountain.sector === box.sector){
        sitFaceLabel = 'FACING'
    }else if(props.houseStars?.sitMountain.sector === box.sector){
        sitFaceLabel = 'SITTING'
    }

    return (
        <Toucher
            onPress={() => {
                const type = box.type
                let path;
                if(type === 'stem'){
                    path = `heavenlyStems.${box.pinyin}`
                }else if(type === 'branch'){
                    path = `earthlyBranches.${box.pinyin}`
                }else if(type === 'trigram'){
                    path = `trigrams.${box.pinyin}`
                }
                props.navigation.push('Library', { path, hideClose: true })
            }}
        >
            <View style={[styles.box, 
                { 
                    width: props.width, 
                    backgroundColor: 'white',
                },
                (props.showHouseSector) && { paddingTop: 0 },
                (box.humanElement) && { paddingBottom: 0 }
            ]}>



                { props.showHouseSector && (
                <Text
                    style={[
                        {alignSelf: 'stretch',  color: 'transparent' , paddingVertical: padd/1.5 , fontWeight: 'bold', fontSize: 12, marginBottom: padd/1.5},
                        sitFaceLabel && { backgroundColor: Color.GREY[100], color: Color.GREY[800], textAlign: 'center',}
                    ]}
                >{ sitFaceLabel || '---'}</Text>
                )}
           
                <View style={{ flexDirection: 'row', justifyContent: 'center', alignItems: 'center'}}>
                    {props.showSector && (<Text style={[styles.txtTitle, { marginRight: 9}]}>{ box.sector.toUpperCase() }</Text>)}
                    <Text   style={[styles.txtChinese, { marginTop: 0, color: Graphics.colors.elements.dark[box.element] }]}>{ box.chinese}</Text>
                </View>
                <Text  numberOfLines={1}  style={styles.txtSubtitle}>{ strings.toTitle(box.pinyin)}{ extra }</Text>

                {box.humanElement && (
                    <View style={{ 
                        height: 6,
                        alignSelf: 'stretch',
                        marginTop: padd/1.5,
                        backgroundColor: Graphics.colors.elements.light[box.humanElement]
                    }}/>
                )}
            </View>
        </Toucher>
    )
}))

