const BlankFiller = React.memo((props) => ( <View style={{ width: props.width}}/> ))
const getVisibleIndexes = (bigRingOffset, width, ringOffset) => {
    const mark1 = Math.abs(bigRingOffset)  + Math.abs(ringOffset)
    const mark2 = mark1 + winWidth 
    const  index1 = Math.floor(mark1/width)   - 1
    const  index2 = Math.ceil(mark2/width)  + 1
    return [index1, index2]
}

const LuoPanContents = (props) => {
    return (
        <View>
            { props.rings.map(ring => {
                const template = ring.template;
                return (
                    <View style={[
                        styles.ring, 
                        { marginLeft: ring.offset },
                        template === 'symbolics' && { backgroundColor: 'white'}
                    ]}>
                        <BlankFiller width={ring.blankFiller}/>
                        { ring.boxes.map((box, index) => {
                            const payload = { houseStars: props.houseStars, bazi: props.bazi, box, index, width: ring.width - 1, visibles: getVisibleIndexes(props.bigRingOffset, ring.width, ring.offset)}
                            if(template === 'hexagrams'){
                                return <HexagramBox { ...payload } />
                            }else if(template === 'mountains'){
                                return <TwentyFourBox { ...payload } showSector={true} showHouseSector={true}/>
                            } else if (template === 'mountainsHeaven') {
                                return <TwentyFourBox {...payload} />
                            } else if (template === 'mountainsHuman') {
                                return <TwentyFourBox {...payload}  />
                            }else if(template === 'trigrams'){
                                return <TrigramBox { ...payload } />
                            }else if(template === 'symbolics'){
                                return <SymbolicsBox { ...payload } />
                            }else if(template === 'annualStars'){
                                return <AnnualStarsBox { ...payload } />
                            }else if(template === 'eightMansions'){
                                return <EightMansionsBox { ...payload } />
                            }else if(template === 'naJiaEightMansions'){
                                return <NaJiaEightMansionsBox { ...payload} />
                            }else if(template === 'houseStars'){
                                return <HouseStarBox { ...payload}/>
                            }else if(template === 'solarTerms'){
                                return <SolarTermsBox { ...payload }/>
                            }else if(template === 'eightRoads'){
                                return <EightRoadsBox { ...payload }/>
                            } else if (template === 'eightYellowSpring'){
                                return <EightYellowSpring { ...payload } />
                            } else if (template === 'piercingMountain'){
                                return <PiercingMountain { ...payload } title={'Piercing Mountain 72 Dragons'}/>
                            } else if (template === 'penetratingMountain'){
                                return <PiercingMountain { ...payload } title={'Earth Penetrating 60 Dragons'}/>
                            } else if (template === 'equalDivisionDragons'){
                                return <EqualDivisionDragons { ...payload} />
                            }else if(template === 'sixElegance'){
                                return <SixElegance { ...payload }  />
                            } else if (template === 'xuanKongDots'){
                                return <XuanKongDots { ...payload } />
                            }
                        })}
                    </View>
                )
            })}
            <View style={{ height: 1, backgroundColor: Color.GREY[600]}}/>
        </View>
    )
}

export default React.memo(withNavigation(LuoPanContents))


