class  LuoPan extends React.Component {
    state={
        compassOn: true,
        bazi: null,
        houseInput: null,
        degree: 0,
        rings: [],
        selectedPan: 0,
        houseStars: null,
    }
    static navigationOptions = ({ navigation }) => {
        const { params={} } = navigation.state 
		return {
            header: null,
        }
    }
    constructor(props){
        super(props)
        this.onDegreeChange = this.onDegreeChange.bind(this)
        this.debouncer = _.debounce(this.onDegreeChange, DEBOUNCER)
        this.getFillers = this.getFillers.bind(this)
        this.process= this.process.bind(this)
        this.onBaziSelected = this.onBaziSelected.bind(this)
        this.onSelectPan = this.onSelectPan.bind(this)
        this.onHouseSelected = this.onHouseSelected.bind(this)
        this.onLockTouch = this.onLockTouch.bind(this)
    }
    onLockTouch(){
        const compassOn = this.state.compassOn
        if(compassOn){
            CompassHeading.stop()
        }else{
            CompassHeading.start(DEGREE_RATE,this.debouncer)
        }
        this.setState({ compassOn: !compassOn})
    }
    onDegreeChange(degree){
        this.setState({ degree })
    }
    onSelectPan(index){
        this.setState({ selectedPan: index}, () => { this.process() })
        analytics.track('LuoPan.' + index, { index })
    }
    async componentDidMount(){
        CompassHeading.start(DEGREE_RATE,this.debouncer)

        //init cache for bazi
        const initialChart1 = await AsyncStorage.getItem('@cache.chart1')
        let data = { time: DateTime.local(), hourUnknown: false, gender: 'male'};
        if(initialChart1){
            data = JSON.parse(initialChart1)
            data.time = DateTime.fromISO(data.time, { setZone: true })
        }
        const bazi = FourPillars.plot({showLuck: true, ...data})


        //init cache for house
        const houseCache = await AsyncStorage.getItem('@cache.houseInput')
        let houseInput = null
        if(houseCache){
            houseInput = JSON.parse(houseCache)
        }
        this.setState({houseInput,  bazi }, ()=> { this.process() })
        analytics.track('LuoPan.0')
    }
    async process(){
        let rings = [];
        const selectedPan = this.state.selectedPan; 
        const houseStars = WindWater.getHouseFlyingStars(this.state.houseInput)
        if(selectedPan === 0){
            rings = [
                Rings.personalSymbolics(this.state.bazi),
                Rings.annualStars(),
                Rings.eightMansionsFromNaJia(this.state.bazi),
                Rings.eightMansionsFromBazi(this.state.bazi),
                Rings.twentyFourMountainsEarth(),
                Rings.trigramsEarth(),
            ]
            if(houseStars){
                rings.splice(4, 0, Rings.eightMansionsFromFacing(houseStars.faceMountain.direction))
                rings.splice(1, 0, Rings.houseStars(houseStars))
            }
        }else if(selectedPan === 1){
            rings = [
                Rings.greatSun(),
                Rings.greatMoon(),
                Rings.eightRoadsDestruction(),
                Rings.sixElegance(),
                Rings.twentyFourMountainsHeaven(),
                Rings.equalDivisionDragons(),
                Rings.penetratingMountain(),
                Rings.twentyFourMountainsHuman(),
                Rings.piercingMountain(),
                Rings.eightYellowSpring(),
                Rings.twentyFourMountainsEarth(),
                Rings.trigramsEarth(),
            ]
        }else if(selectedPan === 2){
            rings = [
                Rings.xuanKongDots(),
                Rings.trigramsXkOuter(),
                Rings.xkHexagrams('outer'),
                Rings.trigramsXkInner(),
                Rings.xkHexagrams('inner'),
                Rings.twentyFourMountainsEarth(),
                Rings.trigramsEarth(),
            ]
        }


        const data = []
        rings.forEach(ring => {
            const width = stripWidth / ring.boxes.length
            const fillers = this.getFillers(ring.boxes, width)
            const offset = (ring.offset / 360) * (ring.boxes.length * width) * -1
            data.push({
                template: ring.template,
                boxes: [...fillers.prefillBoxes, ...ring.boxes, ...fillers.postfillBoxes],
                num: ring.boxes.length,
                width,
                offset,
                blankFiller: fillers.blankFiller,
            })
        })



        this.setState({ rings: data, houseStars})
    }
    getFillers(boxes, width){
        let numFillBoxes = Math.floor(fillWidth / width)
        const prefillBoxes = boxes.slice(-numFillBoxes)
        const postfillBoxes = boxes.slice(0, numFillBoxes)
        const blankFiller =  fillWidth - (numFillBoxes * width)
        return { prefillBoxes, postfillBoxes, blankFiller}
    }
    onBaziSelected(data){
        const bazi = FourPillars.plot({showLuck: true, ...data})
        this.setState({ bazi }, () => { this.process() })
    }
    onHouseSelected(houseInput, usedCompass){
        CompassHeading.start(DEGREE_RATE,this.debouncer)
        this.setState({houseInput}, () => { this.process() })
    }
    render(){ //414 winWidth, 
        const bigRingOffset = -(stripWidth * (this.state.degree / 360) ) - fillWidth + (winWidth / 2)
        if(this.state.rings.length === 0) return <Fragment/>
        return (
            <View style={styles.container}> 
                <View style={styles.vLine}/>
                <View style={styles.topInputBar}>
                    <LuoPanBackButton/>
                    <LockButton onLockTouch={this.onLockTouch} compassOn={this.state.compassOn}/> 
                </View> 

                <View style={{flex: 1 }}/>

                { __DEV__ && (
                    <Slider
                        maximumValue={360} 
                        minimumValue={0}
                        onValueChange = { this.debouncer}
                    />
                )}
                
                <View style={[styles.contentHolder,
                    { marginLeft: bigRingOffset }
                ]}>
                    <LuoPanContents
                        bazi={this.state.bazi}
                        bigRingOffset={bigRingOffset}
                        rings={this.state.rings}
                        houseStars = { this.state.houseStars}
                    />
                </View>
                <View style={styles.bottomBar}>
                    <Text allowFontScaling={false} style={styles.degreeText}>
                        { this.state.degree.toFixed(2)} 
                    </Text>
                </View> 

 
                <View style={styles.inputs}>
                    <Toucher
                        onPress={async () => {
                            this.props.navigation.push('DateSelector', { 
                                initial: this.state.bazi.info,
                                showGender: true,
                                onSubmit: this.onBaziSelected,
                                footer: 'Tap the back arrow to plot new chart.',
                            })
                            analytics.track('LuoPan-DateSelector')
                        }}
                        style={styles.selectBaziButtonTouch}
                    >
                        <MaterialCommunityIcon
                            name={'chevron-right'}
                            color={'white'}
                            size={20}
                        />
                    </Toucher>
                    <Text allowFontScaling={false} style={styles.baziLabel}>{ this.state.bazi?.name ? this.sstate.bazi.name + ': ' : '' }{ this.state.bazi.info.time.toFormat('yyyy-MM-dd, h:mma')}</Text>
                    <View style={{ flex: 1 }}/>
                    <Toucher
                        style={styles.houseButtonTouch}
                        onPress={() => {
                            this.props.navigation.push('HouseSelector', { 
                                onHouseSelected: this.onHouseSelected,
                                initial: this.state.houseInput
                            })
                        }}
                    >
                        { (this.state.houseInput?.houseYear && this.state.houseInput?.houseDegree) ? (
                            <Text allowFontScaling={false} style={styles.houseButton}>
                                { this.state.houseInput.houseYear } / { this.state.houseInput.houseDegree}° ➤
                            </Text>
                        ) : (
                            <Text allowFontScaling={false} style={styles.houseButton}>
                                🏠
                            </Text>
                        )}
                    </Toucher>
                </View>
                <LuoPanTabs selectedPan={this.state.selectedPan} onSelectPan={this.onSelectPan} />

            </View>
        )
    }
}
