const icons = {
    noblemen: 'face',
    intelligence: 'school',
    peachBlossom: 'heart',
}
const CommonSymbolics = (props) => {
    const results = []
    Object.keys(props.data).forEach(k => {
        results.push({ key: k, name:deCamel(k), list: props.data[k] })
    })
    return (
        <View  style={styles.container}>
            { results.map((item, index) => (
                <Toucher
                    onPress={ () => {
                        const animals = item.list.map(i => `[${toTitle(Ordinals.branches[i].animalName)}]`).join(' or ')
                        let msg = ''
                        if(item.key === 'noblemen'){
                            msg = `\nIndividuals with ${animals} have [Mentorship] affinity with me.`
                        }else if(item.key === 'peachBlossom'){
                            msg = `\nIndividuals with ${animals} have [Attraction] affinity with me.`
                        }else if(item.key === 'intelligence'){
                            msg = `\nIndividuals with ${animals} have [Academic] affinity with me.`
                        }
                        Alert.alert(item.name, msg)
                    }}
                    style={{ flex: 1 }}
                >
                    <View style={[styles.box,
                        index < results.length - 1 && { borderRightWidth: 1, borderRightColor: scolor.separator }
                    ]}>
                        <Text style={styles.title}>{ item.name }</Text>
                        <Separator color={Color.GREY[100]}/>
                        <View style={styles.imageHolder}>
                        { item.list.map(val => (
                                <Image
                                    source={CMImages.color.branches[val]}
                                    resizeMode={'contain'}
                                    style={styles.image}
                                />
                        ))}
                        </View>
                    </View>
                </Toucher>
            ))}
            
        </View>
    )
}
export default React.memo(withNavigation(CommonSymbolics))



