
import React, {Fragment} from 'react';
import {
	SafeAreaView,
	StyleSheet,
	ScrollView,
	View,
	Text,
    StatusBar,
    Alert,
	TextInput,
    Button,
    Animated,
    Easing,
    TouchableHighlight,
    TouchableOpacity,
    Dimensions,
} from 'react-native';

import Color from 'react-native-material-color';

import * as objects from '../../lib/utils/objects'
import { toTitle }from '../../lib/utils/strings'
import { sstyle, scolor } from '../../styles/shared'
import { withNavigation, NavigationEvents } from 'react-navigation';
import withPreventDoubleClick from '../../lib/utils/withPreventDoubleClick'
const Toucher = withPreventDoubleClick(TouchableHighlight)
const TouchableOpacityEx = withPreventDoubleClick(TouchableOpacity)
import SectionHeader from '../Layout/SectionHeader'
import FontAwesome from 'react-native-vector-icons/FontAwesome';
import FontAwesome5 from 'react-native-vector-icons/FontAwesome5';
import MaterialCommunityIcon from 'react-native-vector-icons/MaterialCommunityIcons'
import MaterialIcon from 'react-native-vector-icons/MaterialIcons'
import Foundation from 'react-native-vector-icons/Foundation'
import { DateTime } from 'luxon'
import analytics from '@segment/analytics-react-native'
import SegmentedControlTab from 'react-native-segmented-control-tab'
const winWidth = Dimensions.get('window').width
import AsyncStorage from '@react-native-community/async-storage';

const AtlasMenuBar = (props) => {
    const { navigation}  = props
    if(props.menuBarMode === null) return <Fragment/>
    return (
        <View style={styles.container}>
            <Toucher
                style={styles.toggler}
                onPress={() => {
                    props.setMenuBarMode( props.menuBarMode === 1 ? 2 : 1)
                    analytics.track('Bazi.MenuBar.toggle')
                }}
            >
                <MaterialCommunityIcon
                    name={'triangle'}
                    size={16}
                    // color={scolor.iconBlurred}
                    color={Color.BLUEGREY[100]}
                    style={[
                        props.menuBarMode === 2 && { transform: [
                            { rotate: "90deg" }, 
                        ]}
                    ]}
                />
            </Toucher>
            { props.menuBarMode === 1 && (
                <SegmentedControlTab
                    allowFontScaling={false}
                    tabStyle={[sstyle.tabs.atlas.tabStyle, { paddingHorizontal: 0 }]}
                    activeTabStyle={sstyle.tabs.atlas.tabActive}
                    tabTextStyle={[sstyle.tabs.atlas.tabText, {}]}
                    activeTabTextStyle={sstyle.tabs.atlas.tabTextActive}
                    borderRadius={2}
                    tabsContainerStyle={[sstyle.tabs.atlas.tabContainer, { width: winWidth - 44 - 44 - 6  , paddingLeft:3 }]}
                    values={['Main', 'Elem', 'Asp', 'Arch',  'Polar']}
                    selectedIndex={props.pillarContentMode}
                    onTabPress={pillarContentMode =>  { 
                        props.setPillarContentMode(pillarContentMode)
                        analytics.track('Bazi.MenuBar.pillarContentMode-' + pillarContentMode, { pillarContentMode})
                    }}
                />
            )}
            { props.menuBarMode === 2 && (
                <View style={[styles.buttons,
                    // { width: winWidth - 44 - 44 - 6  , paddingLeft:3  },
                ]}>
                     <TouchableOpacityEx 
                        style={[styles.buttonTouch] }
                        onPress={async() =>{ 
                            navigation.push('QiMenScreen')    
                        }}
                    >
                        <MaterialCommunityIcon
                            name="grid"
                            size={26}
                            color={scolor.iconBlurred}
                        />
                    </TouchableOpacityEx>
                    <TouchableOpacityEx 
                        style={[styles.buttonTouch] }
                        onPress={async() =>{ 
                            let flag = await AsyncStorage.getItem('@flags.HexagramSelectorButton')
                            if(!flag){
                                AsyncStorage.setItem('@flags.HexagramSelectorButton', 'yes') 
                                Alert.alert("Hexagram", null,
                                    [ 
                                        { text: '—', onPress: () => { }} ,
                                        
                                        { text: 'Cast', onPress: () => { navigation.push('HexagramSelector')}} ]
                                )
                            }else{
                                navigation.push('HexagramSelector')    
                            }
                        }}
                    >
                        <MaterialCommunityIcon
                            name="google-lens"
                            size={27}
                            color={scolor.iconBlurred}
                        />
                    </TouchableOpacityEx>
                    <TouchableOpacityEx
                        onPress={() => {
                            navigation.push('FlyingStars')
                        }}
                        style={[styles.buttonTouch]}
                    >
                            <MaterialCommunityIcon
                                name="star-box-outline"
                                size={29}
                                color={scolor.iconBlurred}
                            />
                    </TouchableOpacityEx> 
   
                    <TouchableOpacityEx
                        onPress={() => {
                            navigation.push('LuoPan')
                        }}
                        style={[styles.buttonTouch]}
                    >
                            <MaterialCommunityIcon
                                name="border-outside"
                                size={29}
                                color={scolor.iconBlurred}
                            />
                    </TouchableOpacityEx> 
                    <TouchableOpacityEx 
                        style={[styles.buttonTouch] }
                        onPress={async() =>{ navigation.push('Library')    }}
                    >
                        <MaterialCommunityIcon
                            name="file-document-box-outline"
                            size={30}
                            color={scolor.iconBlurred}
                        />
                    </TouchableOpacityEx>
                </View>
            )}
        </View>
    )
        
}
export default withNavigation(AtlasMenuBar)

const styles = StyleSheet.create({
    container:{
        flex:1, 
        flexDirection:'row',
    },
    toggler:{
        height:44,
        width:44,
        alignItems: 'center',
        justifyContent: 'center',
    },
    buttons:{
        justifyContent: 'flex-start',
        flexDirection: 'row',
    },
    buttonTouch:{
        width:44,
        height:44,
        alignItems: 'center',
        justifyContent: 'center',
    }
})
    



