
import { DateTime } from 'luxon'
import _ from 'lodash'

import * as SolarCal from '../../SolarCal'
import * as EightWords from '../../EightWords'
import * as WindWater from '../../WindWater'
import * as Tools from '../../Tools'
import * as Ordinals from '../../Ordinals'

import * as Process from './Process'

const pillarList = Ordinals.pillarOrdering
const stemList = Ordinals.stemOrdering
const branchList = Ordinals.branchOrdering

const hourTable = {
	jia: 'jia',
	yi: 'bing',
	bing: 'wu',
	ding: 'geng',
	wu: 'ren',
	ji:  'jia',
	geng: 'bing',
	xin: 'wu',
	ren: 'geng',
	gui: 'ren',
}
const getHourBranch = (tm) => {
	if (tm >= 1 * 60 && tm < 3 * 60) return 'chou'
	if (tm >= 3 * 60 && tm < 5 * 60) return 'yin'
	if (tm >= 5 * 60 && tm < 7 * 60) return 'mao'
	if (tm >= 7 * 60 && tm < 9 * 60) return 'chen'
	if (tm >= 9 * 60 && tm < 11 * 60) return 'si'
	if (tm >= 11 * 60 && tm < 13 * 60) return 'wu'
	if (tm >= 13 * 60 && tm < 15 * 60) return 'wei'
	if (tm >= 15 * 60 && tm < 17 * 60) return 'shen'
	if (tm >= 17 * 60 && tm < 19 * 60) return 'you'
	if (tm >= 19 * 60 && tm < 21 * 60) return 'xu'
	if (tm >= 21 * 60 && tm < 23 * 60) return 'hai'
	return 'zi'
}
const shiftPillar = (pillar, num=0) => pillarList[pillarList.findIndex(i => i[0] === pillar[0] && i[1] === pillar[1]) + num]


export const plot = (payload) => {
	const { 
		time,  //the only requirement
		chartName=null,
		gender='male', 
		root=null, 
		genderUnknown=false,
		hourUnknown=false, 
		lateZi=false ,
		showLuck=false, 
		showWeights=false, 
		shiftingPalace=undefined ,
		weightsIncludeCombos=true,
		simpleLuckCycle=true,
	} = payload
	let current = time
	if(typeof time === 'string'){ current = DateTime.fromISO(time, { setZone: true }) }
	const chineseTimeString = Tools.chineseTimeString(current)

	// console.log(current.toLocaleString(DateTime.DATETIME_FULL))
	const year = current.year
	const month = current.month
	const day = current.day
	const hour = current.hour
	const minute = current.minute

	// console.log(year, month, day, hour, minute, current.zone)
	let yPillar = []
	let mPillar = []
	let dPillar = []
	let hPillar = []

	let isPreviousYear = false;
	const inceptionYear = 1900  //year starts 1900 2month - 4day - 6hour - 8min
	const inception = DateTime.fromObject({ year: inceptionYear, month: 2, day: 4, hour: 6, minute: 8, zone: current.zone })
	const inceptionMidnight = inception.set({hour: 0, minute: 0 })
	const inceptionYearIndex = pillarList.findIndex(i => i[0] === 'geng' && i[1] === 'zi')
	const inceptionMonthIndex = pillarList.findIndex(i => i[0] === 'wu' && i[1] === 'yin')
	const inceptionDayIndex = pillarList.findIndex(i => i[0] === 'wu' && i[1] === 'shen')
	const minutesSinceDayBegin = hour * 60 + minute


	//Differences
	const yearDiff = year - inceptionYear
	const monthDiff = month - 2  + (yearDiff * 12)
	const modifiedDayDiff = Math.floor(current.diff(inceptionMidnight, ['days'], { conversionAccuracy: 'longterm'}).days)

	//Pillars
	yPillar = pillarList[inceptionYearIndex + yearDiff]
	mPillar = pillarList[inceptionMonthIndex + monthDiff]
	dPillar = pillarList[inceptionDayIndex + modifiedDayDiff]
	hPillar[1] = getHourBranch(minutesSinceDayBegin)
	let hIndex = stemList.indexOf( hourTable[dPillar[0]] ) + branchList.indexOf(hPillar[1])
	if(minutesSinceDayBegin >= 23 * 60) hIndex += 2
	if(hIndex > 9) hIndex -= 10
	hPillar[0] = stemList[hIndex]


	//Minute Pillar
	const minPillar = Process.calcMinutePillar(current, chineseTimeString, hPillar[0], hPillar[1])


	//Adjust Month
	const solarTerm = SolarCal.getYearMonthSolarTerm(year, month, current.zone, current.offset)
	if(solarTerm[0][0] % 2 === 0){ //First Term is Jie
		if(current < solarTerm[0][1]){
			mPillar = shiftPillar(mPillar, -1)
		}
	}else{  //First term is Qi
		if(current >= solarTerm[0][1]){
			mPillar = shiftPillar(mPillar, 1)
		}
	}

	//Adjust Year
	if(current < SolarCal.getCurrentYearJie(current)){
		yPillar = shiftPillar(yPillar, -1)
		isPreviousYear = true
	}

	//Late Zi Hour
	if(lateZi && minutesSinceDayBegin >= 1380 && minutesSinceDayBegin < 1440){
		dPillar = shiftPillar(dPillar, 1)
	}

	// console.log(yPillar, mPillar, dPillar, hPillar)

	//Luck Pillars
	const luckPillars = []
	if(showLuck){
		const yearStemPolarity = stemList.indexOf(yPillar[0]) % 2 ? "yin" : "yang"
		const luckDir = ( (yearStemPolarity === 'yin' && gender === 'male') || (yearStemPolarity === 'yang' && gender === 'female') ) ? 'reverse' : 'forward'

		let forwardMethod
		let reverseMethod
		let firstLuckPillarTime

		if(!simpleLuckCycle){
			forwardMethod =  Math.abs(current.diff(SolarCal.getForwardJie(current), 'minutes', { conversionAccuracy: 'longterm'}).minutes) * 2
			reverseMethod = Math.abs(current.diff(SolarCal.getReverseJie(current), 'minutes', { conversionAccuracy: 'longterm'}).minutes) * 2

			const intervalToFirstLuck = luckDir === 'forward' ? forwardMethod : reverseMethod
			firstLuckPillarTime = current.plus({ hours: intervalToFirstLuck })
		}else{
			forwardMethod =  Math.abs(current.diff(SolarCal.getForwardJie(current), 'days', { conversionAccuracy: 'longterm'}).days)
			reverseMethod = Math.abs(current.diff(SolarCal.getReverseJie(current), 'days', { conversionAccuracy: 'longterm'}).days) 
			const intervalToFirstLuck = luckDir === 'forward' ? (forwardMethod) : (reverseMethod)
			const theJie = luckDir === 'forward' ? SolarCal.getForwardJie(current) : SolarCal.getReverseJie(current)
			// console.log('daysToFirstLuck', luckDir, theJie.toFormat('yyyy-MMM-dd-H:m'), current.toFormat('yyyy-MMM-dd-H:m'), intervalToFirstLuck, intervalToFirstLuck/3 )
			firstLuckPillarTime = current.plus({ days: (intervalToFirstLuck/3) * 365 })
			// console.log('first luck pillar time', firstLuckPillarTime.toFormat('yyyy-MMM-dd-H:m'))
		}

		luckPillars.push({  
			pillar: _.cloneDeep(mPillar),
			time: current,
		})
		for(let i = 1; i < 11; i++ ){
			const pillar = shiftPillar(mPillar, luckDir === 'forward' ? i : -i)
			const time = firstLuckPillarTime.plus({ years: 10 * (i-1) })
			luckPillars.push({
				pillar,
				time
			})
		}
	}

	//Conception + Life Pillar


	const lifePillar = EightWords.getLifePalace(mPillar[1], hPillar[1], yPillar[0], current < solarTerm[0][1] || current >= solarTerm[1][1]) //add one to branch if after midpoint
	const conceptionPillar = EightWords.getConceptionPalace(mPillar[0], mPillar[1])


	//Process Pillars
	const pillars = [yPillar, mPillar, dPillar, hPillar, minPillar, conceptionPillar, lifePillar]
	const info =  { 
		time: current,
		gender, 
		genderUnknown,
		hourUnknown, 
		lateZi, 
		solarTerm: SolarCal.getCurrentSolarTerm(current), 
		shiftingPalace ,
		weightsIncludeCombos,
		chartName,
		isPreviousYear,
		chineseTimeString,
	}
	const processed = Process.formPayload({
		info,
		pillars,
		luckPillars,
		root,
		shiftingPalace,
	})


	if(showWeights) {
		Process.calcCounts(processed)
		Process.calcWeights(processed)
		Process.calcStats(processed)
		Process.calcFavorableGods(processed)
	}

	//Gua Number
	processed.meta.gua = WindWater.getPersonalGua(year, isPreviousYear, gender)

	return processed
}




