import React , { useContext } from 'react';
import AsyncStorage from '@react-native-community/async-storage';
import { DateTime } from 'luxon'
export const AuthContext = React.createContext()

export const myBirthday = async(context) => {
    let localBirth = await AsyncStorage.getItem('@cache.birthday')
    if(localBirth) {
        localBirth = JSON.parse(localBirth)
        localBirth.time = DateTime.fromISO(localBirth.time, { setZone: true })
    }
    const profileBirth = context?.profileQuery?.data?.user?.Birth
    if(profileBirth) profileBirth.time = DateTime.fromISO(profileBirth.time, { setZone: true })
    const birth = profileBirth || localBirth
    return Promise.resolve(birth)
}