

export const dateSuffix = (num) => {
    const date = String(num)
    const end = date.substr(date.length  - 1)
    if(end === '1'){
        return 'st'
    }else if(end === '2'){
        return 'nd'
    }else if(end === '3'){
        return 'rd'
    }else{
        return 'th'
    }
}

export const randomNum = (min, max) => Math.floor(Math.random() * (max - min + 1)) + min;

export const roundToHalf = (value)  => {
    const converted = parseFloat(value); // Make sure we have a number
    const convertedString = String(converted);
    let decimal = (converted - parseInt(convertedString, 10));
    decimal = Math.round(decimal * 10);
    if (decimal === 5) { return (parseInt(convertedString, 10)+0.5); }
    if ( (decimal < 3) || (decimal > 7) ) {
        return Math.round(converted);
    } else {
        return (parseInt(convertedString, 10)+0.5);
    }
}

export const prettyDistance = (num) => {
    const newNum = Math.round(10*num)/10;
    let result;
    if(newNum < 1){
        result = '< 1 mile';
    }else if(newNum > 500){
        result = '> 500 miles';
    }else{
        result = newNum + ' miles';
    }
    return result;
};

export const deg2rad = (deg) => deg * (Math.PI/180);
export const getDistanceFromLatLon = (lat1,lon1,lat2,lon2) => {
    const R = 6371; // Radius of the earth in km
    const dLat = deg2rad(lat2-lat1);  // deg2rad below
    const dLon = deg2rad(lon2-lon1);
    const a =
        Math.sin(dLat/2) * Math.sin(dLat/2) +
        Math.cos(deg2rad(lat1)) * Math.cos(deg2rad(lat2)) *
        Math.sin(dLon/2) * Math.sin(dLon/2)
        ;
    const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
    const dkm = R * c; // Distance in km
    const dmiles = 0.621371 * dkm; //distance in miles
    return dkm;
}

export const degreeToDirection = (degree) => {
    if (degree >= 22.5 && degree < 67.5) {
        return 'NE';
    }else if (degree >= 67.5 && degree < 112.5) {
        return 'E';
    }else if (degree >= 112.5 && degree < 157.5) {
        return 'SE';
    }else if (degree >= 157.5 && degree < 202.5) {
        return 'S';
    }else if (degree >= 202.5 && degree < 247.5) {
        return 'SW';
    }else if (degree >= 247.5 && degree < 292.5) {
        return 'W';
    }else if (degree >= 292.5 && degree < 337.5) {
        return 'NW';
    }else {
        return 'N';
    }
}



export const minute = 1000 * 60;
export const hour = minute * 60;
export const day =  hour * 24;
export const week = day * 7;
export const month = week * 4;
export const year = month * 12;

export const infiniteNegative = -9999999999999
export const infinitePositive = 9999999999999