const heavenTags = ['In appearance', 'To others',  'Outside', 'Above the surface', 'In spirit', 'From Heaven']
const earthTags = ['In reality', 'To myself',  'Inside', 'Below the surface', 'In form', 'On Earth']


export const titleLine = (pillar, stores) => {
    const pillarNameSyn = Dict.EightWords.pillars[pillar.name].$dict_syn
    const line = [
        { 
            words: Dict.EightWords.pillars[pillar.name].$dict_syn.map(i => toTitle(i)),
            shuffle: true,
        },
        {
            words: Dict.EightWords.pillars.$dict_syn.map(i => toTitle(i)),
            shuffle: true,
        }
    ]
    return line
}


export const heavenLine = (pillar, stores, root) => {
    const theStem = pillar.stem
    const stemColor = pillar.stem.elm._colors.light
    const stemElement = pillar.stem.elm
    const stemAspect = pillar.stem.aspc
    const stemGod = pillar.stem.gdd
    const line = [
        { 
            words: heavenTags.map( i => i + ', '),
            store: stores.heavenEarth,
            boxTextStyle:styles.bold
        },
        { 
            words: ['I am a'],
        },
        {
            words: theStem.$dict_adj.map(i => i ),
            shuffle: true,
        },

        { words: [','] },
        {
            words: [
                ...stemElement['$dict_adj2'].map(i => i  ),
                `${theStem.polarity === 'yang' ? 'strong' : 'gentle'}`,
            ],
            shuffle: true,
        },
        { words: [', and']},
        { words: [
            ...stemGod.$dict_adj,
            ...stemGod.$dict_adj_positive,
        ]},
        {
            words: [
                `aspects-${stemAspect.name}|${toTitle(stemAspect.archetype)}.`,
                `gods-${stemGod.abbr}|${toTitle(stemGod.archetype)}.`
            ]
        },
        {
            words:['My']
        },
        { 
            words: [
                toTitle(stemGod.$kin(root.info.gender)[0]),
                ...stemAspect.$dict_noun,
                ...stemAspect.$dict_noun2,
            ],
            shuffle: true,
        },
        { 
            words: ['is']
        },
        { 
            words: ['clearly visible.', 'exposed to others.', 'in plain sight.']
        }
    ]
    return line
}


