import ProPillarDetail from './ProPillarDetail';



class PillarExpansion extends React.Component{
    state={
        mode: 0,
    }
    constructor(props){
        super(props)
        this.switchMode = this.switchMode.bind(this)
    }
    switchMode(){
        const mode = this.state.mode === 0 ? 1 : 0
        this.setState({ mode })
    }
    render(){
        const sid = this.props.payload.section.sid
        return (
            <ProPillarDetail
                switchMode={this.switchMode}
                { ...this.props}
            /> 
        )
        if(this.state.mode === 0){
            if(sid === 'Birth'){
                return (
                    <LaymanRootDetail
                        switchMode={this.switchMode}
                        { ...this.props }
                    />
                )
            }else{
                return (
                    <LaymanExternalDetail
                        switchMode={this.switchMode}
                        { ...this.props }
                    />
                )
            }
        }else{
            return (
                <ProPillarDetail
                    switchMode={this.switchMode}
                    { ...this.props}
                />
            )
        }
    }
}



export default PillarExpansion