import analytics from '@segment/analytics-react-native'

class EnterConfirmationCode extends React.Component {
    constructor(props){
		super(props)
		this.onVerifyAuth = this.onVerifyAuth.bind(this)
		this.phone = this.props.navigation.getParam('phone')
		analytics.track('Auth.ConfirmationCode')
    }
    componentDidMount(){
	}
	async onVerifyAuth(code){
		const birthday = await AsyncStorage.getItem('@cache.birthday')
		const destination = this.props.navigation.getParam('destination')
		try{
			const result = await this.props.client.mutate({
				mutation: queries.verifyAuth,
				variables: { phone: this.phone, code, birthday },
			})
			const token = result?.data?.verifyAuth?.token || null
			if(!token){
				Alert.alert( 'Incorrect Code');
			}else{
				await this.context.completeAuth(token)
				await this.context.profileQuery.refetch()

				if(!this.context.profileQuery?.data?.user?.username){
					this.props.navigation.push('EnterUsername', { destination })
				}else if(destination){
					this.props.navigation.replace(destination)
				}else{
					this.props.navigation.replace('Atlas');
				}
			}
		}catch(err){ console.error(err) }
	}
    render(){
        return (
			<KeyboardAvoidingView 
				style={styles.container}
			>
				<Text style={styles.subtitle}>Enter Confirmation Code</Text>
				<Text style={styles.subtitle2}>sent to {this.phone}</Text>
				<CodeInput
					size={44}
					autoFocus={true}
					codeLength={6}
					inactiveColor={Color.GREY[300]}
					activeColor={Color.BLUE[500]}
					cellBorderWidth={2}
					containerProps={{ style: styles.codeInputContainer} }
					onFulfill={(code) => {
						this.onVerifyAuth(code)	
					}}
				/>
			</KeyboardAvoidingView>
        )
    }
}
EnterConfirmationCode.contextType = AuthContext
export default withApollo(withNavigation(EnterConfirmationCode))

