import React , { useContext }from 'react';
import * as _ from 'lodash'
import ReactNativeHapticFeedback from "react-native-haptic-feedback";
import { AuthContext } from '../../Contexts'
import { withNavigation } from 'react-navigation';
import AsyncStorage from '@react-native-community/async-storage';
import { verifyCheckpoints } from '../../components/Other/Checkpoint'
import { sstyle, scolor } from '../../styles/shared'

const hapticOptions = {
    enableVibrateFallback: false,
    ignoreAndroidSystemSettings: false
};
  

const withPreventDoubleClick = (WrappedComponent) => {
    class PreventDoubleClick extends React.PureComponent {
        debouncedOnPress = async () => {
            if(!this.props?.onPress){ return }
            ReactNativeHapticFeedback.trigger("impactLight", hapticOptions);
            const context= this.context

            const failed = await verifyCheckpoints(this.props.checkpoints, context, this.props.navigation) 
            if(!failed) this.props.onPress();
        }

        onPress = _.debounce(this.debouncedOnPress, 300, { leading: true, trailing: false });
        render() {
            return (<WrappedComponent underlayColor={scolor.touchableHighlightUnderlayColor} {...this.props} onPress={this.onPress} />)
        }
    }
    PreventDoubleClick.contextType = AuthContext
    PreventDoubleClick.displayName = `withPreventDoubleClick(${WrappedComponent.displayName ||WrappedComponent.name})`
    return withNavigation(PreventDoubleClick);
}
export default withPreventDoubleClick;