const HeavenEarthSeparator = ({ pillar }) => {
    if(!pillar) return <Fragment/>
    const cycles = Ordinals.cycles;
    const stemElement = pillar.stem.elm.name
    const branchElement = pillar.branch.stems.main.elm.name
    const line = []
    let image = ''

    if(stemElement === branchElement){
        image = 'roots'
        line.push({ words: ['Reflects', 'Fortifies', 'Reinforces']})
    }else if(cycles.produces[stemElement] === branchElement){
        image = 'produceDown'
        line.push({ words: ['Amplifies', 'Produces', 'Creates']})
    }else if(cycles.produces[branchElement] === stemElement){
        image = 'produceUp'
        line.push({ words: ['Amplifies','Produces',  'Creates']})
    }else if(cycles.controls[stemElement] === branchElement){
        image = 'controlDown'
        line.push({  words: ['Restrains','Controls', 'Suppresses']})
    }else if(cycles.controls[branchElement] === stemElement){
        image = 'controlUp'
        line.push({  words: [  'Restrains','Controls', 'Suppresses']})
    }
    const height = 18
    const iconSize = 18
    const tintColor = Color.GREY[400]
    return (
        <View style={{
            justifyContent: 'center',
            alignItems: 'center',
            flexDirection:'row',
            height,
            marginVertical:padd,

        }}>
            <View style={[{
                zIndex: -1,
                height:1,
                position:'absolute',
                top: height/2-0.5,
                left:0,
                width:winWidth,
                backgroundColor: Color.GREY[100],
            }, ]}/>
            <View style={{ flexDirection:'row', paddingHorizontal: 8, alignItems: 'center', backgroundColor: 'white'}}>
                <Image
                    source={CMImages.black.cycle[image]}
                    style={{ 
                        width: iconSize,
                        height: iconSize,
                        backgroundColor: 'white',
                        tintColor,
                    }}
                    resizeMode={'contain'}
                />
                <MadLibs
                    containerStyle={{ height, backgroundColor: 'white' , paddingLeft:3}}
                    line={line}
                    boxSelectStyle={{ borderBottomWidth: 0, padding: 0, marginTop:0, marginRight:0, height}}
                    boxTextStyle={{ fontSize: 13, fontWeight: '500', textAlign:'center', textTransform:'uppercase', color: tintColor }}
                    shuffle={ false}
                />
            </View>
        </View>
    )
}

export default HeavenEarthSeparator

