class HouseSelector extends React.Component {
    state={
        houseDegree: null,
        houseYear: null,
        doorDegree: undefined,
    }
    constructor(props){
        super(props)
        this.state.houseDegree = this.props.navigation.getParam('initial')?.houseDegree
        this.state.houseYear = this.props.navigation.getParam('initial')?.houseYear
        this.state.doorDegree = this.props.navigation.getParam('initial')?.doorDegree
        this.showDoor = this.props.navigation.getParam('showDoor') || false;
    }
    static navigationOptions = ({ navigation }) => {
        const { params={} } = navigation.state 
		return {
            title: 'House Selector'
        }
    }
    async componentDidMount(){
        this.yearInput.focus() 
        analytics.track('HouseSelector')
    }
    render(){
        return (
            <View style={styles.container}>

                <View style={styles.inputs} >
                    <TextInput
                        ref={c => {this.yearInput= c}} 
                        keyboardType={'numeric'}
                        style={styles.textInput}
                        placeholder={'Year'}
                        placeholderTextColor={Color.GREY[600]}
                        onChangeText={(houseYear) => {
                            this.setState({ houseYear })
                        }}
                        returnKeyType='done' 
                        value={this.state.houseYear ? String(this.state.houseYear) : ""}
                    />
                    <View style={{ flexDirection: 'row', marginTop:12,}}>
                        <TextInput
                            returnKeyType='done' 
                            placeholderTextColor={Color.GREY[600]}
                            style={[styles.textInput, { flex: 1}]}
                            placeholder={'Facing Degree'}
                            keyboardType={'decimal-pad'}
                            onChangeText={(houseDegree) => {
                                this.setState({ houseDegree })
                            }}
                            value={this.state.houseDegree ? String(this.state.houseDegree) : ""}
                        />
                        <Toucher
                            style={styles.compassHolder}
                            onPress={() => {
                                this.props.navigation.push('CompassDegreeSelector', { onSelect: (degree) => {
                                    this.usedCompass = true
                                    this.setState({ houseDegree: degree })
                                }})
                            }}
                        >
                            <MaterialCommunityIcon
                                name={'compass'}
                                size={30}
                                color={scolor.iconBlurred}
                            /> 
                        </Toucher>
                    </View>

                    { this.showDoor && (
                        <View style={{ flexDirection: 'row', marginTop:12,}}>
                            <TextInput
                                returnKeyType='done' 
                                placeholderTextColor={Color.GREY[600]}
                                style={[styles.textInput, { flex: 1}]}
                                placeholder={'Door Location'}
                                keyboardType={'decimal-pad'}
                                onChangeText={(doorDegree) => {
                                    this.setState({  doorDegree })
                                }}
                                value={this.state.doorDegree ? String(this.state.doorDegree) : ''}
                            />

                            <Toucher
                                style={styles.compassHolder}
                                onPress={() => {
                                    this.props.navigation.push('CompassDegreeSelector', { onSelect: (degree) => {
                                        this.usedCompass = true
                                        this.setState({ doorDegree: degree })
                                    }})
                                }}
                            >
                                <MaterialCommunityIcon
                                    name={'compass'}
                                    size={30}
                                    color={scolor.iconBlurred}
                                /> 
                            </Toucher>
                        </View>
                    )}
                </View>




                <View style={[styles.bar, { paddingTop: 0}]} >
                    <Toucher
                        style={styles.clearTouch}
                        onPress={async () => {
                            await AsyncStorage.removeItem('@cache.houseInput')
                            this.props.navigation.getParam('onHouseSelected')(null, this.usedCompass)
                            this.props.navigation.goBack()
                        }}
                    >
                        <Text style={styles.done}>Remove</Text>
                    </Toucher>
                    <View style={{ width: 2 }}/>
                    <Toucher
                        onPress={async () => {
                            const y = parseInt(this.state.houseYear)
                            const faceDegree = parseFloat(this.state.houseDegree)
                            const doorDegree = parseFloat(this.state.doorDegree)

                            if(typeof y === 'undefined' || typeof faceDegree === 'undefined' || isNaN(faceDegree) || y < 1864 || y > 2064 || faceDegree < 0 || faceDegree > 360){
                                Alert.alert('Invalid Values')
                                return 
                            }
                            if(typeof this.state.doorDegree !== 'undefined' && this.state.doorDegree !== null && (this.state.doorDegree < 0 || this.state.doorDegree > 360)){
                                Alert.alert('Invalid Values')
                                return
                            }


                            await AsyncStorage.setItem('@cache.houseInput', JSON.stringify({ 
                                houseYear: this.state.houseYear, 
                                houseDegree: this.state.houseDegree ,
                                doorDegree: this.state.doorDegree,
                            }))

                            this.props.navigation.getParam('onHouseSelected')({ 
                                houseYear: this.state.houseYear, 
                                houseDegree: this.state.houseDegree,
                                doorDegree: this.state.doorDegree,
                            } , this.usedCompass)

                            this.props.navigation.goBack()
                        }}
                        style={styles.doneTouch}
                    >
                        <Text style={[styles.done]}>Done</Text>
                    </Toucher>
                </View>
            </View>
        )
    }
}
export default withNavigation(HouseSelector)



