                                    if(i.type === 'stem'){
                                        return this.stemBox(i.val)
                                    }else if(i.type === 'branch'){
                                        return this.branchBox(i.val)
                                    }else if(i.type === 'text'){
                                        return <View style={styles.box}><Text>{toTitle(i.val)}</Text></View>
                                    }
