export const starsFromPillar = (root, pillar ) => {
    const stars = [] 

    const dayStemIndex = root.pillars.day.stem.number
    const dayBranchIndex = root.pillars.day.branch.number
    const monthBranchIndex = root.pillars.month.branch.number
    const yearBranchIndex = root.pillars.year.branch.number

    const pillarStem = pillar.stem.name
    const pillarBranch = pillar.branch.name


    Object.keys(specialPillarAux).forEach(name => {
        specialPillarAux[name].forEach(arr  => {
            if(arr[0] === pillar.stem.name && arr[1] === pillar.branch.name){
                 stars.push({ name, ref: 'specialPillarAux'})
            }
        })
    })

    if(pillar?.name === 'day'){
        Object.keys(specialDayMasterAux).forEach(name => {
            specialDayMasterAux[name].forEach(arr => {
                if(arr[0] === pillar.stem.name && arr[1] === pillar.branch.name){
                    stars.push({ name, ref: 'specialDayMasterAux'})
                }
            })
        })
    }

    //---------

    Object.keys(dayStemAux).forEach(name => {
        if(name === 'skyWealth'){
            if(dayStemAux[name][dayStemIndex] === pillarStem)
                stars.push({ name , ref: 'dayStemAux' })
        }else{
            const animal = dayStemAux[name][dayStemIndex]
 
            if( 
                (typeof animal === 'string' && pillarBranch === animal) || 
                (typeof animal === 'object' && animal.indexOf(pillarBranch) >= 0)
            ){
                stars.push({ name, ref: 'dayStemAux' })
            } 
        }
    })

    Object.keys(dayBranchAux).forEach(name => {
        const animal = dayBranchAux[name][dayBranchIndex]
        if(animal === pillarBranch)
            stars.push({ name, ref: 'dayBranchAux' })
    })

     
    Object.keys(monthBranchAux).forEach(name => {
        const matchPillar = monthBranchAux[name][monthBranchIndex]
        if(isPillarMatch(matchPillar, [pillarStem, pillarBranch]))
            stars.push({ name, ref: 'monthBranchAux' })
    })

    Object.keys(yearBranchAux).forEach(name => {
        if(name === 'sittingSha' || name === 'facingSha'){
            if(yearBranchAux[name][yearBranchIndex].indexOf(pillarStem) > 0)
                stars.push({ name, ref: 'yearBranchAux' })
        }else{
            const animal = yearBranchAux[name][yearBranchIndex]
            if(animal === pillarBranch)
                stars.push({ name, ref: 'yearBranchAux'})
        }
    })


    const result = stars.map(i => {
        return auxDetails[i.ref][i.name] || null
    })
    return result;
}


const isPillarMatch = (a, b) => {
    //([stem, branch], [stem, branch])
    let stemMatch = false
    let branchMatch = false
    if(a[0] === null && a[1] === null) return false
    if(a[0]){
        if(a[0] === b[0]){
            stemMatch = true
        }
    }else{
        stemMatch = true
    }
    if(a[1]){
        if(a[1] === b[1]){
            branchMatch =  true
        }
    }else{
        branchMatch = true
    }
    return (stemMatch && branchMatch)
}


