const getPillarGrade = (pillar) => {
    for(const item of pillarGrades.a){
        if(item[0] == pillar.heaven && item[1] == pillar.earth){
            pillar.grade = 'A'
            return 
        }
    }
    for(const item of pillarGrades.b){
        if(item[0] == pillar.heaven && item[1] == pillar.earth){
            pillar.grade = 'B'
            return
        }
    }
    for(const item of pillarGrades.c){
        if(item[0] == pillar.heaven && item[1] == pillar.earth){
            pillar.grade = 'C'
            return
        }
    }
}


