const SplitDistributionChart = ({ data }) => {
    const { chart1, chart2, overlap, labels } = data
    return (
        <View style={styles.container}>
            <View style={styles.top}>
                <View style={styles.halfScreen}>
                    {chart1.map(item => {
                        return (
                            <View style={styles.chartRow}>
                                <View style={[styles.againstBar, {  flex: (100-item.score) * .75 }]} />
                                <Text style={[styles.percentText, { marginRight: 6 }]}>{ item.score }%</Text>
                                <View style={[styles.supportBar, { backgroundColor: item.color, flex: (item.score) * 1.25 }]} />
                            </View>
                        )
                    })}
                </View>
                <View style={styles.labelHolder}>
                    {labels.map(label => (
                        <View style={styles.labelRow}>
                            <Text style={styles.labelText}>{ label  }</Text>
                        </View>
                    ))}
                </View>
                <View style={styles.halfScreen}>
                    {chart2.map(item => {
                        return (
                            <View style={styles.chartRow}>
                                <View style={[styles.supportBar, { backgroundColor: item.color, flex: (item.score) * 1.25 }]} />
                                <Text style={[styles.percentText, { marginLeft: 6 }]}>{ item.score }%</Text>
                                <View style={[styles.againstBar, {  flex: (100-item.score) * .75 }]} />
                            </View>
                        )
                    })}
                </View>
            </View>
            
        </View>
    ) 
}

export default SplitDistributionChart


