class GodStrengths extends React.Component{
    state = {
        strengths: null,
        selectedTabIndex: 0,
        tabLabels: ['Arch', 'Gods', 'Life', 'Asp', 'Attr', 'N1', 'N2', 'Kin']
    }
    constructor(props){
        super(props)
        this.process = this.process.bind(this)
    }
    componentDidMount(){
        this.process()
        this.getDisplayName = this.getDisplayName.bind(this)
    }
    componentDidUpdate(prevProps){
        if(prevProps.weightType !== this.props.weightType)
            this.process()
    }
    getDisplayName(k){
        if(this.state.selectedTabIndex === 2){
            const godMap = this.props.chart.meta.maps.godToStem
            return strings.toTitle(Ordinals.stems[godMap[k]].natureName)
        }else if(this.state.selectedTabIndex === 7){
            const gender = this.props.chart.info.gender;
            const defGen = {
                female:{
                    ir: 'Mother',
                    dr: 'Step-Mother', 
                    f: 'Sister',
                    rw: 'Brother',
                    eg: 'Daughter',
                    ho: 'Son',
                    iw: 'Step-Father',
                    dw: 'Father',
                    '7k': 'Boyfriend',
                    do:  'Husband',
                },
                male:{
                    ir: 'Step-Mother',
                    dr: 'Mother', 
                    f: 'Brother',
                    rw: 'Sister',
                    eg: 'Son-in-Law',
                    ho: 'Mother-in-Law',
                    iw: 'Girlfriend, Father',
                    dw: 'Wife',
                    '7k': 'Son',
                    do:  'Daughter',
                }
            }
            return defGen[gender][k]
        } else {
            return strings.toTitle(defs[this.state.selectedTabIndex][k])
        }
    }
    process(){
        const gods = this.props.chart.meta.maps.stemToGod
        const strengths = []
        const weightType = this.props.weightType
        Object.keys(this.props.chart.meta[weightType].ratio.stems).forEach(stem => {
            strengths.push({ display: this.getDisplayName(gods[stem]), stem: stem, god: gods[stem], val: this.props.chart.meta[weightType].ratio.stems[stem] })
        })
        const desiredOrder = ['ir','dr','f','rw','eg','ho','iw','dw','7k','do']
        strengths.sort((a, b) => { return a.val < b.val ? 1 : -1 })
        strengths.sort((a, b) => {
            return desiredOrder.indexOf(a.god.toLowerCase()) - desiredOrder.indexOf(b.god.toLowerCase())
        })

        this.setState({ strengths })
    }
    render(){
        if(!this.state.strengths) return <Fragment/>
        return (
            <View style={styles.container}>
                <View style={styles.tabBar}>
                    <SegmentedControlTab
                        allowFontScaling={false}
                        tabStyle={sstyle.sectionHeader.tabs.segmentTabStyle}
                        activeTabStyle={sstyle.sectionHeader.tabs.segmentTabActive}
                        tabTextStyle={sstyle.sectionHeader.tabs.segmentTabText}
                        activeTabTextStyle={sstyle.sectionHeader.tabs.activeTabTextStyle}
                        borderRadius={1}
                        tabsContainerStyle={{width: winWidth-12, alignSelf: 'center' }}
                        values={this.state.tabLabels}
                        selectedIndex={this.state.selectedTabIndex }
                        onTabPress={index =>  { 
                            this.setState({ selectedTabIndex: index }, () => this.process() )
                            analytics.track('Bazi.Analysis.8Words.Gods-' + index, { index })
                        }}
                    />
                </View>
                <View style={styles.content}>

                { this.state.strengths.map((item) => {
                    return (
                        <Toucher 
                            onPress={() => { this.props.navigation.push('Library', { path: 'fourPillars.' + item.god}) }}
                        >
                            <View style={styles.god}>
                                <Text style={styles.name}>
                                    { item.display } 
                                </Text>
                                <Text style={[styles.chinese]}>
                                    { Ordinals.stems[item.stem].chinese }
                                </Text>
                                { item.val === 0 ? (
                                    <View style={[styles.percent, { width: 1 }]}/>
                                ): (
                                    <View style={[styles.percent, 
                                        { width: 1 + (winWidth - nameWidth - leftWidth) * (item.val / 100) * 1},
                                        {backgroundColor: Graphics.colors.elements.light[Ordinals.stems[item.stem].element] } 
                                    ]}/>
                                )}
                                {item.val > 0 && (
                                <Text style={styles.num}>
                                    { item.val }%
                                </Text>
                                )}
                            </View>
                        </Toucher>
                    )
                })}
                </View>
        </View>
        )
    }
}
