import _ from 'lodash'


export const prettyTime = (seconds) => {
    if(seconds < 60){ //less than 1 minute
        return `${seconds} Seconds`
    }else if(seconds < (60 * 60)){ //less than 1 hour
        const minutes = Math.round(seconds / 60)
        return `${minutes} Minutes`
    }else if(seconds <  (60 * 60 * 24)){ //less than 24 hours
        const hours = (seconds / 3600).toFixed(1)
        return `${hours} Hours`
    }else if(seconds < (60 * 60 * 24 * 31)){ //less than 31 days
        const days = (seconds/86400).toFixed(1)
        return `${days} Days`  
    }else if(seconds < (60 * 60 * 24 * 365)){
        const months = (seconds / (86400 * 31)).toFixed(1)
        return `${months} Months`
    }else{
        const years = (seconds / (86400 * 31 * 12)).toFixed(1)
        return `${years} Years`
    }
}

export const proxyFunc =  {
    get(target, prop) {
        if (!isNaN(prop)) {
            prop = parseInt(prop, 10);
            if (prop < 0) {
                do{
                    prop += target.length;
                }while(prop < 0)
            }else if(prop > target.length -1){
                prop =  prop % target.length
            }
        }
        return target[prop];
    }
}


export const toProxy = (arr) => {
    return new Proxy(arr, proxyFunc)
}


export const chineseTimeString = (time) => {
    if(!time) return null
    let t = time
    if(time.hour % 2  === 0){ t = time.plus({ hours: -1 }) }
    const s = t.toFormat('yyyy-MM-dd-HH')
    return s 
}


export const find = (obj, key, val) => {
    const parts = Object.keys(obj)
    let found = null;
    for(let p of parts){
        if(obj[p][key] === val){
            found = obj[p]
            break;
        }
    }
    return _.cloneDeep(found);
}

export const toTitle = (text) => {
    if(!text) return ''
    return text.replace(/\w\S*/g, function(txt){
        return txt.charAt(0).toUpperCase() + txt.substr(1);
    });
}


export const capFirst = (text) => {
    if(!text) return '';
    return text.charAt(0).toUpperCase() + text.slice(1)
}

