class EnterInvitationCode extends React.Component {
    state={
        code: '',
    }
    constructor(props){
        super(props)
        this.submitCode = this.submitCode.bind(this)
    }
    async componentDidMount(){
        this.codeInput.focus()
        const existingCode = await AsyncStorage.getItem('@cache.branch.code') || ''
        this.setState({ code: existingCode })
    }
    async submitCode(){
        let code =  this.state.code 
        if(code.indexOf('/') >= 0){
            code = code.split('/').pop()
        }
        try{
            this.setState({ isLoading: true })
            const result = await this.props.client.mutate({
                mutation: queries.updateUserInvitationCode,
                variables: { code: code.trim() }
            })
            this.setState({ isLoading: false})
            const err = result.data.updateUserInvitationCode.err
            const newCodes = result.data.updateUserInvitationCode.codes
          
            if(err){
                Alert.alert(err)
                return
            }

            await AsyncStorage.setItem('@cache.invitationCode', this.state.code)
            await AsyncStorage.setItem('@cache.myInvitationCodes', JSON.stringify(newCodes))
            this.context.profileQuery.refetch()
            this.props.navigation.push('InvitationSuccess')
        }catch(err){
            console.log('.......', err)
            this.setState({ isLoading: false })
        }
    
    }
    render(){
        return (
                <KeyboardAvoidingView 
                    style={styles.container} 
                    behavior="padding" 
                    enabled
                >
                    <View style={styles.redBar}></View>
                    {/* <Text style={{
                        paddingHorizontal:24,
                        lineHeight:22,
                        fontSize:20,
                        fontWeight:'bold',
                    }}>Invitation Code</Text> */}
                    {/* <Text style={{
                        paddingHorizontal:24,
                        marginTop:9,
                        lineHeight: 21,
                    }}>
                        We are currently in Phase 1 development.  If you are interested in testing experimental features of our toolkit, please request a code from an existing member.
                    </Text> */}
                    <View style={styles.inputs}>
                        <TextInput
                            ref={c => { this.codeInput = c }} 
                            placeholder={''}
                            style={styles.textBox}
                            value={this.state.code}
                            onChangeText={(code) => {
                                this.setState({ code })
                            }}
                            autoCapitalize= 'none'
                            autoCorrect={false}
                            onSubmitEditing={this.submitCode}
                        />
                        <Toucher
                            underlayColor={scolor.touchableHighlightUnderlayColor} 
                            style={styles.submitButtonHolder}
                            onPress={this.submitCode}
                        >
                            { this.state.isLoading ? (
                                <ActivityIndicator size="small" olor={Color.GREY[700]}  />
                            ) : (
                            <MaterialCommunityIcon
                                name={'arrow-right'}
                                size={30}
                                color={Color.BLUEGREY[300]}
                            />
                            )}
                        </Toucher>
                    </View>
            </KeyboardAvoidingView>
        )
    }
}
EnterInvitationCode.contextType = AuthContext
export default withApollo(EnterInvitationCode)




