const DestinyBox = withNavigation((props) => {
    const { name, chart, settings} = props
    const meta = chart.palaces[name].meta
    const textBox = {
        fontWeight: 'bold',
        marginBottom:3,
        fontSize:12,
    }
    const destinyBox = {
        fontSize:12,
        backgroundColor: Graphics.colors.states.highlight,
        fontWeight: 'bold',
        paddingHorizontal:5,
        paddingVertical:3,
        marginBottom:5,
    }
    return (
        <Toucher 
            onPress={() => {
                props.navigation.push('PalaceDetails', { name, chart , settings})
            }}
            style={{ flex: 1, backgroundColor: props.palaceBackgroundColor , padding: 6,}}
        > 
            <View>
                {meta.destiny?.isDestinyPalace && (
                    <Text style={destinyBox}>Destiny</Text>
                )}
                { meta.destiny?.labels?.map(label => {
                    return (
                        <Text style={textBox} numberOfLines={1}>{ toTitle(label) }</Text>
                    )
                })}
            </View>
        </Toucher>
    )
})

const StructureBox = withNavigation((props) => {
    const textBox = {
        borderRadius: 2,
        padding:3,
        paddingHorizontal:5,
        color:'white',
        fontWeight: '500',
        fontSize:12,
        overflow:'hidden',
        marginBottom:2,
        alignSelf: "flex-start",
    }
    const { name, chart, settings} = props
    const meta = chart.palaces[name].meta
    return (
        <Toucher 
            onPress={() => {
                props.navigation.push('PalaceDetails', { name, chart , settings})
            }}
                style={{ flex: 1, backgroundColor: props.palaceBackgroundColor , padding: 4,}}
        >
            <View >
            {meta.structuresMap.positive.map(i => {
                const thing = MysticDoors.structures[i.name]
                return (
                    <Text
                        style={[
                            textBox,
                            { backgroundColor:Graphics.colors.states.good}
                        ]}
                        numberOfLines={1}
                        ellipsizeMode={'clip'}
                    >{ toTitle(thing.name) }</Text>
                )
            })}
            {meta.structuresMap.negative.map(i => {
                const thing = MysticDoors.structures[i.name]
                return (
                    <Text
                        style={[
                            textBox,
                            { backgroundColor: Graphics.colors.states.bad}
                        ]}
                        numberOfLines={1}
                        ellipsizeMode={'clip'}
                    >{ toTitle(thing.name) }</Text>
                )
            })}
            </View>
        </Toucher>
    )
})

const SquarePalace = (props) => {
    const { chart, name, navigation, settings, isDetailView=false, displayMode}  = props
    const context = useContext(AuthContext)
    const display = MysticDoors.displayTerminology[settings.qmdj.palace.namingConvention]


    const { showStrength, showElementalColor, showDayAndHourStemOutline, showLeadStemDoorStarOutline, showNumberOfStructures } = settings.qmdj.palace

    //Components
    const pillars = chart.bazi.pillars
    const details = chart.details
    const plot = chart.palaces[name].plot
    const meta = chart.palaces[name].meta

    //Details
    const leadDoor = details.leadDoor
    const leadStar = details.leadStar
    const hourStem = pillars.hour.stem.name

    //Plot
    const heavenStem = plot.heavenStem
    const earthStem = plot.earthStem
    const hiddenHeavenStem = plot.hiddenHeavenStem
    const hiddenEarthStem = plot.hiddenEarthStem
    const door = plot.door
    const star = plot.star
    const spirit = plot.spirit
    const deathvoid = plot.void ? '●' : ''
    const horse = plot.horse ? '🐴' : '' 
    const bird = plot.bird
    const isHeavenLeadStem = plot.isHeavenLeadStem
    const isEarthLeadStem = plot.isEarthLeadStem




    const yinDark = ['kan','gen','zhen','xun']
    const yangDark = ['li','kun','dui','qian']
    let isDark = false
    if(details.dun === 'yin'){
        isDark = yinDark.indexOf(plot.name) >= 0 ? true : false
    }else{
        isDark = yangDark.indexOf(plot.name) >= 0 ? true : false
    }
    const palaceBackgroundColor = isDark ? '#F7F7F7' : 'white'
    const positiveStructures = meta.structuresMap?.positive?.length || null
    const neutralStructures = meta.structuresMap?.neutral?.length || null
    const negativeStructures = meta.structuresMap?.negative?.length || null

    //colors
    const doorColor = Graphics.colors.elements.dark[MysticDoors.doors[door].details.element]
    const starColor = Graphics.colors.elements.dark[MysticDoors.stars[star].details.element]
    const spiritColor = Graphics.colors.elements.dark[MysticDoors.spirits[spirit].details.element]

    const heavenStemColorAccent = Graphics.colors.elements.accent[  Ordinals.stems[heavenStem].element ]
    const heavenStemColor = Graphics.colors.elements.dark[  Ordinals.stems[heavenStem].element ]
    const earthStemColor = Graphics.colors.elements.dark[  Ordinals.stems[earthStem].element ]

    //text styles
    const chineseText = {
        color: textColor,
        fontSize: isDetailView ? 18 : 14, 
    }

    const englishText = {
        color: textColor,
        fontSize: isDetailView ? 14 : 11,
    }

    const deText = {
        fontSize: isDetailView ? 17 : 13, 
        color: Color.GREY[500],
    }



    if(displayMode === 2){
        return <StructureBox palaceBackgroundColor={palaceBackgroundColor} { ...props } /> 
    }else if(displayMode === 3){
        return <DestinyBox palaceBackgroundColor={palaceBackgroundColor} { ...props } /> 
    }
   

    const isDayStem = (heavenStem === pillars.day.stem.name  || (isHeavenLeadStem && pillars.day.stem.name == 'jia'))
    const isHourStem = (heavenStem === pillars.hour.stem.name || (isHeavenLeadStem && pillars.hour.stem.name === 'jia'))
    const isDayStemHidden = hiddenHeavenStem === pillars.day.stem.name
    const isHourStemHidden = hiddenHeavenStem === pillars.hour.stem.name


    return (
        <Toucher
            onPress={async () => {
                if(isDetailView) return
                navigation.push('PalaceDetails', { name, chart , settings})
            }}
            underlayColor={isDetailView ? 'transparent' : scolor.touchableHighlightUnderlayColor}
            style={styles.touch}
        >
            <View style={[
                styles.inner,
                { backgroundColor: palaceBackgroundColor},
            ]}>
                <View style={styles.row}>
                    <View style={styles.col}>
                        <Text allowFontScaling={true} 
                            style={[
                                chineseText,
                                showElementalColor && { color: heavenStemColor },
                                (details.forecastStems?.hour === heavenStem || details.forecastStems?.day === heavenStem) && { backgroundColor: heavenStemColorAccent, color: 'black', padding:4, borderRadius: 10, overflow:'hidden'},
                                (showLeadStemDoorStarOutline && isHeavenLeadStem) && styles.lead,
                            ]}
                        >{ Ordinals.stems[heavenStem].chinese }</Text>
                        <Text allowFontScaling={true} style={englishText} ellipsizeMode={'clip'} numberOfLines={1}>{ toTitle(heavenStem) }</Text>
                    </View>
                    <View style={styles.col}>
                        <Text allowFontScaling={true} style={[chineseText,
                            showElementalColor && { color: spiritColor }
                        ]}>{ display.spirit[spirit][1] }</Text>
                        <Text allowFontScaling={true} style={englishText} ellipsizeMode={'clip'} numberOfLines={1}>{ toTitle(display.spirit[spirit][0]) }</Text>
                    </View>
                    <View style={[
                        styles.col,
                    ]}>
                        <Text allowFontScaling={true} 
                            style={[{ 
                                fontWeight: 'bold',
                                fontSize: isDetailView ? 18 : 14
                            },
                            (meta.destiny?.isDestinyPalace && details.reference === 'hour') && {  padding:4,  backgroundColor: Graphics.colors.states.highlight}
                        ]}
                        >{ Ordinals.guas[name].direction }</Text>
                    </View>
                </View>



                <View style={styles.row}>
                    <View style={styles.col}>
          
                        <View style={{ flexDirection: 'row', flex: 1 }}>
                            { !isDetailView && (

                            <View style={{ paddingLeft:4, justifyContent: 'space-between', }}>
                                { hiddenHeavenStem ? (
                                    <Text allowFontScaling={true} style={[
                                        styles.hiddenStem,
                                        (details.forecastStems?.hour === hiddenHeavenStem || details.forecastStems?.day === hiddenHeavenStem) && {backgroundColor:Graphics.colors.elements.accent[Ordinals.stems[hiddenHeavenStem].element], color: 'black', padding:4, borderRadius: 10, overflow:'hidden'},
                                    ]}>{ Ordinals.stems[hiddenHeavenStem].chinese }</Text>
                                ):(
                                    <View style={{ flex: 1 }}></View>
                                )}
                                    <View style={{ flex: 1 }}></View>
                                { hiddenEarthStem ? (
                                    <Text allowFontScaling={true} style={[
                                        styles.hiddenStem
                                    ]}>{ Ordinals.stems[hiddenEarthStem].chinese }</Text>
                                ):(
                                    <View style={{ }}></View>
                                )}
                            </View>
                            )}
                            <View style={{flex: 1,paddingRight:6, alignItems: 'flex-end', justifyContent: 'center'}}>
                                <Text allowFontScaling={true}  style={deText}>{ horse }</Text>
                                <Text allowFontScaling={true}  style={deText}>{ deathvoid}</Text>
                            </View>
                        </View>
                 
                    </View>
                    <View style={styles.col}>
                        <Text allowFontScaling={true} 
                            style={[chineseText,
                                (showLeadStemDoorStarOutline && star === details.leadStar) && styles.lead,
                                showElementalColor && { color: starColor }
                            ]}
                        >
                            { display.star[star][1] }
                        </Text>
                        <Text allowFontScaling={true} 
                            style={[englishText,
                                showStrength && meta.star.style,
                            ]} 
                            ellipsizeMode={'clip'} 
                            numberOfLines={1}
                            >{ toTitle(display.star[star][0]) }</Text>
                    </View>
                    <View style={styles.col}>
                        { displayMode === 0 && (
                            <View>
                                { positiveStructures > 0 && (
                                    <Text allowFontScaling={true} style={[styles.structureNum, { backgroundColor: Graphics.colors.states.good }]}>
                                        {positiveStructures}
                                    </Text>
                                )}
                                { neutralStructures > 0 && (
                                    <Text allowFontScaling={true} style={[styles.structureNum, { backgroundColor: Graphics.colors.states.neutral }]}>
                                        {neutralStructures}
                                    </Text>
                                )}
                                { negativeStructures > 0 && (
                                    <Text allowFontScaling={true} style={[styles.structureNum, { backgroundColor: Graphics.colors.states.bad }]}>
                                        {negativeStructures}
                                    </Text>
                                )}
                            </View>
                        )}
                        { displayMode === 1 && (
                            <View style={styles.hexHolder}>
                                <Text allowFontScaling={true} style={[styles.trigram, { marginBottom:-5}]}>{ Ordinals.guas[ MysticDoors.stars[plot.star].details.natalPalace ].trigram}</Text>
                                <Text allowFontScaling={true} style={[styles.trigram, { marginTop:-5}]}>{ Ordinals.guas[ MysticDoors.doors[plot.door].details.natalPalace ].trigram }</Text>
                            </View>
                        )}
                       
                    </View>
                </View>



                <View style={styles.row}>
                    <View style={styles.col}>
                        <Text allowFontScaling={true} style={[chineseText,
                            showElementalColor && { color: earthStemColor },
                        ]}>{ Ordinals.stems[earthStem].chinese }</Text>
                        <Text allowFontScaling={true} style={englishText} ellipsizeMode={'clip'} numberOfLines={1}>{ toTitle(earthStem) }</Text> 
                    </View>
                    <View style={styles.col}>
                        <View style={{ flexDirection: 'row', justifyContent: 'center', alignItems: 'center'}}>
                
                            { meta.door.specialInteractionIcon && (
                                <MaterialCommunityIcon
                                    name={meta.door.specialInteractionIcon}
                                    size={isDetailView ? 18 : 14}
                                    color={Color.GREY[500]}
                                    style={{ marginRight: 1}}
                                />
                            )}
                            <Text allowFontScaling={true} 
                                style={[chineseText,
                                    (showLeadStemDoorStarOutline && door === details.leadDoor) && styles.lead,
                                    showElementalColor && { color:  doorColor}
                                ]}
                            >
                                { display.door[door][1] }
                            </Text>
                        </View>
                        <Text allowFontScaling={true} 
                            style={[englishText,
                                showStrength && meta.door.style
                            ]} 
                            ellipsizeMode={'clip'} 
                            numberOfLines={1}
                            >{ toTitle(display.door[door][0]) }</Text>
                    </View>
                    <View style={styles.col}>
          

                    { displayMode === 0&& (
                            <MaterialCommunityIcon
                                name={meta.door.palaceInteractionIcon}
                                size={isDetailView ? 24 : 16}
                                color={Color.GREY[500]}
                            />
                    )}

                    { displayMode === 1 && (
                        <Text allowFontScaling={true} style={[styles.periodNum]}>
                            { plot.periodNum}
                        </Text>
                    )}
                        
                        

                    </View>
                </View>
            </View>
        </Toucher>
    )
}
export default withNavigation(SquarePalace)



