const ArchetypeBox = (props) => {
    const { pillar } = props
    const branchGod = pillar.branch.stems.main.gdd
    const branchAspect = pillar.branch.stems.main.aspc

    const  titleLine = [
        {
            words: [
                `gods-${branchGod.abbr}|${toTitle(branchGod.archetype)}`,
                `gods-${branchGod.abbr}|${toTitle(branchAspect.archetype)}`,
            ],
            shuffle: true,
            iconStyle:{ width: 22, height: 22, marginRight:9}
        }
    ]
    const descLine = [
        // { words: ['I']},
        // { words: ['naturally', 'likely', 'generally', 'tend to'], shuffle: true},
        { words: ['Tends to', 'Inclined to']},
        { 
            words: [
                ...branchAspect.$dict_verb.map(i => (i))
            ],
            shuffle: true
        },

        { words: [
            ...branchAspect.$dict_noun.map(i => `${(i)}`),
            `${(branchAspect.name)}`,
        ], shuffle: true},
        { words: ['and']},
        { words:['seek', 'receive']},
        {
            words: [
                ...branchGod.$dict_adj.map(i => i)
            ],
            shuffle: true,
        }, 
        { words: [
            ...branchAspect.$dict_noun2.map(i => `${(i)}.`),
        ], shuffe: true}
    ]


    return (
        <View style={styles.container}>
           
            <View style={styles.right}>
                <MadLibs
                    line={titleLine}
                    containerStyle={{ flexWrap: 'nowrap', paddingHorizontal:padd,}}
                    boxSelectStyle={{ alignItems: 'flex-start', justifyContent: 'center', marginRight:4, paddingVertical:padd }}
                    boxTextStyle={{ fontWeight: 'bold', fontSize: 16,}}
                />
                <View style={{ height: 1, backgroundColor: scolor.separator}}/>
                <View style={styles.content}>
                    <MadLibs
                        line={descLine}
                        boxViewStyle={{ marginRight:4, marginBottom:4,}}
                        containerStyle={{ padding: padd}}
                    />
                </View>
            </View>
            <View style={styles.left}>
                { branchGod.$dict_abilities.map((i, index) => (
                    <View style={[
                        styles.abilityRow,
                        (index === 0 || index === 1) && { borderBottomWidth:1, borderColor: scolor.separator }
                    ]}>
                        <Image
                            source={CMImages.color.abilities[i]}
                            style={styles.icon}
                        />
                        <Text style={{ fontWeight: '600', fontSize: 14, }}>{ toTitle(i) }</Text>
                    </View>
                ))} 
            </View>
        </View>
    )
}
