import * as Ordinals from '../../lib/cmtools/Ordinals'
import * as MysticDoors from '../../lib/cmtools/MysticDoors'

const QiMenDetailTable = ({chart, settings }) => {
    const display = MysticDoors.displayTerminology[settings.qmdj.palace.namingConvention]
    const head = ['Lead Stem – Jia', 'Lead Door – Envoy', 'Lead Star', 'Heavenly Yi', 'Structure', 'Method', 'Star Path'] 

    const details = chart.details
    const pillars = chart.bazi.pillars
    const structure = toTitle(details.dun) + ' ' + details.ju 

    const leadDoor =  display.door[details.leadDoor][1]  + ' ' + toTitle(display.door[details.leadDoor][0])
    const leadStar = (details.grainIsBird && details.leadStar==='grain') ? `${display.star['bird'][1]} ${toTitle(display.star['bird'][0])}` : `${ display.star[details.leadStar][1] } ${toTitle(display.star[details.leadStar][0])}`

    const method = chart.details.method === 0 ? 'Zhi Run' : 'Chai Bu'
    const starPath = chart.details.starPath === 0 ? 'Rotating' : 'Flying'

    const hy = chart.details.victories['light']
    const heavenYi = `${Ordinals.guas[hy].direction} - ${toTitle(hy)} (${toTitle( display.star[chart.palaces[hy].plot.star][0] )})`

    const  data = [ 
        Ordinals.stems[details.leadStem].chinese + ' ' + toTitle(details.leadStem), 
        leadDoor, 
        leadStar,
        heavenYi, 
        structure, 
        method,
        starPath
    ]

    if(details.housePeriod && details.houseStemBranch){
        head.unshift('House Stem Branch')
        head.unshift('House Period')
        data.unshift(toTitle(details.houseStemBranch))
        data.unshift(details.housePeriod)
    }


    return (
        <Table borderStyle={styles.table}>
            <TableWrapper  style={{flexDirection: 'row'}}>
                <Col data={head} textStyle={styles.detailsHead} />
                <Col data={data} textStyle={styles.detailsText} />
            </TableWrapper>
        </Table>
    )
}
export default React.memo(QiMenDetailTable)

