class EditSettings extends React.Component {
    state={
        tabIndex: 0
    }
    static navigationOptions = ({ navigation }) => {
        const { params={} } = navigation.state 
        const tabValues=['Settings', 'Invite', 'Profile']
		return {
            headerTitle:(
                <View style={{ flex: 1}}>
                    <SegmentedControlTab
                        allowFontScaling={false}
                        tabStyle={styles.segmentTabStyle}
                        activeTabStyle={styles.segmentTabActive}
                        tabTextStyle={styles.segmentTabText}
                        borderRadius={2}
                        tabsContainerStyle={{ flex:1, }}
                        values={tabValues}
                        selectedIndex={params.tabIndex}
                        onTabPress={index =>  { 
                            params.setTabIndex(index)
                        }}
                    />
                </View>
            ),
            headerRight:(
                <View style={sstyle.navigation.navHeaderRight} >
                    <AuthContext.Consumer>
                    {context => {
                        if(!context.auth) return <Fragment/>
                        return(
                            <TouchableOpacityEx 
                                onPress={() => {
                                    const buttons = [
                                        'Logout',
                                        '—'
                                    ];
                                    ActionSheet.showActionSheetWithOptions({
                                        options:  buttons,
                                        cancelButtonIndex: 2,
                                        tintColor: Color.GREY[700],
                                    },async (buttonIndex) => {
                                        if(buttonIndex === 0){
                                            await context.logout()
                                            context.profileQuery?.refetch()
                                            Alert.alert('Logout Successful')
                                            navigation.goBack()
                                        }
                                    });
                                }}
                                style={[sstyle.navigation.navHeaderItem] }
                            >
                                <FontAwesome5
                                    name="ellipsis-h"
                                    size={22}
                                    color={scolor.iconBlurred}
                                />
                            </TouchableOpacityEx>
                        )
                    }}
                    </AuthContext.Consumer>
				</View>
            )
 
        }
    }
    constructor(props){
        super(props)
        this.setTabIndex = this.setTabIndex.bind(this)
        this.state.tabIndex = this.props.navigation.getParam('defaultTabIndex', 0)
        this.state.defaultTabIndexPreferences = this.props.navigation.getParam('defaultTabIndexPreferences', 0)
        this.props.navigation.setParams({ tabIndex: this.state.tabIndex, setTabIndex: this.setTabIndex })
    }
    async setTabIndex(tabIndex){
        if(tabIndex === 2){ //profile
            const failed = await verifyCheckpoints(['login'], this.context, this.props.navigation)
            if(failed) return 
        }
        this.setState({ tabIndex}, () => { this.props.navigation.setParams({ tabIndex }) })
    } 
    render(){
        return (
            <View style={styles.container}>
                { this.state.tabIndex === 0 && (
                    <EditPreferences
                        defaultTabIndexPreferences={this.state.defaultTabIndexPreferences}
                     />
                )} 
                {this.state.tabIndex === 1 && (
                    <MyInvitationCodes/>
                )}

                { this.state.tabIndex === 2 && (
                    <EditProfile/>
                )}
            </View>
        )
    }
}
EditSettings.contextType = AuthContext
export default withApollo(withNavigation(EditSettings))

