import * as Ordinals from '../../lib/cmtools/Ordinals'

const ThreeVictorySummary = ({ chart, navigation }) => {
    const data = []

    Object.keys(chart.details.victories).forEach(name => {
        const palace = chart.details.victories[name]
        data.push({
            head: toTitle(name),
            body: `${ Ordinals.guas[palace]?.direction } - ${toTitle(palace)}`
        })
    })

    return (
        <View  style={styles.container}>
            { data.map(item => {
                return (
                    <Toucher
                        onPress={() => {
                            const path = `qiMenDunJia.victoryPalaces.${item.head.toLowerCase()}`
                            navigation.push('Library', { path , hideClose: true})
                        }}
                    >
                        <View style={styles.row}>
                            <Text style={styles.head}>
                                { item.head}
                            </Text>
                            <Text style={styles.body}>
                                {item.body}
                            </Text>
                            <MaterialCommunityIcon
                                name={'chevron-right'}
                                size={24}
                                color={scolor.iconBlurred}
                                style={styles.chevron}
                            />
                        </View>
                    </Toucher>
                )
            })}
        </View>
    )
}
export default React.memo(withNavigation(ThreeVictorySummary))



