class EnterPhone extends React.Component {
	constructor(props){
		super(props)
		this.onPressFlag = this.onPressFlag.bind(this)
		this.selectCountry = this.selectCountry.bind(this)
		this.onRequestAuth = this.onRequestAuth.bind(this)
		this.state = {
			cca2: 'US',
		};
		analytics.track('Auth.Phone')
	}
	componentDidMount(){
		this.phone.focus()
	}
	onPressFlag(){
		this.countryPicker.openModal();
	}
	selectCountry(country) {
		this.phone.selectCountry(country.cca2.toLowerCase());
		this.setState({ cca2: country.cca2 });
	}
	async onRequestAuth(){
		const phone = this.phone.getValue()
		const destination = this.props.navigation.getParam('destination') || null
		try{
			const result = await this.props.client.mutate({
				mutation: queries.requestAuth,
				variables: { phone }
			})
			if(!result?.data?.requestAuth?.success ){
				const error = result?.data.requestAuth?.error || 'Unable to login'
				Alert.alert(error)
			}else{
				this.props.navigation.push('EnterConfirmationCode', { phone, destination })
			}
		}catch(err){ 
			console.log(err) 
		}
	}
    render(){
        return (
			<KeyboardAvoidingView 
				style={styles.container} 
				behavior="padding" 
				enabled
			>
				<View style={{  justifyContent:'center', alignItems: 'center'}}>
					<Image
						source={require('../../assets/images/logo.png')}
						style={styles.logo}
						resizeMode="contain"
					/>
				</View>
				<View style={styles.inputHolder}>
					<PhoneInput
						// value={'88888888'}
						ref={(ref) => { this.phone = ref; }}
						// onPressFlag={this.onPressFlag}
						initialCountry={'us'}
						textProps={{placeholder: 'Phone'}}
						textStyle={styles.phoneInputText}
						style={styles.phoneInput}
						autoFormat={true}
						pickerButtonTextStyle={{padding:10, fontSize:18, fontWeight:'500', color: Color.BLUE[500]}}
					/>
					<Toucher
						style={styles.submitTouch}
						onPress={() => { 
							this.onRequestAuth()
						}}
					>
						<MaterialCommunityIcon
							name={'arrow-right'}
							size={30}
							color={Color.BLUEGREY[300]}
						/>
					</Toucher>
					
				</View>
				<View
					underlayColor={scolor.touchableHighlightUnderlayColor}
					style={styles.termsHolder}
				>
					<Text style={styles.termsText}>We will never send you unsolicited text messages or sell your contact information.</Text>
				</View>
			</KeyboardAvoidingView>
        )
    }
}
export default withApollo(withNavigation(EnterPhone))

