import React, {Fragment, useContext} from 'react';
import {
	SafeAreaView,
	StyleSheet,
	ScrollView,
	View,
	Text,
	StatusBar,
	TextInput,
    Button,
    Animated,
    Easing,
    TouchableHighlight,
    TouchableOpacity,
    Dimensions,
    ActivityIndicator
} from 'react-native';
import AsyncStorage from '@react-native-community/async-storage'
import { AuthContext } from '../../Contexts'


export class Checkpoint extends React.Component{
    state={
        failed: undefined
    }
    constructor(props){
        super(props)
    }
    async componentDidMount(){
        const failed = await verifyCheckpoints(this.props.checkpoints, this.context)
        this.setState({ failed })
    }
    render(){
        if(this.state.failed === null){
            return this.props.children
        }else if(this.props.altView){
            return this.props.altView
        }else{
            return <Fragment/>
        }
    }
}
Checkpoint.contextType = AuthContext;


export const verifyCheckpoints = async(checkpoints, context=null, navigation=null, destination=null) => {
    if(checkpoints && checkpoints.length > 0){
        const usernameCache = await AsyncStorage.getItem('@cache.username')
        const invitationCache = await AsyncStorage.getItem('@cache.invitationCode')

        if(checkpoints.indexOf('login') >= 0){
            if(!context?.auth){
                Promise.resolve('login')
                return navigation?.push('EnterPhone')
            }else if(!usernameCache){
                Promise.resolve('username')
                return navigation?.push('EnterUsername', { destination })
            }
        }

        // if(checkpoints.indexOf('invitation') >= 0 && !invitationCache){
        //     return Promise.resolve('invitation')
        // }

        if(checkpoints.indexOf('hidden') >= 0){
            return Promise.resolve('hidden')
        }

    }
    return Promise.resolve(null)
}
