import React, { useState , useEffect , Fragment} from 'react';

import { TouchableHighlight, StyleSheet, Text, View , Image, Dimensions, Linking} from 'react-native';
import {sstyle, scolor } from '../../styles/shared'
import Color from 'react-native-material-color'
import { toTitle } from '../../lib/utils/strings'
import { PieChart } from 'react-native-chart-kit'
import * as strings from '../../lib/utils/strings'
import SectionHeader from '../Layout/SectionHeader'
import withPreventDoubleClick from '../../lib/utils/withPreventDoubleClick'
const Toucher = withPreventDoubleClick(TouchableHighlight)
import FontAwesome5 from 'react-native-vector-icons/FontAwesome5';
const winWidth = Dimensions.get('window').width
const winHeight = Dimensions.get('window').heigh
import SegmentedControlTab from "react-native-segmented-control-tab";
import * as Graphics from '../../lib/cmtools/Graphics'
import analytics from '@segment/analytics-react-native'
import _ from 'lodash'
import { withNavigation } from 'react-navigation';
import GodStrengths from './GodStrengths'
import {  getPreferences } from '../../containers/PreferencesContainer'

class ElementDistribution extends React.Component{
    state = {
        weightType: null,
        selectedTabIndex: 0,
        data: [],
        favorable: [],
        tabLabels: ['Element', 'Aspect', 'Character', 'Archetype', 'Force', 'Focus']
    }
    constructor(props){
        super(props)
        this.process = this.process.bind(this)

        this.supportScore = this.props.chart.meta.stats.supportScore
    }
    async componentDidMount(){
        const preferences = await getPreferences()
        const weightType = preferences?.bazi?.calculations?.showCombinationsInWeightCalculation ? 'weightsCombo' : 'weightsPlain'
        this.setState({ weightType})
        this.process()
    }
    getDisplayName(k){
        const aspectToElement = this.props.chart.meta.maps.aspectToElement
        const defs = [
            { 
                resource: aspectToElement.resource,
                companion: aspectToElement.companion,
                output: aspectToElement.output,
                wealth: aspectToElement.wealth,
                power: aspectToElement.power,
            },
            { 
                resource: 'resource',
                companion: 'companion',
                output: 'output',
                wealth: 'wealth',
                power: 'power',
            },
            { 
                resource: 'idealistic',
                companion: 'strong',
                output: 'authentic',
                wealth: 'pragmatic',
                power: 'accountable',
            },
            { 
                resource: 'thinker',
                companion: 'leader',
                output: 'creator',
                wealth: 'executor',
                power: 'influencer',
            },
            { 
                resource: 'consume',
                companion: 'gather',
                output: 'create',
                wealth: 'exchange',
                power: 'command',
            },
            { 
                resource: 'supply',
                companion: 'assistance',
                output: 'product',
                wealth: 'value',
                power: 'authority',
            },
   
  
        ]
        return toTitle(defs[this.state.selectedTabIndex][k])
    }
    async process(){

        const scores = this.props.chart.meta[this.state.weightType].ratio.aspects
        const aspectToElement = this.props.chart.meta.maps.aspectToElement
        const data = []

        Object.keys(scores).forEach(k => {
            data.push({ 
                aspect: toTitle(k), 
                name: this.getDisplayName(k),
                score: scores[k],
                color: Graphics.colors.elements.light[aspectToElement[k]]
            })
        })

        const desiredOrder = ['resource','companion','output','wealth','power']
        data.sort((a, b) => { return desiredOrder.indexOf(a.aspect.toLowerCase()) - desiredOrder.indexOf(b.aspect.toLowerCase()) })

        //Favorable elements
        const favorable = this.props.chart.meta?.favorable?.aspects.map(a => {
            return { aspect: a, name: this.getDisplayName(a) }
        })
        this.setState({ data , favorable})
    }    
    render(){
        if(!this.state.data) return <Fragment/>
        return (
            <View style={styles.container}>
                <View style={sstyle.sectionHeader.tabs.tabBarHolder}>
                    <SegmentedControlTab
                        allowFontScaling={false}
                        tabStyle={sstyle.sectionHeader.tabs.segmentTabStyle}
                        activeTabStyle={sstyle.sectionHeader.tabs.segmentTabActive}
                        tabTextStyle={sstyle.sectionHeader.tabs.segmentTabText}
                        activeTabTextStyle={sstyle.sectionHeader.tabs.activeTabTextStyle}
                        borderRadius={1}
                        tabsContainerStyle={{width: winWidth-12, alignSelf: 'center' }}
                        values={this.state.tabLabels}
                        selectedIndex={this.state.selectedTabIndex }
                        onTabPress={index =>  { 
                            this.setState({ selectedTabIndex: index }, () => this.process() )
                            analytics.track('Bazi.Analysis.8Words.PieChart', { index })
                        }}
                    />
                </View>

                <PieChart
                    data={this.state.data}
                    width={winWidth}
                    height={200}
                    chartConfig={{
                        color: (opacity = 1) => `rgba(255, 255, 255, ${opacity})`,
                    }}
                    accessor="score"
                    backgroundColor="transparent"
                />
                <View style={styles.balanceHolder}>
                    <View style={[styles.balanceBar, styles.supporting, { flex: this.supportScore }]}>
                        <Text style={styles.balanceNum}>{this.supportScore}%</Text> 
                    </View>
                    <View style={[styles.balanceBar, styles.against, { flex: 100 - this.supportScore }]}/>
                </View>
{/* 
                <Toucher
                    onPress={() => {
                        this.props.navigation.push('BasicWebView', { uri: 'https://chinesemetaphysics-prod.s3.ap-southeast-1.amazonaws.com/assets/content/8-words-scoring.pdf'})
                    }}
                    style={{ height: 32, backgroundColor: scolor.separator, justifyContent: 'center', alignItems: 'flex-end'}}
                >
                    <View style={{ flexDirection: 'row', justifyContent: 'space-between'}}>

                        <Text style={{ color: Color.GREY[500], fontWeight: '500', fontSize: 12, marginLeft: 12, flex: 1}} >Combinations Included: {  this.props.chart.info.weightsIncludeCombos  ? 'Yes' : 'No' }</Text>
                        <Text style={{ color: Color.GREY[500], fontWeight: '500', fontSize: 12, marginRight: 12, flex:1 , textAlign:'right'}}>Scoring Methodology →</Text>
                    </View>
                </Toucher> */}


                <View style={{
                    flexDirection: 'row', 
                    height: 32, 
                    backgroundColor: Color.GREY[50], 
                    justifyContent: 'space-between', 
                    alignItems: 'center' 
                }}>
                    <Toucher
                        style={{ 
                            flex:1,
                            alignSelf: 'stretch',
                            justifyContent: 'center',
                            alignItems: 'flex-start',
                            paddingLeft:12,
                        }}
                        onPress={() => {
                            this.props.navigation.push('EditSettings', {defaultTabIndexPreferences:  7 }) 
                            // const newValue = this.state.weightType === 'weightsPlain' ? 'weightsCombo' : 'weightsPlain'
                            // console.log(newValue)
                            // this.setState({ weightType: newValue }, () => {
                            //     this.process()
                            // })
                        }}
                    >
                        <Text style={{ fontSize: 13, color: Color.GREY[500] }} >
                            {/* Combinations { this.state.weightType === 'weightsPlain' ? 'Off' : 'On'}  */}
                            Combinations: { this.props.chart.info.weightsIncludeCombos  ? 'On' : 'Off'} 
                        </Text>
                    </Toucher>
                    <Toucher
                        style={{
                            flex:1,
                            alignSelf: 'stretch',
                            justifyContent: 'center',
                            alignItems: 'flex-end',
                            paddingRight:12,
                        }}
                        onPress={() => {
                            this.props.navigation.push('BasicWebView', { uri: 'https://chinesemetaphysics-prod.s3.ap-southeast-1.amazonaws.com/assets/content/8-words-scoring.pdf'})
                        }}
                    >
                        <Text style={{fontSize: 13, color: Color.GREY[500]}}>Methodology ⇾</Text>
                    </Toucher>
                </View>






                { this.state.data.length > 0 && (
                    <View>
                        <View style={styles.separator}/>
                        <Toucher
                            onPress={() => {
                                const arr = _.cloneDeep(this.state.data).sort((a, b) => { return  b.score - a.score  })
                                if(this.state.selectedTabIndex === 0){
                                    const element = arr[0].name.toLowerCase()
                                    const path = 'elements.' + element
                                    this.props.navigation.push('Library', { path } )
                                }else{
                                    const aspect = arr[0].aspect.toLowerCase()
                                    const path = 'fourPillars.' + aspect
                                    this.props.navigation.push('Library', { path } )
                                }
                            }}
                        >
                            <View style={[styles.infoRow]}>
                                <View style={styles.title}>
                                    <Text style={styles.titleText}>
                                        Strongest 
                                    </Text>
                                </View>
                                <View style={styles.detail}>
                                    <Text style={styles.detailText}>
                                        { _.cloneDeep(this.state.data).sort((a, b) => { return  b.score - a.score  })[0].name }
                                    </Text>
                                </View>
                            </View>
                        </Toucher>
                        <View style={styles.separator}/>
                        <Toucher
                            onPress={() => {
                                const arr = _.cloneDeep(this.state.data).sort((a, b) => { return  b.score - a.score  })
                                if(this.state.selectedTabIndex === 0){
                                    const element = arr[4].name.toLowerCase()
                                    const path = 'elements.' + element
                                    this.props.navigation.push('Library', { path } )
                                }else{
                                    const aspect = arr[4].aspect.toLowerCase()
                                    const path = 'fourPillars.' + aspect
                                    this.props.navigation.push('Library', { path } )
                                }
                            }}
                        >
                            <View style={[styles.infoRow]}>
                                <View style={styles.title}>
                                    <Text style={styles.titleText}>
                                        Weakest 
                                    </Text>
                                </View>
                                <View style={styles.detail}>
                                    <Text style={styles.detailText}>
                                        { _.cloneDeep(this.state.data).sort((a, b) => { return a.score - b.score  })[0].name }
                                    </Text>
                                </View>
                            </View>
                        </Toucher>

                    </View>
                )}




                { this.state.favorable.length > 0 && (
                    <View>
                        <SectionHeader title={`Balancing ${this.state.tabLabels[this.state.selectedTabIndex]}`} />
                        { this.state.favorable.map(i => (
                            <Toucher
                                onPress={() => {
                                    if(this.state.selectedTabIndex === 0){
                                        const element = i.name.toLowerCase()
                                        const path = 'elements.' + element
                                        this.props.navigation.push('Library', { path } )
                                    }else{
                                        const aspect = i.aspect.toLowerCase()
                                        const path = 'fourPillars.' + aspect
                                        this.props.navigation.push('Library', { path } )
                                    }
                                }}
                            >
                                <View>
                                    <View style={[styles.infoRow]}>
                                        <View style={styles.title}>
                                            <Text style={styles.titleText}>
                                                { i.name }
                                            </Text>
                                        </View>
                                    </View> 
                                    <View style={styles.separator}/>
                                </View>
                            </Toucher>
                        ))}
                    </View>
                )}


                { this.state.weightType !== null && (
                <GodStrengths
                    chart={this.props.chart}
                    weightType={this.state.weightType}
                />
                )}

            </View>
        )
    }
}

export default withNavigation(ElementDistribution);


