class InitialDisplaySelector extends React.Component {
    state={
        selectedTabIndex: 0
    }
    static navigationOptions = ({ navigation }) => {
        const { params={} } = navigation.state 
		return {
            title: 'Presets'
        }
    }
    constructor(props){
        super(props)
        this.skip = this.skip.bind(this)
        this.submit = this.submit.bind(this)
    }
    async componentDidMount(){
    }
    skip(prefs){
        this.props.navigation.goBack()
        analytics.track('PillarPresetSelector-Skip' + this.state.selectedTabIndex)
    }
    submit(prefs){
        const state = prefs.clone()
        state.bazi.pillars = config[this.state.selectedTabIndex]
        prefs.update(state)
        analytics.track('PillarPresetSelector-' + this.state.selectedTabIndex)
        this.props.navigation.dispatch(StackActions.popToTop());
    }
    render(){
        return (
            <View style={styles.container}>
                <ScrollView
                >
                    <SegmentedControlTab
                        allowFontScaling={false}
                        tabStyle={[sstyle.navigation.headerSegmentTabs.segmentTabStyle, { }]}
                        activeTabStyle={sstyle.navigation.headerSegmentTabs.segmentTabActive}
                        tabTextStyle={[sstyle.navigation.headerSegmentTabs.segmentTabText, {}]}
                        borderRadius={2}
                        tabsContainerStyle={styles.tabs}
                        values={['Picto', 'Detail', 'Raw']}
                        selectedIndex={this.state.selectedTabIndex}
                        onTabPress={selectedTabIndex =>  { 
                            this.setState({ selectedTabIndex})
                            
                        }}
                    />
                    <View style={ styles.imageHolder }>

                        { this.state.selectedTabIndex === 0 && (
                        <Image style={styles.imgPictorial} source={require('../../assets/images/pillarDisplays/pictorial.png')} />
                        )}
                        { this.state.selectedTabIndex === 1 && (
                        <Image style={styles.imgDetail} source={require('../../assets/images/pillarDisplays/detail.png')} />
                        )}
                        { this.state.selectedTabIndex === 2 && (
                        <Image style={styles.imgRaw} source={require('../../assets/images/pillarDisplays/raw.png')} />
                        )}
                    </View>
                    <Subscribe to={[PreferencesContainer]}>
                    {(prefs) => {
                        return (
                            <View style={styles.buttons}>
                                <Toucher
                                    onPress={() => {
                                        this.skip(prefs)
                                    }}
                                    style={[styles.buttonTouch]}
                                >
                                    <Text style={[styles.buttonText]}>{ this.props.navigation.getParam('cancelText') || 'Skip'}</Text>
                                </Toucher>
                                <View style={{ width: 15/2}}/>
                                <Toucher
                                    onPress={() => {
                                        this.submit(prefs)
                                    }}
                                    style={[styles.buttonTouch,
                                        { backgroundColor: Color.BLUE[300]}
                                    ]}
                                >
                                    <Text style={[styles.buttonText,
                                        { color: 'white'} 
                                    ]}>Select</Text>
                                </Toucher>
                            </View>
                        )
                    }}
                    </Subscribe>

                    <Text style={sstyle.layout.footer}>Each setting may be customized later.</Text>
                </ScrollView>
            </View>
        )
    }
}
export default withNavigation(InitialDisplaySelector)



