import analytics from '@segment/analytics-react-native'
import { DateTime } from 'luxon'


class DateSelector extends React.Component {
    state = {
        selectedTabIndex: 0,
        tabs: [],
    }
    static navigationOptions = ({ navigation }) => {
        const { params={} } = navigation.state 
		return {
            title: 'Date',
        }
    }
    constructor(props){
        super(props)
        this.onTabPress = this.onTabPress.bind(this)
        this.initial = this.props.navigation.getParam('initial')
        this.hideHourUnknown = this.props.navigation.getParam('hideHourUnknown')
        this.hideTabBar = this.props.navigation.getParam('hideTabBar')
    }
    async onTabPress(selectedTabIndex){
        if(selectedTabIndex === 1){ //now
            this.props.navigation.getParam('onSubmit')({ 
                ...this.initial,
                time: DateTime.local(),
                hourUnknown: false,
                chartName:'Now',
             })
            this.props.navigation.goBack()
        }
        if(selectedTabIndex === 2){ //me
            const birthday = await myBirthday(this.context)
            birthday.chartName = "Me";
            this.props.navigation.getParam('onSubmit')(birthday);
            this.props.navigation.goBack()
        }
        if(selectedTabIndex === 3){ //saved
            const failed = await verifyCheckpoints(['login'], this.context, this.props.navigation)
            if(failed) return 
        }
        if(selectedTabIndex === 5){
            const dice = strings.randomInt(-2208988800,2556104399)
            const gender = strings.randomInt(0, 1)
            this.props.navigation.getParam('onSubmit')({ 
                ...this.initial,
                time: DateTime.fromMillis(dice * 1000),
                gender: gender === 0 ? 'male' : 'female',
                hourUnknown: false,
                chartName:'Random',
             })
            this.props.navigation.goBack()

        }
        this.setState({ selectedTabIndex })
    }
    async componentDidMount(){
        const tabs = [
            { title: 'Picker' } ,
            { title: 'Now' },
        ]
        this.setState({ tabs })

        const failed = await verifyCheckpoints(['invitation'], this.context)
        if(!failed) tabs.push(
            { title: 'Me'},
            { title: 'Saved'},
            { title: 'Wiki'},
            { title: 'Random'}
        )
        this.setState({ tabs })
    }
    render(){
       
        return (
            <View style={styles.container}>
                { !this.hideTabBar && (
                <TabBar
                    tabs={this.state.tabs}
                    onTabPress={this.onTabPress}
                    selected={this.state.selectedTabIndex}
                />
                )}
                
                { this.state.selectedTabIndex === 0 && (
                    <CustomDateSelector 
                        initial={this.initial}
                        onSubmit={this.props.navigation.getParam('onSubmit')}
                        showGender={this.props.navigation.getParam('showGender') }
                        hideHourUnknown={this.hideHourUnknown || false }
                        footer={this.props.navigation.getParam('footer')}
                    />
                )}
                { this.state.selectedTabIndex === 3 && (
                    <BirthRecordList
                        onSubmit={this.props.navigation.getParam('onSubmit')}
                    />
                )}

                { this.state.selectedTabIndex === 4 && (
                    <WikiPeopleList
                        onSubmit={this.props.navigation.getParam('onSubmit')}
                    />
                )}
            </View>
        )
    }
}
DateSelector.contextType = AuthContext

const styles = StyleSheet.create({
    container:{
        padding:0,
        flex:1,
        flexDirection:'column',
        backgroundColor: '#ffffff',
    }
})
export default withApollo(DateSelector)






