const pollTime = 1000
class FriendList extends React.Component {
    flatListLoading = false
    numItems = 100
    state={
        selectedTabIndex: 0,
        searchQuery: "",
        refreshing: false,
    }
    // static navigationOptions = ({ navigation }) => {
    //     const { params={} } = navigation.state 
	// 	return {
    //         title: `Friends`,
    //         // headerRight:(
    //         //     <View style={sstyle.navigation.navheaderLeft} >
    //         //         <TouchableOpacityEx 
    //         //             onPress={() => {
    //         //                 params.onRightHeaderItemPress()
    //         //             }}
    //         //             style={[sstyle.navigation.navHeaderItem] }
    //         //         >
    //         //             <FontAwesome5
    //         //                 name="ellipsis-h"
    //         //                 size={22}
    //         //                 color={scolor.iconBlurred}
    //         //             />
    //         //         </TouchableOpacityEx>
	// 		// 	</View>
    //         // )
    //     }
    // }
    constructor(props){
        super(props)
        this.onRefresh = this.onRefresh.bind(this)
        this.onLeftHeaderItemPress = this.onLeftHeaderItemPress.bind(this)
        this.onRightHeaderItemPress = this.onRightHeaderItemPress.bind(this)
        this.searchQueryOnChange = this.searchQueryOnChange.bind(this)
        this.props.navigation.setParams({
            onLeftHeaderItemPress: this.onLeftHeaderItemPress,
            onRightHeaderItemPress: this.onRightHeaderItemPress,
        })
    }
    async componentDidMount(){
        const preferences = await getPreferences()
        this.setState({ preferences} )
    }
    onLeftHeaderItemPress(){
    }
    onRightHeaderItemPress(){
    }
    searchQueryOnChange(searchQuery){
        this.setState({ searchQuery })
    }
    onRefresh(){
        this.setState({ refreshing: true }, () => this.setState({ refreshing: false }))
    }
    render(){
        const dataSource = [ {}, {} ]
        return (
            <View style={styles.container}>
                <View style={styles.searchBar}>
                    <TextInput  
                        clearButtonMode={'always'}
                        placeholder={'Find by Username'}
                        style={styles.searchBarTextInput}
                        value={this.state.searchQuery}
                        onChangeText={this.searchQueryOnChange}
                        autoCapitalize="none"
                        autoCorrect={false}
                    />
                </View>
                <Composed
                    data={{
                        num: this.numItems,
                        prefix: this.state.searchQuery
                    }} 
                >
                {(stuff) => {
                    const { pendingFriendshipsQuery, friendshipsQuery, usersByPrefixQuery } = stuff
                    let dataSource = [
                        { title: 'Search', data: usersByPrefixQuery.data?.usersByPrefix || [] },
                    ]
                    if(!this.state.searchQuery){
                        dataSource = [
                            { title: 'Pending', data: pendingFriendshipsQuery.data?.pendingFriendships || [] },
                            { title: 'Matched', data: friendshipsQuery.data?.friendships || [] },
                        ]
                    }
                    return (
                        <SectionList
                            stickySectionHeadersEnabled={true}
                            ref={sectionList => { this.sectionList = sectionList; }}
                            sections={dataSource}
                            keyExtractor={(item, index) => index.toString() }
                            inverted={false}
                            keyboardShouldPersistTaps={true}
                            onScrollToIndexFailed={() => { console.log("Scroll failed") }}
                            renderSectionHeader={payload => {
                                if(payload.section.data.length === 0) return <Fragment/>
                                return <SectionHeader title={payload.section.title} rightItem={null} leftItem={null} />
                            }}
                            renderItem={(payload) => {
                                return <UserRow
                                    item={payload.item}
                                    preferences={this.state.preferences || null }
                                />
                            }}
                            ItemSeparatorComponent={() => (<View style={styles.separator}></View>)}
                            ListFooterComponent={() => (
                                <View style={styles.footer}>
                                    <Text style={[sstyle.layout.footer, { textAlign:'left'}]}>This alpha feature is a work-in-progress.</Text>
                                </View>
                            )}
                            refreshControl={
                                <RefreshControl
                                    refreshing={this.state.refreshing}
                                    onRefresh={this.onRefresh}
                                />
                            }
                        />
                    )
                }}
                </Composed> 
            </View>
        )
    }
}
export default withApollo(withNavigation(FriendList))

const Composed = adopt({
    pendingFriendshipsQuery: ({ render, data }) => (
        <Query query={queries.pendingFriendshipsQuery} variables={{time: DateTime.local().toISO(), num: data.num }} pollInterval={pollTime}>
            { render }
        </Query>
    ),
    friendshipsQuery: ({ render, data}) => (
        <Query query={queries.friendshipsQuery} variables={{time: DateTime.local().toISO(), num: data.num }} pollInterval={pollTime}>
            { render }
        </Query>
    ),
    usersByPrefixQuery: ({ render, data}) => (
        <Query query={queries.usersByPrefixQuery} variables={{ prefix: data.prefix, num: data.num }}>
            { render }
        </Query>
    )
})



