export const titleLine = (pillar, stores) => {
    const pillarName = pillar.name === 'luck' ? 'cycle' : pillar.name //hour, day, month, year
    const stem = pillar.stem
    const branch = pillar.branch
    const season = branch.ssn
    const seasonElement = Ordinals.elements[season.element]
    const words = [
        `This ${toTitle(pillarName)}`,
        `${toTitle(branch.animalName)} ${toTitle(pillarName)}`,
    ]


    const line = [
        {
            words,
            shuffle: true,
        },
    ]
    return line
}

