export const PalaceRelationshipBox = (pillar, stores, root) => {
    const gender = root.info.gender
    const god = pillar.branch.stems.main.gdd.abbr
    const genderWords = EightWords.gods[god].$kin(gender).map(i => toTitle(i))
    const line = []
    line.push({ words: ['with ']})
    line.push({ words: genderWords })
    return line
}





