import * as QiMap from '../cmtools/Plotters/QiMap/'
import md5 from 'md5'

export const almanacPayloadCacheKey = (birthday, year, month, lookups) => {
    const hash = md5(JSON.stringify(lookups))
    const key = `${birthday.time.toSeconds()}:${year}:${month}---::${hash}`
    return key
}

export const almanacQMDJLookups = (prefs) => {
    const lookups = {
        structures:[],
        spirits:[],
        stars:[],
        doors:[],
        maxNegativeStructures: prefs.almanac.qmdj.maxNegativeStructures
    }
    Object.keys(prefs.almanac.qmdj.structures).forEach(k => {
        if(prefs.almanac.qmdj.structures[k]){ lookups.structures.push(k) }
    })
    Object.keys(prefs.almanac.qmdj.spirits).forEach(k => {
        if(prefs.almanac.qmdj.spirits[k]){ lookups.spirits.push(k) }
    })
    Object.keys(prefs.almanac.qmdj.stars).forEach(k => {
        if(prefs.almanac.qmdj.stars[k]){ lookups.stars.push(k) }
    })
    Object.keys(prefs.almanac.qmdj.doors).forEach(k => {
        if(prefs.almanac.qmdj.doors[k]){ lookups.doors.push(k) }
    })
    return lookups
}

export const isThreeVictoryDay = (birthChart, todayBazi, options) => {
    let lightPalace =  birthChart.details.victories.light//chief
    let blessingPalace = birthChart.details.victories.blessing// heaven
    let forcePalace = birthChart.details.victories.force//life
    const dayChart =  QiMap.plot({  bazi: todayBazi ,reference: 'day', ...options })
    const monthChart =  QiMap.plot({  bazi: todayBazi ,reference: 'month', ...options})
    if(
        lightPalace && (
            (dayChart.palaces[lightPalace].plot.door === 'life' && monthChart.palaces[lightPalace].plot.spirit === 'heaven') ||
            (dayChart.palaces[lightPalace].plot.spirit === 'heaven' && monthChart.palaces[lightPalace].plot.door === 'life') ||
            (dayChart.palaces[lightPalace].plot.spirit === 'heaven' && dayChart.palaces[lightPalace].plot.door === 'life')
        )
    ){
        return { name: 'light', palace: lightPalace}
    }

    if(
        (dayChart.palaces[blessingPalace].plot.spirit === 'chief' && monthChart.palaces[blessingPalace].plot.door === 'life') ||
        (dayChart.palaces[blessingPalace].plot.door === 'life' && monthChart.palaces[blessingPalace].plot.spirit === 'chief') ||
        (dayChart.palaces[blessingPalace].plot.door === 'life' && dayChart.palaces[blessingPalace].plot.spirit === 'chief')
    ){
        return { name: 'blessing', palace: blessingPalace}
    }
    if(
        (dayChart.palaces[forcePalace].plot.spirit === 'heaven' && monthChart.palaces[forcePalace].plot.spirit === 'chief') ||
        (dayChart.palaces[forcePalace].plot.spirit === 'chief' && monthChart.palaces[forcePalace].plot.spirit === 'heaven')
    ){
        return { name: 'force', palace: forcePalace}
    }
    return null
}

