export const greatSun = () => {
    let boxes = _.cloneDeep(SolarCal.solarTerms)
    boxes.reverse()
    boxes = boxes.map(i => { 
        i.icon = "brightness-5" ; 
        i.desc = "Great Sun";
        return i; 
    })
    return { boxes, offset: 0, template :"solarTerms"}
}


export const greatMoon = () => {
    const terms = _.cloneDeep(SolarCal.solarTerms)
    const end = terms.splice(21, 24)
    const boxes = [...end, ...terms].map(i => { 
        i.icon="weather-night"; 
        i.desc = "Great Moon";
        return i; 
    })
    return { boxes, offset: 0, template : "solarTerms"}
}



