export const personalSymbolics = (bazi) => {
    const yinNobleman = ShenSha.dayStemAux.nobleman[bazi.pillars.day.stem.number][0]
    const yangNobleman = ShenSha.dayStemAux.nobleman[bazi.pillars.day.stem.number][1]
    const intelligence = ShenSha.dayStemAux.intelligence[bazi.pillars.day.stem.number]
    const peachBlossom = ShenSha.dayBranchAux.peachBlossom[bazi.pillars.day.branch.number]
    const solitude = ShenSha.dayBranchAux.solitude[bazi.pillars.day.branch.number]
    const skyHorse = ShenSha.dayBranchAux.skyHorse[bazi.pillars.day.branch.number]

    const dataset = {
        yinNobleman: { val: yinNobleman, aux: 'branch', meta: ShenSha.auxDetails.dayStemAux.nobleman},
        yangNobleman: { val: yangNobleman, aux: 'branch', meta: ShenSha.auxDetails.dayStemAux.nobleman},
        intelligence: { val: intelligence, aux: 'branch', meta: ShenSha.auxDetails.dayStemAux.intelligence},
        peachBlossom: { val: peachBlossom, aux: 'branch', meta: ShenSha.auxDetails.dayBranchAux.peachBlossom},
        solitude: { val: solitude, aux: 'branch', meta: ShenSha.auxDetails.dayBranchAux.solitude},
        skyHorse: { val: skyHorse, aux: 'branch', meta: ShenSha.auxDetails.dayBranchAux.skyHorse}
    }

    const mountains = WindWater.mountains
    const result = []
    for(let i = 0 ; i < 24; i++){
        result.push([])
    }


    const ww = 600
    result[0].unshift({ name: 'grandDuke', val: 'zi', color: Color.GREY[800], meta: ShenSha.auxDetails.yearBranchAux.grandDuke })
    result[2].unshift({ name: 'sun', val: 'chou', color: Color.RED[ww], meta: ShenSha.auxDetails.yearBranchAux.sun})
    result[5].unshift({ name: '5Yellow', val: 'jia', color: Color.YELLOW[600], meta: ShenSha.auxDetails.yearBranchAux.calamitySha})
    result[6].unshift({ name: '5Yellow', val: 'mao', color: Color.YELLOW[600], meta: ShenSha.auxDetails.yearBranchAux.calamitySha })
    result[6].unshift({name: 'moon', val: 'mao', color: Color.PURPLE[ww],  meta: ShenSha.auxDetails.yearBranchAux.moon})
    result[7].unshift({ name: '5Yellow', val: 'yi', color: Color.YELLOW[600], meta: ShenSha.auxDetails.yearBranchAux.calamitySha })
    result[11].unshift({ name: '3Killings', val: 'zi',  color: Color.BROWN[ww], meta: ShenSha.auxDetails.yearBranchAux.disasterSha})
    result[12].unshift({ name: '3Killings', val: 'zi', color: Color.BROWN[ww],  meta: ShenSha.auxDetails.yearBranchAux.disasterSha })
    result[12].unshift({ name: 'yearBreaker', color: Color.GREY[800],  meta: ShenSha.auxDetails.yearBranchAux.yearBreaker})
    result[13].unshift({ name: '3Killings', val: 'zi', color: Color.BROWN[ww] ,  meta: ShenSha.auxDetails.yearBranchAux.disasterSha})
    result[14].unshift({ name: 'dragonVirtue', val: 'zi',  color: Color.ORANGE[ww],  meta: ShenSha.auxDetails.yearBranchAux.dragonVirtue})
    result[18].unshift({ name: 'fortuneVirtue', val: 'zi',  color: Color.ORANGE[ww],  meta: ShenSha.auxDetails.yearBranchAux.fortuneVirtue})

    Object.keys(mountains).forEach((sector, mountainIndex) => {
        Object.keys(dataset).forEach(star => {
            if(mountains[sector].pinyin === dataset[star].val && mountains[sector].type === dataset[star].aux){
                result[mountainIndex].unshift({
                    name: star,
                    color: Color.RED[900],
                    ...dataset[star]
                })
            }
        })
    })


    return { boxes: result, offset: 7.5, template: 'symbolics'}
}

export const houseStars = (data) => {
    const desiredOrder = ['kan','gen','zhen','xun','li','kun','dui','qian'];
    const boxes = Array(8)
    Object.keys(data.plates.base).forEach(pal => {
        if(pal === 'center') return
        const ind = desiredOrder.indexOf(pal)
        const item = {
            baseStar: data.plates.base[pal],
            facingStar: data.plates.facing[pal],
            sittingStar: data.plates.sitting[pal],
            isFacing: pal === data.faceMountain.palace,
            isSitting: pal === data.sitMountain.palace
            
        }
        boxes[ind] = item
    })

    return { boxes, offset: 22.5, template: 'houseStars'}
}

export const eightMansionsFromNaJia = (bazi) => {
    const mansions = WindWater.getEightMansionNaJia[bazi.meta.gua.luoShu]
    const desiredOrder = []
    Object.keys(WindWater.mountains).forEach(k => { desiredOrder.push(k )})
    const boxes = Array(24)
    Object.keys(mansions).forEach(key => {
        const indx = desiredOrder.indexOf(key.toUpperCase())

        const mansionElement = WindWater.eightMansions[mansions[key]].element
        const dir = key.replace(/[0-9]/g, '').toUpperCase()
        const palaceElement = Ordinals.guas[ Ordinals.directions[dir].postGua ].element
        const strength = Ordinals.elements[mansionElement].strength[palaceElement]
        boxes[indx] = { name: mansions[key], ref: 'Na Jia', strength }
    })
     return { boxes, offset: 7.5, template: 'naJiaEightMansions'}
}

export const eightMansionsFromBazi = (bazi) => {
    const mansions = _.invert(WindWater.guas[bazi.meta.gua.pinyin].eightMansions)
    const desiredOrder = ['N','NE','E','SE','S','SW','W','NW'];
    const boxes = Array(8)
    Object.keys(mansions).forEach(key => {
        const ind = desiredOrder.indexOf(key)
        const mansionElement = WindWater.eightMansions[mansions[key]].element
        const palaceElement = Ordinals.guas[ Ordinals.directions[key].postGua ].element

        const strength = Ordinals.elements[mansionElement].strength[palaceElement]
        boxes[ind] = { name: mansions[key] , ref: 'Personal', strength }
    })
    return { boxes, offset: 22.5, template: 'eightMansions'}
}


export const eightMansionsFromFacing = (dir) => {
    const mansions  = WindWater.getEightMansionsFromFacing(dir)
    const desiredOrder = ['kan','gen','zhen','xun','li','kun','dui','qian']

    const boxes = Array(8)
    Object.keys(mansions).forEach(key => {
        const ind = desiredOrder.indexOf(key)
        const mansionElement = WindWater.eightMansions[mansions[key]].element
        const palaceElement = Ordinals.guas[key].element
        const strength = Ordinals.elements[mansionElement].strength[palaceElement]
        boxes[ind] = { name: mansions[key] , ref: 'House' , strength}
    })

     return { boxes, offset: 22.5, template: 'eightMansions'}
}

