const SymbolicScrollBox = ( {pillar, god, root }) => {
    const stars = pillar.stars.filter(i => 
        i.name === 'nobleman' ||
        (i.name === 'general' && i.ref === 'dayBranchAux')  ||
        (i.name === 'goatBlade' && i.ref === 'dayStemAux') || //Confidence
        (i.name === 'skyHorse' && i.ref === 'dayBranchAux') || //movement
        (i.name === 'solitude' && i.ref === 'dayBranchAux') ||  
        (i.name === 'intelligence' && i.ref === 'dayStemAux') || 
        (i.name === 'studyRoom' && i.ref === 'dayStemAux') || //
        (i.name === 'elegantSeal' && i.ref === 'dayBranchAux') || //creativity
        (i.name === 'peachBlossom' && i.ref === 'dayBranchAux') || //charisma
        (i.name === 'skyWealth' && i.ref === 'dayStemAux') || //opportunity
        (i.name === 'redMatchmaker' && i.ref === 'dayBranchAux')  || //harmony
        (i.name === 'dragonVirtue' && i.ref === 'yearBranchAux')  //luck
    )
    const results = []
    stars.forEach(star => {
        const line = [
            {
                words: [
                    `symbolics-${star.name}|${deCamel(star.name)}`, 
                    ...star.$dict_noun.map(i => `symbolics-${star.name}|` + toTitle(i)),
                ],
                shuffle: false,
            },
        ]
        results.push(line) 
    })
    return (
        <ScrollView 
            style={{ 
                flexDirection: 'row-reverse' ,
            }}
            horizontal={true}
            showsHorizontalScrollIndicator={false}
        >
            { results.map(line => {
                return (
                    <MadLibs
                        line={line}
                        containerStyle={ styles.symbolicWrapper  }
                        boxViewStyle={ styles.symbolicBoxView}
                        boxSelectStyle={styles.symbolicBoxSelect}
                        boxTextStyle={styles.symbolicName}
                        iconStyle={styles.symbolicIcon} 
                    />
                )
            })}
        </ScrollView>
    )
}
export default SymbolicScrollBox;




