import DayBasicInfo from '../Date/DayBasicInfo';
import ScrollChart from '../Bazi/ScrollChart'
import BaziHexagram from '../YiJing/BaziHexagram'
import FlyingStarsSquareChart from './FlyingStarsSquareChart';
import HeadDateBar from '../QiMen/HeadDateBar'
import DatePicker from 'react-native-date-picker';
const iOS = Platform.OS === 'ios'
const TICK = 1000;
const DEFAULT_COMPASS_ENABLED = false
const DEGREE_RATE = iOS ? 3 : 1
const COMPASS_DEBOUNCER = iOS ? 0 : 25
const DEFAULT_TAB = 4
const HOUSEINDEX = 5

import * as Ordinals from '../../lib/cmtools/Ordinals'
import * as WindWater from '../../lib/cmtools/WindWater'
import * as FourPillars from '../../lib/cmtools/Plotters/FourPillars'
import * as Graphics from '../../lib/cmtools/Graphics'

class FlyingStars extends React.Component {
    palaceOrder = ['li','kun','dui','qian','kan','gen','zhen','xun']
    direction = 'S'
    state={
        compassEnabled: DEFAULT_COMPASS_ENABLED,
        palaces: ['li','kun','dui','qian','kan','gen','zhen','xun'],
        timePayload: undefined,
        housePayload: undefined,
        timerOn: false,
        refreshing: false,
        time:  null,
        datePickerVisible: false,
        selectedTabIndex:DEFAULT_TAB,
        houseExtraTabIndex: 0,
        houseInput: null,
    }
    static navigationOptions = ({ navigation }) => {
        const { params={} } = navigation.state 
		return {
            title: null,
            headerRight:(
                <View style={{flex: 1}}>
                    <SegmentedControlTab
                        allowFontScaling={false}
                        tabStyle={sstyle.navigation.headerSegmentTabs.segmentTabStyle}
                        activeTabStyle={sstyle.navigation.headerSegmentTabs.segmentTabActive}
                        tabTextStyle={sstyle.navigation.headerSegmentTabs.segmentTabText}
                        borderRadius={2}
                        tabsContainerStyle={{width: 264, marginRight:12, alignSelf: 'center' }}
                        values={[ 'H', 'D', 'M', 'Y','✡︎',  '🏠',]}
                        selectedIndex={ typeof params.selectedTabIndex === 'undefined' ? DEFAULT_TAB : params.selectedTabIndex }
                        onTabPress={index =>  { 
                            if(typeof params.setTabIndex !== 'undefined') params.setTabIndex(index) 
                        }}
                    />
                </View>
            ),

        }
    }
    constructor(props){
        super(props)
        this.reload = this.reload.bind(this)
        this.formPayload = this.formPayload.bind(this)

        this.setTabIndex = this.setTabIndex.bind(this)


        this.onDateBarPress = this.onDateBarPress.bind(this)
        this.startTimer = this.startTimer.bind(this)
        this.stopTimer = this.stopTimer.bind(this)
        this.onDateChange = this.onDateChange.bind(this)
        this.onCustomDateSelected = this.onCustomDateSelected.bind(this)
        this.props.navigation.setParams({ selectedTabIndex: this.state.selectedTabIndex,  setTabIndex: this.setTabIndex })

        this.state.time = DateTime.local()

        this.stopCompass = this.stopCompass.bind(this)
        this.startCompass = this.startCompass.bind(this)
        this.reorderPalaces = this.reorderPalaces.bind(this)
        this.headingReceived = this.headingReceived.bind(this)
        this.setCompassEnabled = this.setCompassEnabled.bind(this)
        this.debouncer = _.debounce(this.headingReceived, COMPASS_DEBOUNCER)
        this.setLastSet = this.setLastSet.bind(this)
        this.removeLastSet = this.removeLastSet.bind(this)
        this.onHouseSelected = this.onHouseSelected.bind(this)

        analytics.track('FlyingStars-' + DEFAULT_TAB)
    }
    async componentDidMount(){
        //Get Prop Time
        const propTime = this.props.navigation.getParam('time') 

        //Get Last Set
        let lastSet = await AsyncStorage.getItem('@cache.flyingStarsLastSet')
        if(lastSet){
            lastSet = JSON.parse(lastSet)
            if(lastSet.time) lastSet.time = DateTime.fromISO(lastSet.time, { setZone: true }) 
        }

        if(propTime){
            this.onCustomDateSelected({ time: propTime }, false)
        }else if (lastSet?.time){
            this.onCustomDateSelected({ time:  lastSet.time})
        }else{
            this.setState({ time: DateTime.local()}, () => {
                this.formPayload()
                this.startTimer()
            })
        }

        const houseCache = await AsyncStorage.getItem('@cache.houseInput')
        if(houseCache){
            const houseInput = JSON.parse(houseCache)
            this.setState({ houseInput }, () => { this.formPayload() })
        }

    }
    async setLastSet(time){
        await AsyncStorage.setItem('@cache.flyingStarsLastSet', JSON.stringify({ time }))
    }
    async removeLastSet(){
        await AsyncStorage.removeItem('@cache.flyingStarsLastSet')
    }
    setTabIndex(selectedTabIndex){
        this.props.navigation.setParams({ selectedTabIndex })
        this.setState({ selectedTabIndex }, () => {
            this.formPayload()
        })
        analytics.track('FlyingStars-' + selectedTabIndex)
    }
    headingReceived(degree){
        const newDirection = numbers.degreeToDirection(degree)
        if(newDirection !== this.direction){
            this.direction =  newDirection
            this.reorderPalaces()
        }
    }
    startCompass(){
        CompassHeading.start(DEGREE_RATE,this.debouncer)
    }
    stopCompass(){
        CompassHeading.stop()
    }
    setCompassEnabled(){
        if(this.state.compassEnabled){
            analytics.track('FlyingStars.CompassOff')
            this.stopCompass()
            this.direction = 'S'
            this.setState({ compassEnabled: false }, () => {
                this.reorderPalaces()
            })
        }else{
            this.setState({ compassEnabled: true }, () => {
                analytics.track('FlyingStars.CompassOn')
                this.startCompass()
                this.reorderPalaces()
            })
        }
    }
    formPayload(){
        const timePayload = WindWater.getTimeFlyingStars(this.state.time)
        const housePayload = WindWater.getHouseFlyingStars(this.state.houseInput)

        let mansionScores = null
        if(housePayload){
            let sittingMansions = WindWater.getEightMansionsFromFacing(housePayload.faceMountain.direction)
            sittingMansions = WindWater.extendEightMansions(sittingMansions)
            housePayload.sittingMansions = sittingMansions
            mansionScores = {
                palaces: ['kan','gen','zhen','xun','li','kun','dui', 'qian'],
                data: Array(8),
                total: 0,
            }
            Object.keys(sittingMansions).forEach(pal => {
                const indx = mansionScores.palaces.indexOf(pal)
                mansionScores.total += sittingMansions[pal].score
                mansionScores.data[indx] = sittingMansions[pal]
            })
        }

        this.setState({ timePayload , housePayload, mansionScores}, () => {
            this.reorderPalaces()
        })
    }
    reorderPalaces(){
        const point = Ordinals.directions[this.direction].postGua
        let order = this.palaceOrder.slice()
        const index = order.indexOf(point)

        if(index !== 0){
            const arr1 = order.slice(index)
            const arr2 = order.slice(0, index)
            order = arr1.concat(arr2)
        }
        this.setState({ palaces: order })
    }
    onDateBarPress(){
        this.stopTimer()
        this.setState({ 
            timerOn: false,
            datePickerVisible: !this.state.datePickerVisible,
        })
    }
    startTimer(){
        this.removeLastSet()
        this.stopTimer()
        this.setState({ timerOn: true , datePickerVisible: false})
        this.timer = setInterval(() => { 
            const time = DateTime.local()
            this.setState({ time }, () => {
                this.formPayload()
            })
        },TICK)
    }
    stopTimer(){
        clearInterval(this.timer)
        this.setState({ timerOn: false })
    }
    onDateChange(x, setLast = true){
        const time = DateTime.fromJSDate(x)
        this.setState({ time }, () => {
            if(setLast) this.setLastSet(time)
            this.formPayload()
        })
    }
    onCustomDateSelected(x, setLast = true){
        this.stopTimer()
        this.setState({ 
            time:x.time ,
        }, () => {
            if(setLast) this.setLastSet(x.time)
            this.formPayload()
        })
    }
    onHouseSelected(houseInput, usedCompass=false){
        if(usedCompass && this.compassEnabled) this.startCompass()  
        this.setState({houseInput}, () => { this.formPayload() })
    }
    onFacingCompassSelect(degree){
        this.onHouseDegreeChange(degree)
    }
    reload(){
        this.startTimer()
        this.setState({ refreshing: false })
    }
    render(){
        if(!this.state.timePayload) return <Fragment/>
        if(!this.state.time) return <Fragment/>
        const chart = FourPillars.plot({ time: this.state.time })
        const comboPalaceNames = ['kan','gen','zhen','xun','li','kun','dui','qian', 'center']
        return (
            <View style={styles.container}>
                <View style={{ flex: 1 }}>
                    <HeadDateBar
                        time={this.state.time}
                        timerOn={this.state.timerOn}
                        reload={this.reload}
                        onDateBarPress={this.onDateBarPress}
                        onCustomDateSelected={this.onCustomDateSelected}
                    />
                    { this.state.datePickerVisible && (
                        <DatePicker
                            style={styles.datePicker}
                            mode={'datetime'}
                            date={this.state.time.toJSDate()}
                            onDateChange={this.onDateChange}
                        />
                    )}
                    <ScrollView >
                        <FlyingStarsSquareChart
                            timePayload={this.state.timePayload} 
                            housePayload = { this.state.housePayload}
                            selectedTabIndex={this.state.selectedTabIndex}
                            palaces={this.state.palaces}
                            compassEnabled={this.state.compassEnabled}
                            setCompassEnabled={this.setCompassEnabled}
                            houseExtraTabIndex = {this.state.houseExtraTabIndex}
                        />

                        { (this.state.selectedTabIndex === HOUSEINDEX) && (
                            <View style={styles.houseInputBar}>
                                <Toucher
                                    style={styles.houseButtonTouch}
                                    onPress={() => {
                                        this.props.navigation.push('HouseSelector', { 
                                            onHouseSelected: this.onHouseSelected,
                                            initial: this.state.houseInput,
                                        })
                                    }}
                                >
                                    { (this.state.houseInput?.houseYear && this.state.houseInput?.houseDegree) ? (
                                        <Text style={styles.houseButton}>{ this.state.houseInput?.houseYear }   —   { this.state.houseInput?.houseDegree }°</Text>
                                    ) : (
                                        <Text style={styles.houseButton}>Select House ❯</Text>
                                    )}
                                </Toucher>
                            </View>
                        )}

                        { (this.state.selectedTabIndex !== HOUSEINDEX) && (
                            <View style={{ flex: 1 }}>
                                <ScrollChart
                                    scrollEnabled={false}
                                    chart={chart}
                                    hideGods={true}
                                />
                                <DayBasicInfo
                                    chart={chart}
                                    showAll={true}
                                />
                                <SectionHeader
                                title={'Day Pillar Hexagram'}
                                />
                                <BaziHexagram stem={chart.pillars.day.stem.name} branch={chart.pillars.day.branch.name}/>
                            </View>
                        )}

                        { (this.state.selectedTabIndex === HOUSEINDEX && this.state.housePayload) && (
                            <View style={{ flex: 1 }}>
                                <View style={styles.infoBar}>
                                    { this.state.housePayload.period && (
                                        <View style={styles.boxInfo}>
                                            <Text style={styles.boxHead}>Period</Text>
                                            <View style={styles.boxInner}>
                                                <Text style={{ textAlign: 'center',fontSize: 32, fontWeight: '500'}}>{ this.state.housePayload.period }</Text>
                                            </View>
                                        </View>
                                    )}
                                    <View style={{ width: 2 }}/>
                                    { this.state.housePayload.faceMountain && (
                                        <View style={styles.boxInfo}>
                                            <Text style={[styles.boxHead]}>Facing</Text>
                                            <View style={styles.boxInner}>
                                                <Text style={styles.chineseText}>{ this.state.housePayload.faceMountain.chinese }</Text>
                                                <Text>{ toTitle(this.state.housePayload.faceMountain.sector.toUpperCase()) }</Text>
                                                <Text style={{ marginTop: 6, fontWeight: 'bold'}}>{ toTitle(this.state.housePayload.faceMountain.pinyin)}</Text>
                                            </View>
                                        </View>
                                    )}
                                    <View style={{ width: 2 }}/>
                                    { this.state.housePayload.sitMountain && (
                                        <View style={styles.boxInfo}>
                                            <Text style={styles.boxHead}>Sitting</Text>
                                            <View style={styles.boxInner}>
                                                <Text style={styles.chineseText}>{ this.state.housePayload.sitMountain.chinese }</Text>
                                                <Text>{ toTitle(this.state.housePayload.sitMountain.sector).toUpperCase()}</Text>
                                                <Text style={{ marginTop:6, fontWeight: 'bold'}}>{ toTitle(this.state.housePayload.sitMountain.pinyin)}</Text>
                                            </View>
                                        </View>
                                    )}
                                </View>

                                {this.state.housePayload.plates && (
                                    <View>
                                        <View style={styles.houseExtraBar}>
                                            <SegmentedControlTab
                                                allowFontScaling={false}
                                                tabStyle={styles.segmentTabStyle}
                                                activeTabStyle={styles.segmentTabActive}
                                                tabTextStyle={styles.segmentTabText}
                                                borderRadius={2}
                                                tabsContainerStyle={{ width: 256, alignSelf: 'center' }}
                                                values={['Flying Stars', 'Eight Mansions']}
                                                selectedIndex={ this.state.houseExtraTabIndex}
                                                onTabPress={houseExtraTabIndex =>  { 
                                                    this.setState({ houseExtraTabIndex })
                                                }}
                                            />
                                        </View>
                                        { this.state.houseExtraTabIndex === 0 ? (
                                            <View>
                                                { comboPalaceNames.map(pal => {
                                                    const comboArr = [this.state.housePayload.plates.facing[pal], this.state.housePayload.plates.sitting[pal]].sort()
                                                    const comboKey = comboArr[0] + ' + ' + comboArr[1]
                                                    return (
                                                        <View style={styles.comboRow}>
                                                            <Text style={styles.comboDirText}>
                                                                { pal === 'center' ? 'C' : Ordinals.guas[pal].direction }
                                                            </Text>
                                                            <View style={{ flex: 1 }}>
                                                                <Text style={styles.comboPlus}>
                                                                { this.state.housePayload.plates.sitting[pal]} + {this.state.housePayload.plates.facing[pal] }
                                                                </Text>
                                                                <Text style={styles.comboDescText}>
                                                                    {capFirst(WindWater.flyingStarCombinations[comboKey])}            
                                                                </Text>
                                                            </View>
                                                        </View>
                                                    )
                                                })} 
                                            </View>
                                        ) : (
                                            <View>
                                                { this.state.mansionScores.data.map((man, indx) => {
                                                    const item = WindWater.eightMansions[man.name]
                                                    return (
                                                        <Toucher
                                                            onPress={() => {
                                                                const path = `windWater.eightMansions.${man.name}`
                                                                this.props.navigation.push('Library', { path, hideClose: true }) 
                                                            }}
                                                        >
                                                            <View style={[styles.comboRow, { justifyContent: 'space-between'}]}>
                                                                <Text numberOfLines={1} ellipsizeMode={'clip'} style={styles.comboDirText}>{ Ordinals.guas[this.state.mansionScores.palaces[indx]].direction }</Text>
                                                                <Text style={[{fontWeight: 'normal'},
                                                                    man.rating > 0 && { color: Color.RED['A700']} 
                                                                ]}>{ item.chinese } { item.pinyin} - { item.name }</Text>
                                                                <View style={{ flex: 1 }}/>
                                                                <Text style={[styles.manStrength,
                                                                    man.rating > 0 && { color: Color.RED['A700']} ,
                                                                    Graphics.styles.elements[man.strength],
                                                                ]}>{toTitle(man.strength) }</Text>
                                                                <Text style={[styles.manScore,
                                                                    man.rating > 0 && { color: Color.RED['A700']} 
                                                                ]}>{man.score > 0 && '+'}{ man.score}</Text>
                                                            </View>
                                                        </Toucher>
                                                    )
                                                })}
                                                <View style={[styles.comboRow, { alignItems: 'center', justifyContent: 'space-between'}]}>
                                                    <Text style={{fontWeight: 'bold', fontSize: 16, }}>Total</Text>
                                                    <Text style={[{fontWeight: 'bold', fontSize: 16, backgroundColor: Color.GREY[100], padding:8, },
                                                        this.state.mansionScores.total > 0 && { backgroundColor: Color.RED['A700'], color: 'white'} 
                                                    ]}>
                                                        {this.state.mansionScores.total > 0 && '+'}{ this.state.mansionScores.total }
                                                    </Text>
                                                </View>
                                                <Text style={{ padding: 15}}>
                                                    Terminology is based on the [Elemental] interaction between the Palace and the 8-Mansion entity. [Peak] indicates that the entity is of the same element as the Palace.  [Dead] indicates that the element of the entity is being controlled by the element of the Palace — It does not indicate that the entity has reached its lowest point in the Twelve Stages of Growth model.
                                                </Text>
                                            </View>
                                        )}
                                    </View>
                                )}
                            </View>
                            
                        )}
                    </ScrollView>
                </View>
            </View>
        )
    }
}
export default FlyingStars;

