const winHeight = Dimensions.get('window').height
import CompassHeading from 'react-native-compass-heading'
import _ from 'lodash'

const COMPASS_DEBOUNCER = 0
const DEGREE_RATE = 1

class CompassDegreeSelector extends React.Component{
    state={
        degree: 4.4,
        direction:'N'
    }
    static navigationOptions = ({ navigation }) => {
        const { params={} } = navigation.state 
		return {
            title: params.title || '',
        }
    }
    constructor(props){
        super(props)
        this.headingReceived = this.headingReceived.bind(this)
        this.debouncer = _.debounce(this.headingReceived, COMPASS_DEBOUNCER)
        analytics.track('CompassSelector')
    }
    componentDidMount(){
        CompassHeading.start(DEGREE_RATE,this.debouncer)
    }
    headingReceived(degree){
        const direction = numbers.degreeToDirection(degree)
        this.setState({ degree, direction })
    }
    render(){

        return (
            <View style={styles.container}>
                <MaterialCommunityIcon
                    name={'chevron-up'}
                    color={Color.GREY[700]}
                    size={55}
                    style={styles.arrow}
                />
                <Text style={styles.dir}>{ this.state.direction }</Text>
                <Text style={styles.degree}>{ this.state.degree.toFixed(2) }°</Text>
                <Toucher
                    style={styles.buttonTouch}
                    onPress={() => {
                        this.props.navigation.getParam('onSelect')(this.state.degree.toFixed(2))
                        this.props.navigation.goBack()
                    }}
                >
                    <Text style={styles.buttonText}>SELECT</Text> 
                </Toucher>
            </View>
        )
    }
}
export default CompassDegreeSelector

