import _ from 'lodash';


export const randomIndex = (items) => {
    return Math.floor(Math.random() * items.length)
}
export const shuffleTwoArrays  = (obj1, obj2) => {
    var index = obj1.length;
    var rnd, tmp1, tmp2;
  
    while (index) {
      rnd = Math.floor(Math.random() * index);
      index -= 1;
      tmp1 = obj1[index];
      tmp2 = obj2[index];
      obj1[index] = obj1[rnd];
      obj2[index] = obj2[rnd];
      obj1[rnd] = tmp1;
      obj2[rnd] = tmp2;
    }
  }

    
export const proxyFunc =  {
    get(target, prop) {
        if (!isNaN(prop)) {
            prop = parseInt(prop, 10);
            if (prop < 0) {
                do{
                    prop += target.length;
                }while(prop < 0)
            }else if(prop > target.length -1){
                prop =  prop % target.length
            }
        }
        return target[prop];
    }
}


export const toProxy = (arr) => {
    return new Proxy(arr, proxyFunc)
}


export const chineseTimeString = (time) => {
    if(!time) return null
    let t = time
    if(time.hour % 2  === 0){ t = time.plus({ hours: -1 }) }
    const s = t.toFormat('yyyy-MM-dd-HH')
    return s 
}

export const cloneBaziChart = (chart, time) => {
    const newChart = _.cloneDeep(chart)
    newChart.info.time = time
    return newChart
}


export const find = (obj, key, val) => {
    const parts = Object.keys(obj)
    let found = null;
    for(let p of parts){
        if(obj[p][key] === val){
            found = obj[p]
            break;
        }
    }
    return _.cloneDeep(found);
}

