class Synastry extends React.Component {
    state = {
        sectionData:[
            { title: '', data: [] },
        ] 
    }
    static navigationOptions = ({ navigation }) => {
        const { params={} } = navigation.state 
		return {
            title: `Comparison`,
        }
    }
    constructor(props){
        super(props)

        analytics.track('Bazi.Comparison')
        this.chart1 = this.props.navigation.getParam('chart1')
        this.chart2 = this.props.navigation.getParam('chart2')  
        this.jiaGroupComparison = this.jiaGroupComparison.bind(this)
        this.interactionComparison = this.interactionComparison.bind(this)
        this.shenshaComparison = this.shenshaComparison.bind(this)
        this.elementComparison = this.elementComparison.bind(this)
        this.aspectComparison = this.aspectComparison.bind(this)
        this.godComparison = this.godComparison.bind(this)
        this.balanceComparison = this.balanceComparison.bind(this)
        this.basicComparison = this.basicComparison.bind(this)


        this.pillarKeys1 = ['year','month','day']
        if(!this.chart1.info.hourUnknown) this.pillarKeys1.push('hour')
        this.pillarKeys2 = ['year','month','day']
        if(!this.chart2.info.hourUnknown) this.pillarKeys2.push('hour')
        this.pillarKeys2.forEach(key => { EightWords.extendAuxData(this.chart2.pillars[key], DateTime.local(),this.chart1, this.pillarKeys1) })

        const jiaGroupData = this.jiaGroupComparison()
        const shenshaData = this.shenshaComparison()
        const interactionData = this.interactionComparison()

        this.state = {
            sectionData: [
                { title: '', template: 'dm', data:[{}]},

                { title: 'Overview', template: 'information', data: this.basicComparison() },
                { title: 'Jia Streams', template: 'streams',num: jiaGroupData.count , data: jiaGroupData.results },
                { title: 'Identical Pillars', template: 'information', num: interactionData.fuyin.length, data: interactionData.fuyin},
                { title: 'Pillar Clashes', template: 'information', num: interactionData.fanyin.length, data: interactionData.fanyin},
                { title: 'Pillar Combinations', template: 'information', num: interactionData.combo.length, data: interactionData.combo},

                { title: 'Balancing', template: 'haveNeed', data: this.balanceComparison() },
                { title: 'Elements', template: 'split', data: [this.elementComparison()] },
                { title: 'Aspects', template: 'split', data: [this.aspectComparison()] },
                { title: 'Gods', template: 'split', data: [this.godComparison()] },
                { title: 'Symbolics (Mine)', template: 'stars', num: shenshaData.chart1.length, data: shenshaData.chart1},
                { title: 'Symbolics (Theirs)', template: 'stars', num: shenshaData.chart2.length, data: shenshaData.chart2},
            ]
        }

    }
    //DM Combo, DM Yin/Yang,Identical pillar, Stream, fu yin, fan yin, pillar combo, nobleman/intelligence/peachblossom, element, gods
    jiaGroupComparison(){
        const groups = {}

        this.pillarKeys2.forEach(key => {
            const stream = this.chart2.pillars[key].jiaGroup
            if(!(stream in groups)){
                groups[stream] = {}
                groups[stream]['chart1'] = []
                groups[stream]['chart2'] = []
            }
            groups[stream]['chart2'].push(toTitle(key))
        })

        this.pillarKeys1.forEach(key => {
            const stream = this.chart1.pillars[key].jiaGroup
            if(!(stream in groups)){
                groups[stream] = {}
                groups[stream]['chart1'] = []
                groups[stream]['chart2'] = []
            }
            groups[stream]['chart1'].push(toTitle(key))
        })

        Object.keys(groups).forEach(stream => {
            if(groups[stream].chart1.length === 0 || groups[stream].chart2.length === 0){
                delete groups[stream]
            }
        })
        const results = []
        let count = 0
        Object.keys(groups).forEach(stream => {
            results.push({
                stream,
                matches: groups[stream]
            })
            count += groups[stream].chart1.length + groups[stream].chart2.length
        })
        return {
            count: count,
            results
        }
    }
    interactionComparison(){
        const pillarInteractions = {
            fanyin: [],
            fuyin: [],
            combo: [],
        }
        this.pillarKeys2.forEach(key => {
            this.chart2.pillars[key].interactions.forEach(interaction => {
                interaction.affects.forEach(affect => {
                    if(interaction.relation === 'Fan Yin'){
                        pillarInteractions['fanyin'].push({
                            left: toTitle(affect.pillar),
                            right:  toTitle(key),
                            label: 'Clash' 
                        })
                    }else if(pillarInteractions.relation === 'Fu Yin'){
                        pillarInteractions['fuyin'].push({
                            left: toTitle(affect.pillar),
                            right:  toTitle(key),
                            label: 'Identical'
                        })
                    }else if(pillarInteractions.relation === 'Pillar Combo'){
                        pillarInteractions['combo'].push({
                            left: toTitle(affect.pillar),
                            right: toTitle(key),
                            label: 'Combination'
                        })
                    }
                })
            })
        })
        return pillarInteractions;
    }
    shenshaComparison(){
        //Shen Sha ---------------------
        const dm1 = this.chart1.pillars.day.stem.number
        const dm2 = this.chart2.pillars.day.stem.number
        const ssmap = {
            chart1: {},
            chart2: {}
        }
        ssmap.chart1['yangNobleman'] = [ShenSha.dayStemAux.nobleman[dm1][0], ShenSha.auxDetails.dayStemAux.nobleman, 'They can be helpers or mentors to me']
        ssmap.chart1['yinNobleman'] = [ShenSha.dayStemAux.nobleman[dm1][1],  ShenSha.auxDetails.dayStemAux.nobleman, 'They can be helpers or mentors to me']
        ssmap.chart1['intelligence'] = [ShenSha.dayStemAux.intelligence[dm1],  ShenSha.auxDetails.dayStemAux.intelligence, 'They can help me with ideas and insights']
        ssmap.chart1['studyRoom'] = [ShenSha.dayStemAux.studyRoom[dm1],  ShenSha.auxDetails.dayStemAux.studyRoom, 'They can help me with studies and knowledge']
        ssmap.chart1['peachBlossom'] = [ShenSha.dayBranchAux.peachBlossom[dm1],  ShenSha.auxDetails.dayBranchAux.peachBlossom, 'They will find me attractive and charismatic']

        ssmap.chart2['yangNobleman'] = [ShenSha.dayStemAux.nobleman[dm2][0],  ShenSha.auxDetails.dayStemAux.nobleman, 'I can be helpers or mentors to them']
        ssmap.chart2['yinNobleman'] = [ShenSha.dayStemAux.nobleman[dm2][1],  ShenSha.auxDetails.dayStemAux.nobleman, 'I can be helpers or mentors to them']
        ssmap.chart2['intelligence'] = [ShenSha.dayStemAux.intelligence[dm2],  ShenSha.auxDetails.dayStemAux.intelligence, 'I can help them with ideas and insights']
        ssmap.chart2['studyRoom'] = [ShenSha.dayStemAux.studyRoom[dm2],  ShenSha.auxDetails.dayStemAux.studyRoom, 'I can help them with studies and knowledge']
        ssmap.chart2['peachBlossom'] = [ShenSha.dayBranchAux.peachBlossom[dm2],  ShenSha.auxDetails.dayBranchAux.peachBlossom, 'I will find them attractive and charismatic']

        const pillarContext = {
            year: 'social life, friendship, and leisure',
            month: 'career, academics, and self improvement',
            day: 'home, personal, and daily life',
            hour: 'investments, aspirations, and dreams',
        }
        const ssMatch = { chart1: [], chart2:[] }
        Object.keys(ssmap.chart1).forEach(star => {
            this.pillarKeys2.forEach(key2 => {
                if(this.chart2.pillars[key2].branch.name === ssmap.chart1[star][0]){
                    ssMatch.chart1.push({
                        pillar: key2,
                        from: 'my', 
                        to: 'their',
                        name: star.replace('yangN', 'n').replace('yinN','n'),
                        icon: ssmap.chart1[star][1].icon,
                        branch: ssmap.chart1[star][0],
                        desc: ssmap.chart1[star][2],
                        context: pillarContext[key2],
                    })
                }
            });
            this.pillarKeys1.forEach(key1 => {
                if(this.chart1.pillars[key1].branch.name === ssmap.chart2[star][0]){
                    ssMatch.chart2.push({
                        from: 'their',
                        to: 'my',
                        name: star.replace('yangN', 'n').replace('yinN','n'),
                        pillar: key1,
                        icon: ssmap.chart2[star][1].icon,
                        branch: ssmap.chart2[star][0],
                        context: pillarContext[key1],
                        desc: ssmap.chart2[star][2],
                    })
                }
            });
        })
        return ssMatch
    }
    elementComparison(){
        const labels = ['wood','fire','earth','metal','water']
        const matches = {}
        let overlap = 0
        labels.forEach(key => {
            const match = Math.min(this.chart1.meta.weights.ratio.elements[key], this.chart2.meta.weights.ratio.elements[key])
            matches[key] = match
        })
        Object.keys(matches).forEach(key => { overlap += matches[key] })
        const arr1 = []
        const arr2 = []
        labels.forEach(key => {
            arr1.push({
                name: toTitle(key),
                score: this.chart1.meta.weights.ratio.elements[key],
                color: Graphics.colors.elements.light[key]
            })
            arr2.push({
                name: toTitle(key),
                score: this.chart2.meta.weights.ratio.elements[key],
                color: Graphics.colors.elements.light[key]
            })
        })
        arr1.sort((a, b) => { return labels.indexOf(a.name.toLowerCase()) - labels.indexOf(b.name.toLowerCase()) })
        arr2.sort((a, b) => { return labels.indexOf(a.name.toLowerCase()) - labels.indexOf(b.name.toLowerCase()) })
        return {
            labels: labels.map(l => toTitle(l)),
            overlap,
            chart1: arr1,
            chart2: arr2,
        }
    }
    aspectComparison(){
        const labels = ['resource','companion','output','wealth','power']
        const matches = {}
        let overlap = 0
        labels.forEach(key => {
            const match = Math.min(this.chart1.meta.weights.ratio.aspects[key], this.chart2.meta.weights.ratio.aspects[key])
            matches[key] = match
        })
        Object.keys(matches).forEach(key => { overlap += matches[key] })
        const arr1 = []
        const arr2 = []
        const chart1ElementMap = this.chart1.meta.maps.aspectToElement
        const chart2ElementMap = this.chart2.meta.maps.aspectToElement
        labels.forEach(key => {
            arr1.push({
                name: toTitle(key),
                score: this.chart1.meta.weights.ratio.aspects[key],
                color: Graphics.colors.elements.light[ chart1ElementMap[ key ]] ,
                // color:  Color.BLUEGREY[100],
            })
            arr2.push({
                name: toTitle(key),
                score: this.chart2.meta.weights.ratio.aspects[key],
                color: Graphics.colors.elements.light[ chart2ElementMap[ key ]] ,
                // color:  Color.BLUEGREY[100],
            })
        })
        arr1.sort((a, b) => { return labels.indexOf(a.name.toLowerCase()) - labels.indexOf(b.name.toLowerCase()) })
        arr2.sort((a, b) => { return labels.indexOf(a.name.toLowerCase()) - labels.indexOf(b.name.toLowerCase()) })
        return {
            labels: labels.map(l => toTitle(l)),
            overlap,
            chart1: arr1,
            chart2: arr2,
        }
    }
    godComparison(){
        const labels = ['ir', 'dr','f','rw','eg','ho','iw','dw','7k','do']
        const matches = {}
        let overlap = 0
        labels.forEach(key => {
            const match = Math.min(this.chart1.meta.weights.ratio.gods[key], this.chart2.meta.weights.ratio.gods[key])
            matches[key] = match
        })
        Object.keys(matches).forEach(key => { overlap += matches[key] })
        const arr1 = []
        const arr2 = []
        labels.forEach(key => {
            arr1.push({
                name: toTitle(key).toUpperCase(),
                score: this.chart1.meta.weights.ratio.gods[key],
                color:  Color.BLUEGREY[100],
            })
            arr2.push({
                name: toTitle(key).toUpperCase(),
                score: this.chart2.meta.weights.ratio.gods[key],
                color:  Color.BLUEGREY[100],
            })
        })
        arr1.sort((a, b) => { return labels.indexOf(a.name.toLowerCase()) - labels.indexOf(b.name.toLowerCase()) })
        arr2.sort((a, b) => { return labels.indexOf(a.name.toLowerCase()) - labels.indexOf(b.name.toLowerCase()) })
        return {
            labels: labels.map(l => l.toUpperCase() ),
            overlap,
            chart1: arr1,
            chart2: arr2,
        }
    }
    basicComparison(){
        const meta1 = this.chart1.meta
        const meta2 = this.chart2.meta
        const formatKnown = 'yyyy-M-d, H:mm'
        const formatUnknown = 'yyyy-M-d --'
        const chart1birthday = this.chart1.info.hourUnknown ? this.chart1.info.time.toFormat(formatUnknown) : this.chart1.info.time.toFormat(formatKnown) 
        const chart2birthday = this.chart2.info.hourUnknown ? this.chart2.info.time.toFormat(formatUnknown) : this.chart2.info.time.toFormat(formatKnown) 
        const results = [
            { label: 'Time', left: chart1birthday, right: chart2birthday },
            { label: 'Gender', left: this.chart1.info.genderUnknown ? '—' : this.chart1.info.gender, right: this.chart2.info.genderUnknown ? '—' : this.chart2.info.gender },
            { label: '^ Aspect', left: meta1.stats.structure, right: meta2.stats.structure},
            { label: '^ God', left: EightWords.gods[meta1.stats.profile].name, right: EightWords.gods[meta2.stats.profile].name },
            { label: 'Strength', left: `${meta1.stats.strength} (${meta1.stats.supportScore}%)`, right: `${meta2.stats.strength} (${meta2.stats.supportScore}%)` },
            { label: 'Temp', left: meta1.stats.temperature || '—', right: meta2.stats.temperature || '—'},
            { label: 'Polarity', left: toTitle(meta1.stats.polarity.desc), right: toTitle(meta2.stats.polarity.desc)},
        ]
        return results
    }
    balanceComparison(){
        const results = [
            { label: 'Have', left: this.chart1.meta.unfavorable.elements, right: this.chart2.meta.unfavorable.elements },
            { label: 'Need', left: this.chart1.meta.favorable.elements, right: this.chart2.meta.favorable.elements },
        ]
        return results
    }
    render(){
        return (
            <View style={styles.container}>

                <SectionList
                    stickySectionHeadersEnabled={false}
                    keyboardShouldPersistTaps={'always'}
                    ref={sectionList => { this.sectionList = sectionList; }}
                    sections={this.state.sectionData}
                    keyExtractor={(item, index) => index.toString()}
                    inverted={false}
                    ItemSeparatorComponent={() => (<View style={styles.separator}></View>)}
                    renderSectionHeader={payload => {
                        if(payload.section.title === null || payload.section.data.length === 0) return <View/>

                        let leftItem = null;
                        let rightItem = null;

                        if(payload.section.template === 'dm'){
                            if(this.chart1.info.user?.username && this.chart2.info.user?.username){
                                const imageSize = 30

                                const imageStyle = { 
                                    width: imageSize, 
                                    height: imageSize, 
                                    borderRadius:15 ,
                                    borderWidth: 1,
                                    borderColor: 'white',
                                }
                                return (
                                    <View style={{ paddingHorizontal:7, backgroundColor: Color.BLUEGREY[800], flexDirection:'row', height: 50, alignItems: 'center' }}>
                                        <Image
                                            source={{ 
                                                uri: this.chart1.info?.user?.image || 'https://i.imgur.com/1e9gmt7.png',
                                                headers: {Pragma: 'no-cache'},
                                            }}
                                            style={imageStyle}
                                            resizeMode={"cover"}
                                        />
                                        <Text style={{ flex: 1, fontWeight: 'bold', color: 'white', fontSize: 16, textAlign: 'left', marginLeft:12}}>{ this.chart1.info.user.username}</Text> 
                                        <Text style={{ flex: 1, fontWeight: 'bold', color: 'white', fontSize: 16, textAlign: 'right', marginRight:12}}>{ this.chart2.info.user.username}</Text> 
                                        <Image
                                            source={{ 
                                                uri: this.chart2.info?.user?.image || 'https://i.imgur.com/1e9gmt7.png',
                                                headers: {Pragma: 'no-cache'},
                                            }}
                                            style={imageStyle}
                                            resizeMode={"cover"}
                                        />
                                    </View>
                                )
                            }else{
                                return <View style={{  height: 1 , backgroundColor: scolor.separator }}/>
                            }
                        }
                        if(payload.section.template === 'split'){
                            rightItem = <OverlapLabel num={payload.section.data[0].overlap}/>
                        }
                        if(payload.section.num){
                            rightItem = <CountLabel num={payload.section.num }/>
                        }
                        return (
                            <SectionHeader 
                                title={payload.section.title}
                                leftItem={leftItem}
                                rightItem={rightItem}
                            />
                        )
                    }}
                    renderItem={(payload) => {
                        const item = payload.item
                        if(payload.section.template === 'dm'){
                            return (
                                <View style={{ flexDirection:'row' }}>
                                    <View style={{ flex: 1, borderRightWidth:1, borderRightColor: scolor.separator, }}>
                                        <DayMasterPillar
                                            chart={this.chart1}
                                        />
                                    </View>
                                    <View style={{ flex: 1, alignItems: 'center', justifyContent:'center' }}>
                                        {/* <FontAwesome
                                            name={item.relation.icon}
                                            color={Color.GREY[600]}
                                            size={22}
                                            style={{
                                                transform: item.relation.direction === 'left' ? [ {scaleX: -1}, ] : []
                                            }}
                                        />
                                        <Text style={{ fontSize: 15, fontWeight: 'bold' ,marginTop:12, }}>
                                            { toTitle(item.relation.relation) }
                                        </Text> */}
                                    </View>
                                    <View style={{ flex: 1, borderLeftWidth:1, borderLeftColor: scolor.separator, }}>
                                        <DayMasterPillar
                                            chart={this.chart2}
                                        />
                                    </View>
                                </View>
                            )
                        }
                        if(payload.section.template === 'streams'){
                            return (
                                <View style={{  alignItems: 'flex-start'}}>
                                    <View style={styles.interRow}>
                                        <View style={{ flex: 1, padding: 15 }}>
                                            <Text style={styles.numLabel}>{ item.matches.chart1.length }</Text>
                                            <Text style={{ marginTop: 2}}>{ item.matches.chart1.join(', ') }</Text>
                                        </View>
                                        <View style={styles.interRowCenterLabelHolder}>
                                            <Text style={styles.interRowCenterLabel}>
                                                { Ordinals.stems['jia'].chinese } { Ordinals.branches[item.stream].chinese }
                                            </Text>
                                            <Text style={{ textAlign:'center', marginTop:3, }}>
                                                Jia { toTitle(item.stream) }
                                            </Text>
                                            <Text style={{ textAlign:'center', marginTop:2, }}>
                                                { toTitle( Ordinals.branches[item.stream].animalName ) }
                                            </Text>
                                        </View>
                                        <View style={{ flex: 1, alignItems: 'flex-end', padding: 15 }}>
                                            <Text style={styles.numLabel}>{ item.matches.chart2.length }</Text>
                                            <Text style={{ marginTop:2, }}>{ item.matches.chart2.join(', ') }</Text>
                                        </View>
                                    </View>
                                </View>
                            )
                        }
                        if(payload.section.template === 'stars'){
                            return (
                                <View style={{ padding: 15, }}>
                                    <View style={{ flexDirection:'row'}}>
                                        <MaterialCommunityIcon
                                            name={item.icon}
                                            color={Color.GREY[600]}
                                            size={18}
                                        />
                                        <Text style={{ fontWeight: 'bold', marginLeft:12, flex: 1}}>{ toTitle(item.from) } { deCamel(item.name) }</Text>
                                        <Text style={{ textAlign:'right', fontWeight:'bold'}}>{ toTitle( Ordinals.branches[item.branch].animalName ) } { Ordinals.branches[item.branch].chinese }</Text>
                                    </View>
                                    <View style={{ flexDirection:'row', marginTop:4, }}>
                                        <Text style={{ paddingLeft:31, lineHeight:20 }}>
                                            {`In ${item.to} ${toTitle(item.pillar)} Pillar. ${item.desc} in the context of ${item.context}.`} 
                                        </Text>
                                    </View>
                                </View>
                            )
                        }
                        if(payload.section.template === 'haveNeed'){
                            return <HaveNeedRow data={item}></HaveNeedRow>
                        }
                        if(payload.section.template === 'information'){
                            return <InformationRow data={item} />
                        }
                        if(payload.section.template === 'split'){
                            return <SplitDistributionChart data={item} />
                        }

                    }}
                    ListFooterComponent={(<View style={styles.separator}/>)}
                />
            </View>
        )
    }
}
export default withNavigation(Synastry)

const InformationRow = ({data}) => {
    return (
        <View style={styles.interRow}>
            <Text style={styles.interRowLeftText}>
                { toTitle(data.left)}
            </Text>
            <View style={styles.interRowCenterLabelHolder}>
                <Text style={styles.interRowCenterLabel}>
                    {toTitle(data.label)}
                </Text>
            </View>
            <Text style={styles.interRowRightText}>
                {toTitle(data.right)}
            </Text>
        </View>
    )
}


