const DFEAULT_NAV_INDEX = 0
class ChartAnalysis extends React.Component {
    state = {
        pillarContentMode: 0,
        pillarTitleMode: DFEAULT_NAV_INDEX, 
        selectedTabIndex: 0,
        showChart: false,
    }
    static navigationOptions = ({ navigation }) => {
        const { params={} } = navigation.state 
        const title = params.chart.info.chartName ? `${params.chart.info.chartName}` : 'Analysis'
		return {
            title: title,
        }
    }
    constructor(props){
        super(props)
        this.chart = this.props.navigation.getParam('chart')
        this.chartPayload = this.props.navigation.getParam('chartPayload')
        this.onTabPress = this.onTabPress.bind(this)
        this.props.navigation.setParams({ pillarTitleMode: this.state.pillarTitleMode, setNavIndex: this.setNavIndex, showChart: false, toggleChart: this.toggleChart, chart: this.chart })
    }
    componentDidMount(){
    }

 
    async onTabPress(selectedTabIndex){
        this.setState({ selectedTabIndex })
        if(selectedTabIndex >= 2){
            this.tabBar.scrollTo(9999)
        }else{
            this.tabBar.scrollTo(0)
        }
    }
    render(){
        return (
            <View style={styles.container}>
                <View style={styles.navTabBar}>
                    <SegmentedControlTab
                        allowFontScaling={false}
                        tabStyle={[sstyle.navigation.headerSegmentTabs.segmentTabStyle, { paddingHorizontal: 9,}]}
                        activeTabStyle={sstyle.navigation.headerSegmentTabs.segmentTabActive}
                        tabTextStyle={[sstyle.navigation.headerSegmentTabs.segmentTabText, {}]}
                        borderRadius={2}
                        tabsContainerStyle={{flex: 1,}}
                        values={['—', '≡', '#', '>','⚘','☉','⚯', '⃞']}
                        selectedIndex={this.state.pillarTitleMode === 'undefined' ? DFEAULT_NAV_INDEX : this.state.pillarTitleMode}
                        onTabPress={pillarTitleMode =>  { 
                            this.setState({ pillarTitleMode})
                            analytics.track('Bazi.Analysis.PillarTitle', { pillarTitleMode})
                        }}
                    />
                </View>
                { this.state.pillarTitleMode > 0 && (
                    <View>
                        <View style={styles.pillarContentModeBar}>
                            <SegmentedControlTab
                                allowFontScaling={false}
                                tabStyle={sstyle.sectionHeader.tabs.segmentTabStyle}
                                activeTabStyle={sstyle.sectionHeader.tabs.segmentTabActive}
                                tabTextStyle={sstyle.sectionHeader.tabs.segmentTabText}
                                activeTabTextStyle={sstyle.sectionHeader.tabs.activeTabTextStyle}
                                borderRadius={2}
                                tabsContainerStyle={{flex: 1, alignSelf: 'center' }}
                                values={['Main', 'Elements', 'Aspects', 'Archetype',  'Polarity']}
                                selectedIndex={this.state.pillarContentMode}
                                onTabPress={  pillarContentMode =>  { 
                                    this.setState({  pillarContentMode })
                                    analytics.track('Bazi.Analysis.PillarContent', { pillarContentMode})
                                }}
                            />
                        </View>
                        <HorizontalScroll
                            inverted={true}
                            setPillarFocusBirth={null}
                            payload={this.chartPayload}
                            root={this.chart}
                            pillarTitleMode={this.state.pillarTitleMode}
                            pillarContentMode={this.state.pillarContentMode}
                        />
                        <View style={{ height: 1,  backgroundColor: scolor.separator,}}/>
                        
                    </View>
                )}
                <TabBar
                    ref={tabBar => { this.tabBar = tabBar }}
                    tabs={[
                        { title: '8 Words' }, 
                        { title: '8 Mansions' },
                        // { title: 'Mystic Doors' },
                        { title: 'Symbolics' },
                    ]}
                    onTabPress={this.onTabPress}
                    selected={this.state.selectedTabIndex}
                />
                
                { this.state.selectedTabIndex === 0 && (
                    <BasicAnalysis
                        chart={this.chart}
                    />
                )}

                { this.state.selectedTabIndex === 1 && (
                    <EightMansions
                        chart={this.chart}
                    />
                )}

                {/* { this.state.selectedTabIndex === 2 && (
                    <QiMenScreen
                        time={this.chart.info.time}
                        reference={'hour'}
                    />
                )} */}
                { this.state.selectedTabIndex === 2 && (
                    <ChartStars
                        chart={this.chart}
                    />
                )}


            </View>
        )
    }
}
export default withNavigation(ChartAnalysis)




