
import React from 'react';
import { Provider, Subscribe, Container } from 'unstated';
import _ from 'lodash'
import update from 'immutability-helper';
import * as strings from '../lib/utils/strings'
import { DateTime } from 'luxon'

const  pillarDefault = () => {
    const result = {}
    for(let i = 0; i < 32 ; i++){
        result[i] = { stem: null, branch: null}
    }
    return result
}

const INIT_STATE = {
    accent:{
        stem: {
            jia: false,
            yi: false,
            bing: false,
            ding: false,
            wu: false,
            ji: false,
            geng: false,
            xin: false,
            ren: false,
            gui: false,
        },
    },
    flash:{
        sections:{
            Birth:pillarDefault(),
            Comparison:pillarDefault(),
            Luck:pillarDefault(),
            Years:pillarDefault(),
            Months:pillarDefault(),
            Days:pillarDefault(),
            Hours:pillarDefault(),
        }
    }
}
class PillarContainer extends Container {
    state = INIT_STATE
    birthPillarNameMap={
        year: 0,
        month: 1,
        day: 2,
        hour: 3,
        life: 4,
        conception: 5,
    }
    constructor(props) {
        super(props)
        this.updateStemAccent = this.updateStemAccent.bind(this)
        this.resetState = this.resetState.bind(this)
        this.resetFlash = this.resetFlash.bind(this)
    }
    updateStemAccent(map){ //jia, true
        const newState = _.cloneDeep(this.state)
        newState.accent.stem = map
        this.setState(newState)
    }
    updateFlash(items){
        const newState = _.cloneDeep(this.state)
        newState.flash = _.cloneDeep(INIT_STATE.flash);
        const tick = DateTime.local().toMillis()
        items.forEach(item => {
            const { section, index, palace } = item
            newState.flash.sections[section][index][palace] = tick
        })
        this.setState( newState )
    }
    resetFlash(){
        const newState = _.cloneDeep(this.state)
        newState.flash = _.cloneDeep(INIT_STATE.flash); 
        this.setState(newState)
    }
    resetState(){
        this.setState(INIT_STATE)
    }

}

export default PillarContainer


