const UserRow = ({ item , client , preferences, navigation }) => {
    const  context = useContext(AuthContext)
    const birth2 = _.cloneDeep(item?.User?.Birth)
    if(birth2?.time) birth2.time = DateTime.fromISO(birth2.time, { setZone: true })
    const birth1 = _.cloneDeep(context?.profileQuery?.data?.user?.Birth)
    if(birth1?.time) birth1.time = DateTime.fromISO(birth1.time, { setZone: true })

    let chart1 = null;
    let chart2 = null;


    if(birth1){
        chart1 = FourPillars.plot({ 
            ...birth1,
            showLuck: true, 
            simpleLuckCycle: preferences?.bazi?.calculations?.showSimpleLuckCycleCalculation,
            lateZi: preferences?.bazi?.calculations?.showDayStartsFrom_23, 
            weightsIncludeCombos: preferences?.bazi?.calculations?.showCombinationsInWeightCalculation, 
            showWeights: true, 
        })
        chart1.info.user = _.cloneDeep(context?.profileQuery?.data?.user)
    }
    let nowChart = null
    if(birth2){
        chart2 = FourPillars.plot({ 
            ...birth2,
            showLuck: true, 
            simpleLuckCycle: preferences?.bazi?.calculations?.showSimpleLuckCycleCalculation,
            lateZi: preferences?.bazi?.calculations?.showDayStartsFrom_23, 
            weightsIncludeCombos: preferences?.bazi?.calculations?.showCombinationsInWeightCalculation, 
            showWeights: true, 
        })
        chart2.info.user = _.cloneDeep(item?.User)
        nowChart = FourPillars.plot({ time: DateTime.local(), root: chart2 })
    }

    //Message
    let message = null;
    if(item.added){
        if(item.addedBack){
            //no message
            // message = 'See compatibility →'
        }else if(!item.addedBack){
            message = 'Waiting for friend to accept...'
        }
    }else if(!item.added){
        if(item.addedBack){
            message = 'Respond to friend request →';
        }else if(!item.addedBack){
            message = 'Add friend to see compatibility →'
        }
    }

    //Methods 

    const addFriend = async (toUserId) => {
        try{
            const result = await client.mutate({
                mutation: queries.createFriendship,
                variables: { toUserId }
            })
        }catch(err){
            console.log(err)
        }
    }

    const removeFriend = async(toUserId) => {
        try {
            const result = await client.mutate({
                mutation: queries.destroyFriendship,
                variables: { toUserId }
            })
        }catch(err){
            console.log(err)
        }
    }

    const ignoreRequest = async(toUserId) => {
        try {
            const result = await client.mutate({
                mutation: queries.destroyPendingFriendship,
                variables: { toUserId }
            })
        }catch(err){
            console.log(err)
        }
    }


    const showAdd = () => {
        const buttons = [
            'Add Friend',
            '—'
        ];
        ActionSheet.showActionSheetWithOptions({
            options:  buttons,
            cancelButtonIndex: 1,
            tintColor: 'blue',
        },(buttonIndex) => {
            if(buttonIndex === 0){
                addFriend(item.User?.id)
            }
        });
    }

    const showRemove = () => {
        const buttons = [
            'Remove Friend',
            '—'
        ];
        ActionSheet.showActionSheetWithOptions({
            options:  buttons,
            cancelButtonIndex: 1,
            tintColor: 'blue'
        },(buttonIndex) => {
            if(buttonIndex === 0){
                removeFriend(item.User?.id)
            }
        });
    }

    const showAddIgnore = () => {
        const buttons = [
            'Add Friend',
            'Ignore Friend',
            '—'
        ];
        ActionSheet.showActionSheetWithOptions({
            options:  buttons,
            cancelButtonIndex: 1,
            tintColor: 'blue'
        },(buttonIndex) => {
            if(buttonIndex === 0){
                addFriend(item.User?.id)
            }
            if(buttonIndex === 1){
                destroyPendingFriendship(item.User?.id)
            }
        });
    }



    return (
        <Toucher
            underlayColor={scolor.touchableHighlightUnderlayColor}
            style={styles.rowTouch}
            onPress={() => {
                if(item.added){
                    if(item.addedBack){
                        navigation.push('Synastry', { 
                            chart1: chart1,
                            chart2: chart2,
                        })        
                    }else{
                        showRemove()
                    }
                }else{
                    if(item.added){
                        showAddIgnore()
                    }else{
                        showAdd()
                    }
                }
            }}
            onLongPress={() => {
                if(item.added){
                    if(item.addedBack){
                        showRemove()                        
                    }else{
                        showRemove()
                    }
                }else{
                    if(item.added){
                        showAddIgnore()
                    }else{
                        showAdd()
                    }
                }
            }}
        >
            <View style={sstyle.layout.row}>
                <Image
                    source={{ 
                        uri: item.User?.image ||  'https://i.imgur.com/1e9gmt7.png',
                        headers: {
                            Pragma: 'no-cache',
                        },
                    }}
                    style={styles.image}
                    resizeMode={"cover"}
                />
                <View style={styles.content}>
                    <View style={styles.topContent}>
                        <Text style={styles.username}>{item.User.username }</Text>
                    </View>
                    { message && (
                        <View style={styles.secondContent}>
                            <Text style={styles.statusMsg}>
                                { message}
                            </Text> 
                        </View>
                    )}

                </View>
                { (chart2  && item.added && item.addedBack )&& (
                    <View style={styles.dmImages}>
                        <Image 
                            source={CMImages.color.stems[chart2.pillars.day.stem.name]}
                            style={styles.dmImage}
                            resizeMode={'contain'}
                        />
                        <View style={{ width: 6}}/>
                        <Image 
                            source={CMImages.color.branches[chart2.pillars.day.branch.name]}
                            style={styles.dmImage}
                            resizeMode={'contain'}
                        />
                    </View>
                )}
            </View>
        </Toucher>
    )
   
}
export default withApollo(withNavigation(React.memo(UserRow)))



