const SimilarYears = (props) => {
    const { time, pillar } = props
    const year = time.year


    const years = []
    for(let i = year; i > 1000 ; i -= 60){
        years.push(i)
    }


    return (
        <View style={styles.container}>
            {/* <Text style={{
                textTransform:'uppercase',
                textAlign:'center',
                paddingVertical:12,
                color: Color.GREY[400],
            }}>
                TRAVEL
            </Text> */}
            <FlatList
                style={{ height: 44}}
                showsHorizontalScrollIndicator={false}
                horizontal={true}
                data={years}
                keyExtractor={(item, index) => index.toString()}
                renderItem={(payload) => {
                    return (
                        <Toucher
                            style={[styles.yearTouch,
                                payload.index % 2 && { backgroundColor: Color.GREY[100]}
                            ]}
                            onPress={() => {
                                const title = `${toTitle(pillar.stem.elm.name)} ${toTitle(pillar.branch.animalName)} Year`
                                props.navigation.push('BasicWebView', { uri: 'https://onthisday.com/date/' + payload.item, title})
                            }}
                        >
                            <Text 
                                style={[styles.yearText,
                                ]}
                            >{ payload.item }</Text>
                        </Toucher>
                    )
                }}
            />
        </View>
    )
}

export default withNavigation(SimilarYears)

