

import React, {Fragment, useContext} from 'react';
import {
	SafeAreaView,
	StyleSheet,
	ScrollView,
	View,
	Text,
	StatusBar,
	TextInput,
    Button,
    Animated,
    Easing,
    TouchableHighlight,
    TouchableOpacity,
    Dimensions,
    ActivityIndicator
} from 'react-native';


import Color from 'react-native-material-color';

import * as objects from '../../lib/utils/objects'
import { deCamel} from '../../lib/utils/strings'

import { sstyle, scolor } from '../../styles/shared'
import { withNavigation, NavigationEvents } from 'react-navigation';


import { ApolloProvider, ApolloConsumer, Query, Mutation, withApollo } from "react-apollo";

import SectionHeader from '../Layout/SectionHeader'
import withPreventDoubleClick from '../../lib/utils/withPreventDoubleClick'
const Toucher = withPreventDoubleClick(TouchableHighlight)
const TouchableOpacityEx = withPreventDoubleClick(TouchableOpacity)
import FontAwesome from 'react-native-vector-icons/FontAwesome';
import FontAwesome5 from 'react-native-vector-icons/FontAwesome5';
import MaterialCommunityIcon from 'react-native-vector-icons/MaterialCommunityIcons'
import DatePicker from 'react-native-date-picker';
import SegmentedControlTab from "react-native-segmented-control-tab";

import TabBar from '../Layout/TabBar'
const winWidth = Dimensions.get('window').width
import ImagePicker from 'react-native-image-picker';
import PreferencesContainer  from '../../containers/PreferencesContainer'
import { Subscribe } from 'unstated'
import { CheckBox } from 'react-native-ui-kitten'
import { auxDetails } from '../../lib/cmtools/ShenSha'
import QiMenSettings from '../QiMen/QiMenSettings';
import { AuthContext } from '../../Contexts';
import { verifyCheckpoints } from '../Other/Checkpoint'
import analytics from '@segment/analytics-react-native'
import YiJingSettings from './YiJingSettings';
import AlmanacSettings from './AlmanacSettings';

class EditPreferences extends React.Component {
    state={
        selectedTabIndex: 0,
        tabs : []
    }

    constructor(props){
        super(props)
        this.onTabPress = this.onTabPress.bind(this)
        this.defaultTabIndex = this.props.navigation.getParam('defaultTabIndexPreferences', 0)
        this.noteLabel = this.noteLabel.bind(this)
        analytics.track('Settings.Preferences')
    }
    async componentDidMount(){
        let tabs = [
            { title: 'Pillars' },
        ]
        const failed = await verifyCheckpoints(['invitation'], this.context)
        if(!failed){
            tabs = tabs.concat([
                { title: 'Details' },
                { title: 'Day Table' },
                { title: 'Symbolics' },
                { title: 'QMDJ'},
                { title: 'Hexagrams'},
                { title: 'Mystic Doors'},
                { title: 'Calculations' },
            ])
        }
        this.setState({ tabs }, () => {
            if(!this.defaultTabIndex) return
            setTimeout(() => {
                this.onTabPress(this.defaultTabIndex)
            }, 0)
        })
    }
    async onTabPress(selectedTabIndex){
        this.setState({ selectedTabIndex })
        if(selectedTabIndex >= 3 && selectedTabIndex < 4){
            this.tabBar.scrollTo( winWidth / 3.5)
        }else if(selectedTabIndex >= 4 && selectedTabIndex < 6){
            this.tabBar.scrollTo( winWidth / 1.5)
        }else if(selectedTabIndex >= 6){
            this.tabBar.scrollTo(9999)
        }else{
            this.tabBar.scrollTo(0)
        }
    }
    noteLabel(body){
        return  <Text style={{
            padding:9,
            color: Color.GREY[600],
            fontSize:12,
            paddingLeft:15,
            backgroundColor: Color.GREY[50]
        }}>{body}</Text>
    }
    render(){
        return (
            <Subscribe to={[PreferencesContainer]}>
            {(prefs) => {
                return (
                    <View style={{ flex: 1 }}>
                        <TabBar 
                        ref={tabBar => { this.tabBar = tabBar }}
                            tabs={this.state.tabs}
                            onTabPress={this.onTabPress}
                            selected={this.state.selectedTabIndex}
                        />
                        <ScrollView style={styles.scrollView}>

                        { this.state.selectedTabIndex === 0 && (
                            <View style={styles.content}>
                                <Toucher
                                    onPress={() => {
                                        this.props.navigation.push('InitialDisplaySelector', { cancelText: 'Cancel'})
                                    }}
                                    style={{
                                            borderBottomWidth:1,
                                            borderBottomColor: scolor.separator,
                                    }}
                                >
                                    <View
                                        style={{
                                            alignItems: 'center',
                                            flexDirection:'row',
                                            justifyContent: 'center',
                                            margin:15,
                                        }}
                                    >
                                        <Text style={{
                                            fontSize:14,
                                            fontWeight: '500',
                                            color: Color.BLUE[900]
                                        }}>
                                            Presets →
                                        </Text>
                                     
                                    </View>
                                </Toucher>
                                { Object.keys(prefs.state.bazi.pillars).map(key => (
                                    <View>
                                        <View style={styles.row}>
                                            <CheckBox
                                                text={deCamel(key).replace('Show ', '')}
                                                checked={prefs.state.bazi.pillars[key]}
                                                onChange={(val) => { 
                                                    const state = prefs.clone()
                                                    state.bazi.pillars[key] = val
                                                    prefs.update(state)
                                                    analytics.track('Preferences.Bazi.Pillar-' + key , { val })
                                                }}
                                            />
                                        </View>
                                        { key === 'showElementName' && this.noteLabel('For branches, the polarity of the Main Qi will be displayed, not the polarity of the branch.') }
                                        { key === 'showRootingHighlight' && this.noteLabel('Highlight the forces that are strengthened during the selected period.') }
                                    </View>
                                ))}
                            </View>
                        )}
                                                    

                            { this.state.selectedTabIndex === 1 && (
                                <View style={styles.content}>
                                { Object.keys(prefs.state.bazi.details).map(key => (
                                    <View style={styles.row}>
                                        <CheckBox
                                            text={deCamel(key).replace('Show ', '')}
                                            checked={prefs?.state?.bazi?.details[key]}
                                            onChange={(val) => { 
                                                const state = prefs.clone()
                                                state.bazi.details[key] = val
                                                prefs.update(state)
                                                analytics.track('Preferences.Bazi.PillarDetail' + key , { val })
                                            }}
                                        />
                                    </View>
                                ))}
                                </View>
                            )}

                            { this.state.selectedTabIndex === 2 && (
                                <View style={styles.content}>
                                { Object.keys(prefs.state.bazi.dayInfo).map(key => (
                                    <View style={styles.row}>
                                        <CheckBox
                                            text={deCamel(key).replace('Show ', '')}
                                            checked={prefs.state.bazi.dayInfo[key]}
                                            onChange={(val) => { 
                                                const state = prefs.clone()
                                                state.bazi.dayInfo[key] = val
                                                prefs.update(state)
                                                analytics.track('Preferences.Bazi.DayInfo' + key , { val })
                                            }}
                                        />
                                    </View>
                                ))}
                                </View>
                            )}

                            { this.state.selectedTabIndex === 3 && (
                                <View style={styles.content}>
                                { Object.keys(prefs.state.bazi.stars).map(aux => (
                                    <View>
                                        <SectionHeader title={`${deCamel(aux).replace('Aux','')}`}/>
                                        { Object.keys(prefs.state.bazi.stars[aux]).map(name => {
                                            return (
                                                <View style={styles.row}>
                                                    <CheckBox
                                                        text={`${deCamel(name)}  ${auxDetails[aux][name].chinese}` }
                                                        checked={prefs.state.bazi.stars[aux][name]}
                                                        onChange={(val) => { 
                                                            const state = prefs.clone()
                                                            state.bazi.stars[aux][name] = val
                                                            prefs.update(state)
                                                        }}
                                                    />

                                                    <MaterialCommunityIcon
                                                        name={auxDetails[aux][name].icon}
                                                        color={Color.GREY[600]}
                                                        size={18}
                                                        style={styles.starIcon}
                                                        pointerEvents="none"
                                                    />
                                                </View>
                                            )
                                        })}
                                    </View>
                                ))}
                                </View>
                            )}

                            { this.state.selectedTabIndex === 4 && (
                                <QiMenSettings
                                    prefs={prefs}
                                />
                            )}

                            { this.state.selectedTabIndex === 5 && (
                                <YiJingSettings
                                    prefs={prefs}
                                />

                            )}

                            { this.state.selectedTabIndex === 6 && (
                                <AlmanacSettings
                                    prefs={prefs}
                                />
                            )}

                            { this.state.selectedTabIndex === 7 && (
                                <View style={styles.content}>
                                    { Object.keys(prefs.state.bazi.calculations).map(key => (
                                        <View>
                                            <View style={styles.row}>
                                                <CheckBox
                                                    text={deCamel(key).replace('Show ', '')}
                                                    checked={prefs.state.bazi.calculations[key]}
                                                    onChange={(val) => { 
                                                        const state = prefs.clone()
                                                        state.bazi.calculations[key] = val
                                                        prefs.update(state)
                                                    }}
                                                />
                                            </View>
                                            { key === 'showCombinationsInWeightCalculation' && this.noteLabel('You will need to re-plot the chart for weight settings to take effect.') }
                                        </View>
                                    ))}
                                </View>
                            )}

                            { this.state.selectedTabIndex === 8 && (
                                <View style={styles.content}>
                                    { Object.keys(prefs.state.bazi.analysis).map(key => (
                                        <View style={styles.row}>
                                            <CheckBox
                                                text={deCamel(key).replace('Show ', '')}
                                                checked={prefs.state.bazi.analysis[key]}
                                                onChange={(val) => { 
                                                    const state = prefs.clone()
                                                    state.bazi.analysis[key] = val
                                                    prefs.update(state)
                                                }}
                                            />
                                        </View>
                                    ))}
                                </View>
                            )}


        
                        </ScrollView>
                    </View>
                )
            }}
            </Subscribe>
        )
    }
}
EditPreferences.contextType = AuthContext
export default withNavigation(EditPreferences)

const styles = StyleSheet.create({
    container:{
        flex:1,
    },
    scrollView:{
        flex: 1,
    },
    content:{
        flex:1,
    },
    row:{
        padding:15,
        borderBottomWidth:1,
        borderBottomColor: scolor.separator,
    },
    starIcon:{
        position:'absolute',
        top:16,
        right:12,
    }
})




