import * as Ordinals from '../../lib/cmtools/Ordinals'
import * as EightWords from '../../lib/cmtools/EightWords'
import * as QiMap from '../../lib/cmtools/Plotters/QiMap'

class BasicAnalysis extends React.Component {
    state = {
        sectionData:[
            { title: '', data: [] },
        ] 
    }
    constructor(props){
        super(props)
        this.chart = this.props.chart

        analytics.track('Bazi.Analysis.8Words')
    }
    async componentDidMount(){
        const preferences = await getPreferences()

        const pillars = this.chart.pillars
        const elementToAspect = this.chart.meta?.maps.elementToAspect
        const weights = this.chart.meta?.weights
        const temperature = this.chart.meta?.stats.temperature ? toTitle(this.chart.meta.stats.temperature) : '—'
        const structure = this.chart.meta?.stats.structure || '-'
        const godsProfile = this.chart.meta?.stats.profile || '-'
        const gua = this.chart.meta?.gua

        // Stats
        const stats = [
            { heading: 'Year Form', body: `${pillars.year.branch.chinese } ${toTitle( pillars.year.branch.animalName )}` },
            { heading: 'Gua Number', body: toTitle(`${gua.luoShu} ${gua.lifeStarDescArr.join(' ')}`) },
            { heading: 'Gua Name', body: `${toTitle(gua.pinyin)} ${gua.trigram}` },
        ]



        //More Stats
        const moreStats = [
            { heading: 'Temperature', body: temperature },
            { heading: 'Polarity', body: `${this.chart.meta.stats.polarity.yinCount} Yin / ${this.chart.meta.stats.polarity.yangCount} Yang`},
        ]
        if(preferences?.bazi?.calculations?.showDeathEmptinessBasedOnDayPillar){
            moreStats.push({ heading: 'Void / Emptiness (D)', body: this.chart.pillars.day.voidStars.map(s => `${Ordinals.branches[s].chinese} ${toTitle(Ordinals.branches[s].animalName)}`).join(', ')})
        }
        if(preferences?.bazi?.calculations?.showDeathEmptinessBasedOnYearPillar){
            moreStats.push({ heading: 'Void / Emptiness (Y)', body: this.chart.pillars.year.voidStars.map(s => `${Ordinals.branches[s].chinese} ${toTitle(Ordinals.branches[s].animalName)}`).join(', ')})
        }

        //Useful Gods
        const uGods = this.chart.meta?.usefulGods
        const godToStem = this.chart.meta?.maps?.godToStem
        const medicating = uGods.medicating ? `${ Ordinals.stems[godToStem[uGods.medicating]].chinese } (${uGods.medicating.toUpperCase()})` : '—'
        const regulating = uGods.regulating ? `${ Ordinals.stems[godToStem[uGods.regulating]].chinese } (${uGods.regulating.toUpperCase()})` : '—'
        const arbitrating = uGods.arbitrating ? `${ Ordinals.stems[godToStem[uGods.arbitrating]].chinese } (${uGods.arbitrating.toUpperCase()})` : '—'
        const usefulGodsData = [
            { heading: 'Balance', body: medicating},
            { heading: 'Temperature', body: regulating},
            { heading: 'Bridge', body: arbitrating},
        ]        


        //Counts
        const cmap = this.chart.meta?.counts.elements;
        const counts = [
            { heading: `Wood`, body: cmap.wood},
            { heading: `Fire`, body: cmap.fire},
            { heading: `Earth`, body: cmap.earth},
            { heading: `Metal`, body: cmap.metal},
            { heading: `Water`, body: cmap.water},
        ]


        //Plot QMDJ Chart for this guy
        let destinyPalace = null;
        if(!this.chart.info.hourUnknown){
            const starPath = preferences.qmdj?.calculations?.starPath
            const method = preferences.qmdj?.calculations?.method
            const shiftLateZiStream = preferences.qmdj?.calculations?.shiftLateZiStream
            const qmdjChart =  QiMap.plot({ bazi: this.chart , reference: 'hour', starPath, method, shiftLateZiStream, appendDestiny: true, appendMeta: true})
            if(qmdjChart){
                destinyPalace = qmdjChart.palaces[qmdjChart.details.destinyPalace] 
            }
        }

        //Get Common Symbolics
        const commonSyms = {}
        commonSyms['noblemen'] = ShenSha.dayStemAux.nobleman[pillars.day.stem.number]
        commonSyms['peachBlossom'] = [ShenSha.dayBranchAux.peachBlossom[pillars.day.branch.number]]
        commonSyms['intelligence'] = [ShenSha.dayStemAux.intelligence[pillars.day.stem.number]]


        this.setState({ sectionData: [
            { template: 'DayMaster', title: 'Ego', data: [stats] },
            { template: 'CommonSymbolics', title: 'Affinity', data: [commonSyms] },
            { template: 'QiMen', title: 'Mystic Doors', data: [destinyPalace] },
            { template: 'Elements', title: '', data: [0]},
            { title: 'Macros', data : moreStats },
            // { template: 'TenGods', title: '', data: [0]},
            { template: 'UsefulGods', title: 'Utility', data:usefulGodsData},
            { template: 'DayInfo', title: 'Day Information', data: [0]}
        ]})
    }
    render(){
        return (
            <Subscribe to={[PreferencesContainer]}>
            {(prefs) => {
                const settings = prefs?.state
                return (
                <SectionList
                    keyboardShouldPersistTaps={'always'}
                    ref={sectionList => { this.sectionList = sectionList; }}
                    sections={this.state.sectionData}
                    keyExtractor={(item, index) => index.toString()}
                    inverted={false}
                    ItemSeparatorComponent={() => (<View style={styles.separator}></View>)}
                    renderSectionHeader={payload => {
                        let rightItem = null
                        if(!payload.section.title) return <View style={{height: 1, backgroundColor: scolor.separator }} />
                        if(payload.section.template === 'QiMen'){
                            rightItem = (
                                <Toucher
                                    style={styles.settingsButton}
                                    onPress={() => {
                                        this.props.navigation.push('QiMenScreen', { time: this.chart.info.time, reference: 'hour' })
                                    }}
                                >
                                    <Text style={styles.settingsButtonText}>Chart</Text>
                                </Toucher>
                            )
                        }
                        return (
                            <SectionHeader 
                                subtitle={payload.section.subtitle || null}
                                title={payload.section.title}
                                rightItem={rightItem}
                                leftItem={null}
                            />
                        )
                    }}
                    renderItem={(payload) => {
                        if(payload.section.template === 'DayMaster'){
                            return <DayMasterHolder
                                chart={this.chart}
                                data={payload.item} 
                            />
                        }
                        if(payload.section.template === 'Elements'){
                            return  <ElementDistribution
                                chart={this.chart}
                            />
                        }
                        if(payload.section.template === 'TenGods'){
                            return <GodStrengths
                                chart={this.chart}
                            />
                        }
                        if(payload.section.template === 'DayInfo'){
                            return <DayBasicInfo
                                chart={this.chart}
                                showAll={true}
                            />
                        }
                        if(payload.section.template === 'CommonSymbolics'){
                            return <CommonSymbolics
                                data = {payload.item }
                            />
                        }
                        if(payload.section.template === 'QiMen'){
                            if(!payload.item) return <Text style={{ padding: 15}}>Cannot be calculated due to missing hour.</Text>
                            return <QiMenDestinySummary
                                palace={payload.item}
                                settings={settings}
                            />
                        }
                        const data = payload.item
                        return (
                            <View style={[styles.infoRow]}>
                                <View style={styles.title}>
                                    <Text style={styles.titleText}>
                                        { data.heading }
                                    </Text>
                                </View>
                                <View style={styles.detail}>
                                    <Text style={styles.detailText}>
                                        { data.body }
                                    </Text>
                                </View>
                            </View>
                        )
                    }}
                    ListFooterComponent={(<View style={styles.separator}/>)}
                />)
            }}
            </Subscribe>
        )
    }
}
export default withNavigation(BasicAnalysis)



