import gql  from 'graphql-tag'


export const pendingFriendshipsQuery = gql`
    query PendingFriendships($time: Date, $num: Int!){
        pendingFriendships(time: $time, num: $num){
            addedBack
            added
            User{
                id
                username
                image
                Birth{
                    time
                    gender
                    hourUnknown
                }
            }
        }
    }
`

