const TICK = 1000
const iOS = Platform.OS === 'ios'

const DEFAULT_COMPASS_ENABLED = false
const DEGREE_RATE = iOS ? 3 : 1
const COMPASS_DEBOUNCER = iOS ? 0 : 50
const HOUSEINDEX = 4
const DEFAULT_TAB_INDEX = 0

import * as Ordinals from '../../lib/cmtools/Ordinals'
import * as WindWater from '../../lib/cmtools/WindWater'
import * as Tools from '../../lib/cmtools/Tools'
import * as FourPillars from '../../lib/cmtools/Plotters/FourPillars'
import HeadDateBarQuick from './HeadDateBarQuick';

class QiMenScreen extends React.Component {
    palaceOrder = ['li','kun','dui','qian','kan','gen','zhen','xun']
    direction = 'S' //don't re-render
    tabIndexToReference={ 0: 'hour', 1: 'day', 2: 'month', 3: 'year', 4: 'house'}
    state={
        scrollEnabled: true,
        refreshing: false,
        timerOn: false,
        time: DateTime.local(),
        houseInput: null,
        chart: null,
        bazi: null, //for the chart on the bottom.
        datePickerVisible:false,
        tabIndex: DEFAULT_TAB_INDEX,
        compassEnabled: DEFAULT_COMPASS_ENABLED,
        palaces:[null, null, null, null, null, null, null, null],
        displayMode: 0,
    }
    static navigationOptions = ({ navigation }) => {
        const { params={} } = navigation.state 
        const tabValues = ['H', 'D','M', 'Y', '🏠']
		return {
            headerTitle:(
                <View style={{flex: 1}}>
                    <SegmentedControlTab
                        allowFontScaling={false}
                        tabStyle={styles.segmentTabStyle}
                        activeTabStyle={styles.segmentTabActive}
                        tabTextStyle={styles.segmentTabText}
                        borderRadius={2}
                        tabsContainerStyle={{ flex:1, }}
                        values={tabValues}
                        selectedIndex={params.tabIndex}
                        onTabPress={index =>  { 
                            params.setTabIndex(index)
                        }}
                    />
                </View>
            ),
            headerRight: (
                <View style={sstyle.navigation.navHeaderRight} >
                    <TouchableOpacityEx 
                        style={[sstyle.navigation.navHeaderItem] }
                        onPress={async () => { 
                            navigation.push('QiMenUsefulGodList')
                        }}
                        >
                        <MaterialCommunityIcon
                            name="book"
                            size={24}
                            color={scolor.iconBlurred}
                        />
                    </TouchableOpacityEx> 
				</View>
			),
        }
    }
    constructor(props){
        super(props)
        this.setScreenScrollViewEnabled = this.setScreenScrollViewEnabled.bind(this)
        this.onCustomDateSelected = this.onCustomDateSelected.bind(this)
        this.reload = this.reload.bind(this)
        this.onDateBarPress = this.onDateBarPress.bind(this)
        this.startTimer = this.startTimer.bind(this)
        this.stopTimer = this.stopTimer.bind(this)
        this.startCompass = this.startCompass.bind(this)
        this.stopCompass = this.stopCompass.bind(this)
        this.onDateChange = this.onDateChange.bind(this)
        this.setChart = this.setChart.bind(this)
        this.setTabIndex = this.setTabIndex.bind(this)
        this.calculate = this.calculate.bind(this)
        this.checkFirstTimeQiMen = this.checkFirstTimeQiMen.bind(this)
        this.headingReceived = this.headingReceived.bind(this)
        this.setCompassEnabled = this.setCompassEnabled.bind(this)
        this.onHouseSelected = this.onHouseSelected.bind(this)
        this.props.navigation.setParams({  tabIndex: DEFAULT_TAB_INDEX, setTabIndex: this.setTabIndex})
        this.debouncer = _.debounce(this.headingReceived, COMPASS_DEBOUNCER)
        this.setLastSet = this.setLastSet.bind(this)
        this.removeLastSet = this.removeLastSet.bind(this)
        analytics.track('QiMen.Chart-' + DEFAULT_TAB_INDEX)
    }
    async checkFirstTimeQiMen(){
        // let flag = await AsyncStorage.getItem('@flags.QiMenScreen')
        // if(!flag){
        //     Alert.alert("Compass", "Center Palace")
        //     AsyncStorage.setItem('@flags.QiMenScreen', 'yes') 
        // }
    }
    async setTabIndex(tabIndex){
        const newState = { tabIndex}
        if(tabIndex === HOUSEINDEX) analytics.track('QiMen.House')
        if(tabIndex !== 0 && this.state.displayMode === 3){
            newState.displayMode = 0    
        }
        this.setState(newState, () => {
            this.props.navigation.setParams({ tabIndex })
            this.calculate()
        })
        analytics.track('QiMen.Chart-' + tabIndex, { tabIndex })
    }
    setCompassEnabled(){
        if(this.state.compassEnabled){
            analytics.track('QiMen.CompassOff')
            this.stopCompass()
            this.direction = 'S'
            this.setState({ compassEnabled: false }, () => {
                this.setChart()
            })
        }else{
            this.setState({ compassEnabled: true }, () => {
                analytics.track('QiMen.CompassOn')
                this.startCompass()
                this.setChart()
            })
        }
    }
    async componentDidMount(){
        if(DEFAULT_COMPASS_ENABLED) this.startCompass()

        //Load House Cache
        const houseCache = await AsyncStorage.getItem('@cache.houseInput')
        if(houseCache){ this.setState({ houseInput: JSON.parse(houseCache) }) }

        //Get Prop Initials, if any
        let propTime = this.props.time || this.props.navigation.getParam('time')
        const propReference = this.props.reference || this.props.navigation.getParam('reference')

        //Get Last Set
        let lastSet = await AsyncStorage.getItem('@cache.qiMenLastSet')
        if(lastSet){
            lastSet = JSON.parse(lastSet)
            if(lastSet.time) lastSet.time = DateTime.fromISO(lastSet.time, { setZone: true }) 
        }

        if(propTime){
            if(propReference === 'day'){
                this.props.navigation.setParams({ tabIndex: 1 })
                this.setState({ tabIndex: 1 })
            }
            this.onCustomDateSelected({ time: propTime, hourUnknown: false }, false)
        }else if(lastSet?.time){
            this.onCustomDateSelected(lastSet)
        }else{
            this.calculate()
            this.startTimer()
        }
        // this.checkFirstTimeQiMen()
    }
    async setLastSet(time, hourUnknown = false){
        await AsyncStorage.setItem('@cache.qiMenLastSet', JSON.stringify({ time, hourUnknown}))
    }
    async removeLastSet(){
        await AsyncStorage.removeItem('@cache.qiMenLastSet')
    }
    startCompass(){
        CompassHeading.start(DEGREE_RATE,this.debouncer)
    }
    stopCompass(){
        CompassHeading.stop()
    }
    headingReceived(degree){
        const newDirection = numbers.degreeToDirection(degree)
        if(newDirection !== this.direction){
            this.direction =  newDirection
            this.setChart()
        }
    }
    onDateBarPress(){
        this.stopTimer()
        this.setState({ 
            timerOn: false,
            datePickerVisible: !this.state.datePickerVisible,
        })
    }
    startTimer(){
        this.removeLastSet()
        this.stopTimer()
        this.setState({ timerOn: true , datePickerVisible: false})
        this.timer = setInterval(() => { 
            const time = DateTime.local()
            this.setState({ time }, () => {
                this.calculate()
            })
        },TICK)
    }
    stopTimer(){
        clearInterval(this.timer)
        this.setState({ timerOn: false })
    }
    onDateChange(x, setLast = true){
        const time = DateTime.fromJSDate(x)
        this.setState({ time }, () => {
            if(setLast) this.setLastSet(time)
            this.calculate()
        })
    }
    onCustomDateSelected(x, setLast=true){
        this.stopTimer()
        if(x.time.year > 2050 || x.time.year < 1900){
            Alert.alert('Please plot between 1900-2050.')
            return
        }
        this.setState({ 
            time:x.time ,
            hourUnknown: x.hourUnknown,
        }, () => {
            if(setLast) this.setLastSet(x.time, x.hourUnknown)
            this.calculate()
        })
    }
    onHouseSelected(houseInput, usedCompass=false){
        if(usedCompass && this.compassEnabled) this.startCompass()  
        this.setState({houseInput}, () => { this.calculate() })
    }
    shouldCalculate(){
        const reference = this.tabIndexToReference[this.state.tabIndex]
        if(reference !== 'house'){
            const equalTimeString = Tools.chineseTimeString(this.state.time) === this.state.chart?.bazi?.info?.chineseTimeString 
            if(equalTimeString &&  this.state.chart?.details?.reference === reference){
                return false
            }
        }
        return true
    }
    async calculate(){
        if(this.state.time.year < 1901) return
        const reference = this.tabIndexToReference[this.state.tabIndex]

        //Check if should calculate.
        const proceed = this.shouldCalculate()
        if(!proceed){
            if(reference !==  'house'){
                const bazi = this.state.bazi
                bazi.info.time = this.state.time
                this.setState({ bazi })
            }
            return
        }

        //Get Preferences
        const preferences = await getPreferences() 
        const starPath = preferences.qmdj?.calculations?.starPath
        const method = preferences.qmdj?.calculations?.method
        const shiftLateZiStream = preferences.qmdj?.calculations?.shiftLateZiStream
        const lateZi = preferences.bazi?.calculations?.showDayStartsFrom_23

        //Plot Chart
        const bazi = FourPillars.plot({ time:  this.state.time, lateZi})
        const houseInput = reference === 'house' ? this.state.houseInput : null

        const chart =  QiMap.plot({ bazi , reference, starPath, method, shiftLateZiStream, houseInput, appendDestiny: reference === 'hour', appendMeta: true, appendStyle: true})
        if(!chart){
            this.setState({ palaces: Array(8), chart: null, bazi })
            return
        }
        this.setChart(chart, bazi)
    }
    setChart(chart=this.state.chart, bazi = this.state.bazi){
        //Rearrange order of palaces
        const point = Ordinals.directions[this.direction].postGua
        let order = this.palaceOrder.slice()
        const index = order.indexOf(point)

        if(index !== 0){
            const arr1 = order.slice(index)
            const arr2 = order.slice(0, index)
            order = arr1.concat(arr2)
        }
        this.setState({ palaces: order, chart, bazi})
    }
    reload(){
        this.startTimer()
        this.setState({ refreshing: false, hourUnknown: false })
        if(this.state.tabIndex === 4){
            this.setTabIndex(0)
        }
    }
    setScreenScrollViewEnabled(scrollEnabled){
        this.setState({ scrollEnabled })
    }

    render(){
        const displayModeTabs = ['Primary', 'Secondary', 'Structures']
        if(this.state.chart?.details.reference === 'hour') displayModeTabs.push('Destiny')
        return (
            <Subscribe to={[PreferencesContainer]}>
            {(prefs) => {
                const settings = prefs?.state
                return (
                    <View style={styles.container}>
                        { this.state.tabIndex === HOUSEINDEX ? (
                            <View style={styles.houseInputBar}>
                                <Toucher
                                    style={styles.houseButtonTouch}
                                    onPress={() => {
                                        this.props.navigation.push('HouseSelector', { 
                                            onHouseSelected: this.onHouseSelected,
                                            showDoor: true,
                                            initial: this.state.houseInput,
                                        })
                                    }}
                                >
                                    { (this.state.houseInput?.houseYear && this.state.houseInput?.houseDegree && this.state.houseInput?.doorDegree) ? (
                                        <Text style={styles.houseButton}>
                                         { this.state.houseInput.houseYear } / F: { this.state.houseInput.houseDegree }° { WindWater.degreeToMountain(this.state.houseInput.houseDegree) } / D: { this.state.houseInput.doorDegree}° { WindWater.degreeToMountain(this.state.houseInput.doorDegree).toUpperCase() }</Text>
                                    ) : (
                                        <Text style={styles.houseButton}>Select House ❯</Text>
                                    )}
                                </Toucher>
                            </View> 
                        ) : (
                            <HeadDateBar
                                time={this.state.time}
                                timerOn={this.state.timerOn}
                                reload={this.reload}
                                onDateBarPress={this.onDateBarPress}
                                onCustomDateSelected={this.onCustomDateSelected}
                                hourUnknown={this.state.hourUnknown}
                            />
                        )}

                        { this.state.datePickerVisible && (
                            <DatePicker
                                style={styles.datePicker}
                                mode={'datetime'}
                                date={this.state.time.toJSDate()}
                                onDateChange={this.onDateChange}
                            />
                        )}

                        { (this.state.chart && this.state.palaces[0]) && (
                        <ScrollView 
                            showsVerticalScrollIndicator={false}
                            style={styles.scrollView}
                            scrollEnabled={this.state.scrollEnabled}
                        >
                            <View style={{ padding: 0}}>
                                { this.state.tabIndex !== HOUSEINDEX && (
                                    <HeadDateBarQuick
                                        time={this.state.time}
                                        onCustomDateSelected={this.onCustomDateSelected}
                                        hourUnknown={this.state.hourUnknown} 
                                    />
                                )}


                                { ((this.state.tabIndex === 0)&& this.state.hourUnknown) ? (
                                    <View style={{
                                        height: winWidth,
                                        width: winWidth,
                                        backgroundColor:Color.GREY[100],
                                        justifyContent: 'center',
                                        alignItems: 'center'
                                    }}>
                                        <Text style={{
                                            textAlign:'center',
                                            fontWeight: 'bold'
                                        }}>Hour Unknown</Text>
                                    </View>
                                ) : (
                                    <View>
                                        <SquareQiChart
                                            chart={this.state.chart}
                                            palaces={this.state.palaces}
                                            settings={settings}
                                            compassEnabled={this.state.compassEnabled}
                                            setCompassEnabled={this.setCompassEnabled}
                                            setScreenScrollViewEnabled={this.setScreenScrollViewEnabled}
                                            screenScrollEnabled={this.state.scrollEnabled}
                                            displayMode = { this.state.displayMode }
                                        />
                                        <View style={styles.displayModeBar}>
                                            <SegmentedControlTab
                                                allowFontScaling={false}
                                                tabStyle={sstyle.sectionHeader.tabsLight.segmentTabStyle}
                                                activeTabStyle={sstyle.sectionHeader.tabsLight.segmentTabActive}
                                                tabTextStyle={sstyle.sectionHeader.tabsLight.segmentTabText}
                                                activeTabTextStyle={sstyle.sectionHeader.tabsLight.activeTabTextStyle}
                                                borderRadius={2}
                                                tabsContainerStyle={{width: winWidth-12, alignSelf: 'center' }}
                                                values={displayModeTabs}
                                                selectedIndex={this.state.displayMode }
                                                onTabPress={ displayMode =>  { 
                                                    this.setState({ displayMode })
                                                    analytics.track('QiMen.Mode-' + displayMode, {  displayMode })
                                                }}
                                            />
                                        </View>
                                    </View>
                                )}



                                { this.state.chart?.details.lateZiStreamShifted && (
                                    <Toucher
                                        style={{ marginBottom:4, padding: 12, backgroundColor: Color.GREY[100]}}
                                        onPress={() => {this.props.navigation.push('EditSettings', {defaultTabIndexPreferences: 4 })}}
                                    >
                                        <Text style={{ fontSize: 11, flex:1, textAlign:'right' }}>
                                            Contemporary school late-zi stream shift applied ❯
                                        </Text>
                                    </Toucher>
                                )}


                                { (this.state.tabIndex !== 4 && this.state.bazi) && (
                                    <ScrollChart
                                        scrollEnabled={false}
                                        chart={this.state.bazi}
                                        hideGods={true}
                                    />
                                )}
                                <QiMenDataTable
                                    chart={this.state.chart}
                                    settings={settings}
                                />
                            </View>

                            { this.state.tabIndex === 0 && (
                                <View>
                                    <SectionHeader title={'Destiny'}  
                                     subtitle={`Based on chart of person born on ${this.state.bazi.info.time.toFormat('MMMM, d, yyyy H:mm')}.`}
                                     />
                                    <QiMenDestinySummary
                                        settings={settings}
                                        palace={this.state.chart.palaces[this.state.chart.details.destinyPalace]}
                                    />
                                    <SectionHeader
                                        title={'Victories'}
                                        subtitle={`Based on chart of person born on ${this.state.bazi.info.time.toFormat('MMMM, d, yyyy H:mm')}.`}
                                    />
                                    <ThreeVictorySummary
                                        chart={this.state.chart}
                                    />
                                </View>
                            )}

                            <QiMenLegend/>
                        </ScrollView>
                        )}
                </View>)
            }}
            </Subscribe>
        )
    }
}
QiMenScreen.contextType = AuthContext
export default withNavigation(QiMenScreen)


