class BasicWebView extends React.Component {
    state = {
        uri: null,
        loadingProgress: null,
        navState: null,
    }
    static navigationOptions = ({ navigation }) => {
        const { params={} } = navigation.state 
		return {
            title: params.title || `Browser`,
            headerRight:(
                <TouchableOpacityEx 
                    style={[sstyle.navigation.navHeaderItem] }
                    onPress={async () => { 
                        Linking.openURL(params.uri)
                    }}
                >
                    <MaterialCommunityIcon
                        name="arrow-top-right"
                        size={24}
                        color={scolor.iconBlurred}
                    />
                </TouchableOpacityEx> 
            )
        }
    }
    constructor(props){
        super(props)
        this.handleWebViewNavigationStateChange = this.handleWebViewNavigationStateChange.bind(this)
    }
    componentDidMount(){
        const uri = this.props.uri || this.props.navigation.getParam('uri')
        analytics.track('WebView', { uri })
        this.setState({ uri })
    }
    handleWebViewNavigationStateChange(navState){
        this.setState({ navState})
    }
    render(){
        return (
            <View style={styles.container}>
                <View style={styles.topBar}>
                    <Text numberOfLines={1} ellipsizeMode={'clip'} style={styles.uriBox}>{ this.state.uri }</Text>
                    { this.state.loadingProgress !== 1 && (
                        <ActivityIndicator size="small" color={Color.GREY[700]} style={{ paddingRight: 12 }}/>
                    )}
                </View>
                <WebView
                    ref={ref => (this.webview = ref)}
                    originWhitelist={['*']}
                    source={{ uri: this.state.uri }}
                    onLoadProgress={({ nativeEvent }) => {
                        const loadingProgress = nativeEvent.progress;
                        if(loadingProgress === 1)
                            this.setState({ loadingProgress })
                    }}
                    style={styles.webview}
                    onNavigationStateChange={this.handleWebViewNavigationStateChange}
                />
                <View style={styles.toolbar}>
                    <Toucher
                        onPress={() => {
                            this.webview.goBack()   
                        }}
                        style={styles.touchbutton}
                    >
                        <FontAwesome5
                            name="caret-left"
                            size={28}
                            color={this.state.navState?.canGoBack ? scolor.iconBlurred : Color.GREY[200]}
                        />
                    </Toucher>
                    <Toucher
                        onPress={() => {
                            this.webview.goForward()   
                        }}
                        style={styles.touchbutton}
                    >
                        <FontAwesome5
                            name="caret-right"
                            size={28}
                            color={this.state.navState?.canGoForward ? scolor.iconBlurred : Color.GREY[200]}
                        />
                    </Toucher>
                </View>

            </View>
        );
    }

}

export default BasicWebView;

