const Wrapper = (props) => {
    const { pillar, settings , pillarContainer , pillarContentMode } = props
    const formColorStyle = (pillar, pillarContainer, hideHighlights) => {
        const isAccent = (stem) => {
            if(hideHighlights) return false;
            return stem && pillarContainer.state.accent.stem[stem]
        }
        const colors = Graphics.colors.elements
        const colorStyle = {}
        const accentColor = Color.GREY[900]
        const normalColor = Color.GREY[800]
        colorStyle['heavenStem'] = { 
            bgColor: isAccent(pillar.stem.name) ? colors.accent[pillar.stem.elm.name] : colors.light[pillar.stem.elm.name], 
            color: isAccent(pillar.stem.name) ? accentColor : normalColor 
        }
        if(pillar.branch.stems.storage){
            colorStyle['earthStorage'] = { 
                bgColor: isAccent(pillar.branch.stems.storage.name) ? colors.accent[pillar.branch.stems.storage.elm.name] : colors.light[pillar.branch.stems.storage.elm.name], 
                color: isAccent(pillar.branch.stems.storage.name) ? accentColor : normalColor 
            }
        }
        if(pillar.branch.stems.main){
            colorStyle['earthMain'] = { 
                bgColor: isAccent(pillar.branch.stems.main.name) ? colors.accent[pillar.branch.stems.main.elm.name] : colors.light[pillar.branch.stems.main.elm.name], 
                color: isAccent(pillar.branch.stems.main.name) ? accentColor : normalColor 
            }
        }
        if(pillar.branch.stems.tomb){
            colorStyle['earthTomb'] = { 
                bgColor: isAccent(pillar.branch.stems.tomb.name) ? colors.accent[pillar.branch.stems.tomb.elm.name] : colors.light[pillar.branch.stems.tomb.elm.name], 
                color: isAccent(pillar.branch.stems.tomb.name) ? accentColor : normalColor 
            }
        }
        if(pillar.branch.stems.growth){
            colorStyle['earthGrowth'] =  { 
                bgColor: isAccent(pillar.branch.stems.growth.name) ? colors.accent[pillar.branch.stems.growth.elm.name] : colors.light[pillar.branch.stems.growth.elm.name], 
                color: isAccent(pillar.branch.stems.growth.name) ? accentColor : normalColor 
            }
        }
        return colorStyle
    }
    const colorStyle = formColorStyle(pillar, pillarContainer, props.hideHighlights || settings.pillars.showRootingHighlight=== false )

    const { sectionSID, itemIndex } = props
    //pillar.name
    //Flashes
    const [flashKeys, setFlashKeys] = useState({ stem: 0, branch: 0 })
    const [overlays, setOverlays] = useState({ stem: 0, branch: 0 })
    useEffect(() =>  {
        const sKey = pillarContainer.state.flash.sections[sectionSID]?.[itemIndex]?.stem
        const bKey = pillarContainer.state.flash.sections[sectionSID]?.[itemIndex]?.branch
        const newFlashKeys = { stem: 0, branch: 0 } 
        const newOverlays = { stem: false, branch: false }
        // console.log('keys', sKey, bKey)

        if(sKey && sKey > flashKeys.stem){
            newFlashKeys.stem = sKey 
            newOverlays.stem = true
        }
        if(bKey && bKey > flashKeys.branch){
            newFlashKeys.branch = bKey
            newOverlays.branch = true
        }
        if(newFlashKeys.stem || newFlashKeys.branch){
            setFlashKeys(newFlashKeys)
            setOverlays({ 
                stem: newOverlays.stem ? 1 : 0,
                branch: newOverlays.branch ? 1 : 0
            })
            setTimeout(() => { 
                setOverlays({ stem: 0, branch: 0})
            } , 100)
        } 
        

    })
   
    if(!pillarContentMode)
        return <PillarNominal {...props}  colorStyle={colorStyle} overlays={overlays} pillarContainer={pillarContainer} />
    if(pillarContentMode === 1)
        return <PillarElement { ...props } colorStyle={colorStyle} overlays={overlays} pillarContainer={pillarContainer}  />
    if(pillarContentMode === 2)
        return <PillarAspect { ...props } colorStyle={colorStyle} overlays={overlays} pillarContainer={pillarContainer} />
    if(pillarContentMode === 3)
        return <PillarGods { ...props } colorStyle={colorStyle} overlays={overlays} pillarContainer={pillarContainer} />
    if(pillarContentMode === 4)
        return <PillarPolarity { ...props } colorStyle={colorStyle} overlays={overlays} pillarContainer={pillarContainer} />
}


const ProPillar = (props) => {
    const context = useContext(AuthContext)
    const settings = props.settings
    const boxStyle = props.style  || styles.box
    const pillar = props.pillar
    if(!props.pillar){ return <View style={[boxStyle, styles.placeholder]}/> }

    const isVoidDayBranch = pillar ? props.root.pillars.day.voidStars.indexOf(pillar.branch.name) >= 0 : null
    const isVoidYearBranch = pillar ? props.root.pillars.year.voidStars.indexOf(pillar.branch.name) >= 0 : null

    //FuYin Fan Yin
    let yinMarker = null;
    if(settings.pillars.showFanYinHost || settings.pillars.showFanYinGuest || settings.pillars.showFuYin || settings.pillars.showPillarCombo){
        const pillarKeys = []
        Object.keys(props.root.pillars).forEach(p => {
            const name = props.root.pillars[p]?.name
            if(!name || ['conception','life','minute'].indexOf(name) >= 0) return
            pillarKeys.push(name)
        })
        if(pillar.name &&  props.sectionSID === 'Birth'){
            pillarKeys.splice(pillarKeys.indexOf(pillar?.name), 1)
        }
        const pInt = EightWords.getPillarInteractions(props.root, pillar,pillarKeys)
        if(pInt.length > 0){
            if(settings.pillars.showFanYinHost && pInt[0].relation === 'Fan Yin' && pInt[0].type === 'host') yinMarker = '◆';
            if(settings.pillars.showFanYinGuest && pInt[0].relation === 'Fan Yin' && pInt[0].type === 'guest') yinMarker = '◆';
            if(settings.pillars.showFuYin && pInt[0].relation === 'Fu Yin') yinMarker = '◇';
            if(settings.pillars.showPillarCombo && pInt[0].relation === 'Pillar Combo') yinMarker = '✪';
        }
    }


    //Title
    let theTitle = props.pillarTitle
    const pillarTitleMap = {
        0: null,
        1: null,
        2: 'age',
        3: 'stage',
        4: 'life',
        5: 'psyche',
        6: 'relationship',
        7: 'space'
    }
    if(pillarTitleMap[props.pillarTitleMode] && props.pillar?.name && ['conception', 'life'].indexOf(props.pillar?.name) < 0){
        theTitle = toTitle(EightWords.pillars[props.pillar?.name][pillarTitleMap[props.pillarTitleMode]])
    }


    return (
        <View style={styles.container}>
            <Subscribe to={[PillarContainer]}>
            {(pillarContainer) => {
                return (
                    <DoubleClick
                        style={boxStyle}
                        singleTap={async () => {
                            requestAnimationFrame(() => { if(props?.onPillarPress) props.onPillarPress(props) })
                            analytics.track('Bazi.Pillar.SingleTap', { pillarTitle: props.pillarTitle, sectionSID: props.sectionSID })
                        }}
                        doubleTap={() => {
                            requestAnimationFrame(() => { if(props?.onPillarLongPress) props.onPillarLongPress(props) })
                            analytics.track('Bazi.Pillar.DoubleTap', { pillarTitle: props.pillarTitle, sectionSID: props.sectionSID })
                        }}
                        delay={350}
                    >
                        <Wrapper
                            yinMarker={yinMarker}
                            theTitle={theTitle}
                            isVoidDayBranch={isVoidDayBranch}
                            isVoidYearBranch={isVoidYearBranch}
                            { ...props }
                            pillarContainer={pillarContainer}
                        />
                    </DoubleClick>
                )
            }}
            </Subscribe>
            { props.isSolarTermMarker &&  (
                    <View style={styles.solarTermMarker}>
                        <Text style={styles.solarTermText}>
                            { toTitle(props.isSolarTermMarker.thisTerm.data.english) }  { props.isSolarTermMarker.thisTerm.data.chinese }
                        </Text>
                    </View>
                )}
        </View>
    )
}
export default React.memo(withNavigation(ProPillar),(prevProps, nextProps) => {
    let different = false
    let whatChanged = null
    if(JSON.stringify(prevProps.settings) !== JSON.stringify(nextProps.settings)){
        whatChanged = 'Settings_' 
        different = true
    }else if(prevProps.pillarTitle !== nextProps.pillarTitle){
        whatChanged = 'title_' + nextProps.pillarTitle
        different = true
    }else if(prevProps.isPillarTopFocused !== nextProps.isPillarTopFocused){
        whatChanged = 'top_focus';
        different = true
    }else if(prevProps.isPillarBottomFocused !== nextProps.isPillarBottomFocused){
        whatChanged = 'bottom_focus';
        different = true
    }else if(prevProps.pillar?.stem?.name !== nextProps.pillar?.stem?.name){
        whatChanged = 'stem_' + nextProps.pillar?.stem?.name
        different = true
    }else if(prevProps.pillar?.branch?.name !== nextProps.pillar?.branch?.name){
        whatChanged = 'branch_' + nextProps.pillar?.branch?.name
        different = true
    }else if(prevProps.pillar?.stem?.gdd.abbr !== nextProps.pillar?.stem?.gdd.abbr ){
        whatChanged = 'god_' + nextProps.pillar?.stem?.gdd.abbr
        different = true
    }else if(prevProps.pillarTitleMode !== nextProps.pillarTitleMode){
        whatChanged = 'title_'
        different = true
    }else if(prevProps.pillarContentMode !== nextProps.pillarContentMode){
        whatChanged = 'pillarContentMode'
        different = true
    }
    if(different){
        // console.log('CHANGED PILLAR', nextProps.sectionSID, nextProps.pillarTitle, whatChanged)
    }
    return !different
})



