const PalaceRelationshipBox = ( {pillar, type , root }) => {
    const palaceName = Dict.EightWords.pillars[pillar.name]['$' + type](root.info.gender)
    const boxElement = type === 'stem' ? pillar.stem.elm.name : pillar.branch.stems.main.elm.name
    const dm = root.pillars.day.stem

    const relate = relationships[boxElement][dm.elm.name]
    return (
        <View style={styles.container}>
            <View style={styles.left}>
                <Image 
                    source={CMImages.color.people[palaceName]} 
                    // source={root.pillars[pillar.name][type].$icon.source}
                    style={styles.icon}
                    resizeMode={'contain'}
                />
                <Text style={styles.title}>{ toTitle(palaceName) }</Text>
            </View>
            <View style={{ width: borderWidth, backgroundColor: scolor.separator }}/>
            <View style={styles.mid}>
                <Image
                    source={CMImages.black.cycle[relationshipIcons[relate]]}
                    style={[styles.icon, { tintColor: Color.GREY[500]}]}
                    resizeMode={'contain'}
                />
                <Text style={styles.title}>
                    { toTitle(relate)}
                </Text>
            </View>
            <View style={{ width: borderWidth, backgroundColor: scolor.separator }}/>
            <View style={styles.right}>
                <Image 
                    source={dm.$icon.source} 
                    style={styles.icon}
                    resizeMode={'contain'}
                />
                <Text style={styles.title}>Me</Text>
            </View>
        </View>
    )
}
export default PalaceRelationshipBox;

