
import React, {Fragment, useState, useEffect } from 'react';
import {
	SafeAreaView,
	StyleSheet,
    ScrollView,
    Image, 
	View,
    Text,
    Alert,
	StatusBar,
	TextInput,
    Button,
    Animated,
    Easing,
    TouchableHighlight,
    TouchableOpacity,
    Dimensions
} from 'react-native';
import Color from 'react-native-material-color';
import analytics from '@segment/analytics-react-native'

import * as objects from '../../lib/utils/objects'
import { deCamel , toTitle }from '../../lib/utils/strings'
import MaterialCommunityIcon from 'react-native-vector-icons/MaterialCommunityIcons';
import { sstyle, scolor } from '../../styles/shared'
import { withNavigation } from 'react-navigation';
import withPreventDoubleClick from '../../lib/utils/withPreventDoubleClick'
const Toucher = withPreventDoubleClick(TouchableHighlight)
const TouchableOpacityEx = withPreventDoubleClick(TouchableOpacity)
import * as _ from 'lodash'
import {Subscribe} from 'unstated'
import PreferencesContainer from '../../containers/PreferencesContainer'
import SectionHeader from '../Layout/SectionHeader'
import SegmentedControlTab from "react-native-segmented-control-tab";

const ShenShaDetailList = (props) => {
    const [ selectedTabIndex, setTabIndex ] = useState(0)
    let data = []
    if(selectedTabIndex === 0){
        data = props.pillar.stars;
    }else{
        data = props.pillar.annualStars
    }

    const tabs = ['Symbolics']
    if(props.showAnnualStars) tabs.push('2020 Annual')
    return (
        <View style={styles.container}>
            <View style={sstyle.tabs.light.bar}>
                <SegmentedControlTab
                    allowFontScaling={false}
                    tabStyle={sstyle.tabs.light.tabStyle}
                    activeTabStyle={sstyle.tabs.light.tabActive}
                    tabTextStyle={sstyle.tabs.light.tabText}
                    activeTabTextStyle={sstyle.tabs.light.tabTextActive}
                    borderRadius={0}
                    tabsContainerStyle={sstyle.tabs.light.tabContainer}
                    values={tabs}
                    selectedIndex={ selectedTabIndex  }
                    onTabPress={index =>  { 
                        if(index === 1){
                            analytics.track('Bazi.Pillar.ShenSha.AnnualStars')
                        }else{
                            analytics.track('Bazi.Pillar.ShenSha.Symbolics')
                        }
                        setTabIndex(index) 
                    }}
                />
            </View>
            <View style={styles.list}>
            { data.map(item => {
                if(!item) return <Fragment/>
                if(item.ref && !props.prefs?.state?.bazi?.stars[item.ref][item.name]) return <React.Fragment/>
                return (
                    <Toucher 
                        underlayColor={scolor.touchableHighlightUnderlayColor}
                        onPress={() => {
                            let msg = '\n' + toTitle(item.$dict_noun.join(', '))
                            msg += '\n\n——\n\n' + item.desc
                            Alert.alert(deCamel(item.name), msg)
                        }}
                    >
                        <View style={styles.starRow}>
                            { selectedTabIndex === 0 && (
                            <MaterialCommunityIcon
                                name={item.icon}
                                color={item.rating ? Color.RED['A700'] : selectedColor}
                                size={16}
                                style={styles.starIcon}
                            />
                            )}
                            <Text style={[styles.starText,
                                item.rating && { color: Color.RED['A700']} 
                            ]}>
                                {`${deCamel(item.name)}  ${ item.chinese }`}
                            </Text>
                            <View style={{ flex: 1 }}/>
                                { item.ref?.indexOf('special') >= 0 ? (
                                    <Text style={styles.starSubLabel}>
                                        Special
                                    </Text>
                                ) : (
                                    <Text style={styles.starTextSub}>
                                        { (selectedTabIndex === 0 && item.ref) && deCamel(item.ref).trim().split(' ')[0].substring(0, 1) }
                                    </Text>
                                )}
                        </View>
                    </Toucher>
                )
            })} 
            </View>
        </View>
    )
}

const rowHeight = 44
const selectedColor = Color.GREY[500]
const styles = StyleSheet.create({
    starRow:{
        flexDirection:'row',
        alignItems: 'center',
        justifyContent:'space-between',
        marginLeft:0,
        paddingHorizontal:12,
        height:rowHeight,
        borderBottomWidth:1,
        borderBottomColor: scolor.separator,
    },
    starIcon:{
        marginRight:6,
    },
    starText:{
        marginRight:6,
    },
    starTextSub:{
        fontWeight:'bold',
        fontSize:11,
        color: Color.GREY[300],
    },
    starSubLabel:{
        paddingHorizontal:6,
        paddingVertical:4,
        fontWeight: 'bold',
        fontSize:11,
        backgroundColor: Color.GREY[400],
        color: 'white',
        borderRadius:2,
    },
    container:{
        flex: 1
    },


})

export default React.memo(ShenShaDetailList)
