class LaymanExternalDetail extends React.Component{
    state = {
    }
    stores = {}
    constructor(props){
        super(props)
        this.process = this.process.bind(this)
    }
    componentDidMount(){
        this.process()
        this.stores['heavenEarth'] = new MadContainer()
        this.stores['palaceLabels'] = new MadContainer()
    }
    shouldComponentUpdate(nextProps, nextState){
        const selectedIndex = nextProps.selectedIndex
        if(JSON.stringify(nextState) !== JSON.stringify(this.state)) return true
        if(nextProps.selectedIndex !== this.props.selectedIndex){
            return true
        }else{
            const thisTime = this.props.payload.item[this.props.selectedIndex].time
            const nextTime = nextProps.payload.item[nextProps.selectedIndex].time
            if(
                nextProps.payload.item[selectedIndex].pillar.name === 'hour' && 
                Math.abs(thisTime.diff(nextTime, 'seconds').seconds) > 60
            ) 
                return true
            if(objects.chineseTimeString(thisTime) !== objects.chineseTimeString(nextTime))
                return true
        }
        return false
    }
    componentDidUpdate(prevProps, prevState){
        this.process()
    }
    process(){
        const pillar =  this.props.payload.item[this.props.selectedIndex].pillar
        const time =  this.props.payload.item[this.props.selectedIndex].time
        EightWords.extendAuxData(pillar, time, this.props.root, this.props.pillarKeys)
        
        const titleLine = PillarLines.titleLine(pillar, this.stores)
        const heavenLabel = PillarLines.heavenLabel(pillar, this.stores)
        const  earthLabel = PillarLines.earthLabel(pillar, this.stores)
        const heavenLines = PillarLines.heavenLine(pillar, this.stores, this.props.root)
        const earthLines = PillarLines.earthLine(pillar, this.stores, this.props.root)
        const PalaceRelationshipBox = PillarLines.PalaceRelationshipBox(pillar, this.stores, this.props.root)

        this.setState({ pillar, time, heavenLabel, earthLabel,  titleLine, heavenLines, earthLines , PalaceRelationshipBox })
    }
    render(){
        if(!this.state.pillar) return <Fragment/>

        return (
            <Subscribe to={[PreferencesContainer, PillarContainer]}>
            {(prefs, pillarContainer) => {
            return (
            <View style={styles.container}>
                <View style={styles.titleHolder}>
                    <MadLibs
                        line={this.state.titleLine}
                        containerStyle={{ }}
                        boxTextStyle={styles.titleBoxText}
                        boxSelectStyle={styles.titleBoxSelect}
                    />
                    <View style={{flex: 1 }}/>
                    <Toucher
                        onPress={this.props.switchMode}
                        style={styles.titleSwitcherTouch}
                    >
                        <FontAwesome5
                            name={'window-maximize'}
                            size={22}
                            color={scolor.iconFocused}
                            style={{ transform: [{ rotate: '270deg'}] }}
                        />
                    </Toucher>
                </View>

              <View style={sstyle.separator}/> 
              <MinorCycle
                    {...this.props}
                    pillar={this.state.pillar}
                    time={this.state.time}
                /> 
                <View style={sstyle.separator}/> 
                <YinYangBar pillar={this.state.pillar} time={this.state.time}  />
                <SymbolicScrollBox pillar={this.state.pillar} />
                <View style={sstyle.separator}/> 

                <MadLibs 
                    line={this.state.heavenLabel}
                    containerStyle={styles.palaceTitleContainer}
                    boxTextStyle={styles.palaceTitleText}
                    boxSelectStyle={{
                        ...styles.palaceTitleSelect,
                        borderColor: this.state.pillar.stem.elm._colors.light
                    }}
                    iconStyle={styles.palaceTitleIcon}
                />

          
                <MadLibs
                    // line={ this.state.heavenLines[store.state.index] }
                    line={ this.state.heavenLines.reduce((prev, curr) => prev.concat(curr)) }
                    containerStyle={{padding: padd, paddingTop: padd/2  }}
                    boxViewStyle={styles.longForm.boxViewStyle}
                />
            

                <AffinityBox  
                    root={this.props.root} 
                    god={this.state.pillar.stem.gdd}  
                    containerStyle={{ marginBottom:6, marginHorizontal:padd }}
                    preLabel={{
                        words: ['I\'m around', 'I\'m with', 'I see', 'I meet', 'I find', 'I spot', 'Affinity with'],
                        shuffle: true,
                    }}
                /> 
                {/* <LaymanInteractionStems
                    {...this.props}
                    pillarContainer={pillarContainer}
                    pillar={this.state.pillar}
                    time={this.state.time}
                />  */}

                <HeavenEarthSeparator
                    pillar={this.state.pillar}
                />

                <MadLibs 
                    line={this.state.earthLabel}
                    containerStyle={{...styles.palaceTitleContainer,paddingTop: 0}}
                    boxTextStyle={styles.palaceTitleText}
                    boxSelectStyle={{
                        ...styles.palaceTitleSelect,
                        borderColor: this.state.pillar.branch.stems.main.elm._colors.light
                    }}
                    iconStyle={styles.palaceTitleIcon}
                />
                
             
                <MadLibs
                    line={ this.state.earthLines.reduce((prev, curr) => prev.concat(curr)) }
                    containerStyle={{padding: padd, paddingTop: padd/2  }}
                    boxViewStyle={styles.longForm.boxViewStyle}
                />
             

                <ArchetypeBox
                    pillar={this.state.pillar}
                />


                <View style={{ height: padd }}/>

                {/* <View style={sstyle.separator}/>

                <View style={{ height: padd }}/> */}
               {/* <AffinityBox  root={this.props.root} god={this.state.pillar.branch.stems.main.gdd}  containerStyle={{ marginBottom:6, marginHorizontal:padd }}/>  */}
                {/* <LaymanInteractionBranches
                    {...this.props}
                    pillarContainer={pillarContainer}
                    pillar={this.state.pillar}
                    time={this.state.time}
                />
                */}
                <MajorCycle
                    { ...this.props }
                    pillar={this.state.pillar}
                    time={this.state.time}
                />  
                <View style={sstyle.separator}/>
            </View>)
            }}
            </Subscribe>
        )
    }
}
export default withNavigation(LaymanExternalDetail);


