import { DateTime } from 'luxon'
import analytics from '@segment/analytics-react-native'

const HeadDateBarQuick = (props) => {
    if(!props.time) return <View style={styles.container}/>
    return (
        <View style={styles.quickToggle}>

            <Toucher
                style={styles.quickBtn}
                onPress={() => {
                    const toChange = props.time.hour % 2 ? 2 : 2
                    const data = {
                        time: props.time.minus({ hours: toChange }),
                        gender: 'male',
                        hourUnknown: props.hourUnknown,
                    }
                    props.onCustomDateSelected(data)
                    analytics.track('QiMen.DateQuickToggle-H')
                }}
            >
                <Text style={styles.quickBtnText}>-H</Text>
            </Toucher>

            <Toucher
                style={styles.quickBtn}
                onPress={() => {
                    const data = {
                        time: props.time.minus({days : 1 }),
                        gender: 'male',
                        hourUnknown: props.hourUnknown,
                    }
                    props.onCustomDateSelected(data)
                    analytics.track('QiMen.DateQuickToggle-D')
                }}
            >
                <Text style={styles.quickBtnText}>-D</Text>
            </Toucher>

            <Toucher
                style={styles.quickBtn}
                onPress={() => {
                    const data = {
                        time: props.time.minus({ months: 1 }),
                        gender: 'male',
                        hourUnknown: props.hourUnknown,
                    }
                    props.onCustomDateSelected(data)
                    analytics.track('QiMen.DateQuickToggle-M')
                }}
            >
                <Text style={styles.quickBtnText}>-M</Text>
            </Toucher>

            <Toucher
                style={styles.quickBtn}
                onPress={() => {
                    const data = {
                        time: props.time.minus({ years: 1 }),
                        gender: 'male',
                        hourUnknown: props.hourUnknown,
                    }
                    props.onCustomDateSelected(data)
                    analytics.track('QiMen.DateQuickToggle-Y')
                }}
            >
                <Text style={styles.quickBtnText}>-Y</Text>
            </Toucher>

            <Toucher
                style={[styles.quickBtn, ]}
                onPress={() => {
                    const data = {
                        time: props.time.plus({years: 1 }),
                        gender: 'male',
                        hourUnknown: props.hourUnknown,
                    }
                    props.onCustomDateSelected(data)
                    analytics.track('QiMen.DateQuickToggle-Y')
                }}
            >
                <Text style={styles.quickBtnText}>+Y</Text>
            </Toucher>
       
            <Toucher
                style={styles.quickBtn}
                onPress={() => {
                    const data = {
                        time: props.time.plus({months: 1 }),
                        gender: 'male',
                        hourUnknown: props.hourUnknown,
                    }
                    props.onCustomDateSelected(data)
                    analytics.track('QiMen.DateQuickToggle-M')
                }}
            >
                <Text style={styles.quickBtnText}>+M</Text>
            </Toucher>


            <Toucher
                style={styles.quickBtn}
                onPress={() => {
                    const data = {
                        time: props.time.plus({days: 1 }),
                        gender: 'male',
                        hourUnknown: props.hourUnknown,
                    }
                    props.onCustomDateSelected(data)
                    analytics.track('QiMen.DateQuickToggle-D')
                }}
            >
                <Text style={styles.quickBtnText}>+D</Text>
            </Toucher>



            <Toucher
                style={[styles.quickBtn, { borderRightWidth: 0}]}
                onPress={() => {
                    const toChange = props.time.hour % 2 ? 2 : 2
                    const data = {
                        time: props.time.plus({hours : toChange }),
                        gender: 'male',
                        hourUnknown: props.hourUnknown,
                    }
                    props.onCustomDateSelected(data)
                    analytics.track('QiMen.DateQuickToggle-H')
                }}
            >
                <Text style={styles.quickBtnText}>+H</Text>
            </Toucher>

        </View>
    )
}

export default withNavigation(HeadDateBarQuick)



