class QiMenUsefulGodDetails extends React.Component {
    static navigationOptions = ({ navigation }) => {
        const { params={} } = navigation.state 
		return {
            title: params.title || '',
        }
    }
    constructor(props){
        super(props)
        this.topic = this.props.navigation.getParam('topic')
        this.props.navigation.setParams({ title: strings.deCamel(this.topic )})
        this.data = MysticDoors.usefulGodSymbols[this.topic].map(a => ({
            title: a[0],
            body: a [1],
        }))
        analytics.track('QiMen.Symbols.Details', { topic: this.topic })
    }
    render(){
        return (
            <View style={styles.container}>
                <ScrollView>
                    <DataTable
                        data={this.data}
                    /> 
                    <Disclaimer
                    />
                </ScrollView> 
            </View>
        )
    }
}
export default QiMenUsefulGodDetails;

