import * as queries from '../../queries/queries'

import * as FourPillars from '../../lib/cmtools/Plotters/FourPillars'
import * as Ordinals from '../../lib/cmtools/Ordinals'

const PersonRecord = ({ info, onSubmit, navigation , client }) => {
    const [isDeleted, setIsDeleted] = useState(false)
    // const chartName = info.name + ' (' + info.gender.substring(0,1).toUpperCase() + ')'
    const chartName = info.name
    const chart = FourPillars.plot({ chartName, time: info.time, gender: info.gender, hourUnknown: info.hourUnknown , lateZi: info.lateZi})
    if(isDeleted) return <Fragment/>
    return (
        <Toucher
            underlayColor={scolor.touchableHighlightUnderlayColor}
            style={styles.record}
            onPress={() => {
                if(!info.time.isValid) return 
                onSubmit(chart.info)
                navigation.goBack()
            }}
            onLongPress={() => {
                if(info.link) return 
                Alert.alert(
                    'Delete',
                    null,
                    [
                        { text: 'Cancel', style: 'cancel'}, 
                        { text: 'Confirm', onPress: () => { 
                            client.mutate({
                                mutation: queries.destroyBirthRecord,
                                variables: { id: info.id }
                            }).then(result => { setIsDeleted(true) })
                        }}, 
                    ]
                )
            }}
        >
            <View style={sstyle.layout.row}>
                { info.link && (
                    <Toucher 
                        underlayColor={scolor.touchableHighlightUnderlayColor}
                        style={styles.leftColHolder}
                        onPress={() => {
                            Linking.openURL(info.link)
                        }}
                    >
                        <Image
                            source={{ 
                                uri: info.image || 'https://i.imgur.com/1e9gmt7.png',
                                headers: {
                                    Pragma: 'no-cache',
                                },
                             }}
                            style={{ flex: 1, width: 50 }}
                            resizeMode={"cover"}
                        />
                    </Toucher>
                )}

                <View style={{flex: 1, padding: 15}}>
                    <View style={styles.innerRow}>
                        <Text style={styles.name} adjustsFontSizeToFit={true}>{ info.name }</Text>
                    <View style={{ flex: 1 }}/>
                    <Text style={styles.date}>
                        { info.hourUnknown ? `${info.time.toFormat('MMM d, yyyy')}  —` : info.time.toFormat("MMM d, yyyy, H:mm 'GMT'Z") }
                    </Text>
                    </View>
                    <View style={[styles.innerRow, { marginTop:6}]}>  
                        <Text style={styles.daymaster}>
                        { chart.pillars.day.stem.chinese } { strings.toTitle(chart.pillars.day.stem.name) }  { chart.pillars.day.branch.chinese } { strings.toTitle(chart.pillars.day.branch.name) }
                        </Text>
                    <View style={{ flex: 1 }}/>
                        <Text style={styles.gender}>{ info.gender }</Text>
                    </View>
                    { (info.description?.length > 0) && (
                        <View style={[styles.innerRow, { marginTop:6}]}>  
                        <Text style={styles.description}>{ strings.capFirst(info.description) }</Text>
                    </View>
                    )}
                </View>
            
                
            </View>
        </Toucher>
    )
   
}
export default withApollo(withNavigation(PersonRecord))


