const Box = (props) => {
    const { item } = props
    let [localIndex, setLocalIndex] = useState( (props.shuffle || item.shuffle) ? randomIndex(item.words) : 0)
    if(!item.words) return <Fragment/>
    const subscriptions = item.store ? [item.store] : []
       

    return (
        <Subscribe to={ subscriptions }>
        {(store) => {
            let index = _.isNumber(store?.state?.index) ? store?.state?.index : localIndex

            let icon = null
            if(index > item.words.length - 1) { index = item.words.length - 1 }
            let body = item.words[index] 
            if(body.indexOf('|') >= 0){
                icon = body.split('|')[0]?.split('-')
                body = body.split('|')[1]
            }
            return (
                <Toucher 
                    style={[
                        item.boxViewStyle || props.boxViewStyle || styles.boxView, 
                        item.words.length > 1 && (item.boxSelectStyle || props.boxSelectStyle || styles.boxSelect),
                        item.borderColor && { borderBottomColor: item.borderColor},
                        item.backgroundColor && { backgroundColor: item.backgroundColor },
                    ]}
                    underlayColor={item.words.length === 1 ? 'transparent' : scolor.touchableHighlightUnderlayColor}
                    onPress={() => {
                        let newIndex = index + 1
                        if(newIndex >= item.words.length) newIndex = 0
                        if(item.store){
                            store.setIndex(newIndex)
                        }else{
                            setLocalIndex(newIndex)
                        }
                    }}
                >
                    <View style={
                        item.boxInnerStyle || props.boxInnerStyle || styles.boxInner
                    }>
                        { icon && (
                        <Image
                            source={ CMImages.color[icon[0]][icon[1]]}
                            style={item.iconStyle || props.iconStyle || styles.icon}
                            resizeMode={'contain'}
                        />
                        )}
                        <Text style={[ 
                            styles.boxText, 
                            item.boxTextStyle || props.boxTextStyle || {},
                            item.backgroundColor && { backgroundColor: item.backgroundColor}
                        ]}>
                            { body }
                        </Text>
                    </View>
                </Toucher>
            )
        }}
        </Subscribe>
    )
}


const MadLibs = (props) => {
    if(!props.line || props.line.length === 0) return <Fragment/>
    return (
        <View 
            style={{
                ...styles.container, 
                ...props.containerStyle 
            }}
        >
            { props.line.map((item, index) => {
                return <Box { ...props} item={item} />
            })}
        </View>
    )
}
export default MadLibs


