import styles from '../../styles/SecondaryPillars'
const Pillar = (props) => {
    const { pillar, settings , colorStyle, overlays } = props

    const stemBackgroundColor = pillar.stem.elm._colors.light
    const branchBackgroundColor = pillar.branch.stems.main.elm._colors.light
    return (
        <View >
            { (props.pillarTitle && props.hidePillarTitle !== true ) && (
                <Text 
                    includeFontPadding={false}
                    numberOfLines={1} 
                    ellipsizeMode={'clip'}
                    style={[styles.pillarTitle,
                        props.isPillarTopFocused && styles.pillarTitleFocused,
                        props.pillar.name === 'minute' && { backgroundColor: Color.GREY[900], color: 'white'}
                    ]}
                >
                    { props.theTitle }
                </Text>
            )}

            <View style={[styles.heaven, { backgroundColor: stemBackgroundColor }]}>
                <Animatable.View 
                    style={[styles.flashOverlay,{ opacity:overlays.stem} ]}
                    transition={'opacity'}
                />
                <Image 
                    source={ CMImages.color.stems[pillar.stem.name]}
                    style={styles.icon}
                    resizeMode={'contain'}
                />
                <Text style={styles.lab}>{ toTitle(pillar.stem.natureName) }</Text>
                <Text style={styles.lab2}>{ toTitle(pillar.stem.elementName ) }</Text>
            </View>
            <View style={[styles.earth, { backgroundColor: branchBackgroundColor}]}>
                <Animatable.View 
                    style={[styles.flashOverlay,{ opacity: overlays.branch} ]}
                    transition={'opacity'}
                />
                <Image 
                    source={ CMImages.color.stems[pillar.branch.stems.main.name]}
                    style={styles.icon}
                    resizeMode={'contain'}
                /> 
                <Text style={styles.lab}>{ toTitle(pillar.branch.stems.main.natureName) }</Text>
                <Text style={styles.lab2}>{ toTitle(pillar.branch.stems.main.elementName) }</Text>
            </View>
            <View style={styles.man}>
                { pillar.branch.stems.storage && ( 
                    <Text style={[styles.hstem,
                        { backgroundColor: pillar.branch.stems.storage.elm._colors.light}
                    ]}>❒ { toTitle(pillar.branch.stems.storage.natureName) }</Text>
                )}

                { pillar.branch.stems.tomb && (
                    <Text style={[styles.hstem,
                        { backgroundColor: pillar.branch.stems.tomb.elm._colors.light}
                    ]}>⚰︎ { toTitle(pillar.branch.stems.tomb.natureName) }</Text>
                )}
                { pillar.branch.stems.growth && (
                    <Text style={[styles.hstem,
                        { backgroundColor: pillar.branch.stems.growth.elm._colors.light}
                    ]}>⇡ { toTitle(pillar.branch.stems.growth.natureName) }</Text>
                )} 
            </View>
            { props.isPillarBottomFocused && <View style={styles.pillarBottomFocused}/>}
        </View>
    )
}

export default Pillar

