
import * as Ordinals from '../Ordinals'
import * as WindWater from '../WindWater'
import * as MysticDoors from '../MysticDoors'
import * as EightWords from '../EightWords'
import {capFirst, toTitle, deCamel } from '../Tools'

const titles = {
    'elements': '5 Elements',
    'trigrams': '8 Trigrams',
    'heavenlyStems': '10 Heavenly Stems',
    'earthlyBranches': '12 Earthly Branches',
    'fourPillars': '8 Words — Bazi',
    'windWater': 'Wind Water — Feng Shui',
    'qiMenDunJia': 'Mystic Doors — Qi Men Dun Jia',
    'dateSelection': 'Date Selection — Ze Ri',
    'qiMenDunJia.doors': 'Doors 门',
    'qiMenDunJia.stars': 'Stars 星',
    'qiMenDunJia.spirits': 'Spirits 神', 
    'qiMenDunJia.structures': 'Structures 结构 ',
    'qiMenDunJia.victoryPalaces': 'Victories 胜利',

    'windWater.twentyFourMountains': '24 Mountains',
    'windWater.eightMansions': '8 Mansions',
    'dateSelection.twelveOfficers': '12 Officers',
    'dateSelection.twentyEightConstellations': '28 Constellations',
    'dateSelection.threeKillings': '3 Killings',
}

const pillars = ['year','month','day','hour']
pillars.forEach(t => {
    const map = { year: '年', month:'月' , day:  '日', hour: '时'}
    titles[`fourPillars.${t}`] =  toTitle(t) 
})

Object.keys(EightWords.aspects).forEach(asp => {
    const item = EightWords.aspects[asp]
    titles[`fourPillars.${asp}`] = `${toTitle(asp)}`
})

Object.keys(EightWords.gods).forEach(god => {
    const item = EightWords.gods[god]
    titles[`fourPillars.${god}`] =   `${god.toUpperCase()} - ${toTitle(item.name)} (${toTitle(item.archetype)})`
})

Object.keys(MysticDoors.displayTerminology[0].door).forEach(door => {
    const item = MysticDoors.displayTerminology[0].door[door]
    titles[`qiMenDunJia.doors.${door}`] = `${toTitle(item[0])} ${item[1]}`
})

Object.keys(MysticDoors.displayTerminology[0].star).forEach(star => {
    const item = MysticDoors.displayTerminology[0].star[star]
    titles[`qiMenDunJia.stars.${star}`] = `${toTitle(item[0])} ${item[1]}`
})

Object.keys(MysticDoors.displayTerminology[0].spirit).forEach(spirit => {
    const item = MysticDoors.displayTerminology[0].spirit[spirit]
    titles[`qiMenDunJia.spirits.${spirit}`] = `${toTitle(item[0])} ${item[1]}`
})

Object.keys(Ordinals.guas).forEach(gua => {
    const item = Ordinals.guas[gua]
    titles[`trigrams.${gua}`] = `${item.trigram } ${toTitle(item.english)} ${item.chinese} ${toTitle(item.pinyin)}`
})

Object.keys(Ordinals.elements).forEach(el => {
    const item = Ordinals.elements[el]
    titles[`elements.${el}`] = `${toTitle(el)}`
})

Ordinals.stemOrdering.forEach(stem => {
    const item = Ordinals.stems[stem]
    titles[`heavenlyStems.${stem}`] = `${toTitle(item.natureName)} — ${toTitle(item.elementName)} (${item.chinese} ${toTitle(stem)})`
})

Ordinals.branchOrdering.forEach(branch => {
    const item = Ordinals.branches[branch]
    const natureName = Ordinals.stems[item._hiddenStemsDict.main].natureName
    titles[`earthlyBranches.${branch}`] = `${toTitle(item.animalName)} — ${toTitle(natureName)} (${item.chinese} ${toTitle(branch)})`
})

Object.keys(WindWater.eightMansions).forEach(m => {
    const item = WindWater.eightMansions[m]
    titles[`windWater.eightMansions.${m}`] = `${ item.name } — ${item.chinese} (${item.pinyin})`
})

Object.keys(WindWater.flyingStars).forEach(m => {
    const item = WindWater.flyingStars[m]
    titles[`windWater.flyingStars.${m}`] = `${m}.  ${item.chinese} ${item.pinyin} (${item.nickname})`
})

Object.keys(WindWater.mountains).forEach(m => {
    const item = WindWater.mountains[m]
    titles[`windWater.twentyFourMountains.${m}`] = `${item.sector}  ${item.chinese} ${toTitle(item.pinyin)}`
})



export default titles;