class Almanac extends React.Component {
    static navigationOptions = ({ navigation }) => {
        const { params={} } = navigation.state 
		return {
            headerTitle:(
                <View style={{flex: 1}}>
                    { (params.selectedTabIndex === 0 || params.selectedTabIndex === 1 ) && (
                    <SegmentedControlTab
                        allowFontScaling={false}
                        tabStyle={sstyle.navigation.headerSegmentTabs.segmentTabStyle}
                        activeTabStyle={sstyle.navigation.headerSegmentTabs.segmentTabActive}
                        tabTextStyle={sstyle.navigation.headerSegmentTabs.segmentTabText}
                        borderRadius={2}
                        tabsContainerStyle={{width:220, alignSelf: 'center' }}
                        values={['Almanac', 'Mystic Doors']}
                        selectedIndex={ params.selectedTabIndex }
                        onTabPress={index =>  { 
                            if(params.setTabIndex)
                                params.setTabIndex(index) 
                        }}
                    />
                    )}
                </View>
            ),
            headerRight:(
                <View style={sstyle.navigation.navHeaderRight} >
                    { params.selectedTabIndex === 1 && (

                    <TouchableOpacityEx 
                        style={[sstyle.navigation.navHeaderItem] }
                        onPress={async () => { 
                            navigation.push('EditSettings', {defaultTabIndexPreferences: 6 })
                        }}
                        >
                        <MaterialCommunityIcon
                            name="settings"
                            size={24}
                            color={scolor.iconBlurred}
                        />
                    </TouchableOpacityEx> 
                    )}
                </View>
            )
        }
    }
    state={
        qmPayload: null,
        tongShuPayload: null,
        selectedTabIndex:0,
        refreshing: false,
        tableHead: ['Sun','Mon','Tues','Wed','Thur','Fri','Sat'],
        tableData: [
            ['','','','','','',''],
            ['','','','','','',''],
            ['','','','','','',''],
            ['','','','','','',''],
            ['','','','','','',''],
            ['','','','','','',''],
        ],
        legend: [
            { title: 'M3K', body: 'Monthly Three Killings'},
            { title: 'Y3K', body: 'Yearly Three Killings'},
            { title: '⨂ M', body: 'Day <Clash> Month'},
            { title: '⨂ Y', body: 'Day <Clash> Year'},
            { title: '𝕯-M', body: 'Day <Destruction> Month'},
            { title: 'Blue Circle', body: 'Current Day'},
            { title: 'Yellow Circle', body: 'Start of Month'},
            { title: 'Green Circle', body: 'Middle of Month'},
        ]
    }
    constructor(props){
        super(props)
        this.process = this.process.bind(this)
        this.tongShuCell = this.tongShuCell.bind(this)
        this.qmCell = this.qmCell.bind(this)
        this.getCellNum = this.getCellNum.bind(this)
        this.leftButton = this.leftButton.bind(this)
        this.rightButton = this.rightButton.bind(this)
        this.setTime = this.setTime.bind(this)
        this.onRefresh = this.onRefresh.bind(this)
        this.setTabIndex = this.setTabIndex.bind(this)
        this.props.navigation.setParams({ selectedTabIndex: null,  setTabIndex: this.setTabIndex })
        this.state.root = FourPillars.plot({ time: DateTime.local().set({ day: 1, hour: 12, minute: 30}) }) //root is the first day of the month.
        this.checkFirstTime = this.checkFirstTime.bind(this)
        analytics.track('Almanac.TongShu')
    }
    async componentDidMount(){
        const initTabIndex = await AsyncStorage.getItem('@cache.Almanac.selectedTabIndex') || 0
        if(parseInt(initTabIndex) > 0){
            this.setTabIndex(1)
        }else{
            this.setTabIndex(0)
        }
    }
    async checkFirstTime(){
        // let flag = await AsyncStorage.getItem('@flags.Almanac')
        // if(!flag){
        //     Alert.alert('Victory Day', "See Yellow Label")
        //     AsyncStorage.setItem('@flags.Almanac', 'yes') 
        // }
    }
    async setTabIndex(selectedTabIndex){
        this.props.navigation.setParams({ selectedTabIndex })
        this.setState({ selectedTabIndex, qmPayload: null, tongShuPayload: null }, () => {
            this.process()
        })
        if(selectedTabIndex === 1) analytics.track('Almanac.QiMen')
        await AsyncStorage.setItem('@cache.Almanac.selectedTabIndex', String(selectedTabIndex)) 
    }
    setTime(num){
        const newTime = this.state.root.info.time.plus({ months: num }).set({ day: 1, hour: 12, minute: 30 })
        const newBazi = FourPillars.plot({ time: newTime })
        this.setState({ root: newBazi,qmPayload: null, tongShuPayload: null }, () => {
            this.process()
        })
    }

    async process(){
        const preferences = await getPreferences()
        this.preferences = preferences
        const lateZi = preferences.bazi.calculations.showDayStartsFrom_23
        const starPath = preferences.qmdj.calculations.starPath
        const method = preferences.qmdj.calculations.method
        const shiftLateZiStream = preferences.qmdj.calculations.shiftLateZiStream
        const rootTime = this.state.root.info.time
        const birthday = await myBirthday(this.context)
        const lookups = QMDJAssist.almanacQMDJLookups(preferences)
        if(this.state.selectedTabIndex === 1){
            let qmPayload = {}
            const cKey = QMDJAssist.almanacPayloadCacheKey(birthday, rootTime.year, rootTime.month, lookups)
            const cache = await AsyncStorage.getItem(cKey)
            if(cache ){
                qmPayload = JSON.parse(cache)
                this.setState({ qmPayload })
                return
            }
            for(let d = 1; d < 32; d++){
                const theDay = DateTime.fromObject({ year: rootTime.year, month: rootTime.month, day: d, hour: 23, minute: 59 })
                if(theDay.isValid === false) continue
    
                //3 Victory Day
                this.myBazi = FourPillars.plot({ time: birthday.time, lateZi})
                this.myQMChart = QiMap.plot({ bazi: this.myBazi, reference: 'hour' , starPath, method, shiftLateZiStream , appendMeta: true})
                const victoryDay = QMDJAssist.isThreeVictoryDay(this.myQMChart, FourPillars.plot({ time: theDay.set({ hour: 12 }) }), { starPath, method, shiftLateZiStream })

                const hourCharts = []
                for(let h = 0; h < 24;h++){
                    if(!(h === 0 || h % 2 === 1)) continue
                    const time = theDay.set({ hour: h, minute: 0 })
                    const bazi = FourPillars.plot({ time, lateZi})
                    const chart = QiMap.plot({ bazi, reference: 'hour', starPath, method, shiftLateZiStream , appendMeta: true}) 
                    hourCharts.push(chart)
                }
    
                //Payload for Hours
                let goodHours = []
                hourCharts.forEach(chart => {
                    const palaceNames =  Object.keys(chart.palaces)
                    for(let pal of palaceNames){
                        if(pal === 'center') continue;
                        const structures = chart.palaces[pal].meta.structuresArray
                        const plot = chart.palaces[pal].plot
                        const meta = chart.palaces[pal].meta
                        if(lookups.doors.indexOf(plot.door) < 0) continue;
                        if(lookups.stars.indexOf(plot.star) < 0) continue;
                        if(lookups.spirits.indexOf(plot.spirit) < 0) continue;
                        if(meta.structuresMap.negative.length > lookups.maxNegativeStructures) continue
                        for(let struct of structures){
                            if( lookups.structures.indexOf(struct.name) >= 0){
                                goodHours.push({
                                    structure: struct,
                                    time: chart.bazi.info.time.toISO(),
                                    palace: pal,
                                    numPositiveStructures: meta.structuresMap.positive.length,
                                })
                                break;
                            }
                        }
                    }
                })
                qmPayload[String(d)] = { goodHours, victoryDay }
            }
            try{
                await AsyncStorage.setItem(cKey, JSON.stringify(qmPayload))
            }catch(err){
            }
            this.setState({ qmPayload })
            this.checkFirstTime()
        }else{
            const tongShuPayload = {}
            for(let d = 1; d < 32; d++){
                const theDay = DateTime.fromObject({ year: rootTime.year, month: rootTime.month, day: d, hour: 23 , minute: 59 })
                if(theDay.isValid === false) continue

                //Day Selection Info
                const todayBazi = FourPillars.plot({ time: theDay , hourUnknown: true, lateZi: false})
                const stem = todayBazi.pillars.day.stem.name
                const branch = todayBazi.pillars.day.branch.name
                const info = Timing.getAllDayInfo({ bazi: todayBazi , stem, branch})

                //Today Solar Term
                let todayStartTerm = null
                const solarTermBegins = todayBazi.info.solarTerm.thisTerm.begins.toFormat('yyyy-MM-d')

                if(todayBazi.info.time.toFormat('yyyy-MM-d') === solarTermBegins){ todayStartTerm = todayBazi.info.solarTerm.thisTerm.data.num }
                tongShuPayload[String(d)] = { todayBazi, info, todayStartTerm, }
            }
            this.setState({ tongShuPayload })
        }
    }

    getCellNum( rowIndex, cellIndex ){
        const wd = this.state.root.info.time.weekday
        const cellNum = rowIndex * 7 + cellIndex - wd + 1
        return cellNum
    }
    qmCell(rowIndex, cellIndex, prefs, lookups){
        const cellNum = this.getCellNum(rowIndex, cellIndex)
        const thisDate = DateTime.fromObject({ year: this.state.root.info.time.year, month: this.state.root.info.time.month, day: cellNum, hour: 23, minute: 59 })
        if(cellNum <= 0 || thisDate.isValid === false) return <Fragment/>
        const res = this.state.qmPayload[String(cellNum)]
        const isToday = DateTime.local().toFormat('yyyy-MM-dd') === thisDate.toFormat('yyyy-MM-dd')
        if(!res) return <Fragment/>
        return (
            <Toucher 
                style={styles.qiMenCell}
                onPress={() => {
                    if(!res.victoryDay && res.goodHours.length === 0) return
                    this.props.navigation.push('QiMenDayList', {  day: thisDate, ...res })
                }}
            >
                <View>
                    <Text style={[styles.cellNum,
                        isToday && styles.isToday 
                    ]}>
                        { cellNum }
                    </Text>
                    { res.victoryDay && (
                        <Text 
                            numberOfLines={1} 
                            ellipsizeMode={'clip'}
                            style={[styles.labelColor, { backgroundColor: Color.YELLOW[600]}]}
                        >
                            ▼ {toTitle(res.victoryDay.name)}
                        </Text>
                    )}
                    { res.goodHours.map(item => {
                        const labelText = MysticDoors.structures[item.structure.name].abbr || toTitle( MysticDoors.structures[item.structure.name].name)
                        const backgroundColor = MysticDoors.structures[item.structure.name].color || Color.RED[400]
                        return (
                            <Text 
                                style={[
                                    styles.labelColor,
                                    { backgroundColor}
                                ]} 
                                numberOfLines={1} 
                                ellipsizeMode={'clip'}
                            >
                                { item.numPositiveStructures >= 5 && `✭ `}
                                { labelText }

                            </Text>
                        )
                    })}
                </View>
            </Toucher>
        )
    }
    tongShuCell(rowIndex, cellIndex){
        const cellNum = this.getCellNum(rowIndex, cellIndex)
        const thisDate = DateTime.fromObject({ year: this.state.root.info.time.year, month: this.state.root.info.time.month, day: cellNum, hour: 23, minute: 59 })
        if(cellNum <= 0 || thisDate.isValid === false) return <Fragment/>
        const res = this.state.tongShuPayload[String(cellNum)]
        if(!res) return <Fragment/>
        const { info,  todayBazi, todayStartTerm } = res
        const stem = todayBazi.pillars.day.stem
        const branch = todayBazi.pillars.day.branch
      
        const settings = this.preferences.bazi.dayInfo
        const isToday = DateTime.local().toFormat('yyyy-MM-dd') === thisDate.toFormat('yyyy-MM-dd')
        return (
            <Toucher 
                style={[styles.tongShuCell]}
                onPress={() => {
                    const rightNow = DateTime.local()
                    const theTime = todayBazi.info.time.set({ hour: rightNow.hour, minute: rightNow.minute })

                    this.props.navigation.push('FlyingStars', { time:  theTime })
                }}
            >
                <View>
                    <Text style={[styles.cellNum,
                        isToday && styles.isToday,
                        (todayStartTerm !== null && todayStartTerm % 2 == 1) && styles.solarTerm1,
                        (todayStartTerm !== null && todayStartTerm % 2 == 0) && styles.solarTerm2
                    ]}>
                        { cellNum }
                    </Text>
                    <View style={styles.content}>
                        <Text style={styles.pillar} numberOfLines={1} ellipsizeMode="clip">
                            { stem.chinese } { toTitle(stem.name) }
                        </Text>

                        <Text style={styles.pillar} numberOfLines={1} ellipsizeMode="clip">
                            { branch.chinese } { toTitle(branch.name) }
                        </Text>

                        <Text style={[styles.label, styles.primary]} numberOfLines={1} ellipsizeMode="clip">{ toTitle(info.officer) }</Text>
                        <Text style={[styles.label, styles.primary]} numberOfLines={1} ellipsizeMode="clip">{ toTitle(info.constellation) }</Text>
                        <Text style={[styles.label, styles.primary]} numberOfLines={1} ellipsizeMode="clip">{ toTitle(info.yellowBlack) }</Text>


                
                        <Text style={[styles.label, styles.donggong]} numberOfLines={1} ellipsizeMode="clip">
                            { info.dongGongNum}

                        </Text>

                        { info.m3k && (
                            <Text style={[styles.label, styles.rightAlign]} numberOfLines={1} ellipsizeMode="clip">M3K</Text>
                        )}
                        { info.y3k && (
                            <Text style={[styles.label, styles.rightAlign]}  numberOfLines={1} ellipsizeMode="clip">Y3K</Text>
                        )}
                        { info.bigDisaster && (
                            <Text style={styles.label} numberOfLines={1} ellipsizeMode="clip">Disaster</Text>
                        )}
                        { info.yearBreaker && (
                            <Text style={[styles.label, styles.breaker, styles.rightAlign]} numberOfLines={1} ellipsizeMode="clip">⨂ Y</Text>
                        )}
                        { info.monthBreaker && (
                            <Text style={[styles.label, styles.breaker, styles.rightAlign]} numberOfLines={1} ellipsizeMode="clip">⨂ M</Text>
                        )}
                        { info.monthDestructor && (
                            <Text style={[styles.label, styles.breaker, styles.rightAlign]} numberOfLines={1} ellipsizeMode="clip">𝕯-M</Text>
                        )}
                    </View>
                </View>
            </Toucher>
        )
    }

    leftButton(){
        return (
            <TouchableOpacityEx 
                style={sstyle.sectionHeader.sectionHeaderTouchLeft}
                onPress={() => this.setTime(-1)}
            >
                <MaterialCommunityIcon
                    name={'chevron-left'}
                    size={22}
                    color={'white'}
                />
            </TouchableOpacityEx> 
        )
    }
    rightButton(){
        return (
            <TouchableOpacityEx 
                style={sstyle.sectionHeader.sectionHeaderTouchRight}
                onPress={() => this.setTime(1)}
            >
                <MaterialCommunityIcon
                    name={'chevron-right'}
                    size={22}
                    color={'white'}
                />
            </TouchableOpacityEx>
        )
    }
    onRefresh(){
        const newTime = DateTime.local().set({ day: 1, hour: 12, minute: 30 })
        const newBazi = FourPillars.plot({ time: newTime })
        this.setState({ root: newBazi, qmPayload: null, tongShuPayload: null  }, () => {
            this.process()
        })
    }
    render(){

        const midRoot = this.state.root.info.time.set({ day: 15 })
        const midRootBazi = FourPillars.plot({ time: midRoot })
        const rp = midRootBazi.pillars
        const mo = midRoot.toFormat('MMMM')
        const year  = midRoot.toFormat('yyyy')
        const ms = rp.month.stem.chinese
        const mb = rp.month.branch.chinese
        const ys = rp.year.stem.chinese
        const yb = rp.year.branch.chinese
        const sectionTitle = `${year} ${ys} ${yb} – ${mo} ${ms} ${mb}`

        return (
            <View style={styles.container}>
                <SectionHeader 
                    title={sectionTitle}
                    rightItem={this.rightButton()}
                    leftItem={this.leftButton()}
                />
                <Table borderStyle={styles.table}>
                    <Row data={this.state.tableHead} style={styles.head} textStyle={styles.headText} />
                </Table>
                { ((this.state.selectedTabIndex === 1 && this.state.qmPayload) || (this.state.selectedTabIndex === 0 && this.state.tongShuPayload)) ? (
                    <ScrollView 
                        showsVerticalScrollIndicator={false}
                        style={styles.scrollView}
                        refreshControl={
                            <RefreshControl
                                refreshing={this.state.refreshing}
                                onRefresh={this.onRefresh}
                            />
                        }
                    >
                        <Table borderStyle={styles.table}>
                        { this.state.tableData.map((rowData, index) => (
                            <TableWrapper key={index} style={styles.row} >
                            { rowData.map((cellData, cellIndex) => {
                                if(this.state.selectedTabIndex === 1 )
                                    return <Cell key={cellIndex} data={this.qmCell(index, cellIndex)}/>
                                else
                                    return <Cell key={cellIndex} data={this.tongShuCell(index, cellIndex)}/>
                            })}
                            </TableWrapper>
                        ))}
                        </Table>
                        { this.state.selectedTabIndex === 0 && (
                            <DataTable
                                data={this.state.legend}
                            />
                        )}
                    </ScrollView>
                ) : (
                    <View style={{ flex: 1, alignItems: 'center' , paddingTop:24,}}>
                        <ActivityIndicator size={'large'} color={Color.GREY[500]}/>
                    </View>
                )}
            
            </View>
        )
    }
}
Almanac.contextType = AuthContext
export default Almanac;




