import * as MysticDoors from '../MysticDoors'
import * as SolarCal from '../SolarCal'
import _ from 'lodash'
import { toTitle } from '../Tools'

export const structures = () => {
    const result = {}
    const structures = MysticDoors.structures
    Object.keys(structures).forEach(key => {
        const item = structures[key]
        let auspicious
        let symbol
        if(item.rating > 0) {
            auspicious = 'Auspicious'
            symbol = '✭'
        }else if(item.rating < 0) {
            auspicious = 'Inauspicious'
            symbol = '⨂'
        }
        const payload = {
            name: item.name,
            chinese: item.chinese,
            description: item.note,
            auspicious,
        }
        const kkk = symbol + '  ' + item.name + ' ' + item.chinese
        result[kkk] = payload
    })
    return result;
}

export const doors = () => {
    const doorStrengthScoreMap = { 8: 'peak', 7: 'strong', 6: 'weak', 5: 'trap', 4: 'dead' }
    const doors = _.cloneDeep(MysticDoors.doors)
    Object.keys(doors).forEach(door => {
        const newStrength =  {}
        const oldStrength = doors[door].strength
        Object.keys(oldStrength).forEach(num => {
            const term = SolarCal.solarTerms[num]
            const label = `${toTitle(term.english)}`
            const body = doorStrengthScoreMap[oldStrength[num]] + ' (' + oldStrength[num]  + ')'
            newStrength[label] = body
        })
        doors[door].strength = newStrength
        doors[door].strength['$body'] = 'According to the QMDJ Compendium by Joey Yap (pg. 410), the strength of a door is based on the Solar Term of the plotted chart time. Furthermore, the strength is shifted by (1) month.  For eg. Rest Door, of Water element, does not reach its peak at the point of Winter Solstice. According to Joey Yap, it reaches its peak in Minor Cold, which is 1 month past Winter Solstice. For consistency, we have assigned numeric values to the terms chosen by Joey Yap.\n\nProsperous: 8\nAbandoned: 7\nWeak: 6\nTrap: 5\nDeath: 4\nAbsent: 5\nConceived: 6\nStrong: 7\n\nWe have consolidated the terminology such that it reflects the numeric scale. Strong is synonymous with Abandoned.  Trap is synonymous with Absent.  Weak is synonymous with Conceived. \n\nProsperous — Peak\nAbandoned — Strong\nWeak — Weak\nTrap — Trap\nDeath — Death\nAbsent — Trap\nConceived — Weak\nStrong — Strong\n'
    })
    return doors
}

export const stars = () => {
    const stars = _.cloneDeep(MysticDoors.stars)
    Object.keys(stars).forEach(name=> {
        stars[name].strength['$body'] = 'The strength of a star is based on the element of the palace in which it resides.  According to the QMDJ Compendium by Joey Yap (pg. 548), a star does [not] reach its peak when it lands in a palace of identical element.  Rather, a star reaches its peak when it lands in a palace of the element that it produces.\n\nFor example: Heavenly Assistant, a star of Wood, does not reach peak in the Wood palaces of Zhen and Xun.  Rather, it reaches peak in Li, a Fire palace, because (according to Joey Yap), the effects of the star is more noticeable.\n\nThe current strength calculation is based on this approach. A linear model that aligns directly with the 12 Stages of Growth may be added as a future option.'
    })
    return stars
}