
import React, {Fragment, useState, useEffect } from 'react';
import {
	SafeAreaView,
	StyleSheet,
    ScrollView,
    Image, 
	View,
    Text,
    Alert,
	StatusBar,
	TextInput,
    Button,
    Animated,
    Easing,
    TouchableHighlight,
    TouchableOpacity,
    Dimensions
} from 'react-native';
import Color from 'react-native-material-color';

import * as objects from '../../lib/utils/objects'
import { deCamel , toTitle }from '../../lib/utils/strings'
import MaterialCommunityIcon from 'react-native-vector-icons/MaterialCommunityIcons';
import { sstyle, scolor } from '../../styles/shared'
import { withNavigation } from 'react-navigation';
import withPreventDoubleClick from '../../lib/utils/withPreventDoubleClick'
const Toucher = withPreventDoubleClick(TouchableHighlight)
const TouchableOpacityEx = withPreventDoubleClick(TouchableOpacity)
import * as _ from 'lodash'
import {Subscribe} from 'unstated'
import PreferencesContainer from '../../containers/PreferencesContainer'
import SegmentedControlTab from "react-native-segmented-control-tab";
import AsyncStorage from '@react-native-community/async-storage';
import analytics from '@segment/analytics-react-native'
import * as Ordinals from '../../lib/cmtools/Ordinals'
import * as Graphics from '../../lib/cmtools/Graphics'
import * as EightWords from '../../lib/cmtools/EightWords'
import * as CMImages from '../../lib/cmtools/Assets'




class InteractionDetailBox extends React.Component{
    state={
        selectedTabIndex: null,
        tabVals: ['1', '2','3'],
        showRelationType: false,
    }
    constructor(props){
        super(props)
    }
    async componentDidMount(){
        const defaultTab = await AsyncStorage.getItem('@cache.InteractionDetailBox.tab') || 2
        this.setState({ selectedTabIndex: parseInt(defaultTab) })
    }
    render(){
        const { settingsDetails,pillarContainer, pillar} = this.props
        const currentSectionSID =  this.props.payload.section.sid
        const theStem = pillar.stem
        const theBranch = pillar.branch

        const elementToAspect = this.props.root.meta.maps.elementToAspect
        const stemToGod = this.props.root.meta.maps.stemToGod

        if(pillar.stem.interactions.length === 0 && pillar.branch.interactions.length === 0) return <Fragment/>

        const blankHeight = (pillar.stem.interactions.length +  pillar.branch.interactions.length) * rowHeight
        if(this.state.selectedTabIndex === null) return <View style={{ height: blankHeight }} />
        const STI = this.state.selectedTabIndex
        const standardIconSize = 15

        return (
            <View style={styles.container}>
                <View style={sstyle.tabs.light.bar}>
                    <SegmentedControlTab
                        allowFontScaling={false}
                        tabStyle={sstyle.tabs.light.tabStyle}
                        activeTabStyle={sstyle.tabs.light.tabActive}
                        tabTextStyle={[sstyle.tabs.light.tabText, { fontSize: 12,}]}
                        activeTabTextStyle={[sstyle.tabs.light.tabTextActive,]}
                        borderRadius={0}
                        tabsContainerStyle={sstyle.tabs.light.tabContainer}
                        values={this.state.tabVals}
                        selectedIndex={ this.state.selectedTabIndex  }
                        onTabPress={async selectedTabIndex =>  { 
                            this.setState({ selectedTabIndex })
                            await AsyncStorage.setItem('@cache.InteractionDetailBox.tab', String(selectedTabIndex))
                            analytics.track('Bazi.Pillar.Interactions.toggleLens-' + selectedTabIndex)
                        }}
                    />
                </View>

                                    
                { (pillar.interactions.length > 0 && (settingsDetails.showFuYin || settingsDetails.showFanYinGuest || settingsDetails.showFanYinHost || settingsDetails.showPillarCombo)) && (
                    <View style={styles.interactionHolder}>
                        { pillar.interactions.map(item => {
                            if(item.relation === 'Fu Yin' && !settingsDetails.showFuYin) return <Fragment/>
                            if(item.relation === 'Fan Yin' && item.type === 'host' && !settingsDetails.showFanYinHost) return <Fragment/>
                            if(item.relation === 'Fan Yin' && item.type === 'guest' && !settingsDetails.showFanYinGuest) return <Fragment/>
                            if(item.relation === 'Pillar Combo' && !settingsDetails.showPillarCombo) return <Fragment/>
                            let symbol
                            let pillarRel 
                            if(item.relation === 'Fu Yin'){
                                pillarRel = 'Pillar Mirror'
                                symbol = '◇' 
                            }
                            if(item.relation === 'Fan Yin') {
                                pillarRel = `Pillar Clash`
                                symbol = '◆' 
                            }
                            if(item.relation === 'Pillar Combo') {
                                pillarRel = 'Pillar Combo'
                                symbol = '✪' 
                            }
                            const desiredOrder = ['H','D', 'M', 'Y', 'L']
                            const pillarArr =  item.affects.map(affect => toTitle(affect.pillar.substring(0, 1)))
                            pillarArr.sort((a, b) => { return desiredOrder.indexOf(a) - desiredOrder.indexOf(b) })
                            const pillarAbbr = pillarArr.join(' ')
                            return (
                                <Toucher
                                    onPress={() => {
                                        const items = []
                                        item.affects.forEach(affect => {
                                            items.push({ section: 'Birth', index: pillarContainer.birthPillarNameMap[affect.pillar], palace: 'stem'})
                                            items.push({ section: 'Birth', index: pillarContainer.birthPillarNameMap[affect.pillar], palace: 'branch'})
                                        })
                                        items.push({ section: currentSectionSID, index: this.props.selectedIndex, palace: 'stem', })
                                        items.push({ section: currentSectionSID, index: this.props.selectedIndex, palace: 'branch', })
                                        pillarContainer.updateFlash(items)

                                        analytics.track('Bazi.Pillar.Interactions.FuYinFanYin')
                                        setTimeout(() => { pillarContainer.resetFlash() }, 2000)
                                    }}
                                >
                                    <View style={styles.interactionRow}>
                                        <View style={{ flex: 3, flexDirection: 'row', alignItems: 'center'}}>
                                            <View style={[styles.letterLabel, styles.letterLabelPillar]}>
                                                <Text style={styles.letterLabelText}>
                                                    { symbol }
                                                </Text>
                                            </View>
                                            <Text >
                                                { pillarRel }
                                            </Text>
                                        </View>
                                        <View style={styles.flashTouch}>
                                            <Text style={styles.flashTouchText}>
                                            {pillarAbbr}
                                            </Text>
                                        </View>
                                    </View>
                                </Toucher>
                            )
                        })}
                    </View>
                )}

                { (pillar.stem.interactions.length > 0 ) && (
                    <View style={[styles.interactionHolder]}>
                        { pillar.stem.interactions.map(item  => {
                            if(item.relation === 'combo' && !settingsDetails.showStemCombos) return <Fragment/>
                            if(item.relation === 'conflict' && !settingsDetails.showStemConflicts) return <Fragment/>
                            const stemPillarAbbr = item.affects.map(affect => toTitle(affect.pillar.substring(0, 1))).join(' ')
                            return (
                                <View style={styles.interactionRow}>
                                    <View style={styles.mainContent}>
                                        <Toucher
                                            style={{ flex: 1}}
                                            onPress={() => {
                                                const path = STI === 1 ? `fourPillars.${stemToGod[theStem.name]}` : `heavenlyStems.${theStem.name}`
                                                this.props.navigation.push('Library', { path, hideClose: true })
                                                analytics.track('Bazi.Pillar.Interactions.Stem')
                                            }}
                                        >
                                            <View style={styles.leftCol}>
                                                <View style={[styles.sideElementBar,
                                                    { backgroundColor: pillar.stem.elm._colors.light} 
                                                ]}/>
                                                { STI === 0 && (
                                                    <View>
                                                        <Text style={styles.textLabel}>
                                                            { theStem.chinese }
                                                        </Text>
                                                        <Text style={styles.textLabel2}>
                                                            { toTitle(theStem.name)}
                                                        </Text>
                                                    </View>
                                                )}
                                                { STI === 1 && (
                                                    <View>
                                                        <Text style={styles.textLabel}>{ stemToGod[theStem.name].toUpperCase() }</Text>
                                                    </View>
                                                )}
                                                { STI === 2 && ( <Image source={CMImages.color.stems[theStem.name]} resizeMode="contain" style={styles.pic} />)}
                    
                                            </View>
                                        </Toucher>
                                        <Toucher
                                            style={styles.middleColTouch}
                                            onPress={() => {
                                                this.setState({ showRelationType: !this.state.showRelationType })
                                                analytics.track('Bazi.Pillar.Interactions.Stem.Relation')
                                            }}
                                        >
                                            <View style={styles.middleCol}>
                                                <MaterialCommunityIcon
                                                    name={item.relation === 'combo' ? 'circle' : 'mixer'}
                                                    size={standardIconSize}
                                                    color={item.relation === 'combo' ? Graphics.colors.elements.dark[item.relationElementResult] : Color.GREY[300]}
                                                />
                                                { this.state.showRelationType && (
                                                    <Text numberOfLines={1} ellipsizeMode={'clip'}  style={styles.textLabel2}>{ item.relation === 'conflict' ? 'Control' : toTitle(item.relation) }
                                                      { item.relationElementResult && ` [${ toTitle(elementToAspect[item.relationElementResult]).substring(0, 1) }]`}
                                                    </Text>
                                                )}
                                            </View>
                                        </Toucher>
                                        <Toucher 
                                            style={{ flex: 1 }} 
                                            onPress={() => {
                                                const path = STI === 1 ? `fourPillars.${stemToGod[item.affects[0].stem]}` : `heavenlyStems.${item.affects[0].stem}`
                                                this.props.navigation.push('Library', { path, hideClose: true })
                                                analytics.track('Bazi.Pillar.Interactions.Stem')
                                            }}
                                        >
                                            <View style={styles.rightCol}>
                                            { STI === 0 && (
                                            item.affects.map(affect => (
                                                    <View style={{justifyContent: 'center'}}>
                                                        <Text style={styles.textLabel}>
                                                            { Ordinals.stems[affect.stem].chinese }
                                                        </Text>
                                                        <Text style={styles.textLabel2}>
                                                            { toTitle(affect.stem)}
                                                        </Text>
                                                    </View>
                                            )))}
                                            { STI === 1 && ( item.affects.map(affect => (
                                                    <Text style={styles.textLabel}>
                                                        { stemToGod[affect.stem].toUpperCase() }
                                                    </Text>
                                            )))}
                                            { STI === 2 && ( item.affects.map(affect => ( 
                                                    <Image source={CMImages.color.stems[affect.stem]} resizeMode="contain" style={styles.pic} /> 
                                            )))}
 
                                            </View>
                                        </Toucher>
                                        <Toucher
                                            onPress={() => {
                                                const items = []
                                                item.affects.forEach(affect => {
                                                    items.push({ section: 'Birth',index: pillarContainer.birthPillarNameMap[affect.pillar], palace: 'stem'})
                                                })
                                                items.push({ section: currentSectionSID, index: this.props.selectedIndex , palace: 'stem', })
                                                pillarContainer.updateFlash(items)
                                                analytics.track('Bazi.Pillar.Interactions.Stem.Flash')
                                                setTimeout(() => { pillarContainer.resetFlash() }, 2000)
                                            }}
                                            style={styles.flashTouch}
                                        >
                                            <Text style={styles.flashTouchText}>{ stemPillarAbbr }</Text>
                                        </Toucher>
                                    </View>
                                </View>
                            )
                        })}
                    </View>
                    )}

                    <View style={{ height: 1.5, backgroundColor: scolor.separator}}/>
                    { (pillar.branch.interactions.length > 0 ) && (
                    <View style={styles.interactionHolder}>
                        { pillar.branch.interactions.map(item  => {
                            if(item.relation === 'direction' && !settingsDetails.showBranchDirectionCombinations) return <Fragment/>
                            if(item.relation === 'harmony' && !settingsDetails.showBranchHarmonyCombinations) return <Fragment/>
                            if(item.relation === 'penalty' && !settingsDetails.showBranchThreePenalties) return <Fragment/>
                            if(item.relation === 'clash' && !settingsDetails.showBranchClashes) return <Fragment/>
                            if(item.relation === '⅔ harmony' && !settingsDetails.showBranchHalfHarmonyCombinations) return <Fragment/>
                            if(item.relation === '6 combo' && !settingsDetails.showBranchSixCombinations) return <Fragment/>
                            if(item.relation === 'self penalty' && !settingsDetails.showBranchSelfPenalities) return <Fragment/>
                            if(item.relation === 'harm' && !settingsDetails.showBranchHarms) return <Fragment/>
                            if(item.relation === 'destruction' && !settingsDetails.showBranchDestructions) return <Fragment/>
                            if(item.relation === 'hidden combo' && !settingsDetails.showBranchHiddenCombinations) return <Fragment/>

                            const desiredOrder = ['H','D', 'M', 'Y', 'L']
                            const pillarArr =  item.affects.map(affect => toTitle(affect.pillar.substring(0, 1)))
                            pillarArr.sort((a, b) => { return desiredOrder.indexOf(a) - desiredOrder.indexOf(b) })
                            const branchPillarAbbr = pillarArr.join(' ')


                            const iconMap = {
                                'direction': ['square', Graphics.colors.elements.dark[item.relationElementResult ], standardIconSize],
                                'harmony': ['triangle', Graphics.colors.elements.dark[item.relationElementResult ], standardIconSize],
                                '⅔ harmony': ['triangle-outline', Graphics.colors.elements.dark[item.relationElementResult ], standardIconSize],
                                '6 combo': ['circle', Graphics.colors.elements.dark[item.relationElementResult ], standardIconSize],
                                'hidden combo': ['circle-outline', Graphics.colors.elements.dark[item.relationElementResult ], 0],
                                'clash': ['mixer', Color.GREY[800], standardIconSize],
                                'harm': ['format-text-wrapping-clip', Color.GREY[800], standardIconSize],
                                'destruction': ['decagram', Color.GREY[800], standardIconSize],
                                'self penalty': ['alpha-p-box', Color.GREY[800], 19],
                                'uncivilized penalty': ['alpha-p-box', Color.GREY[800], 19],
                                'ungrateful penalty': ['hazard-lights', Color.GREY[800], standardIconSize],
                                'bullying penalty': ['hazard-lights', Color.GREY[800], standardIconSize]
                            }
                            return (
                                <View style={[styles.interactionRow]}>
                                    <View style={styles.mainContent}>
                                        <Toucher
                                            style={{ flex: 1}}
                                            onPress={() => {
                                                const path = STI === 1 ? `fourPillars.${stemToGod[pillar.branch.stems.main.name]}` : `earthlyBranches.${theBranch.name}`
                                                this.props.navigation.push('Library', { path, hideClose: true })
                                                analytics.track('Bazi.Pillar.Interactions.Branch')
                                            }}
                                        >
                                            <View style={styles.leftCol}>
                                                <View style={[styles.sideElementBar,
                                                    { backgroundColor: pillar.branch.stems.main.elm._colors.light } 
                                                ]}/>
                                                { STI === 0 && (
                                                    <View>
                                                        <Text style={styles.textLabel}>
                                                            { theBranch.chinese }
                                                        </Text>
                                                        <Text style={styles.textLabel2}>
                                                            { toTitle(theBranch.name)}
                                                        </Text>
                                                    </View>
                                                )}
                                                { STI === 1 && (
                                                    <View>
                                                        <Text style={styles.textLabel}>{ stemToGod[pillar.branch.stems.main.name].toUpperCase() }</Text>
                                                    </View>
                                                )} 
                                                { STI === 2 && ( <Image source={CMImages.color.branches[theBranch.name]} resizeMode="contain" style={styles.pic} />)}
                                            </View>
                                        </Toucher>
                                        <Toucher
                                            style={styles.middleColTouch}
                                            onPress={() => {
                                                this.setState({ showRelationType: !this.state.showRelationType })
                                                analytics.track('Bazi.Pillar.Interactions.Branch.Relation')
                                            }}
                                        >
                                            <View style={styles.middleCol}>
                                                <MaterialCommunityIcon
                                                    name={iconMap[item.relation][0]}
                                                    color={iconMap[item.relation][1]}
                                                    size={iconMap[item.relation][2]}
                                                />
                                                { this.state.showRelationType && (
                                                        <Text numberOfLines={1} ellipsizeMode={'clip'} style={styles.textLabel2}>{ toTitle(item.relation) }
                                                        { item.relationElementResult && ` [${ toTitle(elementToAspect[item.relationElementResult]).substring(0, 1) }]`}
                                                        </Text>
                                                )}
                                            </View>
                                        </Toucher>
                                        <View style={styles.rightCol}>
                                            { STI === 0 && (
                                            item.affects.map(affect => (
                                                <Toucher
                                                    style={styles.rightColInnerTouch}
                                                    onPress={() => {
                                                        const path =  `earthlyBranches.${affect.branch}`
                                                        this.props.navigation.push('Library', { path, hideClose: true })
                                                        analytics.track('Bazi.Pillar.Interactions.Branch')
                                                    }}
                                                >
                                                    <View>
                                                        <Text style={styles.textLabel}>
                                                            { Ordinals.branches[affect.branch].chinese }
                                                        </Text>
                                                        <Text style={styles.textLabel2}>
                                                            { toTitle(affect.branch)}
                                                        </Text>
                                                    </View>
                                                </Toucher>
                                            )))}
                                            { STI === 1 && (
                                                item.affects.map(affect => (
                                                    <Toucher
                                                        style={styles.rightColInnerTouch}
                                                        onPress={() => {
                                                            const path = `fourPillars.${stemToGod[Ordinals.branches[affect.branch]._hiddenStemsDict.main]}` 
                                                            this.props.navigation.push('Library', { path, hideClose: true })
                                                            analytics.track('Bazi.Pillar.Interactions.Branch')
                                                        }}
                                                    >
                                                        <Text style={styles.textLabel}>
                                                            { stemToGod[Ordinals.branches[affect.branch]._hiddenStemsDict.main].toUpperCase() }
                                                        </Text>
                                                    </Toucher>
                                                ))
                                            )}
                                            { STI === 2 && ( 
                                                item.affects.map(affect => ( 
                                                <Toucher
                                                    style={styles.rightColInnerTouch}
                                                    onPress={() => {
                                                        const path =  `earthlyBranches.${affect.branch}`
                                                        this.props.navigation.push('Library', { path, hideClose: true })
                                                        analytics.track('Bazi.Pillar.Interactions.Branch')
                                                    }}
                                                >
                                                    <Image source={CMImages.color.branches[affect.branch]} resizeMode="contain" style={styles.pic} /> 
                                                </Toucher>
                                            )))}

                                        </View>
                                        <Toucher
                                            onPress={() => {
                                                const items = []
                                                item.affects.forEach(affect => {
                                                    if(affect.pillar === 'luck'){
                                                        items.push({ section: 'Comparison', index: 4, palace: 'branch'})
                                                    }else{
                                                        items.push({ section: 'Birth', index: pillarContainer.birthPillarNameMap[affect.pillar], palace: 'branch'})
                                                    }
                                                })
                                                items.push({ section: currentSectionSID, index: this.props.selectedIndex, palace: 'branch', })
                                                pillarContainer.updateFlash(items)

                                                setTimeout(() => { pillarContainer.resetFlash() }, 2000)
                                                analytics.track('Bazi.Pillar.Interactions.Branch.Flash')
                                            }}
                                            style={styles.flashTouch}
                                        >
                                            <Text style={styles.flashTouchText}>{ branchPillarAbbr}</Text>
                                        </Toucher>
                                    </View>
                                </View>
                            )
                        })}
                    </View>
                    )} 
            </View>
        )
    }
}
export default withNavigation(InteractionDetailBox);





