                    let note = ''
                    if(pillar.indexOf('jia') >= 0) note = '-------'
                    if(pillar.indexOf('jia-zi') === 0) note += '*********'
                    if(point.toFormat('yyyy-MM-dd') === '2019-06-21') note += ' -------- (Summer Solstice)'
                    if(point.toFormat('yyyy-MM-dd') === '2019-12-21') note += ' -------- (Winter Solstice)'

                    const line =  `${point.toFormat('yyyy MM dd')}   ${theDayJus} / ${zhiRunHour[0]} ${zhiRunHour[1]} / ${chaiBuHour[0]} ${chaiBuHour[1]}    ${pillar} ${note}`
