class LaymanRootDetail extends React.Component{
    state = {
    }
    stores = {}
    constructor(props){
        super(props)
        this.process = this.process.bind(this)
        this.stores['heavenEarth'] = new MadContainer()
        this.stores['qi'] = new MadContainer()
    }
    componentDidMount(){
        this.process()
    }
    shouldComponentUpdate(nextProps, nextState){
        if(JSON.stringify(nextState) !== JSON.stringify(this.state)) return true
        if(nextProps.selectedIndex !== this.props.selectedIndex){
            return true
        }else{
            const thisTime = this.props.payload.item[this.props.selectedIndex].time
            const nextTime = nextProps.payload.item[nextProps.selectedIndex].time
            if(objects.chineseTimeString(thisTime) !== objects.chineseTimeString(nextTime))
                return true
        }
        return false
    }
    componentDidUpdate(prevProps, prevState){
        this.process()
    }
    process(){
        const pillar =  this.props.payload.item[this.props.selectedIndex].pillar
        const time =  this.props.payload.item[this.props.selectedIndex].time
        EightWords.extendAuxData(pillar, time, this.props.root, this.props.pillarKeys)
 
        const heavenLine = RootLines.heavenLine(pillar, this.stores, this.props.root)
        const earthLine = RootLines.earthLine(pillar, this.stores, this.props.root)
        const titleLine = RootLines.titleLine(pillar, this.stores)
      

        
        const monthBranch = this.props.root.pillars.month.branch.name
        const heavenScore =  EightWords.getStemRawScore('stem', pillar.stem.name, monthBranch)
        const earthScores = {}
        earthScores['main'] =  EightWords.getStemRawScore('main', pillar.branch.stems.main.name, monthBranch)
        if(pillar.branch.stems.storage)
            earthScores['storage'] = EightWords.getStemRawScore('storage', pillar.branch.stems.storage.name, monthBranch)
        if(pillar.branch.stems.tomb)
            earthScores['tomb'] =  EightWords.getStemRawScore('tomb', pillar.branch.stems.tomb.name, monthBranch)
        if(pillar.branch.stems.growth)
            earthScores['growth'] =  EightWords.getStemRawScore('growth', pillar.branch.stems.growth.name, monthBranch)

        this.setState({ pillar, time, heavenLine, earthLine, titleLine , earthScores, heavenScore})
    }
    render(){
        if(!this.state.pillar) return <Fragment/>
        const titleHeight = 50

        return (
            <Subscribe to={[PreferencesContainer, PillarContainer]}>
            {(prefs, pillarContainer) => {
            return (
                <View style={styles.container}>
                    <View style={styles.titleHolder}>
                        <MadLibs
                            line={this.state.titleLine}
                            containerStyle={{ }}
                            boxTextStyle={styles.titleBoxText}
                            boxSelectStyle={styles.titleBoxSelect}
                        />
                        <View style={{flex: 1 }}/>
                        <Toucher
                            onPress={this.props.switchMode}
                            style={styles.titleSwitcherTouch}
                        >
                            <FontAwesome5
                                name={'window-maximize'}
                                size={22}
                                color={scolor.iconFocused}
                                style={{ transform: [{ rotate: '270deg'}] }}
                            />
                        </Toucher>
                    </View>
                    <View style={sstyle.separator}/> 


                    <SymbolicScrollBox
                        pillar={this.state.pillar} 
                    />
                    <View style={[sstyle.separator, { marginBottom: padd}]}/> 



                    {/* <MadLibs
                        line={this.state.heavenLine}
                        containerStyle={{padding: padd, paddingTop: padd/2  }}
                        boxViewStyle={styles.longForm.boxViewStyle} 
                    />  */}

             
                    <AffinityBox 
                        root={this.props.root} 
                        god={this.state.pillar.stem.gdd}  
                        preLabel={{
                            words: ['I\'m around', 'I\'m with', 'I see', 'I meet', 'I find', 'I spot', 'Affinity with'],
                            shuffle: true,
                        }}
                        containerStyle={{ paddingLeft:44 }}
                    /> 
                    <View style={{ height: padd-6}}/>
                    { this.state.pillar.name !== 'day' && (
                        <LaymanStrengthBar stores={this.stores} stemKey={'stem'} stem={this.state.pillar.stem} score={this.state.heavenScore} root={this.props.root}/>
                    )}




                    <View style={{ height: padd}}/>
                    <View style={sstyle.separator}/> 
                    <View style={{ height: padd}}/>

                    {/* <HeavenEarthSeparator pillar={this.state.pillar} /> */}

{/* 
                    <MadLibs
                        line={this.state.earthLine}
                        containerStyle={{padding: padd, paddingTop: padd/2  }}
                        boxViewStyle={styles.longForm.boxViewStyle} 
                    /> */}


               
                 
            
                    <View style={{ height: padd-6}}/>

                    {Object.keys(this.state.earthScores).map(key => (
                         <LaymanStrengthBar stores={this.stores} stemKey={key} stem={this.state.pillar.branch.stems[key]} score={this.state.earthScores[key]} root={this.props.root}/>
                    ))}

                    <View style={{ height: padd-6}}/>



                    <ArchetypeBox
                        pillar={this.state.pillar}
                    />


                    <SectionHeader subtitle={'Palaces'}/>

                    { this.state.pillar.name !== 'day' && (
                    <PalaceRelationshipBox
                        pillar={this.state.pillar}
                        type={'stem'}
                        root={this.props.root}
                    />
                    )}
                    <View style={sstyle.separator}/> 

                    <PalaceRelationshipBox
                        pillar={this.state.pillar}
                        type={'branch'}
                        root={this.props.root}
                    />
                    <View style={sstyle.separator}/> 
                    
                </View>
            )}}
            </Subscribe>
        )
    }
}
export default withNavigation(LaymanRootDetail);





