export const toTitle = (text) => {
    if(!text) return ''
    if(typeof text !== 'string') return text
    return text.replace(/\w\S*/g, function(txt){
        return txt.charAt(0).toUpperCase() + txt.substr(1);
    });
}


export const titleEveryWord = (text) => {
    if(!text) return ''
    if(typeof  text !== 'string') return text
    return text.replace(/\w\S*/g, function(txt){
        return txt.charAt(0).toUpperCase() + txt.substr(1).toLowerCase();
    });
}

export const capFirst = (text) => {
    if(!text) return ''
    if(typeof text !== 'string') return text
    return text.charAt(0).toUpperCase() + text.slice(1)
}

export const removeEmoji = (text) => {
    return text.replace(/([\uE000-\uF8FF]|\uD83C[\uDF00-\uDFFF]|\uD83D[\uDC00-\uDDFF])/g, '')
}

export const deCamel = (text) => {
    if(!text) return ''
    if(typeof text === 'string' && text.indexOf(' ') >= 0) {
        return titleEveryWord(text)
    }
    return toTitle(String(text)).replace(/([A-Z])/g, ' $1').replace('_',' ').replace('  ', ' ').trim()
}

export const removeUnderscore = (text) => {
    if(text && text.length > 0){
        return text.replace(/\_/g, ' ')
    }else{
        return text;
    }
}




export const spaces = (text) => {
    if(text && text.length > 0){
        return text.replace(/\-/g, ' ')
    }else{
        return text;
    }
}


export const hyphen = (text) => {
    if(text && text.length > 0){
        return text.replace(/ /g, '-')
    }else{
        return text;
    }
}


export const getMentions = (str, keepSign=false) => {
    if (typeof str !== "string") {
        return [];
    }
    const pattern = /\B@[A-Za-z0-9]+\b/gi;
    const matches = str.match(pattern);
    if (matches && matches.length > 0)
        return matches.map(item => {
            if(keepSign){
                return item.toLowerCase()
            }else{
                return item.replace('@', '').toLowerCase()
            }
        });
    return [];
};


export const randomInt = (min, max) => {
    min = Math.ceil(min);
    max = Math.floor(max);
    return Math.floor(Math.random() * (max - min + 1)) + min;
}

export const randomString = (string_length) => {
    const chars = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXTZabcdefghiklmnopqrstuvwxyz";
    let rss = '';
    for (let i=0; i < string_length; i++) {
        const rnum = Math.floor(Math.random() * chars.length);
        rss += chars.substring(rnum,rnum+1);
    }
    return rss;
}

export const emailInString = (str) => /(([^<>()[\]\\.,;:\s@\"]+(\.[^<>()[\]\\.,;:\s@\"]+)*)|(\".+\"))@((\[[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\])|(([a-zA-Z\-0-9]+\.)+[a-zA-Z]{2,}))/.test(str);
export const br2nl = (s) => s.replace(/(?:\r\n|\r|\n)/g, '<br/>');
export const base64 = (s) => new Buffer(s).toString('base64');
export const removeSymbols = (str) => str.replace(/[^A-Za-z0-9]/g,'');
export const isValidEmail = (email) => email.match(/^(([^<>()[\]\\.,;:\s@\"]+(\.[^<>()[\]\\.,;:\s@\"]+)*)|(\".+\"))@((\[[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\])|(([a-zA-Z\-0-9]+\.)+[a-zA-Z]{2,}))$/);
export const isValidUsername = (str) => /^[a-z0-9]+$/.test(str.trim());
export const isValidThing = (str) => /^[a-z0-9_]+$/.test(str.trim());

export const addNumbersInString = (str) => {
    try{
        let total = 0
        for(let i = 0; i < str.length; i++){
            total += parseInt(str.charAt(i))
        }
        return parseInt(total);
    }catch(err){
        console.error('addnmbersinstring', err)
        return null;
    }
}

export const liSheeYeeLetterConversion = (s) => {
    let result = '';
    let str = s.replace(/ /g,'')
    for (var i = 0; i < str.length; i++) {
        const input = String(str.charAt(i).toLowerCase());
        if(['1','2','3','4','5','6','7','8','9','0'].indexOf(input) >= 0){
            result += input;
        }else if(['a','j','s'].indexOf(input) >= 0){
            result += '1';
        }else if(['b','k','t'].indexOf(input) >= 0){
            result += '2';
        }else if(['c','l','u'].indexOf(input) >= 0){
            result += '3';
        }else if(['d','m','v'].indexOf(input) >= 0){
            result += '4';
        }else if(['e','n','w'].indexOf(input) >= 0){
            result += '5';
        }else if(['f','o','x'].indexOf(input) >= 0){
            result += '6';
        }else if(['g','p','y'].indexOf(input) >= 0){
            result += '7';
        }else if(['h','q','z'].indexOf(input) >= 0){
            result += '8';
        }else if(['i','r'].indexOf(input) >= 0){
            result += '9';
        }
    }
    return result;
}
