const process = (inter, stores, props, additional=undefined) => {
    const { pillarContainer, pillar , root} = props
    const cycles = Ordinals.cycles
    const affectedStem = Ordinals.stems[inter.affects[0].stem]
    const affectedElement = Ordinals.elements[affectedStem.element]
    const affectedGod = EightWords.gods[inter.affects[0].god]
    const affectedAspect = EightWords.aspects[affectedGod.aspect]
    const affectedPillar = Dict.EightWords.pillars[inter.affects[0].pillar]
    const currentSectionSID = props.payload.section.sid;

    let action = ['']
    let touchIcon = ''

    if(inter.relation === 'conflict'){
        if(cycles.controls[pillar.stem.elm.name] === affectedStem.element){
            action = [ 'Controls', 'Suppresses', 'Restrains']; 
            touchIcon = 'arrow-top-right'
        }else{
            action = ['Controlled by', 'Suppressed by', 'Restrained by']; 
            touchIcon = 'arrow-bottom-left'
        }

    }else{
        action = [ 'Combines with', 'Merges with', 'Joins with', 'Unites with']
        touchIcon = 'circle'
    }
    const myActionBox = { 
        words: action,
        shuffle: false,
        boxViewStyle:{
            ...istyle.madlibs.boxViewStyle,
            // borderRightWidth:1,
        }
    }

    let myPillarBox = null
    let myContentBox = null
    if(inter.affects[0].pillar === 'day'){
        myContentBox = { 
            words: [
                `Ego`, 
                `Me`,
            ], 
            shuffle:false, 
            // borderColor: affectedElement._colors.light
        }
    }else{
        myPillarBox =  { 
            words: [
                ...affectedPillar.$dict_syn.map(i => toTitle(i))
            ],
            shuffle: true,
            boxViewStyle:{
                ...istyle.madlibs.boxViewStyle,
            }
        }
        myContentBox = { 
            words: [
                `${toTitle(affectedAspect.name)}`,
                ...affectedAspect.$dict_noun.map(i => toTitle(i)),
                ...affectedAspect.$dict_noun2.map(i => toTitle(i)),
            ], 
            shuffle: false ,
            // borderColor: affectedElement._colors.light
        }
    }

    const line = [
        myActionBox,
        myContentBox,
    ]
    if(myPillarBox) line.splice(1, 0, myPillarBox)


    let newElementColor = null
    if(inter.relation === 'combo'){
        const newElement = inter.relationElementResult
        const newAspect = EightWords.aspects[root.meta.maps.elementToAspect[newElement]]
        newElementColor =  Graphics.colors.elements.light[newElement]
        const newStem = Ordinals.elements[newElement].stems[0]
        line.push({ words: [' ⇢ ', 'producing', 'forming'], shuffle: false})
        line.push({
            words: [
                `${toTitle(newAspect.name)}`,
                ...newAspect.$dict_noun.map(i => toTitle(i)),
                ...newAspect.$dict_noun2.map(i => toTitle(i)),
            ],
            // borderColor: newElementColor,
        })
    }
    return (
        <View style={[istyle.row,
            additional && { marginTop: 6}
        ]}> 
            <MadLibs
                line={line}
                containerStyle={istyle.madlibs.containerStyle}
                boxViewStyle={istyle.madlibs.boxViewStyle}
                boxSelectStyle={istyle.madlibs.boxSelectStyle}
                boxTextStyle={istyle.madlibs.boxTextStyle}
                iconStyle={istyle.madlibs.iconStyle} 
            />
            <Toucher
                style={istyle.actionTouch}
                onPress={() => {
                    const items = []
                    inter.affects.forEach(affect => {
                        items.push({ section: 'Birth',index: pillarContainer.birthPillarNameMap[affect.pillar], palace: 'stem'})
                    })
                    items.push({ section: currentSectionSID, index: props.selectedIndex , palace: 'stem', })
                    pillarContainer.updateFlash(items)

                    analytics.track('Bazi.Pillar.Interactions.Stem.Flash')
                    setTimeout(() => { pillarContainer.resetFlash() }, 2000)
                }}
            >
                <MaterialCommunityIcon
                    name={touchIcon}
                    color={newElementColor || Color.GREY[600]}
                    size={ touchIcon === 'circle' ? 16 : 18}
                />
            </Toucher>
        </View>
    )
}
const LaymanInteractionStems = (props) => {
    const { pillar } = props
    const interactions = _.cloneDeep(pillar.stem.interactions)
    if(!interactions || interactions.length === 0) return <Fragment/>
    const [state, setState] = useState({ showAll: false })
    const [stores, setStores] = useState(null)
    const firstInter = interactions.splice(0, 1)

    return (
        <View style={istyle.container}>
            { firstInter.map(inter => process(inter, stores, props))}
            { (!state.showAll && interactions.length > 0) && (
                <Toucher
                    style={istyle.showAllTouch}
                    onPress={() => { setState({ showAll: !state.showAll}) }}
                >
                       <MaterialCommunityIcon
                        name={'chevron-down-box'}
                        size={22}
                        color={Color.GREY[300]}
                    />
                </Toucher>
            )}
            { (state.showAll && interactions.length > 0) && (
                <View>
                    { interactions.map(inter => process(inter, stores,  props, true))}
                </View>
            )}



        </View>
    )
}

const borderRadius = 4


export default withNavigation(LaymanInteractionStems)

















