const preHeavenToTrigram = {
	0: Ordinals.guas.kun,
	1: Ordinals.guas.qian,
	2: Ordinals.guas.dui,
	3: Ordinals.guas.li,
	4: Ordinals.guas.zhen,
	5: Ordinals.guas.xun,
	6: Ordinals.guas.kan,
	7: Ordinals.guas.gen,
	8: Ordinals.guas.kun,
	9: Ordinals.guas.qian,
}

const LiSheeYeeSelector = (props) => {
    let textInput;
    let inputVal;
    const [hexResult, setHexResult] = useState(null)
    const calcData = () => {
        let num = strings.liSheeYeeLetterConversion(inputVal)
        let extra = ''
        let h1 = null
        let h2 = null
        let firstTrigramNum
        let secondTrigramNum
        
        if(num.length < 2){ 
            setHexResult(null)
            return ;
        }else if(num.length === 2){
            h1 = num.charAt(0)
            h2 = num.charAt(1)
            firstTrigramNum = num.charAt(0)
            secondTrigramNum = num.charAt(1)
            extra = ''
        }else{
            if(num.length % 2){
                extra = num.charAt(num.length-1)
                num = num.substring(0, num.length)
                h1 = num.substring(0, num.length/2)
                h2 = num.substring(num.length/2, num.length-1)
            }else{
                h1 = num.substring(0, num.length/2)
                h2 = num.substring(num.length/2, num.length)
            }
            firstTrigramNum = strings.addNumbersInString(h1) % 8
            secondTrigramNum = strings.addNumbersInString(h2 + extra) % 8
        }

        const numTotal = strings.addNumbersInString(num)
        const  now = FourPillars.plot({ time: DateTime.local()})
        const whichHour  = parseInt(now.pillars.hour.branch.number) + 1
       
        let movingLine = (  numTotal + whichHour) % 6
        if(movingLine === 0) movingLine = 6
    

        setHexResult({
            now,
            whichHour,
            movingLine,
            h1, h2, extra,
            firstTri: preHeavenToTrigram[firstTrigramNum],
            secondTri: preHeavenToTrigram[secondTrigramNum]
        })
    }
    useEffect(() => {
        textInput.focus()
    })
    return (
        <ScrollView keyboardShouldPersistTaps={'always'} style={styles.container}>
            <SectionHeader
                title={'Hexagram from String'}
                subtitle={'Generate a hexagram from letters and numbers (LSY method).'}
            />
            <View style={styles.inner}>
                <TextInput
                    clearButtonMode={'while-editing'}
                    ref={c => {textInput = c}} 
                    autoCapitalize="none"
                    autoCorrect={false}
                    returnKeyType={'done'}
                    style={styles.inputBox}
                    // value={inputVal}
                    onChangeText={(text) => {
                        inputVal = text;
                        calcData()
                    }}
                    onSubmitEditing={() => {
                        if(!hexResult) return
                        const data = hexResult.firstTri.binary + hexResult.secondTri.binary
                        props.finishInputMethod(data.split('').map(i => parseInt(i)), hexResult.movingLine)
                        analytics.track('Hexagram.LiSheeYee', { inputVal })
                    }}
                />
                { hexResult && (
                    <View>

                        <View style={styles.info}>
                            <Text style={styles.numInfo}>{ hexResult.h1 }  /  { hexResult.h2}{hexResult.extra} </Text>
                            <Text style={styles.trigramInfo}>{ hexResult.firstTri.preHeaven}-{ hexResult.firstTri.pinyin.toUpperCase() }  /  { hexResult.secondTri.preHeaven}-{ hexResult.secondTri.pinyin.toUpperCase() } </Text>
                            <Text style={[styles.numInfo, { marginTop:12 }]}>Hour: { strings.toTitle(hexResult.now.pillars.hour.branch.name)} ({hexResult.now.pillars.hour.branch.number + 1})</Text>
                            <Text style={styles.trigramInfo}>Moving Line: { parseInt(hexResult.movingLine) }</Text>
                        </View>
                        <Toucher
                            onPress={() => {
                                const data = hexResult.firstTri.binary + hexResult.secondTri.binary
                                props.finishInputMethod(data.split('').map(i => parseInt(i)), hexResult.movingLine)
                                analytics.track('Hexagram.LiSheeYee', { inputVal })
                            }}
                            style={styles.buttonTouch}
                        >
                            <Text style={styles.buttonText}>Generate Hexagram</Text>
                        </Toucher>
                    </View>
                )}
            </View>
        </ScrollView>
    )
}
