import { Header } from 'react-navigation-stack'
import { Dimensions } from 'react-native';
import { isIphoneX, getStatusBarHeight,  getBottomSpace } from 'react-native-iphone-x-helper';

export const keyboardVerticalOffset = () => {
    return isIphoneX() ? 88 : Header.HEIGHT
}

export const keyboardAvoidingViewStyle  = {
    backgroundColor:"#ffffff",
}

export const getViewableWindowHeight  = (subtractHeader = true, subtractMore=0) => {
    const winWidth = Dimensions.get('window').width
    const winHeight = Dimensions.get('window').height
    const stackHeaderHeight = Header.HEIGHT;
    const TAB_BAR_DEFAULT_HEIGHT = 42; //was 49
    const TAB_BAR_COMPACT_HEIGHT = 29; 
    const TAB_BAR_HEIGHT = TAB_BAR_DEFAULT_HEIGHT;
    let viewableWindowHeight = winHeight  - (getBottomSpace() + TAB_BAR_HEIGHT)
    if(subtractHeader){
        viewableWindowHeight -= (getStatusBarHeight() + stackHeaderHeight)
    }
    viewableWindowHeight -= subtractMore
    return viewableWindowHeight
}