export const getPersonalGua = (year, isPreviousYear, gender) => {
	const lifeStarDescArr = {
		'1': ['white','water'],
		'2': ['black', 'earth'],
		'3': ['green', 'wood'],
		'4': ['green', 'wood'],
		'5': ['yellow', 'earth'],
		'6': ['white', 'metal'],
		'7': ['red', 'metal'],
		'8': ['white', 'earth'],
		'9': ['purple', 'fire'],
	}
	const guaList = {
		female: Tools.toProxy([1, 2, 3, 4, 5, 6, 7, 8, 9]),
		male: Tools.toProxy([5, 4, 3, 2, 1, 9, 8, 7, 6]),
	}
	let y = year;
	if(isPreviousYear) y -= 1
	const diff = y - 1932
	let guaNumber = guaList[gender][diff]
	if(guaNumber === 5){
		if(gender === 'male') guaNumber = 2
		else guaNumber = 8
	}
	const data = Tools.find(Ordinals.guas, 'luoShu', guaNumber)
	data.lifeStarDescArr = lifeStarDescArr[String(guaNumber)]
	return data
}


