export const getTimeFlyingStars = (time) => {
    const flyStars = (center) => {
        const palaces = Tools.toProxy(['kan', 'kun','zhen','xun','center','qian','dui','gen','li'])
        const nums = Tools.toProxy([1, 2, 3, 4, 5, 6, 7, 8, 9])
        const data = {}
        palaces.forEach((pal, index) => { data[pal] = nums[index + 4 + center] })
        return data
    }
    const calcYearCenter = () => {
        let year = time.year;
        if(time < SolarCal.getCurrentYearJie(time)){
            year = year - 1
        }
        const nums = Tools.toProxy([1, 2, 3, 4, 5, 6, 7, 8, 9])
        const centerNum = nums[2017-year]
        return centerNum
    }
    const calcMonthCenter = () => {
        const bazi = FourPillars.plot({ time })
        const centerNum = monthCenterTable(bazi.pillars.month.branch.name, bazi.pillars.year.branch.name)
        return centerNum
    }
    const calcDayCenter = () => {
        const bazi = FourPillars.plot({ time: time.set({ hour: 12 })  })
        const term = bazi.info.solarTerm.thisTerm
        const dun = (term.data.num >= 9 && term.data.num < 21) ? 'yin' : 'yang'
        const solstice = SolarCal.getSolstice(bazi)
        let ziMark 
        for(let i = 0; i < 61; i++){
            const bb = FourPillars.plot({ time: solstice.time.set({ hour: 12 }).plus({ day: i }) })
            if(bb.pillars.day.stem.name === 'jia' && bb.pillars.day.branch.name === 'zi'){
                ziMark = bb
                break
            }
        }
        const diffDays = bazi.info.time.diff(ziMark.info.time, 'days'  ).days 
        const path = dun === 'yin' ? Tools.toProxy([9,8,7,6,5,4,3,2,1] ) : Tools.toProxy([1, 2, 3, 4, 5, 6, 7, 8, 9] )
        const center = path[Math.round(diffDays)]
        return center
    }
    const calcHourCenter = () => {
        const bazi = FourPillars.plot({ time: time }) 
		const term = bazi.info.solarTerm.thisTerm
		const dun = (term.data.num >= 9 && term.data.num < 21) ? 'yin' : 'yang'

        const ziHourCenter = ziHourCenterTable(bazi.pillars.day.branch.name, dun)
        const path = dun === 'yin' ? Tools.toProxy([9,8,7,6,5,4,3,2,1] ) : Tools.toProxy([1, 2, 3, 4, 5, 6, 7, 8, 9] )
        path.indexOf(ziHourCenter) 

        const hbIndex = Ordinals.branchOrdering.indexOf(bazi.pillars.hour.branch.name)
        return path[hbIndex + path.indexOf(ziHourCenter)]
    }
    const ziHourCenterTable = (db, dun) => {
        if(dun === 'yang'){
            if(['zi','mao','wu','you'].indexOf(db) >= 0){
                return 1
            }else if(['yin','si','shen','hai'].indexOf(db) >= 0){
                return 7
            }else if(['chou','chen','wei','xu'].indexOf(db) >= 0){
                return 4
            }
        }else{
            if(['zi','mao','wu','you'].indexOf(db) >= 0){
                return 9
            }else if(['yin','si','shen','hai'].indexOf(db) >= 0){
                return 3
            }else if(['chou','chen','wei','xu'].indexOf(db) >= 0){
                return 6
            }
        }
    }
    const  monthCenterTable = (mb, yb) => {
        let index = null;
        if(['zi','mao','wu','you'].indexOf(yb) >= 0){
            index = 0
        }else if(['yin','si','shen','hai'].indexOf(yb) >= 0){
            index = 1
        }else if(['chou','chen','wei','xu'].indexOf(yb) >= 0){
            index = 2
        }
        const table = {
            yin: [8, 2, 5],
            mao: [7, 1, 4],
            chen: [6, 9, 3],
            si: [5, 8, 2],
            wu: [4, 7, 1],
            wei: [3, 6, 9],
            shen: [2, 5, 8],
            you: [1, 4, 7],
            xu: [9, 3, 6],
            hai: [8,2,5],
            zi: [7, 1, 4],
            chou: [6, 9, 3],
        }
        return table[mb][index]
    }

    const hour =flyStars(calcHourCenter())
    const day = flyStars(calcDayCenter())
    const month = flyStars(calcMonthCenter())
    const year = flyStars(calcYearCenter())

    const payload = { hour, day, month, year }
    return payload


}

export const getHouseFlyingStars = (data) => {
    if(!data) return null;
    const year = parseInt(data?.houseYear) 
    const degree = parseFloat(data?.houseDegree) 
    if(!year || typeof degree === 'undefined' || isNaN(degree)|| year < 1864 || year > 2064 || degree < 0 || degree > 360){
        return null
    }

    const flightPath = (gua, period,s) => {
        const sector = parseInt(s.replace(/\D/g,''))
        if([1, 3, 7, 9].indexOf(gua) >= 0){
            if(sector === 1) return 1
            if(sector === 2) return 0
            if(sector === 3) return 0
        }else if([2, 4, 6, 8].indexOf(gua) >= 0){
            if(sector === 1) return 0
            if(sector === 2) return 1
            if(sector === 3) return 1
        }else{
            if(period % 2 === 0){ //even
                if(sector === 1) return 0
                if(sector === 2) return 1
                if(sector === 3) return 1
            }else{
                if(sector === 1) return 1
                if(sector === 2) return 0
                if(sector === 3) return 0
            }
        }
    }
    const flyStars = (center, flow = 1) => {
        const palaces = Tools.toProxy(['kan', 'kun','zhen','xun','center','qian','dui','gen','li'])
        const data = {}
        if(flow === 0){
            const nums = Tools.toProxy([9, 8, 7, 6, 5, 4, 3, 2, 1])
            palaces.forEach((pal, index) => { 
                data[pal] = nums[index - 4 - center] 
            })
        }else{
            const nums = Tools.toProxy([1, 2, 3, 4, 5, 6, 7, 8, 9])
            palaces.forEach((pal, index) => { 
                data[pal] = nums[index + 4 + center] 
            })
        }
        return data
    }

    const oppositeDegree = parseFloat((degree + 180) % 360);
    const period = yearToPeriod(year)
    const faceInfo = mountains[degreeToMountain(degree)]
    const sitInfo = mountains[degreeToMountain(oppositeDegree)]


    const basePlate = flyStars(period)

    const facePath = flightPath(basePlate[faceInfo.palace], period, faceInfo.sector)
    const sitPath = flightPath(basePlate[sitInfo.palace],period, sitInfo.sector)

    const facingPlate = flyStars(basePlate[faceInfo.palace], facePath)
    const sittingPlate = flyStars(basePlate[sitInfo.palace], sitPath)

    const payload= { 
        plates: { base: basePlate, facing: facingPlate, sitting: sittingPlate},
        period,
        faceMountain: faceInfo,
        sitMountain: sitInfo,
        houseDegree: degree,
        houseYear: year,
    }
    return payload
}


export const degreeToMountain = (degree) => {
    let sector = null
    const d = parseFloat(degree)
    switch(true){
        case d >= 157.6 && d <= 172.5:
            sector = 's1'
            break;
        case d >= 172.6 && d <= 187.5:
            sector = 's2'
            break;
        case d >= 187.6 && d <= 202.5:
            sector = 's3'
            break;
        case d >= 202.6 && d <= 217.5:
            sector = 'sw1'
            break;
        case d >= 217.6 && d <= 232.5:
            sector = 'sw2'
            break;
        case d >= 232.6 && d <= 247.5:
            sector = 'sw3';
            break;
        case d >= 247.6 && d <= 262.5:
            sector='w1';
            break;
        case d >= 262.6 && d <= 277.5:
            sector='w2'
            break;
        case d >= 277.6 && d <= 292.5:
            sector='w3'
            break;
        case d >= 292.6 && d <= 307.5:
            sector='nw1'
            break;
        case d >= 307.6 && d <= 322.5:
            sector='nw2'
            break;
        case d >= 322.6 && d <= 337.5:
            sector='nw3'
            break;
        case d >= 337.6 && d <= 352.5:
            sector='n1'
            break;
        case d >= 352.6:
            sector='n2'
            break;
        case d <= 7.5:
            sector='n2'
            break;
        case d >= 7.6 && d <= 22.5:
            sector='n3';
            break;
        case d >= 22.6 && d <= 37.5:
            sector='ne1';
            break;
        case d >= 37.6 && d <= 52.5:
            sector='ne2'
            break;
        case d >= 52.6 && d <= 67.5:
            sector='ne3'
            break;
        case d >= 67.6 && d <= 82.5:
            sector='e1';
            break;
        case d >= 82.6 && d <= 97.5:
            sector='e2';
            break;
        case d >= 97.6 && d <= 112.5:
            sector='e3';
            break;
        case d >= 112.6 && d <= 127.5:
            sector='se1';
            break;
        case d >= 127.6 && d <= 142.5:
            sector='se2';
            break;
        case d >= 142.6 && d <= 157.5:
            sector='se3';
            break;
	}

    return sector?.toUpperCase();
}


export const yearToPeriod = (y) => {
    let res = null;
    switch (true){
        case y >= 1844 && y < 1864:
            res = 9;
            break;
        case y >= 1864 && y < 1884:
            res = 1
            break;
        case y >= 1884 && y < 1904:
            res = 2
            break;
        case y >= 1904 && y < 1924 :
            res = 3
            break;
        case y >=  1924 && y < 1944:
            res = 4
            break;
        case y >=  1944 && y < 1964:
            res = 5
            break;
        case y >=  1964 && y < 1984:
            res = 6
            break;
        case y >=   1984 && y < 2004:
            res = 7
            break;
        case y >=   2004 && y < 2024:
            res = 8
            break;
        case y >=    2024 && y < 2044:
            res = 9
            break;
        case y >= 2044 && y < 2064:
            res = 1;
            break;
        case y >= 2064 && y  < 2084:
            res = 2;
            break;
    }
    return res
}


