export const extendEightMansions = (map) => {
    const result = {}
    const elementStrengthToScore = {
        peak: 4,
        strong: 3,
        weak: 2,
        trap: 1,
        dead: 0,
    }
    Object.keys(map).forEach(pal => {
        const palaceElement = Ordinals.guas[pal].element 
        const mansionElement = eightMansions[map[pal]].element
        const strength = Ordinals.elements[mansionElement].strength[palaceElement]
        const rating = ['shengQi','tianYi','yanNian','fuWei'].indexOf(map[pal]) >= 0 ? 1 : -1
        const score = elementStrengthToScore[strength] * rating
        result[pal] = {
            name: map[pal],
            strength,
            rating,
            score,
            
        } 
    })
    return result;
}


